insert into public.bible_verses (translation_id, book_code, chapter, verse, verse_end, text, para) values
('bunong-vn','NUM',1,1,null,$b$Yêhôva ngơi ma Y-Môis tâm bri rdah Sinai, gŭ tâm ngih bok tâm rƀŭn, nar ntơm bôk khay bar, năm rơh bar, khân păng lĕ luh du jêh tă bơh n'gor bri Êjipt, lah:$b$,true),
('bunong-vn','NUM',1,2,null,$b$“Ƀư hom nau kơp lĕ rngôch phung Israel, rgum tĭng noi deh jêh ri ndŭl mpôl khân păng, kơp tĭng amoh săk ăp nơm bu klâu,$b$,false),
('bunong-vn','NUM',1,3,null,$b$ntơm bơh bar jât năm bơi rlau, jêng lĕ rngôch bunuyh tâm phung Israel dơi hăn ma nau tâm lơh; ăn may jêh ri Y-Arôn kơp khân păng, du phung du phung.$b$,false),
('bunong-vn','NUM',1,4,null,$b$Tâm ăp ndŭl mpôl dơi geh du huê bunuyh kâp kơl khân may, jêng bunuyh ƀư kôranh tơm noi deh ma ndŭl mpôl khân păng.$b$,false),
('bunong-vn','NUM',1,5,null,$b$Aơ amoh săk phung mra kâp kơl khân may: Bơh phung Ruben geh Y-Êlisur, kon bu klâu Y-Sêdur;$b$,false),
('bunong-vn','NUM',1,6,null,$b$bơh phung Simêôn geh Y-Sêlumiêl, kon bu klâu Y-Suri sadai;$b$,false),
('bunong-vn','NUM',1,7,null,$b$bơh phung Yuđa geh Y-Nahsôn, kon bu klâu Y-Aminadap;$b$,false),
('bunong-vn','NUM',1,8,null,$b$bơh phung Isakar geh Y-Nêthanel, kon bu klâu Y-Suar;$b$,false),
('bunong-vn','NUM',1,9,null,$b$bơh phung Sabulôn geh Y-Êliap, kon bu klâu Y-Êlôn;$b$,false),
('bunong-vn','NUM',1,10,null,$b$bơh phung kon sau Y-Yôsep, jêng phung Êphraim, geh Y-Êlisama kon bu klâu Y-Amihut; bơh phung Manasê geh Y-Gamaliel, kon bu klâu Y-Pêdasur;$b$,false),
('bunong-vn','NUM',1,11,null,$b$bơh phung Benjamin geh Y-Abidan, kon bu klâu Y-Gidêôni;$b$,false),
('bunong-vn','NUM',1,12,null,$b$bơh phung Dan geh Y-Ahiêser, kon bu klâu Y-Amisadai;$b$,false),
('bunong-vn','NUM',1,13,null,$b$bơh phung Aser geh Y-Pagiel, kon bu klâu Y-Ôkran;$b$,false),
('bunong-vn','NUM',1,14,null,$b$bơh phung Gat geh Y-Êliasap, kon bu klâu Y-Dêuel;$b$,false),
('bunong-vn','NUM',1,15,null,$b$bơh phung Naptali Y-Ahira, kon bu klâu Y-Ênan.”$b$,false),
('bunong-vn','NUM',1,16,null,$b$Phung aơ jêng phung bu săch bơh phung tâm rgum băl, phung kôranh ma noi deh phung ndŭl mpôl khân păng, phung kôranh ma mpôl Israel.$b$,true),
('bunong-vn','NUM',1,17,null,$b$Pô ri, Y-Môis jêh ri Y-Arôn sŏk phung bu klâu aơ bu lĕ ntơ amoh jêh;$b$,false),
('bunong-vn','NUM',1,18,null,$b$tât ta nar ntơm bôk khay bar, khân păng tâm rƀŭn ndrel lĕ rngôch phung ƀon lan, chih amoh khân păng ăp nuyh tĭng rnăk sa, jêh ri tĭng ndŭl mpôl khân păng, kơp amoh ăp nuyh, ntơm bơh bar jât năm bơi rlau.$b$,false),
('bunong-vn','NUM',1,19,null,$b$Pô nây, Y-Môis kơp khân păng tâm bri rdah Sinai, tĭng nâm nau Yêhôva hŏ ntăm.$b$,false),
('bunong-vn','NUM',1,20,null,$b$Phung Ruben, jêng kon bôk rah ma Israel, noi deh khân păng tĭng nâm mpôl, tĭng nâm ndŭl deh khân păng, tĭng nâm rnoh kơp amoh khân păng, kơp ăp nuyh, bu klâu ntơm bar jât năm bơi rlau, lĕ rngôch dơi hăn ma nau tâm lơh:$b$,false),
('bunong-vn','NUM',1,21,null,$b$Rnoh kơp bunuyh bơh ndŭl mpôl Ruben geh puăn rmưn prao rbăn prăm rhiăng nuyh.$b$,false),
('bunong-vn','NUM',1,22,null,$b$Phung Simêôn, phung kon sau khân păng, tĭng nâm mpôl khân păng, jêh ri noi deh khân păng, tĭng nâm rnoh kơp amoh khân păng, kơp ăp nuyh, bu klâu ntơm bar jât năm bơi rlau, lĕ rngôch dơi hăn ma nau tâm lơh:$b$,true),
('bunong-vn','NUM',1,23,null,$b$Rnoh kơp bunuyh bơh ndŭl mpôl Simêôn geh prăm rmưn sĭn rbăn pe rhiăng nuyh.$b$,false),
('bunong-vn','NUM',1,24,null,$b$Phung Gat, phung kon sau khân păng, tĭng nâm mpôl khân păng, jêh ri noi deh khân păng, tĭng nâm rnoh kơp amoh khân păng, kơp ăp nuyh bu klâu ntơm bar jât năm bơi rlau, lĕ rngôch dơi hăn ma nau tâm lơh:$b$,false),
('bunong-vn','NUM',1,25,null,$b$Rnoh kơp bunuyh bơh ndŭl mpôl Gat geh puăn rmưn prao rbăn prăm rhiăng nuyh.$b$,false),
