('bunong-vn','NUM',3,4,null,$b$Ƀiă lah Y-Nadap jêh ri Y-Abihu hŏ khĭt ta năp Yêhôva tơ lah bar hê nhhơr du ntil ŭnh mâu kloh ta năp Yêhôva tâm bri rdah Sinai; jêh ri khân păng mâu geh kon ôh. Bi ma Y-Êlêasar jêh ri Y-Ithamar ƀư kan kôranh ƀư brah ta năp măt Y-Arôn, jêng mbơ̆ khân păng.$b$,true),
('bunong-vn','NUM',3,5,6,$b$“Ăn hom ndŭl mpôl Lêvi văch dăch ngih bok, dăp pa năp kôranh ƀư brah Y-Arôn, gay ma phung Lêvi pah kan ma păng.$b$,false),
('bunong-vn','NUM',3,7,null,$b$Phung Lêvi mra pah kan ma păng jêh ri pah kan ma lĕ rngôch phung tâm rƀŭn ta năp ngih bok, dôl khân păng pah kan tâm ngih bok.$b$,false),
('bunong-vn','NUM',3,8,null,$b$Khân păng ăt mra pah đŏng kan uănh lĕ rngôch ndô ndơ dŏng tâm ngih bok nau tâm rƀŭn, jêh ri kơl kan phung ƀon lan Israel dôl khân păng pah kan ta ngih bok.$b$,false),
('bunong-vn','NUM',3,9,null,$b$Pô nây, ăn may jao phung Lêvi ma Y-Arôn jêh ri ma phung kon bu klâu păng; yor lah hŏ sŏk jêh khân păng bơh ta nklang phung Israel gay jao lĕ khân păng ma Y-Arôn ro.$b$,false),
('bunong-vn','NUM',3,10,null,$b$Ăn may dơm ma Y-Arôn jêh ri phung kon bu klâu păng, jêh nây khân păng mra pah kan kôranh ƀư brah; ƀiă lah, tơ lah bunuyh êng văch dăch ngih bok, ăn bu nkhĭt păng.”$b$,false),
('bunong-vn','NUM',3,11,null,$b$Yêhôva lah ma Y-Môis,$b$,true),
('bunong-vn','NUM',3,12,null,$b$“Aơ, tă bơh ta nklang phung ƀon lan Israel, gâp sŏk săch jêh phung Lêvi ntrok ntŭk lĕ rngôch kon bôk rah bơh phung ƀon lan Israel; pô nây phung Lêvi mra jêng ndơ gâp.$b$,false),
('bunong-vn','NUM',3,13,null,$b$Yor lah lĕ rngôch kon bôk rah jêng ndơ gâp; kăl e ta nar gâp nkhĭt lĕ rngôch kon bôk rah tâm n'gor bri Êjipt, gâp hŏ prăp ăn ma gâp nơm lĕ rngôch kon bôk rah tâm Israel, nđâp ma bunuyh jêh ri mpô mpa; Khân păng mra jêng ndơ gâp; gâp jêng Yêhôva.”$b$,false),
('bunong-vn','NUM',3,14,null,$b$Yêhôva lah ma Y-Môis tâm bri rdah Sinai,$b$,false),
('bunong-vn','NUM',3,15,null,$b$“Kơp hom phung kon bu klâu Lêvi tĭng nâm noi deh khân păng, tĭng nâm mpôl khân păng; ăn may kơp lĕ rngôch bu klâu ntơm bơh phung geh du khay bơi rlau.”$b$,false),
('bunong-vn','NUM',3,16,null,$b$Pô nây Y-Môis kơp khân păng tĭng nâm nau Yêhôva hŏ ntĭnh jêh ma păng.$b$,true),
('bunong-vn','NUM',3,17,null,$b$Aơ jêng phung kon bu klâu Lêvi tĭng nâm amoh khân păng: Y-Gersôn, Y-Kôhat, jêh ri Y-Mêrari.$b$,true),
