('bunong-vn','NUM',3,24,null,$b$geh Y-Êliap, kon bu klâu Y-Laêl, jêng kôranh ma noi deh phung Gersôn.$b$,false),
('bunong-vn','NUM',3,25,null,$b$Kan phung kon bu klâu Y-Gersôn pah tâm ngih bok nau tâm rƀŭn jêng kan đah ngih bok, jêh ri ngih bok, nđâp ma ndơ ntă păng, bok nching mpông ngih bok nau tâm rƀŭn,$b$,true),
('bunong-vn','NUM',3,26,null,$b$bok nching tâm nhuang, bok nching mpông lăp ta nhuang jŭm ngih bok jêh ri ta nơng ƀư brah, nđâp ma rse ndrăn kât; lĕ kan dŏng di ma ndơ aơ.$b$,false),
('bunong-vn','NUM',3,27,null,$b$Tă bơh Y-Kôhat luh du mpôl Amram mpôl Ishar, mpôl Hêbron, jêh ri mpôl Usiel; phung aơ jêng mpôl Y-Kôhat.$b$,true),
('bunong-vn','NUM',3,28,null,$b$Tĭng nâm rnoh kơp lĕ rngôch phung bu klâu ntơm du khay bơi rlau, geh pham rbăn prao rhiăng nuyh pah kan tâm jrô kloh ueh.$b$,false),
('bunong-vn','NUM',3,29,null,$b$Lĕ mpôl phung kon sau Kôhat ƀư ntŭk rmlak pa pŭng ngih bok mpeh tâm rđŭng.$b$,true),
('bunong-vn','NUM',3,30,null,$b$Geh Y-Êlisapan, kon bu klâu Y-Usiel jêng kôranh ma noi deh Kôhat.$b$,true),
('bunong-vn','NUM',3,31,null,$b$Kan khân păng jâng kan mât uănh hip nau tâm rnglăp, sưng, jêng jrêng, lĕ rngôch nơng, ndơ dŏng ma jrô kloh ueh, ma ndơ nây phung kôranh ƀư brah pah kan, jêh ri bok nching, lĕ kan dŏng di ma ndơ aơ.$b$,false),
('bunong-vn','NUM',3,32,null,$b$Y-Êlêasar kon bu klâu kôranh ƀư brah Y-Arôn, jêng kôranh klơ lơn ma phung Lêvi, jêh ri geh kan chiă uănh phung geh kan tâm ntŭk kloh ueh.$b$,false),
('bunong-vn','NUM',3,33,null,$b$Tă bơh Y-Mêrari luh du mpôl Mahli jêh ri mpôl Musi. Aơ jêng phung mpôl băl Y-Mêrari.$b$,false),
('bunong-vn','NUM',3,34,null,$b$Rnoh kơp lĕ rngôch phung bu klâu khân păng ntơm du khay bơi rlau geh prao rbăn bar rhiăng nuyh.$b$,false),
('bunong-vn','NUM',3,35,null,$b$Kôranh ma noi deh phung mpôl Mêrari jêng Y-Suriel, kon bu klâu Y-Abihal; khân păng ƀư ntŭk rmbak papŭng ngih bok mpeh klơ dor.$b$,false),
('bunong-vn','NUM',3,36,null,$b$Kan jao ma phung kon bu klâu Y-Mêrari jêng kan mât uănh lĕ kađar ngih bok, mâng nđăng, meh, rnơl lĕ rngôch ndô ndơ jêh ri lĕ kan dŏng di ma ndơ aơ.$b$,true),
('bunong-vn','NUM',3,37,null,$b$Lĕ rngôch meh văr jŭm nhuang nđâp ma rnơl, mâng n'gâng jêh ri rse ndrăn kât n'gâng khân păng.$b$,true),
('bunong-vn','NUM',3,38,null,$b$Phung ƀư ntŭk rmlak pa năp ngih bok mpeh pa lơ jêng pa năp ngih bok nau tâm rƀŭn mpeh luh nar, geh Y-Môis, Y-Arôn jêh ri phung kon bu klâu păng, geh kan chiă uănh nau mbah yơk tâm jrô kloh ueh, ntrok an ma phung ƀon lan Israel.$b$,false),
('bunong-vn','NUM',3,39,null,$b$Lĕ rngôch phung Lêvi bu kơp jêh, phung Y-Môi jêh Y-Arôn kơp jêh tĭng nâm Yêhôva ntăm, tĭng nâm mpôl khân păng, lĕ rngôch bu klâu phung geh ntơm du khay bơi rlau, geh bar rmưn bar rbăn nuyh.$b$,false),
('bunong-vn','NUM',3,40,null,$b$Yor ri, Yêhôva lah ma Y-Môis, “Kơp hom lĕ rngôch phung kon bu klâu bôk rah tâm phung ƀon lan Israel ntơm phung geh du khay bơi rlau, phung Y-Môis jêh ri Y-Arôn kơp tĭng nâm amoh khân păng$b$,true),
('bunong-vn','NUM',3,41,null,$b$Ăn may sŏk phung Lêvi ăn ma gâp. Gâp jêng Yêhôva ntrok ma lĕ rngôch phung kon bu klâu bôk rah tâm phung ƀon lan Israel, jêh ri sŏk mpô mpa rong tă bơh phung Lêvi ntrok an ma lĕ rngôch mpô mpa rong deh kon dak bôk tă bơh phung ƀon lan Israel.”$b$,false),
('bunong-vn','NUM',3,42,null,$b$Pô ri Y-Môis kơp lĕ rngôch phung kon bôk rah tâm phung ƀon lan Israel, tĭng nâm Yêhôva ntĭnh ma păng.$b$,true),
('bunong-vn','NUM',3,43,null,$b$Lĕ rngôch phung kon bu klâu bôk rah tĭng nâm rnoh kơp amoh khân păng ntơm phung geh du khay bơi rlau bu kơp jêh geh bar rmưn bar rbăn bar rhiăng pơh jât ma pe nuyh.$b$,false),
('bunong-vn','NUM',3,44,null,$b$Yêhôva lah ma Y-Môis,$b$,true),
('bunong-vn','NUM',3,45,null,$b$“Sŏk hom phung Lêvi ntrok ma lĕ rngôch phung kon bôk rah tâm phung kon bôk rah tâm phung ƀon lan Israel, jêh ri ntrok an mpô mpa rong khân păng; jêh ri phung Lêvi mra jêng ndơ gâp. Gâp jêng Yêhôva.$b$,false),
('bunong-vn','NUM',3,46,null,$b$Bi ma nau tâm chuai phung bar rhiăng pơh jât ma pe nuyh phung kon bôk rah tâm phung ƀon lan Israel rmeh lơn ma phung Lêvi,$b$,false),
('bunong-vn','NUM',3,47,null,$b$ăn may sŏk prăm Sêkel ăp nơm tĭng nâm Sêkel tâm jrô kloh ueh, du sêkel jêng bar jât gêra. Ăn may sŏk ndơ nây,$b$,false),
('bunong-vn','NUM',3,48,null,$b$jêh ri ăn prăp ma Y-Arôn jêh ri ma phung kon bu klâu păng tă bơh rnoh tâm chuai phung rmeh lơn ma phung Lêvi,”$b$,false),
('bunong-vn','NUM',3,49,null,$b$Pô nây Y-Môis sŏk prăk tâm chuai bơh phung rmeh lơn ma phung Lêvi hŏ tâm chuai jêh.$b$,false),
('bunong-vn','NUM',3,50,null,$b$Păng sŏk prăk bơh phung kon bôk rah tâm phung ƀon lan Israel, du rbăn pe rhiăng prao jât ma prăm Sêkel, kơp tĭng nâm Sêkel tâm jrô kloh ueh.$b$,false),
('bunong-vn','NUM',3,51,null,$b$Jêh ri Y-Môis ăn prăk tâm chuai nây ma Y-Arôn jêh ri ma phung kon bu klâu păng, tĭng nâm nau Yêhôva ntĭnh jêh ma Y-Môis.$b$,true),
('bunong-vn','NUM',4,1,null,$b$Pô nây, Yêhôva lah ma Y-Môis jêh ri Y-Arôn,$b$,true),
('bunong-vn','NUM',4,2,null,$b$“Kơp hom phung kon bu klâu Y-Kôhat tâm phung kon bu klâu Lêvi tĭng nâm mpôl khân păng, tĭng nâm noi deh khân păng,$b$,false),
('bunong-vn','NUM',4,3,null,$b$ntơm phung geh pe jât năm tât ma prăm jât năm, lĕ rngôch phung dơi lăp tâm kan prăp ƀư kan tâm ngih bok nau tâm rƀŭn.$b$,false),
('bunong-vn','NUM',4,4,null,$b$Aơ jêng kan phung kon bu klâu Y-Kôhat tâm ngih bok nau tâm rƀŭn: Ndơ kloh ueh lơn.$b$,false),
('bunong-vn','NUM',4,5,null,$b$Tơ lah phung ƀon lan du trơn ntŭk, Y-Arôn jêh ri phung kon bu klâu păng mra lăp rơih lơi bok nching jêh ri nkŭm hip nau tâm rnglăp ma ndơ nây.$b$,false),
('bunong-vn','NUM',4,6,null,$b$Jêh ri khân păng nkŭm klơ hip ma du blah ndơ nkŭm ƀư ma ntâu ka toyh, jêh ri ling ta klơ ndơ nây du blah bok rvanh ĭr, jêh ri nsro mâng rnung tung ta păng.$b$,true),
('bunong-vn','NUM',4,7,null,$b$Khân păng ling đŏng du blah bok ĭr ta klơ sưng piăng let nhhơr ma Brah Ndu, jêh ri klơ sưng bu krĭp thaih, ngan ndơ ƀâu kah, ngan rlŭ, jêh ri kachok prăp ndơ nhhơr nhêt; piăng let bu ăn mro ta klơ nây đŏng.$b$,false),
('bunong-vn','NUM',4,8,null,$b$Jêh nây khân păng mra ling bok chăng ta klơ ndơ nây, nkŭm ndơ nây ma ndơ nkŭm bu ƀư ma ntâu ka toyh, jêh ri nsro mâng rnung tung.$b$,false),
('bunong-vn','NUM',4,9,null,$b$Khân păng sŏk đŏng du blah bok rvanh ĭr gay nkŭm jâng jrêng dôl hit, ndrel ma ŭch kađen, ndơ nhhât, ngŏ dơ buh, jêh ri lĕ rngôch yăng dak Ôlivơ bu prăp ma jâng jrêng.$b$,true),
('bunong-vn','NUM',4,10,null,$b$Khân păng mra dơm lĕ rngôch ndơ dŏng ma păng tâm ndơ nkŭm ƀư ma ntâu ka toyh, jêh ri dơm klơ nâr.$b$,false),
('bunong-vn','NUM',4,11,null,$b$Khân păng mra ling bok ĭr ta klơ nơng mah, jêh ri nkŭm ma ndơ bu ƀư đah ntâu ka toyh, jêh ri nsro mâng rnung tung.$b$,false),
('bunong-vn','NUM',4,12,null,$b$Geh đŏng, khân păng mra sŏk lĕ rngôch ndơ dŏng prăp ma kan dŏng tâm jrô kloh ueh, jêh ri dơm khân păng tâm bok ĭr, jêh nây nkŭm ma ndơ nkŭm bu ƀư ma ntâu ka toyh, jêh ri dơm ta klơ nâr.$b$,false),
('bunong-vn','NUM',4,13,null,$b$Khân păng mra kuak lơi ŭnh buh ta klơ nơng, jêh ri lăk bok chăng ta klơ nơng;$b$,false),
('bunong-vn','NUM',4,14,null,$b$jêh nây khân păng mra dơm ta klơ ndơ nây lĕ rngôch ndơ dŏng ma nơng prăp dŏng ma kan ta nây, ŭnh năk, n'hoi srang, ndroh, ngan grưng, lĕ rngôch ndơ dŏng ma nơng; jêh ri khân păng mra ling ta klơ ndơ nây nkŭm ma ndơ bu ƀư ma ntâu ka toyh, jêh ri nso mâng rnung tung.$b$,false),
('bunong-vn','NUM',4,15,null,$b$Tơ lah jêh Y-Arôn jêh ri phung kon bu klâu păng nkŭm jrô kloh ueh jêh ri lĕ rngôch ndô ndơ dŏng ma jrô kloh ueh lôch jêh, dôl phung ƀon lan dâk hăn trơn du, phung kon bu klâu Y-Kôhat văch tung ndơ aơ, ƀiă lah khân păng mâu dơi pah ôh ndơ kloh ueh, klach lah khĭt khân păng. Nây jêng ndơ tâm ngih tâm rƀŭn ma phung kon bu klâu Y-Kôhat mra tung.$b$,true),
('bunong-vn','NUM',4,16,null,$b$“Y-Êlêasar, kon bu klâu kôranh ƀư brah Y-Arôn, mra pah kan mât uănh dak Ôlivơ mpoh ŭnh, ndơ ƀâu kah, ndơ nhhơr rnih muy mro mrăng, jêh ri dak ƀâu kah prăp tŏ, nđâp ma kan mât uănh lĕ ngih bok jêh ri lĕ rngôch ndô ndơ tâm păng, jrô kloh ueh jêh ri ndơ dŏng ma păng.”$b$,false),
('bunong-vn','NUM',4,17,null,$b$Yêhôva lah ma Y-Môis jêh ri Y-Arôn,$b$,false),
('bunong-vn','NUM',4,18,null,$b$“Lơi ăn ôh mpôl phung Kôhat roh rai tă bơh ta nklang phung Lêvi;$b$,false),
('bunong-vn','NUM',4,19,null,$b$ƀiă lah ƀư pô aơ ma khân păng gay ma khân păng gŭ rêh jêh ri mâu geh khĭt ôh tơ lah khân păng hăn dăch ndơ kloh ueh ngăn, Y-Arôn jêh ri phung kon bu klâu păng mra lăp jêh ri ntĭm kan ma ăp nơm khân păng,$b$,false),
('bunong-vn','NUM',4,20,null,$b$ƀiă lah khân păng mâu dơi uănh ôh ndơ kloh ueh, nđâp lah ƀât lât kđôi lĕ, klach lah khĭt khân păng.”$b$,false),
('bunong-vn','NUM',4,21,null,$b$Yêhôva lah ma Y-Môis,$b$,false),
('bunong-vn','NUM',4,22,null,$b$“Kơp phung kon bu klâu Y-Gersôn đŏng, tĭng nâm mpôl jêh ri noi deh khân păng;$b$,false),
('bunong-vn','NUM',4,23,null,$b$ntơm pe jât năm bơi rlau tât ma prăm jât, may mra kơp khân păng, lĕ rngôch phung dơi lăp kan, prăp pah kan tâm ngih bok tâm rƀŭn.$b$,false),
('bunong-vn','NUM',4,24,null,$b$Aơ jêng kan phung mpôl Gersôn mra pah jêh ri ndơ khân păng mra tung;$b$,false),
('bunong-vn','NUM',4,25,null,$b$Khân păng mra tung bok nching ngih bok, jêh ri ngih bok tâm rƀŭn, nđâp ma ndơ nkŭm păng, jêh nây ndơ nkŭm bu ƀư ma ntâu ka toyh ta klơ păng, jêh ri bok nchăng mpông ngih bok tâm rƀŭn,$b$,false),
('bunong-vn','NUM',4,26,null,$b$bok nching tâm nhuang, jêh ri bok ta mpông lăp nhuang jŭm ngih bok jêh ri nơng ƀư brah, rse kât khân păng, jêh ri lĕ rngôch ndơ prăp dŏng ma păng; jêh nây khân păng mra ƀư lĕ rngôch kan di ma ndơ nây.$b$,false),
('bunong-vn','NUM',4,27,null,$b$Lĕ rngôch kan phung kon bu klâu Y-Gersôn mra ƀư tĭng nâm nau Y-Arôn jêh ri phung kon bu klâu păng ntĭnh, ma lĕ ntil ndơ khân păng mra tung, jêh ri lĕ ntil kan khân păng mra pah; ăn may jao ma khân păng mât uănh lĕ rngôch ndơ khân păng mra tung.$b$,false),
('bunong-vn','NUM',4,28,null,$b$Nây jêng kan ma phung mpôl kon bu klâu Y-Gersôn tâm ngih bok tâm rƀŭn, jêh ri khân păng mra pah kan tĭng nâm Y-Itham kon bu klâu kôranh ƀư brah Y-Arôn uănh.$b$,false),
('bunong-vn','NUM',4,29,null,$b$“Ăn may kơp phung kon bu klâu Y-Mêrari tĭng nâm mpôl khân păng jêh ri noi deh khân păng.$b$,false),
('bunong-vn','NUM',4,30,null,$b$May mra kơp khân păng ntơm phung geh pe jât năm tât ma prăm jât, lĕ rngôch phung dơi lăp kan, gay pah kan tâm ngih bok nau rƀŭn.$b$,true),
('bunong-vn','NUM',4,31,null,$b$Aơ kan bu jao khân păng pah tâm ngih bok tâm rƀŭn, jêng ndơ khân păng mât uănh jêh ri tung: Lĕ rngôch kađar ngih bok, njon rkăng, meh, jêh ri trôm nsro meh,$b$,false),
('bunong-vn','NUM',4,32,null,$b$lĕ meh jŭm nhuang jêh ri trôm nsro meh, chor, rse kât, lĕ rngôch ndô ndơ jêh ri lĕ ndơ dŏng tâm di prăp ma khân păng; ăn may mbơh ăp săk moh ndơ khân păng mât uănh jêh ri tung.$b$,false),
('bunong-vn','NUM',4,33,null,$b$Nây jêng kan ma phung mpôl kon bu klâu Y-Mêrari, lĕ rngôch kan khân păng ƀư tâm ngih bok nau rƀŭn, tĭng nâm nau đă bơh Y-Ithamar, kon bu klâu kôranh ƀư brah Y-Arôn.”$b$,false),
('bunong-vn','NUM',4,34,null,$b$Pô nây, Y-Arôn jêh ri phung kôranh phung ƀon lan kơp rƀŭn lĕ phung kon bu klâu Y-Kôhat, tĭng nâm mpôl jêh ri noi deh khân păng,$b$,true),
('bunong-vn','NUM',4,35,null,$b$ntơm pe jât năm bơi rlau tât ma prăm jât, lĕ rngôch dơi lăp kan, prăp pah kan tâm ngih bok tâm rƀŭn.$b$,false),
('bunong-vn','NUM',4,36,null,$b$Rnoh kơp tĭng nâm mpôl khân păng geh bar rbăn pơh rhiăng prăm jât nuyh.$b$,false),
('bunong-vn','NUM',4,37,null,$b$Dah nây rnoh kơp phung mpôl Kôhat, lĕ rngôch phung pah kan tâm ngih bok nau rƀŭn, phung Y-Môis jêh ri Y-Arôn kơp tĭng nâm nau Yêhôva hŏ mbơh jêh ma Y-Môis.$b$,false),
('bunong-vn','NUM',4,38,null,$b$Rnoh kơp phung mpôl kon bu klâu Y-Gersôn, tĭng nâm mpôl jêh ri noi deh khân păng,$b$,false),
('bunong-vn','NUM',4,39,null,$b$ntơm pe jât năm bơi rlau tât ma prăm jât, lĕ rngôch phung dơi lăp kan prăp pah kan tâm ngih bok tâm rƀŭn$b$,false),
('bunong-vn','NUM',4,40,null,$b$rnoh kơp tĭng nâm mpôl khân păng, tĭng nâm noi deh khân păng geh bar rbăn prao rhiăng pe jât nuyh.$b$,false),
('bunong-vn','NUM',4,41,null,$b$Dah nây rnoh kơp phung mpôl kon bu klâu Y-Ger sôn, lĕ rngôch phung pah kan tâm ngih bok tâm rƀŭn, phung Y-Môis jêh ri Y-Arôn hŏ kơp jêh tĭng nâm nau Yêhôva ntĭnh.$b$,true),
('bunong-vn','NUM',4,42,null,$b$Rnoh kơp phung mpôl kon bu klâu Y-Mêrari tĭng nâm mpôl, tĭng nâm noi deh khân păng,$b$,false),
('bunong-vn','NUM',4,43,null,$b$ntơm pe jât năm tât ma prăm jât, lĕ rngôch dơi lăp kan, prăp pah kan tâm ngih bok tâm rƀŭn$b$,false),
('bunong-vn','NUM',4,44,null,$b$rnoh kơp tĭng nâm phung mpôl khân păng geh pe rbăn bar rhiăng nuyh.$b$,false),
('bunong-vn','NUM',4,45,null,$b$Dah nây rnoh kơp mpôl phung kon bu klâu Y-Mêrari, phung Y-Môis jêh ri Y-Arôn hŏ kơp jêh tĭng nâm nau Yêhôva ntĭnh ma Y-Môis.$b$,false),
('bunong-vn','NUM',4,46,null,$b$Lĕ rngôch phung Lêvi bu hŏ kơp jêh, phung Y-Môis, Y-Arôn, jêh ri phung kôranh Israel kơp jêh, tĭng nâm mpôl khân păng jêh ri tĭng nâm noi deh khân păng,$b$,false),
('bunong-vn','NUM',4,47,null,$b$ntơm pe jât năm bơi rlau tât ma prăm jât năm, lĕ rngôch dơi lăp kan prăp pah kan jêh ri tung ndô ndơ tâm ngih bok tâm rƀŭn,$b$,false),
('bunong-vn','NUM',4,48,null,$b$phung khân păng hŏ kơp jêh geh pham rbăn prăm rhiăng pham jât nuyh.$b$,false),
('bunong-vn','NUM',4,49,null,$b$Tĭng nâm nau Yêhôva ntĭnh ma Y-Môis, bu dơm khân păng, ăp nơm ma kan khân păng nơm prăp dŏng jêh ri tung ndô ndơ; pô nây bu hŏ kơp jêh khân păng tĭng nâm nau Yêhôva ntĭnh jêh ma Y-Môis.$b$,false),
('bunong-vn','NUM',5,1,null,$b$Yêhôva lah ma Y-Môis,$b$,true),
('bunong-vn','NUM',5,2,null,$b$“Ntĭnh hom ma phung ƀon lan Israel ăn mprơh lơi lĕ rngôch phung geh phŭng, bunuyh geh nau ji luh, jêh ri lĕ nau ƀơ̆ yor brot du huê bunuyh lĕ khĭt.$b$,false),
('bunong-vn','NUM',5,3,null,$b$Ăn khân may mprơh lơi phung bu klâu nđâp bu ur, mprơh khân păng pa dih mpâr pô nây mơ khân păng mâu mra ƀư ƀơ̆ ôh nhuang ntŭk khân păng, ta nklang ntŭk nây gâp gŭ.”$b$,false),
('bunong-vn','NUM',5,4,null,$b$Phung ƀon lan Israel ƀư pô nây tĭng nâm nau Yêhôva lah jêh ma Y-Môis.$b$,false),
('bunong-vn','NUM',5,5,null,$b$Yêhôva lah ma Y-Môis,$b$,true),
('bunong-vn','NUM',5,6,null,$b$“Lah hom ma phung ƀon lan Israel: Tơ lah du huê bu klâu mâu lah bu ur ƀư du ntil nau tih bunuyh vay ƀư, mâu gŭ răp jăp ôh đah Yêhôva jêh ri yor nau nây bunuyh nây jêng tih jêh,$b$,false),
('bunong-vn','NUM',5,7,null,$b$ăn păng mbơh nau tih păng hŏ ƀư; jêh ri păng mra mplơ̆ ăn nŭm yor nau tih păng, ntop tay ma ndơ nây du kô̆ tâm prăm jêh ri jao ndơ nây ma bunuyh păng hŏ geh nau tih.$b$,false),
('bunong-vn','NUM',5,8,null,$b$Ƀiă lah tơ lah bunuyh nây mâu hôm, jêh ri mâu geh mpôl băl dăch gay dơn ndơ nây, pô ri ndơ nây mra nsĭt ma Yêhôva ăn ma kôranh ƀư brah, ntop đŏng pa dih biăp nkuăng ma nau ƀư kloh nau tih, ma biăp nây kôranh ƀư brah mra ƀư gay dŏng tâm chuai nau tih ăn bunuyh geh nau tih nây.$b$,false),
('bunong-vn','NUM',5,9,null,$b$Moh ntil ndơ nhhơr, ndơ kloh ueh tă bơh phung ƀon lan Israel, ndơ khân păng leo ma kôranh ƀư brah mra jêng ndơ păng;$b$,true),
('bunong-vn','NUM',5,10,null,$b$jêh ri lĕ rngôch ndơ nhhơr kloh ueh lĕ bunuyh nhhơr ăn jêh ma kôranh ƀư brah mra jêng ndơ păng nây đŏng.”$b$,false),
('bunong-vn','NUM',5,11,null,$b$Yêhôva lah đŏng ma Y-Môis,$b$,true),
('bunong-vn','NUM',5,12,null,$b$“Lah hom ma phung ƀon lan Israel: Tơ lah du huê bu ur tih đah nau nti jêh ri ƀư tih lâm rlau sai păng,$b$,false),
('bunong-vn','NUM',5,13,null,$b$tơ lah du huê bu klâu bêch ƀư tih đah păng, nau nây ndâp măt sai păng, jêh ri nau nây mâu mpơl ôh, nđâp tơ lah păng ƀư ƀơ̆ păng nơm, jêh ri mâu geh ôh nơm mbơh nau păng ƀư, yor lah bu mâu geh nhŭp ôh păng dôl păng ƀư;$b$,false),
('bunong-vn','NUM',5,14,null,$b$jêh ri nau mĭn ntôn tât ma păng jêh ri păng ntôn ma ur păng nơm lĕ ƀư ƀơ̆ jêh păng nơm, jêh ri păng ntôn ur păng, ƀiă lah păng mâu mâp ƀư ƀơ̆ ôh păng nơm;$b$,false),
('bunong-vn','NUM',5,15,null,$b$nôk nây bu klâu nây njŭn ur păng ma kôranh ƀư brah, jêh ri djôt leo ndơ nhhơr yor ur păng tĭng nâm nau vay, du kô̆ tâm jât êpha rnih muy ba orgơ; păng mâu mra kêt ôh dak play ôlivơ jêh ri ndơ ƀâu kah ta klơ ndơ nây, yor lah ndơ nây jêng ndơ nhhơr rnih muy ma nau tâm ntôn, ndơ nhhơr rnih muy ma nau kah gĭt, gay kah gĭt ma nau kue.$b$,false),
('bunong-vn','NUM',5,16,null,$b$Kôranh ƀư brah mra ăn bu ur nây hăn dăch ma ngih bok jêh ri ăn păng gŭ ta năp Yêhôva.$b$,false),
('bunong-vn','NUM',5,17,null,$b$Kôranh ƀư brah mra sŏk dak kloh ueh troch tâm yăng neh, kuak ndruyh neh tă tâm gre ngih bok jêh ri ăn păng tâm dak.$b$,true),
('bunong-vn','NUM',5,18,null,$b$Kôranh ƀư brah mra ăn bu ur gŭ ta năp Yêhôva, rơih lơi sŏk ta klơ bôk bu ur, jêh ri ăn ndơ kah gĭt ta klŏ ti bu ur jêng ndơ nhhơr rnih muy ma nau tâm ntôn; jêh ri kôranh ƀư brah djôt dak tăng tâm ti păng gay ăn tât nau rak rtăp.$b$,true),
('bunong-vn','NUM',5,19,null,$b$Kôranh ƀư brah ăn bu ur nây ton sơm jêh ri lah ma păng: ‘Tơ lah ay mâu mâp geh ôh du huê bu klâu lĕ tă bêch ndrel ay, jêh ri dôl gŭ tâm dâng nau dơi sai ay mâu geh tih đah nau nti jêh ri mâu geh nau ƀơ̆ ôh, ay mra jêng kon me ma dak nau tăng aơ ăn tât nau rah rtăp.$b$,false),
('bunong-vn','NUM',5,20,null,$b$Bi tơ lah ay dôl gŭ tâm dâng nau dơi sai ay tih đah nau nti; tơ lah ay geh nau ƀơ̆ , jêh ri geh du huê bu klâu êng ay rlau sai hŏ bêch jêh ndrel ay$b$,true),
('bunong-vn','NUM',5,21,null,$b$nôk nây kôranh ƀư brah ăn bu ur ton sơm ma nau rak rtăp, jêh ri lah ma bu ur: ‘Dăn Yêhôva ăn ma ay jêng du ntil ndơ rak rtăp, jêh ri ndơ bu suai rak ta nklang phung ƀon lan ay, ƀư ăn ay glet nglu jêng ji pŭk ji môr săk jăn;$b$,false),
('bunong-vn','NUM',5,22,null,$b$dăk tăng ăn nau rak rtăp aơ lăp tâm proch klơm ay jêng ji pŭk ji môr jêh ri glet nglu. Jêh ri bu ur nây mra lah, ‘Amen, Amen!’$b$,false),
('bunong-vn','NUM',5,23,null,$b$“Jêh nây, kôranh ƀư brah mra chih nau rak rtăp aơ tâm du ndrom săm ƀŭt, jêh ri păng mhĭng ma dak tăng.$b$,false),
('bunong-vn','NUM',5,24,null,$b$Kôranh ƀư brah mra ăn bu ur nây nhêt dak tăng ăn tât nau rak rtăp, dak tăng ăn tât nau rak rtăp lăp tâm săk bu ur ăn geh nau ji glăm ngăn ma păng.$b$,false),
('bunong-vn','NUM',5,25,null,$b$Pô nây, kôranh ƀư brah mra sŏk tă bơh ti bu ur nây ndơ nhhơr rnih muy ma nau tâm ntôn jêh ri ryeng ndơ nhhơr rnih muy ta năp Yêhôva jêh ri leo klơ nơng.$b$,false),
('bunong-vn','NUM',5,26,null,$b$Jêh nây sŏk du mbăt rnih muy ăn kah gĭt jêh ri su klơ nơng; jêh nau nây păng mra ăn bu ur nhêt dak tăng.$b$,true),
('bunong-vn','NUM',5,27,null,$b$Tơ lah kôranh ƀư brah lĕ ăn jêh bu ur nhêt dak tăng, tơ lah bu ur nây ƀư ƀơ̆ jêh păng nơm jêh ri mâu gŭ ngao n'hêl nanê̆ ôh đah sai păng, pô ri dak tăng ăn tât nau rak rtăp mra lăp tâm săk păng geh nau ji glăm ngăn; jêng ji pŭk ji môr jêh ri glet nglu, bu ur nây jêng ndơ rak rtăp ta nklang phung ƀon lan păng.$b$,false),
('bunong-vn','NUM',5,28,null,$b$Bi tơ lah bu ur nây mâu geh ƀư ƀơ̆ ôh păng, ăt jêng kloh rsang, pô ri păng mâu geh du ntil nau djơh êng ôh jêh ri păng mra deh ma phung kon.$b$,false),
('bunong-vn','NUM',5,29,null,$b$“Nây nau vay tơ lah geh nau tâm ntôn, tơ lah du huê ur bu, gŭ tâm dâng nau dơi sai păng, tih đah nau nti jêh ri ƀư ƀơ̆ păng nơm;$b$,false),
('bunong-vn','NUM',5,30,null,$b$mâu lah tơ lah nau mĭn tâm ntôn tât ma du huê bu klâu jêh ri păng ntôn ur păng; păng mra ăn bu ur nây gŭ ta năp Yêhôva, jêh ri kôranh ƀư brah mra ƀư ma bu ur tĭng nâm lĕ nau vay nây.$b$,false),
('bunong-vn','NUM',5,31,null,$b$Pô ri sai păng mâu mra tih ôh, ƀiă lah bu ur nây mra anh nau kue păng.”$b$,true),
('bunong-vn','NUM',6,1,null,$b$Yêhôva lah ma Y-Môis,$b$,true),
('bunong-vn','NUM',6,2,null,$b$“Lah hom ma phung ƀon lan Israel, Tơ lah du huê bu klâu mâu lah bu ur, tơ lah ƀư nau ton du huê Nasirit, gay prăp ăn păng nơm ma Yêhôva,$b$,false),
('bunong-vn','NUM',6,3,null,$b$păng mra ver ndrănh jêh ri ndơ nhêt nhŭl; păng mâu dơi nhêt ôh ndrănh mâu lah piăng bih ndrănh, mâu lah piăng bih ndơ nhêt nhŭl; tâm ban đŏng mâu dơi nhêt ôh dak bu ƀư ma dak play kriăk ƀâu, mâu lah sa play kriăk ƀâu mhe mâu lah lĕ kro jêh.$b$,false),
('bunong-vn','NUM',6,4,null,$b$Lĕ nar dôl păng prăp ăn păng nơm, păng mâu dơi sa ôh moh ndơ luh tă bơh tơm play kriăk ƀâu, nđâp ma găr ntil mâu lah ntâu.$b$,false),
('bunong-vn','NUM',6,5,null,$b$“Lĕ rngôch nar dôl păng ton ma nau prăp ăn păng nơm, păng mâu dơi poih ôh sŏk păng; kŏ tât lĕ nar prăp ăn ma Yêhôva, păng mra jêng kloh ueh; păng rong sŏk jong.”$b$,false),
('bunong-vn','NUM',6,6,null,$b$“Dôl lĕ rngôch nar prăp ăn păng nơm ma Yêhôva păng mâu dơi hăn dăch ôh bunuyh khĭt.$b$,false),
('bunong-vn','NUM',6,7,null,$b$Păng mâu dơi ƀư ƀơ̆ păng nơm yor mbơ̆ păng, mê̆ păng, oh nâu păng, mâu lah oh nur păng, tơ lah khân ô băl khĭt; yor lah nau păng prăp ăn păng nơm ma Yêhôva gŭ klơ bôk păng.$b$,true),
('bunong-vn','NUM',6,8,null,$b$Dôl lĕ rngôch nar nau prăp ăn păng nơm, păng jêng kloh ueh ma Yêhôva.$b$,false),
('bunong-vn','NUM',6,9,null,$b$“Tơ lah du huê khĭt ndal êp kêng păng, ƀư ăn ƀơ̆ jêh bôk păng hŏ prăp jêh ăn kloh, pô ri păng mra poih lơi sŏk păng ta nar nau ƀư kloh păng. Păng mra poih păng ta nar năng pơh.$b$,false),
('bunong-vn','NUM',6,10,null,$b$Ta nar năng pham păng mra djôt leo ma kôranh ƀư brah bar mlâm plŭk mâu lah bar mlâm kon ntơp ta mpông ngih bok tâm rƀŭn.$b$,false),
('bunong-vn','NUM',6,11,null,$b$Kôranh ƀư brah mra nhhơr du mlâm jêng ndơ nhhơr chuai nau tih, jêh ri du mlâm êng jêng ndơ nhhơr gŭch, jêh ri ƀư ăn kloh nau tih păng, yor lah păng hŏ ƀư tih yor săk jăn khĭt. Jêh ri tâm nar nây păng mra prăp ăn kloh bôk păng đŏng.$b$,false),
('bunong-vn','NUM',6,12,null,$b$Pô nây, păng prăp ăn păng nơm ma Yêhôva tĭng nâm ndah nar nau prăp ăn păng nơm tay, jêh ri nhhơr du mlâm biăp kon nkuăng du năm deh jêng ndơ nhhơr chuai ma nau rlau nau vay, jêh ri lĕ rngôch nar păng prăp ăn păng nơm ntơm sa ơm mâu kơp ôh, yor lah nau păng prăp ăn păng nơm jêng ƀơ̆ jêh.$b$,false),
('bunong-vn','NUM',6,13,null,$b$“Aơ nau vay ma bunuyh Nasirit; tơ lah lĕ lôch jêh nar ma nau prăp ăn păng nơm: Bu mra njŭn leo păng ma mpông ngih bok tâm rƀŭn,$b$,false),
('bunong-vn','NUM',6,14,null,$b$jêh ri păng nhhơr ndơ păng ăn ma Yêhôva, du mlâm biăp kon nkuăng du năm deh mâu geh sôt ôh, jêng ndơ nhhơr gŭch, jêh ri du mlâm biăp kon me du năm deh mâu geh sôt ôh, jêng ndơ nhhơr chuai nau tih, jêh ri du mlâm biăp nkuăng mâu geh sôt jêng ndơ nhhơr ma nau đăp mpăn,$b$,false),
('bunong-vn','NUM',6,15,null,$b$jêh ri du bĭ piăng let mâu geh ndrui, ƀănh ƀư ma rnih muy tâm pot đah dak play ôlivơ, ndrel ma ndơ nhhơr rnih muy nđâp ndơ nhhơr nhêt.$b$,false),
('bunong-vn','NUM',6,16,null,$b$Kôranh ƀư brah mra leo lĕ ndơ nây ta năp Yêhôva, jêh ri nhhơr ndơ nhhơr chuai nau tih jêh ri ndơ păng nhhơr gŭch;$b$,false),
('bunong-vn','NUM',6,17,null,$b$păng mra nhhơr ma Yêhôva biăp nkuăng jêng ndơ nhhơr nau đăp mpăn, ndrel ma bĭ piăng let mâu geh ndrui; kôranh ƀư brah mra nhhơr ndrel đŏng ndơ nhhơr rnih muy jêh ri ndơ nhhơr nhêt.$b$,false),
('bunong-vn','NUM',6,18,null,$b$Bunuyh Nasirit mra poih bôk păng prăp ăn jêh ma Yêhôva ta mpông ngih bok tâm rƀŭn; păng mra sŏk, sŏk bơh bôk păng prăp ăn jêh ma Yêhôva, jêh ri ăn tâm ŭnh gŭ tâm dâng ndơ ƀư brah nhhơr ma nau đăp mpăn.$b$,true),
('bunong-vn','NUM',6,19,null,$b$Kôranh ƀư brah mra sŏk nglik biăp nkuăng lĕ gâm sĭn jêh, jêh ri du glo ƀănh mâu geh ndrui tă tâm bĭ, jêh nây du rlat ƀănh n'hơ mâu geh ndrui jêh ri dơm ndơ nây ta ti bunuyh Nasirit lĕ jêh păng poih jêh sŏk prăp ăn păng nơm.$b$,false),
('bunong-vn','NUM',6,20,null,$b$Kôranh ƀư brah ryeng ndơ nây jêng du ndơ kloh ta năp Yêhôva: Nây jêng du ndơ kloh prăp ma kôranh ƀư brah, ndrel ma ntang ntơh ryeng jêh, jêh ri nglik nhhơr jêh, jêh ta nây bunuyh Nasirit dơi nhêt ndrănh dak kriăk ƀâu.$b$,false),
('bunong-vn','NUM',6,21,null,$b$“Nây jêng nau vay ma bunuyh Nasirit hŏ ƀư jêh nau ton, jêh ri aơ jêng ndơ păng mra nhhơr ăn ma Yêhôva mra jêng tĭng nâm păng ton dôl jêng bunuyh Nasirit, rmeh ma ndơ êng păng dơi geh. Tĭng nâm nau păng ton jêh, pô nây păng mra ƀư tĭng nâm nau vay ma nau prăp ăn păng jêng du huê bunuyh Nasirit.”$b$,false),
('bunong-vn','NUM',6,22,null,$b$Yêhôva lah ma Y-Môis:$b$,true),
('bunong-vn','NUM',6,23,null,$b$“Lah hom ma Y-Arôn jêh ri phung kon bu klâu păng: Pô aơ nau khân păng mra mât ton ma phung ƀon lan Israel; khân may mra lah ma khân păng:$b$,false),
('bunong-vn','NUM',6,24,null,$b$Dăn hom ma Yêhôva ăn nau ueh lăng ma may jêh ri mât king may;$b$,false),
('bunong-vn','NUM',6,25,null,$b$dăn ma Yêhôva nchrat ang muh măt Păng ma may, jêh ri yô̆ an ma may.$b$,false),
('bunong-vn','NUM',6,26,null,$b$Dăn ma Yêhôva mêt uănh an may, jêh ri ăn nau đăp mpăn ma may.$b$,true),
('bunong-vn','NUM',6,27,null,$b$Tâm ban đŏng khân păng mra dơm amoh gâp ta klơ phung ƀon lan Israel, jêh ri gâp mra ăn nau ueh lăng ma khân păng.$b$,true),
('bunong-vn','NUM',7,1,null,$b$Tơ lah Y-Môis hŏ ndâk jêh ngih bok, tŏ jêh dak ƀâu kah jêh ri prăp ăn păng ndrel lĕ rngôch ndơ dŏng ma păng, tŏ jêh dak ƀâu kah jêh ri prăp ăn nơng ndrel ma lĕ rngôch ndơ dŏng ma păng,$b$,true),
('bunong-vn','NUM',7,2,null,$b$phung kôranh Israel, phung kôranh ma ndŭl mpôl khân păng, phung kôranh ma phung mpôl chiă uănh kơp jêh,$b$,false),
('bunong-vn','NUM',7,3,null,$b$nhhơr jêh ri njŭn ndơ khân păng nhhơr ta năp Yêhôva, prao bôk ndeh geh ndơ nkŭm jêh ri jât ma bar mlâm ndrôk, du bôk ndeh ma bar hê kôranh, jêh ri du mlâm ndrôk nkuăng ma ăp nơm kôranh; khân păng nhhơr ndơ nây pa năp ngih bok.$b$,false),
('bunong-vn','NUM',7,4,null,$b$Nôk nây Yêhôva lah ma Y-Môis,$b$,true),
('bunong-vn','NUM',7,5,null,$b$“Dơn hom ndơ aơ tă bơh khân păng prăp dŏng tâm kan ngih bok tâm rƀŭn, jêh ri jao ăn ma phung Lêvi, ma ăp nơm tĭng nâm kan păng.”$b$,false),
('bunong-vn','NUM',7,6,null,$b$Pô nây, Y-Môis sŏk ndeh jêh ri ndrôk nkuăng, jao ma phung Lêvi.$b$,true),
('bunong-vn','NUM',7,7,null,$b$Păng ăn bar bôk ndeh jêh ri puăn mlâm ndrôk nkuăng ma phung kon sau Y-Gersôn tĭng nâm kan khân păng.$b$,false),
('bunong-vn','NUM',7,8,null,$b$Păng ăn puăn bôk ndeh jêh ri pham mlâm ndrôk nkuăng ma phung kon sau Y-Mêrari, tĭng nâm kan khân păng, tâm dâng nau Y-Ithamar kon bu klâu kôranh ƀư brah Y-Arôn chiă uănh.$b$,false),
('bunong-vn','NUM',7,9,null,$b$Ƀiă lah păng mâu ăn ôh ma phung kon sau Y-Kôhat, yor lah bu jao ma khân păng mât uănh ndơ kloh ueh bu tung ta klơ săng nglik.$b$,false),
('bunong-vn','NUM',7,10,null,$b$Phung kôranh nhhơr ndơ nhhơr ma nau prăp ăn nơng ta nar bu tŏ păng ma dak ƀâu kah; jêh ri phung kôranh nhhơr ndơ khân păng nhhơr pa năp nơng.$b$,true),
('bunong-vn','NUM',7,11,null,$b$Yêhôva lah ma Y-Môis, “Khân păng mra nhhơr ndơ khân păng nhhơr prăp ăn ma nơng, nar aơ nơm aơ, nơm êng nar êng.”$b$,false),
('bunong-vn','NUM',7,12,null,$b$Nơm nhhơr ndơ păng nhhơr nar ntơm sa ơm jêng Y-Nahsôn kon bu klâu Y-Aminadap bơh ndŭl mpôl Yuđa,$b$,true),
('bunong-vn','NUM',7,13,null,$b$jêh ri ndơ păng nhhơr jêng du mlâm ngan pala prăk njing jâk du rhiăng pe jât Sêkel, du mlâm ngan grưng njing jâk pơh jât sêkel tĭng nâm sêkel tâm jrô kloh ueh, lĕ bar ndơ nây bêng ma rnih muy tâm pot đah dak play ôlivơ, jêng ndơ nhhơr rnih muy;$b$,false),
('bunong-vn','NUM',7,14,null,$b$du mlâm ngan mah jâk jât sêkel, bêng ma ndơ ƀâu kah;$b$,false),
('bunong-vn','NUM',7,15,null,$b$du mlâm ndrôk nkuăng rah, du mlâm biăp nkuăng, du mlâm biăp kon nkuăng du năm deh, jêng ndơ nhhơr gŭch;$b$,false),
('bunong-vn','NUM',7,16,null,$b$du mlâm be nkuăng jêng ndơ nhhơr chuai yor nau tih;$b$,false),
('bunong-vn','NUM',7,17,null,$b$jêh ri ma nau ƀư brah nhhơr ndơ ma nau đăp mpăn, bar mlâm ndrôk nkuăng, prăm mlâm biăp nkuăng, prăm mlâm be nkuăng jêh ri prăm mlâm biăp kon du năm deh. Nây jêng ndơ Y-Nahsôn, kon bu klâu Y-Aminadap nhhơr.$b$,false),
('bunong-vn','NUM',7,18,null,$b$Nar rơh bar, Y-Nêthanel kon bu klâu Y-Suar, kôranh ma ndŭl mpôl phung Isakar, nhhơr ndơ.$b$,true),
('bunong-vn','NUM',7,19,null,$b$Ndơ păng nhhơr jêng du mlâm ngan pala prăk njing jâk păng du rhiăng pe jât sêkel, du mlâm ngan grưng prăk njing jâk păng pơh jât Sêkel tĭng nâm sêkel tâm jrô kloh ueh, lĕ bar ndơ nây bêng ma rnih muy tâm pot dak play ôlivơ jêng ndơ nhhơr rnih muy.$b$,true),
('bunong-vn','NUM',7,20,null,$b$Du mlâm ngan mah njing jâk păng jât sêkel bêng ma ndơ ƀâu kah;$b$,false),
