('bunong-vn','NUM',7,84,null,$b$Nây jêng ndơ phung kôranh Israel nhhơr prăp ăn nơng ta nar bu tŏ păng dak ƀâu kah: Jât ma bar mlâm ngan pala prăk, jât ma bar mlâm ngan grưng prăk, jât ma bar mlâm ngan mah,$b$,false),
