('bunong-vn','NUM',7,86,null,$b$jât ma bar mlâm ngan mah bêng ma ndơ ƀâu kah, njing jâk ăp mlâm ngan mah jât sêkel tĭng nâm sêkel tâm jrô kloh ueh, njing jâk lĕ rngôch ngan mah geh du rhiăng bar jât sêkel;$b$,false),
('bunong-vn','NUM',7,87,null,$b$Lĕ rngôch ndrôk biăp ma ndơ gŭch geh jât ma bar mlâm ndrôk nkuăng, jât ma bar mlâm biăp nkuăng, jât ma bar mlâm biăp kon nkuăng du năm deh, ndrel ma ndơ nhhơr rnih muy; jêh ri jât ma bar mlâm be nkuăng jêng ndơ nhhơr chuai yor nau tih;$b$,false),
('bunong-vn','NUM',7,88,null,$b$lĕ rngôch ndrôk biăp ma nau ƀư brah nhhơr ndơ ma nau đăp mpăn geh bar jât ma puăn mlâm ndrôk nkuăng, prao jât mlâm biăp nkuăng, prao jât mlâm be nkuăng, jêh ri prao jât mlâm biăp kon nkuăng du năm deh. Nây jêng ndơ nhhơr ma nau prăp ăn nơng jêh bu tŏ păng dak ƀâu kah.$b$,false),
('bunong-vn','NUM',7,89,null,$b$Tơ lah Y-Môis lăp ngih bok tâm rƀŭn gay ngơi ndrel ma Yêhôva, păng tăng bâr ngơi ma păng tă bơh klơ ntŭk yô̆ an ta klơ hip nau mbơh, vah vang bar chêrubim, jêh ri bâr nây ngơi ma păng.$b$,false),
('bunong-vn','NUM',8,1,null,$b$Yêhôva lah ma Y-Môis,$b$,true),
('bunong-vn','NUM',8,2,null,$b$“Lah hom ma Y-Arôn, Tơ lah may dăp krĭp ŭnh kađen, pơh mlâm ŭnh kađen nây mra ăn ang pa năp jâng jrêng”$b$,false),
('bunong-vn','NUM',8,3,null,$b$Y-Arôn ƀư pô nây; păng dăp krĭp ŭnh kađen păng gay ăn pa năp jâng jrêng, tĭng nâm Yêhôva ntĭnh jêh ma Y-Môis.$b$,false),
('bunong-vn','NUM',8,4,null,$b$Aơ nau blau bu ƀư jâng jrêng, ma mah bu chiăr, ntơm bơh jâng tât ta kao păng jêng kan bu chiăr, tĭng nâm rup Yêhôva nchŏng jêh ma Y-Môis, tâm ban pô nây păng ƀư jâng jrêng.$b$,false),
('bunong-vn','NUM',8,5,null,$b$Yêhôva lah ma Y-Môis,$b$,true),
('bunong-vn','NUM',8,6,null,$b$“Sŏk hom phung Lêvi bơh ta nklang phung Israel jêh ri ƀư ăn khân păng dơi kloh.$b$,false),
('bunong-vn','NUM',8,7,null,$b$Pô aơ ăn may ƀư ma khân păng gay ƀư kloh: May nsrih dak nau ƀư kloh ta klơ khân păng; ăn khân păng poih lĕ rngôch rsau săk jăn khân păng, pih bok ao khân păng, jêh ri ƀư kloh khân păng nơm.$b$,false),
('bunong-vn','NUM',8,8,null,$b$Pô nây, ăn khân păng sŏk du mlâm ndrôk nkuăng rah ndrel ma ndơ nhhơr rnih muy tâm pot đah dak play ôlivơ, jêh ri ăn may sŏk du mlâm ndrôk nkuăng rah êng jêng ndơ nhhơr chuai yor nau tih.$b$,false),
('bunong-vn','NUM',8,9,null,$b$Ăn may tâm mpơl phung Lêvi pa năp ngih bok tâm rƀŭn, jêh ri rgum lĕ rngôch phung Israel.$b$,true),
('bunong-vn','NUM',8,10,null,$b$Pô nây, may ăn phung Lêvi văch dăch ta năp măt Yêhôva, jêh nây phung Israel mra dra ti khân păng ta phung Lêvi,$b$,false),
('bunong-vn','NUM',8,11,null,$b$jêh ri Y-Arôn mra nhhơr phung Lêvi ta năp Yêhôva jêng ndơ nhhơr ryeng bơh phung ƀon lan Israel, gay ma khân păng dơi pah kan ma Yêhôva.$b$,false),
('bunong-vn','NUM',8,12,null,$b$Jêh nây, phung Lêvi dra ti ta klơ bôk lĕ bar mlâm ndrôk nkuăng; jêh ri may mra nhhơr du mlâm jêng ndơ nhhơr chuai yor nau tih, jêh ri du mlâm êng jêng ndơ nhhơr gŭch ma Yêhôva, gay chuai nau ƀư kloh nau tih phung Lêvi.$b$,false),
('bunong-vn','NUM',8,13,null,$b$Jêh ta nây, may mra ăn phung Lêvi kơl Y-Arôn jêh ri phung kon bu klâu păng, jêh nây may mra nhhơr khân păng jêng ndơ nhhơr ryeng ma Yêhôva.$b$,true),
('bunong-vn','NUM',8,14,null,$b$“Pô ri may mra prăp ăn phung Lêvi tă ta nklang ƀon lan Israel, jêh ri phung Lêvi mra jêng phung gâp.$b$,true),
('bunong-vn','NUM',8,15,null,$b$Jêh nau nây phung Lêvi mra lăp pah kan tâm ngih bok nau tâm rƀŭn, tơ lah lĕ ƀư kloh jêh khân păng, jêh ri nhhơr khân păng jêng ndơ nhhơr ryeng rvăh plơ̆ sĭt:$b$,false),
('bunong-vn','NUM',8,16,null,$b$Yor lah, bơh ta nklang ƀon lan Israel phung Lêvi ăn n'ho ma gâp; gâp nơm hŏ sŏk khân păng ntrok ăn lĕ rngôch kon bôk rah tâm phung ƀon lan Israel.$b$,false),
('bunong-vn','NUM',8,17,null,$b$Yor lah lĕ rngôch phung kon bôk rah tâm phung ƀon lan Israel jêng ndơ gâp, bunuyh nđâp ma mpô mpa; tâm nar gâp nkhĭt jêh lĕ rngôch phung kon bu klâu bôk rah tâm n'gor bri Êjipt, gâp prăp an jêh khân păng ma gâp nơm.$b$,false),
('bunong-vn','NUM',8,18,null,$b$Jêh ri gâp sŏk jêh phung Lêvi ntrok ma lĕ rngôch phung kon bôk rah bơh phung ƀon lan Israel.$b$,false),
('bunong-vn','NUM',8,19,null,$b$Jêh ri gâp ăn jêh phung Lêvi jêng ndơ ăn ma Y-Arôn jêh ri ma phung kon bu klâu păng tă bơh ta nklang phung ƀon lan Israel, pah kan ma phung ƀon lan Israel ta ngih bok nau tâm rƀŭn, jêh nây ƀư nau ăn kloh nau tih phung ƀon lan Israel, gay lơi dĭng geh ôh nau tât mhĭk ta nklang phung ƀon lan Israel tơ lah phung ƀon lan Israel hăn dăch jrô kloh ueh.”$b$,true),
('bunong-vn','NUM',8,20,null,$b$“Pô ri Y-Môis, Y-Arôn, jêh ri lĕ rngôch phung ƀon lan Israel tâm rƀŭn ƀư ma phung Lêvi tĭng nâm lĕ rngôch nau Yêhôva ntĭnh jêh ma Y-Môis di ma phung Lêvi, pô ri phung ƀon lan Israel ƀư tâm ban nây đŏng.$b$,true),
('bunong-vn','NUM',8,21,null,$b$Phung Lêvi ƀư kloh khân păng nơm bơh nau tih, jêh ri pih bok ao khân păng; Y-Arôn nhhơr khân păng jêng ndơ nhhơr ryeng ta năp Yêhôva, jêh ri Y-Arôn ƀư brah chuai an gay ăn kloh nau tih khân păng.$b$,true),
('bunong-vn','NUM',8,22,null,$b$Jêh nau nây phung Lêvi lăp pah kan tâm ngih bok nau tâm rƀŭn kơl Y-Arôn jêh ri phung kon bu klâu păng; tĭng nâm Yêhôva ntĭnh jêh ma Y-Môis di ma phung Lêvi, pô nây bu ăn khân păng ƀư.$b$,true),
('bunong-vn','NUM',8,23,null,$b$Pô aơ Yêhôva lah ma Y-Môis,$b$,true),
('bunong-vn','NUM',8,24,null,$b$“Aơ jêng nau vay nal ma phung Lêvi: Ntơm ma bar jât ma prăm năm bơi rlau, phung Lêvi mra lăp pah kan tâm ngih bok tâm rƀŭn;$b$,false),
('bunong-vn','NUM',8,25,null,$b$jêh ri ntơm bơh prăm jât năm khân păng mra luh du bơh nau kan jêh ri mâu hôm pah kan ôh,$b$,false),
('bunong-vn','NUM',8,26,null,$b$ƀiă lah kâp kơl phung oh nâu khân păng tâm ngih bok tâm rƀŭn, gay mât mray ndơ bu jao jêh ma khân păng, jêh ri khân păng mâu mra ƀư kan ôh. Ăn may ƀư pô nây ma phung Lêvi dôl jao kan ma khân păng.”$b$,false),
('bunong-vn','NUM',9,1,null,$b$Yêhôva lah ma Y-Môis tâm bri rdah Sinai, khay tal nguay, năm rơh bar, jêh khân păng du luh tă bơh n'gor bri Êjipt, lah:$b$,true),
('bunong-vn','NUM',9,2,null,$b$“Ăn phung ƀon lan Israel kah gĭt prăp Nau Găn ta nar tâm nal jêh.$b$,false),
('bunong-vn','NUM',9,3,null,$b$Ta nar jât ma puăn khay aơ kêng măng, ăn khân may kah gĭt prăp păng tĭng nâm nar tâm nal jêh; ăn khân may ƀư tĭng ndô̆ lĕ rngôch nau vay jêh ri lĕ rngôch nau ntĭnh.”$b$,false),
('bunong-vn','NUM',9,4,null,$b$Pô nây, Y-Môis lah ma phung ƀon lan Israel ăn khân păng kah gĭt prăp Nau Găn.$b$,false),
('bunong-vn','NUM',9,5,null,$b$Jêh ri khân păng kah gĭt Nau Găn tâm khay tal nguay, ta nar jât ma puăn khay nây, kêng măng tâm bri rdah Sinai; pô ri phung ƀon lan Israel ƀư tĭng ndô̆ lĕ rngôch nau Yêhôva ntĭnh jêh ma Y-Môis.$b$,false),
('bunong-vn','NUM',9,6,null,$b$Jêh ri geh ƀa ƀă bunuyh lĕ ƀơ̆ jêh yor geh rđĭl săk jăn bunuyh khĭt, pô nây khân păng mâu dơi ôh kah gĭt prăp Nau Găn nar nây; jêh ri nar nây khân păng văch tra năp Y-Môis jêh ri Y-Arôn,$b$,true),
('bunong-vn','NUM',9,7,null,$b$jêh ri phung bunuyh nây lah ma Y-Môis, “Hên jêng ƀơ̆ jêh yor geh rđĭl đah săk jăn bunuyh khĭt; mâm bu buay hên nhhơr ndơ nhhơr ma Yêhôva ta nar tâm nal jêh ta nklang phung ƀon lan Israel?”$b$,false),
('bunong-vn','NUM',9,8,null,$b$Y-Môis lah ma khân păng, “Kâp hom, gay gâp dơi tăng moh nau Yêhôva mra ntĭnh nau di ma khân may.”$b$,false),
('bunong-vn','NUM',9,9,null,$b$Yêhôva lah ma Y-Môis,$b$,true),
('bunong-vn','NUM',9,10,null,$b$“Lah hom ma phung ƀon lan Israel, Tơ lah du huê tâm phung khân may mâu lah tâm phung kon sau khân may jêng ƀơ̆ yor geh rđĭl đah săk jăn bunuyh khĭt, mâu lah nsong tâm ntŭk ngai, ăt păng mra kah gĭt prăp Nau Găn ma Yêhôva.$b$,false),
('bunong-vn','NUM',9,11,null,$b$Tâm khay bar ta nar jât ma puăn kêng măng, khân păng mra kah gĭt prăp sa piăng let mâu geh ndrui, jêh ri trau biăp tăng.$b$,false),
('bunong-vn','NUM',9,12,null,$b$Khân păng mâu mra ăn rmeh ôh ndơ sa tât ang ôi taơ, jêh ri ăt mâu lĕ ăn deh (pă) du mlâm nting păng; khân păng mra kah gĭt prăp păng tĭng ndô̆ lĕ rngôch nau ntĭnh di ma Nau Găn.$b$,false),
('bunong-vn','NUM',9,13,null,$b$Ƀiă lah nơm jêng kloh jêh ri mâu nsong ôh ntŭk ngai, ƀiă lah mâu kah gĭt prăp ôh Nau Găn, nơm nây bu mra ngroh lơi bơh phung ƀon lan păng, yor lah păng mâu mâp nhhơr ôh ndơ nhhơr ma Yêhôva ta nar tâm nal jêh; bunuyh nây mra anh nau tih păng.$b$,false),
('bunong-vn','NUM',9,14,null,$b$Jêh ri tơ lah du huê bu năch gŭ njơh ƀât lât ta nklang khân păng may, jêh ri ŭch kah gĭt prăp Nau Găn ma Yêhôva, tĭng nâm nau ntĭnh di ma Nau Găn jêh ri tĭng nâm nau vay păng, pô ri păng mra ƀư; khân may mra geh du nau vay ma nơm gŭ njơh ƀât lât jêh ri ma bunuyh ƀon lan nơm.”$b$,false),
('bunong-vn','NUM',9,15,null,$b$Ta nar bu ndâk ngih bok tŭk nkâm ngih bok, ngih bok nau mbơh; jêh ri ta măng tât ma ang ôi tŭk gŭ ta klơ ngih bok nâm bu ŭnh.$b$,true),
('bunong-vn','NUM',9,16,null,$b$Păng jêng ƀa ƀơ pô nây; tŭk nkâm ngih bok nôk nar, jêh ri jêng ŭnh nâm bu dôl măng.$b$,false),
('bunong-vn','NUM',9,17,null,$b$Tơ lah tŭk hao rlet klơ tă bơh ngih bok, jêh nau nây phung ƀon lan Israel dâk hăn; Jêh ri ta ntŭk tŭk trŭnh gŭ, ta nây phung ƀon lan Israel gŭ njơh.$b$,false),
('bunong-vn','NUM',9,18,null,$b$Phung ƀon lan Israel dâk hăn tĭng nâm nau Yêhôva ntĭnh, jêh ri khân păng gŭ njơh tĭng nâm nau Yêhôva ntĭnh đŏng. Khân păng gŭ njơh tĭng nâm ndah jŏ tŭk gŭ ta klơ ngih bok.$b$,false),
('bunong-vn','NUM',9,19,null,$b$Nđâp tơ lah tŭk hôm e ta klơ ngih bok âk nar, phung ƀon lan Israel ăt djôt kan Yêhôva jêh ri mâu dâk hăn ôh.$b$,true),
('bunong-vn','NUM',9,20,null,$b$Geh tơ̆ tŭk gŭ ƀhôi nar ta klơ ngih bok, jêh ri khân păng ăt gŭ njơh tĭng nâm Yêhôva ntĭnh; jêh ri khân păng dâk hăn tĭng nâm Yêhôva ntĭnh đŏng$b$,false),
('bunong-vn','NUM',9,21,null,$b$Geh tơ̆ tŭk ăt gŭ ntơm bơh kêng măng tât ma ôi taơ; khân păng dâk hăn ro, mâu lah tơ lah tŭk ăt gŭ du nar jêh ri du măng, tơ lah tŭk hao rlet klơ khân păng hăn ro.$b$,false),
('bunong-vn','NUM',9,22,null,$b$Gĭt lah tŭk hôm e ta klơ ngih bok bar nar mâu lah du khay, mâu lah jŏ lơn hôm e ta nây, phung ƀon lan Israel gŭ njơh jêh ri mâu dâk hăn ôh; ƀiă lah tơ lah tŭk hao leo klơ khân păng dâk hăn ro yơh.$b$,false),
('bunong-vn','NUM',9,23,null,$b$Khân păng njơh tĭng nâm nau Yêhôva ntĭnh, jêh ri khân păng dâk hăn tĭng nâm nau Yêhôva ntĭnh đŏng; khân păng ăt djôt kan Yêhôva tĭng nâm Yêhôva ntĭnh ma Y-Môis.$b$,false),
('bunong-vn','NUM',10,1,null,$b$Yêhôva lah ma Y-Môis,$b$,true),
('bunong-vn','NUM',10,2,null,$b$“Ƀư hom bar mlâm nŭng prăk; ăn may chiăr khân păng, jêh ri may mra dŏng khân păng gay kuăl phung tâm rƀŭn jêh ri mbơh nau dâk hăn.$b$,false),
('bunong-vn','NUM',10,3,null,$b$Ƀiă lah tơ lah bu uh lĕ bar, lĕ rngôch phung tâm rƀŭn mra văch ma may ta mpông lăp ngih bok tâm rƀŭn.$b$,false),
('bunong-vn','NUM',10,4,null,$b$Tơ lah khân păng uh knŏng du mlâm, nôk nây phung kôranh phung mpôl Israel mra tâm rƀŭn n'hanh may.$b$,false),
('bunong-vn','NUM',10,5,null,$b$Tơ lah khân may uh ăn hăn ma nau tâm lơh, phung gŭ mpeh pa lơ mra dâk hăn.$b$,false),
('bunong-vn','NUM',10,6,null,$b$Jêh ri tơ lah khân may uh tal bar, phung gŭ mpeh tâm rđŭng mra dâk hăn. Bu mra uh nŭng ăn tâm lơh tơ lah bu ăn khân păng dâk hăn.$b$,false),
('bunong-vn','NUM',10,7,null,$b$Ƀiă lah tơ lah bu gay ăn phung ƀon lan tâm rƀŭn, khân may mra uh, ƀiă lah khân may mâu mra uh nau ăn tâm lơh ôh.$b$,false),
('bunong-vn','NUM',10,8,null,$b$Phung kon bu klâu Y-Arôn phung kôranh ƀư brah mra uh nŭng; nŭng nây mra jêng nau vay gŭ ƀa ƀơ ma khân may tâm lĕ rngôch rnôk.$b$,false),
('bunong-vn','NUM',10,9,null,$b$Jêh ri tâm n'gor bri khân may, tơ lah khân may hăn tâm lơh đah rlăng tŭn jot khân may, pô ri khân may mra uh nŭng ăn hăn tâm lơh, gay ma Yêhôva Brah Ndu khân may kah gĭt ma khân may, jêh ri khân may mra klaih ma phung rlăng khân may.$b$,false),
('bunong-vn','NUM',10,10,null,$b$Tâm ban đŏng tâm nar khân may hâk maak, tâm nar nau nhêt sông tâm nal jêh, jêh ri ta bôk khay ma khân may, ăn khân may uh nŭng dôl khân may nhhơr ndơ nhhơr gŭch jêh ri dôl khân may ƀư brah nhhơr ndơ ma nau đăp mpăn. Khân păng mra kơl khân may geh nau ăn kah gĭt ta năp Brah Ndu khân may; gâp jêng Yêhôva Brah Ndu khân may.”$b$,false),
('bunong-vn','NUM',10,11,null,$b$Tâm năm rơh bar, khay bar, nar bar jât khay nây tŭk hao leo klơ tă bơh ngih bok nau mbơh,$b$,true),
('bunong-vn','NUM',10,12,null,$b$jêh ri phung ƀon lan Israel dâk hăn bơh bri rdah Sinai; jêh ri tŭk trŭnh gŭ tâm bri rdah Paran.$b$,false),
('bunong-vn','NUM',10,13,null,$b$Khân păng dâk hăn ntơm sa ơm tĭng nâm nau Yêhôva ntĭnh ma Y-Môis.$b$,false),
('bunong-vn','NUM',10,14,null,$b$Bok pla ma phung bu klâu Yuđa dâk hăn lor tĭng nâm phung khân păng; Y-Nahsôn, kon bu klâu Y-Aminadap jêng kôranh ma phung ta han khân păng.$b$,false),
('bunong-vn','NUM',10,15,null,$b$Y-Nêthanel, kon bu klâu Y-Suar jêng kôranh ma phung ta han phung bu klâu mpôl Isakar.$b$,true),
('bunong-vn','NUM',10,16,null,$b$Y-Êliap kon bu klâu Y-Hêlôn jêng kôranh ma phung ta han phung bu klâu mpôl Sabulôn.$b$,false),
('bunong-vn','NUM',10,17,null,$b$Tơ lah bu rơi lơi ngih bok, phung kon bu klâu Y-Gersôn jêh ri phung kon bu klâu Y-Mêrari, phung tung leo ngih bok dâk hăn.$b$,false),
('bunong-vn','NUM',10,18,null,$b$Bok pla phung Ruben dâk hăn tĭng nâm phung khân păng; Y-Êlisur kon bu klâu Y-Sêdur jêng kôranh ma phung ta han khân păng.$b$,false),
('bunong-vn','NUM',10,19,null,$b$Y-Sêlumiel kon bu klâu Y-Surisadai jêng kôranh ma phung ta han phung bu klâu mpôl Simêôn.$b$,false),
('bunong-vn','NUM',10,20,null,$b$Y-Êliasap kon bu klâu Y-Dêuel jêng kôranh ma phung ta han phung bu klâu mpôl Gat.$b$,true),
('bunong-vn','NUM',10,21,null,$b$Jêh ri phung Kôhat dâk hăn, tung leo ndơ kloh ueh, jêh ri bu ndâk jêh ngih bok lor ma khân păng tât.$b$,false),
('bunong-vn','NUM',10,22,null,$b$Bok pla phung bu klâu mpôl Êphraim dâk hăn tĭng nâm phung khân păng Y-Êlisama, kon bu klâu Y-Amihut jêng kôranh ma phung ta han khân păng.$b$,false),
('bunong-vn','NUM',10,23,null,$b$Y-Gamaliel kon bu klâu Y-Pêsadur jêng kôranh ma phung ta han phung bu klâu mpôl Mananê.$b$,false),
('bunong-vn','NUM',10,24,null,$b$Y-Abidan kon bu klâu Y-Gidêôni jêng kôranh ma phung ta han bu klâu mpôl Benjamin.$b$,true),
('bunong-vn','NUM',10,25,null,$b$Jêh ri bok pla phung bu klâu mpôl Dan dâk hăn tĭng nâm phung khân păng; khân păng jêng phung gak pa kơi lĕ rngôch phung mpôl; Y-Ahiêser kon bu klâu Y-Amisadai jêng kôranh ma phung ta han khân păng.$b$,false),
('bunong-vn','NUM',10,26,null,$b$Y-Pagiel, kon bu klâu Y-Ôkran jêng kôranh ma phung ta han phung bu klâu mpôl Aser.$b$,false),
('bunong-vn','NUM',10,27,null,$b$Y-Ahira, kon bu klâu Y-Ênan jêng kôranh ma phung ta han mpôl bu klâu Naptali.$b$,false),
('bunong-vn','NUM',10,28,null,$b$Pô aơ jêng mbor phung ƀon lan Israel hăn tĭng nâm phung ta han khân păng, tơ lah khân păng dâk hăn.$b$,false),
('bunong-vn','NUM',10,29,null,$b$Y-Môis lah ma Y-Hôbap, kon bu klâu Y-Rêuel, du huê Madian, po bu klâu Y-Môis, “Hên dâk hăn ma ntŭk Yêhôva lah jêh, Gâp mra ăn păng ma khân may! Hăn ndrel ma hên, jêh ri hên mra ƀư ueh ma may, yor lah Yêhôva ton jêh nau ueh ma phung Israel.”$b$,true),
('bunong-vn','NUM',10,30,null,$b$Ƀiă lah Y-Hôbap lah ma păng, “Gâp mâu mra hăn ôh; gâp mâu mra hăn ôh; gâp mra hăn ma n'gor gâp jêh ri phung ƀon lan gâp nơm.”$b$,true),
('bunong-vn','NUM',10,31,null,$b$Jêh ri Y-Môis lah, “Gâp vơl dăn ma may, lơi ta du đah hên ôh, yor lah may gĭt ta ntŭk hên dơi njơh tâm bri rdah, jêh ri may jêng nâm bu măt ma hên.$b$,false),
('bunong-vn','NUM',10,32,null,$b$Jêh ri tơ lah may hăn ndrel ma hên, moh nau ueh Yêhôva mra ƀư ma hên, pô nây đŏng hên mra ƀư ueh đah may.”$b$,false),
('bunong-vn','NUM',10,33,null,$b$Pô ri khân may dâk hăn tă bơh yôk Yêhôva pe nar hăn; jêh ri hip nau tâm rnglăp Yêhôva hăn pa năp khân păng pe nar hăn, gay joi du ntŭk rlu ma khân păng.$b$,true),
('bunong-vn','NUM',10,34,null,$b$Tŭk Yêhôva gŭ ta klơ khân păng dôl nar tơ lah khân păng dâk hăn tă bơh ntŭk njơh.$b$,true),
('bunong-vn','NUM',10,35,null,$b$Tơ lah hip dâk hăn, Y-Môis lah, “Dâk hăn hom may, Ơ Yêhôva, jêh ri ăn phung rlăng may nchuăt du pru pra êng êng; jêh ri ăn phung tâm rmot ma may du pa năp may.”$b$,false),
('bunong-vn','NUM',10,36,null,$b$Jêh ri tơ lah hip gŭ rlu, păng lah, “Plơ̆ sĭt hom, Ơ Yêhôva, ma rkeh rkai Israel.”$b$,false),
('bunong-vn','NUM',11,1,null,$b$Phung ƀon lan ngơi ƀrôk tăng ma tôr Yêhôva yor nau hŏt khân păng. Tơ lah Yêhôva tăng nau nây, păng hao ji nuih, jêh ri ŭnh Yêhôva su ta nklang khân păng, jêh ri ŭnh sa ta pĭt ntŭk rmlak.$b$,true),
('bunong-vn','NUM',11,2,null,$b$Nôk nây phung ƀon lan nter ma Y-Môis; Y-Môis mbơh sơm ma Yêhôva, jêh ri ŭnh rngơt ro.$b$,false),
('bunong-vn','NUM',11,3,null,$b$Pô ri bu ntơ ntŭk nây Tabêra, yor lah ŭnh Yêhôva hŏ su ta nklang khân păng.$b$,false),
('bunong-vn','NUM',11,4,null,$b$Phung bu năch gŭ ta nklang phung Israel geh nau ŭch kơnh ngăn; jêh ri nđâp phung ƀon lan Israel kŏ tât nhĭm đŏng jêh ri lah, “Mbu sâm ăn ma he puăch sa?$b$,true),
('bunong-vn','NUM',11,5,null,$b$He kah gĭt ma ka he sa dơm ta n'gor bri Êjipt, rpŭng, rpŭng tôk, kdĭm, jiăm jêh ri toi.$b$,false),
('bunong-vn','NUM',11,6,null,$b$Aƀaơ ri, nau nđơr, he lĕ hŭch jêh, mâu geh du ntil ndơ ôh măt he saơ, knŏng mana.”$b$,false),
('bunong-vn','NUM',11,7,null,$b$Mana jêng nâm bu găr kôriander, uănh nâm bu lŭ bêdêlium.$b$,false),
('bunong-vn','NUM',11,8,null,$b$Phung ƀon lan hăn bra mana, jêh ri vâr ăn lêk păng mâu lah juh păng đah mpăl, jêh ri gâm păng tâm glah jêh ri ƀư ƀănh; sa păng nâm bu sa ƀănh gŭch geh pot dak play ôlivơ.$b$,false),
('bunong-vn','NUM',11,9,null,$b$Tơ lah dak ngom tŭp dôl măng ta nhuang ntŭk rmlak, pô ri mana ăt tŭp đŏng.$b$,false),
('bunong-vn','NUM',11,10,null,$b$Y-Môis tăng phung ƀon lan gŭ nhĭm tâm lĕ rngôch phung mpôl khân păng, ăp nơm ta mpông ngih bok păng. Nau Yêhôva ji nuih hit duh ngăn, jêh ri Y-Môis rngot.$b$,false),
('bunong-vn','NUM',11,11,null,$b$Y-Môis lah ma Yêhôva. “Mâm may ƀư jêr ma oh mon may? Jêh ri mâm gâp dĭng mâu saơ nau yô̆ ôh ta năp măt may, kŏ tât may ăn tŭp nau jâk lĕ rngôch phung ƀon lan aơ ta gâp?$b$,false),
('bunong-vn','NUM',11,12,null,$b$Gâp hĕ ntreo ma lĕ rngôch phung ƀon lan aơ? Geh gâp hĕ deh ma khân păng kŏ tât may lah ma gâp. ‘Chông khân păng ta ntang ntơh may, nâm bu du huê rong kon se hôm e pu toh, tât ta n'gor may sơm ton ăn jêh gay ăn ma phung chô che khân păng?’$b$,false),
('bunong-vn','NUM',11,13,null,$b$Ta ntŭk gâp sŏk puăch gay ăn ma lĕ rngôch phung ƀon lan aơ? Yor lah khân păng ta năp gâp jêh ri lah, ‘Ăn ma hên puăch sa.’$b$,false),
('bunong-vn','NUM',11,14,null,$b$Êng gâp mâu dơi anh lĕ rngôch phung ƀon lan aơ, khân păng jêng jâk ir ma gâp.$b$,false),
('bunong-vn','NUM',11,15,null,$b$Tơ lah may ƀư pô aơ ma gâp, nkhĭt hom gâp aƀaơ ro, tơ lah gâp mâu geh nau yô̆ ta năp măt may, gay lơi ăn gâp saơ ôh nau rêh ni gâp.”$b$,true),
('bunong-vn','NUM',11,16,null,$b$Yêhôva lah ma Y-Môis, “Rgum hom ăn gâp pơh jât nuyh bu klâu phung bu bŭnh bu ranh Israel, đơ phung may gĭt năl jêh jêng bu ranh tâm phung ƀon lan jêh ri kôranh ta klơ khân păng; jêh ri njŭn leo khân păng rlet ngih bok tâm rƀŭn, jêh ri ăn khân păng gŭ ngao ndrel ma may.$b$,false),
('bunong-vn','NUM',11,17,null,$b$Gâp ma trŭnh jêh ri ta nây gâp mra ngơi ma may; gâp mra sŏk Huêng Brah gŭ ta klơ may jêh ri dơm păng tâm ban đŏng ta klơ khân păng; jêh ri khân păng mra anh nau jâk phung ƀon lan ndrel ma may, gay ma may mâu anh êng may ôh nau nây.$b$,true),
('bunong-vn','NUM',11,18,null,$b$Lah hom ma phung ƀon lan, prăp ăn kloh hom khân may nơm ma ôi taơ, jêh ri khân may mra sa puăch; yor lah khân may nhĭm jêh tăng ma tôr Yêhôva. “Mbu mra ăn ma hên puăch sa? Yor lah ueh jêh ma hên gŭ tâm bri Êjipt.” Pô ri Yêhôva mra ăn puăch ma khân may, jêh ri khân may mra sa.$b$,false),
('bunong-vn','NUM',11,19,null,$b$Khân may mra sa mâu di ôh knŏng du nar dơm, mâu lah bar nar, mâu lah prăm nar, mâu lah jât nar, mâu lah bar jât nar.$b$,false),
('bunong-vn','NUM',11,20,null,$b$Ƀiă lah lĕ du khay, kŏ tât puăch nây luh du ta trôm muh khân may jêh ri tât khân may tâm rmot ma ndơ nây, yor lah khân may dun jêh ma Yêhôva nơm gŭ ta nklang khân may, jêh ri nhĭm ta năp păng lah, “Mâm hên dĭng du luh nkhơng tă bơh n'gor bri Êjipt.”$b$,false),
('bunong-vn','NUM',11,21,null,$b$Ƀiă lah lah Y-Môis lah, “Phung ƀon lan gâp gŭ ndrel geh prao rsen bunuyh hăn jâng; jêh ri may lah jêh,” Gâp mra ăn puăch ma khân păng, gay ăn khân păng sa lĕ du khay!$b$,false),
('bunong-vn','NUM',11,22,null,$b$Bu mra sreh ma khân păng biăp jêh ri ndrôk tât dơi tŏng ma khân păng lĕ?$b$,false),
('bunong-vn','NUM',11,23,null,$b$“Yêhôva lah ma Y-Môis,” Ti Yêhôva jêng gleh ir lĕ? Aƀaơ ri may mra saơ gĭt lah nau gâp ngơi jêh mra tât ngăn mâu lah mâu.”$b$,false),
('bunong-vn','NUM',11,24,null,$b$Pô nây Y-Môis du luh hăn mbơh ma phung ƀon lan nau Yêhôva ngơi; jêh ri rgum pơh jât nuyh phung bu ranh tâm phung ƀon lan jêh ri dơm khân păng gŭ jŭm ngih bok.$b$,true),
('bunong-vn','NUM',11,25,null,$b$Nôk nây Yêhôva trŭnh tâm tŭk jêh ri ngơi ma Y-Môis. Păng sŏk Huêng Brah gŭ ta klơ Y-Môis jêh ri dơm tâm ban đŏng ta klơ pơh jât nuyh phung bu ranh; jêh ri tơ lah Huêng Brah gŭ ta klơ khân păng, khân păng mbơh lor. Ƀiă lah khân păng mâu hôm ngơi mro pô nây ôh.$b$,false),
('bunong-vn','NUM',11,26,null,$b$Geh bar hê hôm e gŭ tâm nhuang ntŭk rmlak; du huê amoh păng Y-Eldat jêh ri du huê êng ntơ amoh Y-Mêdat, geh Huêng Brah gŭ ta klơ khân păng. Ngơi mbơh lor tâm nhuang ntŭk rmlak. Bar hê aơ jêng tâm phung bu chih săk, ƀiă lah khân păng mâu dơi hăn ma ngih bok ôh.$b$,true),
('bunong-vn','NUM',11,27,null,$b$Du huê bu klâu ndăm nchuăt hăn mbơh nau nây ma Y-Môis “Y-Êldat jêh ri Y-Mêdat gŭ ngơi mbơh lor tâm nhuang ntŭk rmlak.”$b$,false),
('bunong-vn','NUM',11,28,null,$b$Jêh nây Y-Yôsuê, kon bu klâu Y-Nun, jêng oh mon Y-Môis, du huê tâm phung păng săch jêh, lah “Hơi kôranh gâp Y-Môis, buay hom khân păng!”$b$,false),
('bunong-vn','NUM',11,29,null,$b$Ƀiă lah Y-Môis lah ma păng, “May nach yor ma gâp? Gâp ŭch ma lĕ rngôch phung ƀon lan Yêhôva jêng phung kôranh mbơh lor, gay ma Yêhôva dơm Huêng Brah păng ta khân păng.”$b$,false),
('bunong-vn','NUM',11,30,null,$b$Pô ri Y-Môis jêh ri phung bu ranh phung Israel sĭt ma nhuang ntŭk rmlak.$b$,false),
('bunong-vn','NUM',11,31,null,$b$Yêhôva ăn du rôn sial khôm tă bơh dak mƀŭt, leo phung sĭm gôi ăn khân păng tŭp dăch nhuang ntŭk gŭ mbrach jŭm klăp du nar hăn mpeh du ding jêh ri gŭ mbrach mpeh du ding êng du nar hăn, klăp prêh tă klơ neh bar hăt mbâl.$b$,true),
('bunong-vn','NUM',11,32,null,$b$Phung ƀon lan dâk hăn dônh phung sĭm gôi tâm nar nây, măng nây jêh ri du nar ôi taơ; mbu dônh ƀhôi lơn geh bar jât hômer; bu ih nthăng păng jŭm văr ntŭk rmlak.$b$,true),
('bunong-vn','NUM',11,33,null,$b$Puăch sĭm ăt hôm ta trôm bâr khân păng ê hŏ rvăn ôh, nau Yêhôva ji nuih hit hâr ma phung ƀon lan, jêh ri Yêhôva dong phung ƀon lan ma nau rêh ni toyh.$b$,true),
('bunong-vn','NUM',11,34,null,$b$Bu ntơ amoh ntŭk nây jêng Kibrôt-Hatava, yor lah ta nây bu tâp brôi phung ƀon lan geh nuih n'hâm hay kơnh.$b$,false),
('bunong-vn','NUM',11,35,null,$b$Ntơm bơh Kibrôt-Hatava phung ƀon lan dâk hăn tât Hasêrôt, jêh ri khân păng gŭ njơh ta Hasêrôt.$b$,false),
('bunong-vn','NUM',12,1,null,$b$H'Miriam jêh ri Y-Arôn ngơi tâm rdâng đah Y-Môis yor ô băl hŏ gŭ jêh ur đah du huê bu ur Kus.$b$,true),
('bunong-vn','NUM',12,2,null,$b$Khân păng lah, “Yêhôva ŭch dŏng knŏng êng Y-Môis hĕ dĭng păng ngơi jêh? Mâu hĕ păng dŏng he dĭng mâu ŭch ngơi đŏng? “Yêhôva tăng nau nây.$b$,false),
('bunong-vn','NUM',12,3,null,$b$Pô ri, Y-Môis jêng du huê bunuyh hêt rhôi ngăn ma lĕ rngôch bunuyh ta neh ntu.$b$,false),
('bunong-vn','NUM',12,4,null,$b$Ƀât lât Yêhôva lah ma Y-Môis, ma Y-Arôn jêh ri ma H'Miriam. “Văch hom lĕ pe nuyh rlet ngih bok tâm rƀŭn.” Jêh ri lĕ pe khân păng dâk hăn.$b$,false),
('bunong-vn','NUM',12,5,null,$b$Yêhôva jŭr văch tâm meh ndâr tŭk jêh ri gŭ ta mpông ngih bok, kuăl Y-Arôn jêh ri H'Miriam; jêh nây bar hê khân păng hăn pa năp.$b$,false),
('bunong-vn','NUM',12,6,null,$b$Păng lah, “Iăt hom nau gâp ngơi: Tơ lah geh du huê kôranh nơm mbơh lor tâm phung khân may, gâp yơh Yêhôva nơm tâm mpơl gâp nơm ma păng tâm nau tâm saơ, gâp ngơi ma păng tâm nau mbơi.$b$,false),
('bunong-vn','NUM',12,7,null,$b$Oh mon Y-Môis mâu geh pô nây ôh, păng răp jăp ngăn tâm lĕ ngih gâp.$b$,true),
('bunong-vn','NUM',12,8,null,$b$Gâp ngơi đah păng mbung ndrăng mbung ma nau rah vah, mâu geh ngơi ndâp; păng saơ rup Yêhôva. Pô nây mâm khân may mâu klach tâm rdâng đah oh mon Y-Môis?”$b$,true),
('bunong-vn','NUM',12,9,null,$b$Nau Yêhôva ji nuih hit hâr ma khân păng jêh ri Păng du hăn.$b$,false),
('bunong-vn','NUM',12,10,null,$b$Tơ lah tŭk hao du tă bơh ngih bok, ta aơ H'Miriam geh phŭng, jêng nglang nâm bu pler. Y-Arôn rle uănh ma H'Miriam, saơ păng lĕ geh phŭng jêh.$b$,false),
('bunong-vn','NUM',12,11,null,$b$Y-Arôn lah ma Y-Môis, “Hơi kôranh gâp, lơi tâm rmal hên yor lah hên lĕ rluk jêh ri ƀư nau tih jêh.$b$,false),
('bunong-vn','NUM',12,12,null,$b$Lơi ta ăn ô băl jêng nâm bu du huê bunuyh hŏ rai jêh du n'gul nglay săk tơ lah ô băl luh du bơh ndŭl me.”$b$,false),
('bunong-vn','NUM',12,13,null,$b$Y-Môis nter ma Yêhôva, “Hơi Brah Ndu! Gâp vơh vơl ma may, ƀư bah an păng.”$b$,false),
('bunong-vn','NUM',12,14,null,$b$Ƀiă lah Yêhôva lah ma Y-Môis, “Tơ lah mbơ̆ păng soh jêh dak diu tra muh măt păng, mâu hĕ păng mra prêng dôl tâm pơh nar? Ăn bu krŭng păng pa dih mpâr dôl pơh nar; jêh nau nây bu dơi njŭn tay tâm nhuang ntŭk rmlak.$b$,false),
('bunong-vn','NUM',12,15,null,$b$Pô nây bu krŭng H'Miriam pa dih ntŭk rmlak dôl pơh nar; jêh ri phung ƀon lan mâu hŏ dâk hăn ôh tât bu plơ̆ njŭn tay H'Miriam rlet nhuang ntŭk.$b$,true),
('bunong-vn','NUM',12,16,null,$b$Jêh nau nây phung ƀon lan dâk hăn tă bơh Hasêrôt, jêh ri gŭ njơh tâm bri rdah Paran.$b$,false),
('bunong-vn','NUM',13,1,null,$b$Yêhôva lah ma Y-Môis,$b$,true),
('bunong-vn','NUM',13,2,null,$b$“Prơh bunuyh hăn uănh n'hut bri Kanaan, bri gâp mra ăn ma phung ƀon lan Israel. Ăn may prơh hăn du huê bunuyh bơh ăp mpôl khân păng, ăp nơm jêng kôranh tâm mpôl khân păng.”$b$,false),
('bunong-vn','NUM',13,3,null,$b$Pô ri Y-Môis prơh khân păng hăn tă bơh bri rdah Paran, tĭng nâm Yêhôva ntĭnh; lĕ rngôch khân păng jêng kôranh ma phung ƀon lan Israel.$b$,false),
('bunong-vn','NUM',13,4,null,$b$Aơ amoh khân păng: Y-Samua kon bu klâu Y-Sakur bơh mpôl Ruben;$b$,true),
('bunong-vn','NUM',13,5,null,$b$Y-Saphat kon bu klâu Y-Hôri bơh mpôl Simêôn;$b$,false),
('bunong-vn','NUM',13,6,null,$b$Y-Kalep kon bu klâu Y-Jêphunê bơh mpôl Yuđa;$b$,false),
('bunong-vn','NUM',13,7,null,$b$Y-Igai kon bu klâu Y-Yôsep bơh mpôl Isakar;$b$,false),
('bunong-vn','NUM',13,8,null,$b$Y-Hôsê kon bu klâu Y-Nun bơh mpôl Êphraim;$b$,false),
('bunong-vn','NUM',13,9,null,$b$Y-Palti kon bu klâu Y-Raphu bơh mpôl Benjamin;$b$,false),
('bunong-vn','NUM',13,10,null,$b$Y-Gadiel kon bu klâu Y-Sôdi bơh mpôl Sabulôn;$b$,false),
('bunong-vn','NUM',13,11,null,$b$Y-Gadi kon bu klâu Y-Susi bơh mpôl Yôsep (nâm bu ntĭt mpôl Manasê);$b$,false),
('bunong-vn','NUM',13,12,null,$b$Y-Amiel kon bu klâu Y-Gêmali bơh mpôl Dan;$b$,false),
('bunong-vn','NUM',13,13,null,$b$Y-Sêthur kon bu klâu Y-Miket bơh mpôl Aser;$b$,false),
('bunong-vn','NUM',13,14,null,$b$Y-Nahbi kon bu klâu Y-vôsi bơh mpôl Naptali;$b$,false),
('bunong-vn','NUM',13,15,null,$b$Y-Gêuel kon bu klâu Y-Maki bơh mpôl Gat.$b$,false),
('bunong-vn','NUM',13,16,null,$b$Aơ amoh phung bunuyh Y-Môis prơh hăn uănh n'hut bri. Y-Môis ntơ amoh ma Y-Hôsê, kon bu klâu Y-Nun jêng Y-Yôsuê.$b$,false),
('bunong-vn','NUM',13,17,null,$b$Pô nây, Y-Môis prơh hăn uănh n'hut n'gor bri Kanaan, jêh ri ntĭnh ntăn: “Ntơm bơh aơ hăn hom rlet bri Rđŭng ri, jêh ri hao leo klơ dor,$b$,false),
('bunong-vn','NUM',13,18,null,$b$jêh nây n'gơr uănh mâm n'gor bri jêng, jêh ri sek uănh gĭt lah bunuyh ƀon lan gŭ ta nây jêng ktang mâu lah huơi, gĭt lah khân păng jêng ƀhôi mâu lah âk.$b$,false),
('bunong-vn','NUM',13,19,null,$b$Gĭt lah bri khân păng gŭ nây jêng ueh mâu lah mhĭk, gĭt lah ƀon toyh khân păng gŭ jêng ntŭk njơh mâu lah pôih nâp,$b$,false),
('bunong-vn','NUM',13,20,null,$b$gĭt lah neh jêng ndô ndơ mâu lah mâu jêng ndơ ôh, gĭt lah geh tơm si ta nây mâu lah mâu. Ăn khân may geh nau janh nănh, jêh ri djôt leo ƀa ƀă play bơh bri Kanaan.” Nôk nây jêng yan play kriăk ƀâu ntơm dŭm.$b$,false),
('bunong-vn','NUM',13,21,null,$b$Pô nây khân păng hăn hao jêh ri uănh n'hut bri ntơm bơh bri rdah Sin tât ta ƀon Rêhôp, dăch mpông pêr ƀon Hamat.$b$,true),
('bunong-vn','NUM',13,22,null,$b$Khân păng hăn hao bơh bri Rđŭng jêh ri tât ta ƀon Hêbron; jêng ntŭk geh Y-Ahiam, Y-Sêsai jêh ri Y-Talmai, kon sau Y-Anak, gŭ ta nây. (Bu ndâk ƀon Hêbron lor pơh năm ma ƀon Sôan tâm bri Êjipt)$b$,true),
('bunong-vn','NUM',13,23,null,$b$Khân păng tât ta rlŭng Êskôl, ta nây khân păng te du n'gĭng tơm play kriăk ƀâu geh du rkŭm play kriăk ƀâu; jêh ri bar hê tâm tung ma mâng n'ger, khân păng djôt leo đŏng play pôm gra nat jêh ri play rvi.$b$,false),
('bunong-vn','NUM',13,24,null,$b$Bu ntơ ntŭk nây rlŭng Êskôl, yor rkŭm play kriăk ƀâu phung Israel te sŏk jêh tă bơh ntŭk nây.$b$,false),
('bunong-vn','NUM',13,25,null,$b$Lôch puăn jât nar khân păng plơ̆ sĭt tă bơh nau hăn uănh n'hut bri nây.$b$,true),
('bunong-vn','NUM',13,26,null,$b$Khân păng tât ma Y-Môis, Y-Arôn jêh ri ma lĕ rngôch phung ƀon lan Israel tâm rgum ta Kadês tâm bri rdah Paran. Khân păng sĭt nkoch bri ma khân păng jêh ri ma lĕ rngôch phung gŭ rgum iăt, khân păng mpơl ăn uănh play tă bơh n'gor nây.$b$,false),
('bunong-vn','NUM',13,27,null,$b$Pô ri, khân păng nkoch ăn ma Y-Môis pô aơ: “Hên tât jêh ma n'gor bri may prơh hên hăn; n'gor nây geh ndơ sông sa nhêt rmeh rmai jêh ri aơ play tă bơh n'gor nây.$b$,false),
('bunong-vn','NUM',13,28,null,$b$Ƀiă lah bunuyh ƀon lan gŭ tâm n'gor nây jêng ktang, jêh ri ƀon jêng toyh ngăn geh mpêr nâp; rmeh ma nây hên saơ ta nây phung kon sau Y-Anak.$b$,false),
('bunong-vn','NUM',13,29,null,$b$Phung Amalek gŭ tâm bri Rđŭng; phung Hitit, phung Jêbusit, jêh ri phung Amôrit gŭ tâm bri klơ dor; jêh ri phung Kanaan gŭ dăch dak mƀŭt jêh ri n'gŏ kơh dak krong Yurdan.”$b$,true),
('bunong-vn','NUM',13,30,null,$b$Ƀiă lah Y-Kalep ăn phung ƀon lan gŭ rklăk ta năp Y-Môis jêh ri lah, “Ăn he hăn hao ro jêh ri gŭ tâm n'gor bri nây, yor lah he dơi ngăn sŏk n'gor bri nây.”$b$,false);
insert into public.bible_verses (translation_id, book_code, chapter, verse, verse_end, text, para) values
('bunong-vn','NUM',13,31,null,$b$Nôk nây phung bu klâu hăn ndrel ma păng lah, “He mâu dơi hao lơh ôh ma phung ƀon lan nây; yor lah khân păng jêng ktang lơn ma he.”$b$,true),
('bunong-vn','NUM',13,32,null,$b$Pô ri khân păng nkoch bri ta năp phung ƀon lan Israel nau mhĭk ma n'gor bri khân păng hăn uănh n'hut jêh, lah: “N'gor bri hên nsong jêh hăn uănh n'hut jêng du n'gor bri sa phung ƀon lan păng nơm; jêh ri lĕ rngôch phung bunuyh hên saơ tâm n'gor bri nây jêng phung toyh juat.$b$,false),
('bunong-vn','NUM',13,33,null,$b$Jêh ri tâm n'gor bri nây hên saơ phung Nêphilim (phung kon sau Y-Anak, phung luh du tă bơh Nêphilim); hên uănh ma hên nơm nâm bu krah, jêh ri khân păng uănh ma hên tâm ban pô nây đŏng.”$b$,false),
('bunong-vn','NUM',14,1,null,$b$Jêh ri lĕ rngôch phung tâm rƀŭn nter huy; jêh ri phung ƀon lan nhĭm măng nây.$b$,true),
('bunong-vn','NUM',14,2,null,$b$Lĕ rngôch phung ƀon lan Israel ngơi ƀrôk tâm rdâng đah Y-Môis jêh ri Y-Arôn. Lĕ rngôch phung tâm rƀŭn lah ma khân păng, “Ueh lơn hên khĭt tâm n'gor bri Êjipt! Mâu lah ueh lơn hên khĭt tâm bri rdah aơ.$b$,true),
('bunong-vn','NUM',14,3,null,$b$Mâm Yêhôva ăn hên lăp tâm bri aơ gay ăn hên khĭt ma đao? Phung ur kon hên mra jêng ndơ khân păng sŏk gro. Bi ma hên, mâu ueh hĕ ăn ma hên plơ̆ sĭt rlet ma n'gor bri Êjipt?”$b$,false),
('bunong-vn','NUM',14,4,null,$b$Khân păng lah ndrăng khân păng, “Ăn he săch du huê kôranh jêh ri plơ̆ sĭt tay ma n'gor bri Êjipt.”$b$,false),
('bunong-vn','NUM',14,5,null,$b$Nôk nây Y-Môis jêh ri Y-Arôn chon mon chŭn muh măt ta neh ta năp lĕ rngôch phung ƀon lan Israel tâm rƀŭn.$b$,false),
('bunong-vn','NUM',14,6,null,$b$Jêh ri đơ phung hăn uănh n'hut jêh n'gor bri, Y-Yôsuê kon bu klâu Y-Nun jêh ri Y-Kalep kon bu klâu Y-Jêphunê, nkhêk bok ao khân păng nơm,$b$,false),
('bunong-vn','NUM',14,7,null,$b$jêh ri lah ma lĕ rngôch phung ƀon lan Israel tâm rƀŭn, “N'gor bri hên hăn uănh n'hut jêng du n'gor bri ueh ngăn ngên.$b$,false),
('bunong-vn','NUM',14,8,null,$b$Tơ lah Yêhôva maak đah he, păng mra njŭn he lăp tâm n'gor bri nây jêh ri ăn păng ma he, du n'gor bri geh ndơ sông sa nhêt rmeh rmai.$b$,false),
('bunong-vn','NUM',14,9,null,$b$Knŏng lơi ta tâm rdâng ôh đah Yêhôva; Jêh ri lơi ta klach ôh ma bunuyh ƀon lan tâm n'gor bri nây, yor lah khân păng jêng ndơ sông sa ma he; bu sŏk lơi jêh nau king tă bơh khân păng, jêh ri Yêhôva gŭ ndrel ma he; lơi ta klach ôh ma khân păng.”$b$,true),
('bunong-vn','NUM',14,10,null,$b$Ƀiă lah lĕ rngôch phung tâm rgum ngơi ŭch klŭp khân păng ma lŭ. Nôk nây nau chrêk ma lơp Yêhôva tâm mpơl ta ngih bok tâm rƀŭn ma lĕ rngôch phung ƀon lan Israel.$b$,true),
('bunong-vn','NUM',14,11,null,$b$Jêh ri Yêhôva lah ma Y-Môis, “Ndah hŏ jŏ phung ƀon lan aơ ŭch tâm rmot ma gâp? Jêh ri ndah nâm jŏ khân păng mâu mra chroh ôh ma gâp, nđâp tơ lah lĕ rngôch nau mbên gâp hŏ ƀư jêh ta nklang khân păng kđôi?$b$,false),
('bunong-vn','NUM',14,12,null,$b$Gâp mra dong khân păng ma nau ji tưp khĭt jêh ri mra sŏk sĭt tă bơh khân păng drăp ndơn, jêh ri gâp mra njêng bơh may du mpôl băl toyh lơn jêh ri ktang lơn ma khân păng.”$b$,true),
('bunong-vn','NUM',14,13,null,$b$Ƀiă lah Y-Môis lah ma Yêhôva, “Phung Êjipt mra tăng nau nây, yor lah may ngluh jêh phung ƀon lan aơ ma nau brah may bơh nklang khân păng,$b$,false),
('bunong-vn','NUM',14,14,null,$b$jêh ri khân păng mra mbơh ma phung ƀon lan bri aơ. Hơi Yêhôva, khân păng tăng jêh ma may gŭ ta nklang phung ƀon lan aơ; yor lah may tâm mpơl jêh ăn bu saơ may, Hơi Yêhôva, n'gâng tŭk may ta klơ khân păng jêh ri may hăn pa năp khân păng tâm n'gâng tŭk dôl nar jêh ri tâm meh n'gâng ŭnh dôl măng.$b$,false),
('bunong-vn','NUM',14,15,null,$b$Tơ lah may nkhĭt lơi phung ƀon lan aơ nâm bu nkhĭt du huê bunuyh, phung mpôl băl bunuyh tăng jêh nau lư n'găr may mra lah,$b$,false),
('bunong-vn','NUM',14,16,null,$b$‘Yor lah Yêhôva mâu dơi ôh njŭn phung ƀon lan aơ ma bri păng sơm ton ăn jêh ma khân păng, yor nây păng nkhĭt khân păng tâm bri rdah.’$b$,false),
('bunong-vn','NUM',14,17,null,$b$Aƀaơ ri, gâp vơh vơl ma may, ăn nau brah Yêhôva jêng toyh jêh dôl lah,$b$,false),
('bunong-vn','NUM',14,18,null,$b$‘Yêhôva mâu gơnh nuih ôh, jêh ri ndrŏng ma nau rŏng răp jăp, yô̆ ăn nau kue jêh ri nau rlau nau vay, ƀiă lah mâu păng mâu kơp sŏng ôh nơm tih jêh ri ntŭp nau kue phung mbơ̆ ma phung kon kŏ tât ta pe jêh ri puăn rô̆ !$b$,false),
('bunong-vn','NUM',14,19,null,$b$Yô̆ an ma nau kue phung ƀon lan aơ, gâp vơh vơl ma may, tĭng nâm nau toyh nau may rŏng răp jăp, jêh ri tĭng nâm nau may yô̆ an jêh ma phung ƀon lan aơ tă bơh n'gor bri Êjipt tât ma aƀaơ ri.”$b$,false),
('bunong-vn','NUM',14,20,null,$b$Jêh ri Yêhôva lah, “Gâp yô̆ an jêh tĭng nâm nau may dăn.$b$,true),
('bunong-vn','NUM',14,21,null,$b$Ƀiă lah n'hêl nanê̆, yor gâp gŭ rêh, jêh ri lĕ neh ntu mra bêng ma nau chrêk ma lơp Yêhôva,$b$,false),
('bunong-vn','NUM',14,22,null,$b$mâu geh du huê tâm phung saơ jêh nau chrêk ma lơp gâp jêh ri nau tâm mbên gâp hŏ ƀư jêh tâm n'gor bri Êjipt jêh ri tâm bri rdah, ƀiă lah ăt rlong uănh jêh gâp jât tơ̆ aơ jêh ri mâu ŭch iăt nau gâp ôh,$b$,false),
('bunong-vn','NUM',14,23,null,$b$mra saơ n'gor bri gâp sơm ton jêh gay ăn ma phung chô che khân păng; jêh ri mâu geh du huê ôh tâm phung tâm rmot jêh ma gâp mra saơ n'gor bri nây.$b$,false),
('bunong-vn','NUM',14,24,null,$b$Ƀiă lah oh mon gâp Y-Kalep, yor lah păng geh nau mĭn êng jêh ri ŭch tĭng ndô̆ gâp ma lĕ nuih n'hâm, gâp mra njŭn păng lăp tâm n'gor bri păng lĕ hăn jêh, jêh ri phung kon sau păng mra ndơn chăm n'gor bri nây.$b$,true),
('bunong-vn','NUM',14,25,null,$b$Aƀaơ ri yor phung Amalek jêh ri phung Kanaan gŭ tâm rlŭng, ôi taơ ăn khân may rle plơ̆ pa kơi, hăn tât bri rdah mpeh ma Dak Mƀŭt Chăng.”$b$,true),
('bunong-vn','NUM',14,26,null,$b$Yêhôva lah ma Y-Môis jêh ri ma Y-Arôn,$b$,true),
('bunong-vn','NUM',14,27,null,$b$“Ndah nâm jŏ phung janh ƀai aơ tâm rƀŭn mra ngơi ƀrôk tâm rdâng đah gâp? Gâp hŏ tăng jêh nau phung ƀon lan Israel ngơi ƀrôk, nau khân păng ngơi ƀrôk tâm rdâng đah gâp.$b$,false),
('bunong-vn','NUM',14,28,null,$b$Lah hom ma khân păng, ‘Yêhôva lah, Yor gâp gŭ rêh, moh nau khân may ngơi jêh ma tôr gâp, gâp mra ƀư khân may:$b$,false),
('bunong-vn','NUM',14,29,null,$b$Săk jăn khân may khĭt mra cha lôt tâm bri rdah aơ; jêh ri tâm lĕ rngôch rnoh kơp jêh bơh nơm geh ntơm bar jât năm bơi rlau, phung ngơi ƀrôk tâm rdâng jêh đah gâp,$b$,false),
('bunong-vn','NUM',14,30,null,$b$mâu geh du huê mra lăp ôh tâm n'gor bri gâp sơm ton jêh gay ăn khân may gŭ, knŏng Y-Kalep kon bu klâu Y-Jêphunê jêh ri Y-Yôsuê kon bu klâu Y-Nun.$b$,false),
('bunong-vn','NUM',14,31,null,$b$Ƀiă lah phung kon jê̆ khân may, phung khân may lah jêh mra jêng ndơ bu sŏk gro, gâp mra njŭn khân păng lăp, jêh ri khân păng mra gĭt năl n'gor bri khân may hŏ tâm rmot jêh.$b$,false),
('bunong-vn','NUM',14,32,null,$b$Bi khân may, săk jăn khân may khĭt mra cha lôt tâm bri rdah aơ.$b$,true),
('bunong-vn','NUM',14,33,null,$b$Jêh ri phung kon khân may mra jêng phung rmăk biăp tâm bri rdah dôl puăn jât năm, jêh ri mra dơm nau rêh ni yor nau khân may mâu ŭch chroh ôh, kŏ tât săk jăn nơm nglĕ dŭt tâm phung khân may cha lôt jêh tâm bri rdah.$b$,false),
('bunong-vn','NUM',14,34,null,$b$Tĭng nâm ndah âk nar khân may hăn uănh n'hut jêh n'gor bri nây, jêng puăn jât nar, pô ri khân may mra anh nau kue khân may dôl puăn jât năm, du năm ma ăp nar, jêh ri khân may mra gĭt năl nau gâp mâu maak ôh ma khân may!$b$,true),
('bunong-vn','NUM',14,35,null,$b$Gâp yơh Yêhôva hŏ ngơi jêh! N'hêl nanê̆ pô aơ gâp mra ƀư ma lĕ rngôch phung janh ƀai tâm rƀŭn aơ, phung gŭ tâm rƀŭn ndrel tâm rdâng đah gâp; tâm bri rdah aơ khân păng mra rai lôch lĕ ro, jêh ri ta nây khân păng mra khĭt.”$b$,false),
('bunong-vn','NUM',14,36,null,$b$Phung bunuyh Y-Môis prơh hăn jêh ăn hăn uănh n'hut n'gor bri nây, jêh ri sĭt jêh nsônh ăn lĕ rngôch phung tâm rƀŭn ngơi ƀrôk tâm rdâng đah păng dôl nkoch bri nau mhĭk ma n'gor bri nây,$b$,true),
('bunong-vn','NUM',14,37,null,$b$phung bunuyh nkoch bri nau mhĭk ma n'gor bri nây khĭt ma nau tât mhĭk ta năp Yêhôva.$b$,false),
('bunong-vn','NUM',14,38,null,$b$Ƀiă lah Y-Yôsuê, kon bu klâu Y-Nun jêh ri Y-Kalep kon bu klâu Y-Jephunê hôm e rêh đơ phung hăn jêh uănh n'hut n'gor bri nây.$b$,false),
('bunong-vn','NUM',14,39,null,$b$Y-Môis ngơi nau aơ ma lĕ rngôch phung ƀon lan Israel, jêh ri phung ƀon lan nhhiăng nhĭm hâu ngăn.$b$,true),
('bunong-vn','NUM',14,40,null,$b$Khân păng kah rngăl ơm ôi jêh ri hao ta ntŭk klơ yôk bri klơ dor, lah, “Uănh hom, hên ta aơ, hên mra hăn hao rlet ntŭk Yêhôva ton jêh; yor lah hên ƀư tih jêh”$b$,false),
('bunong-vn','NUM',14,41,null,$b$Ƀiă lah Y-Môis lah, Mâm aƀaơ ri khân may rlau nau Yêhôva ntĭnh, yor lah nau nây mâu mra dơi ôh?$b$,false),
('bunong-vn','NUM',14,42,null,$b$Lơi ta hăn hao ôh klach lah khân may cha lôt pa năp phung rlăng khân may, yor lah Yêhôva mâu gŭ ta nklang khân may ôh.$b$,false),
('bunong-vn','NUM',14,43,null,$b$Yor lah ta nây phung Amalek jêh ri phung Kanaan gŭ pa năp khân may, jêh ri khân may mra cha lôt ma mpiăt đao; yor lah khân may cha lơi mâu hôm tĭng ndô̆ ôh Yêhôva, Yêhôva mâu mra gŭ ndrel ôh ma khân may.”$b$,true),
('bunong-vn','NUM',14,44,null,$b$Ƀiă lah khân păng ăt hăn hao ta ntŭk klơ bri dor; bi ma hip nau tâm rnglăp Yêhôva jêh ri Y-Môis mâu ŭch ăn luh ôh tă bơh nhuang ntŭk rmlak.$b$,false),
('bunong-vn','NUM',14,45,null,$b$Pô ri phung Amalek jêh ri phung Kanaan gŭ tâm bri klơ dor nây trŭnh rduh ran lơh rai jêh ri tĭng khân păng tât ta ƀon Hôrma.$b$,false),
('bunong-vn','NUM',15,1,null,$b$Yêhôva lah ma Y-Môis,$b$,true),
('bunong-vn','NUM',15,2,null,$b$Lah hom ma phung ƀon lan Israel, Tơ lah khân may lăp tâm n'gor bri gâp ăn ma khân may gŭ,$b$,false),
('bunong-vn','NUM',15,3,null,$b$jêh ri khân may nhhơr ma Yêhôva ndrôk mâu lah biăp du ndơ nhhơr ăn ŭnh sa du ndơ nhhơr gŭch mâu lah du ndơ ƀư brah ăn nanê̆ nau ton mâu lah du ndơ nhhơr ma nau ŭch mâu lah tâm nar năng khân may tâm nal jêh, gay nkra n'hôl ƀâu kah ma Yêhôva,$b$,false),
('bunong-vn','NUM',15,4,null,$b$pô nây nơm djôt leo ndơ păng nhhơr mra nhhơr ma Yêhôva jêng ndơ nhhơr rnih muy tâm pot đah du kô̆ tâm puăn hin dak play ôlivơ,$b$,false),
('bunong-vn','NUM',15,5,null,$b$jêh ri dak play kriăk ƀâu prăp ma ndơ nhhơr nhêt du kô̆ tâm puăn hin may mra nkra ndrel ma ndơ nhhơr gŭch, mâu lah ma ndơ ƀư brah, ma ăp mlâm biăp kon.$b$,false),
('bunong-vn','NUM',15,6,null,$b$Mâu lah du mlâm biăp nkuăng ăn may nkra prăp ma ndơ nhhơr rnih muy tâm pot đah du kô̆ tâm pe hin dak play ôlivơ,$b$,false),
('bunong-vn','NUM',15,7,null,$b$jêh ri prăp ma ndơ nhhơr nhêt ăn may nhhơr du kô̆ tâm pe hin dak play kriăk ƀâu jêng n'hôl ƀâu kah ma Yêhôva.$b$,false),
('bunong-vn','NUM',15,8,null,$b$Tơ lah may nkra du mlâm ndrôk nkuăng jêng ndơ nhhơr gŭch, mâu lah jêng ndơ ƀư brah ăn nanê̆ nau ton, mâu lah jêng ndơ nhhơr ma nau đăp mpăn ma Yêhôva.$b$,false),
('bunong-vn','NUM',15,9,null,$b$Pô ri ăn bu nhhơr ndrel ma ndrôk nkuăng ndơ nhhơr rnih muy pe kô̆ tâm jât êpha rnih muy tâm pot đah du n'gul hin dak play ôlivơ,$b$,false),
('bunong-vn','NUM',15,10,null,$b$jêh ri ăn may nhhơr ndơ nhhơr nhêt du n'gul hin dak play kriăk ƀâu jêng ndơ nhhơr ăn ŭnh sa, n'hôl ƀâu kah ma Yêhôva.$b$,false),
('bunong-vn','NUM',15,11,null,$b$Pô ri ăn bu ƀư ma ăp mlâm ndrôk nkuăng, biăp nkuăng, ăp mlâm biăp kon nkuăng, mâu lah be kon.$b$,false),
('bunong-vn','NUM',15,12,null,$b$Tĭng nâm ndah khân may nkra, pô nây khân may mra ƀư ma ăp mlâm tĭng nâm ndah geh khân păng.$b$,false),
('bunong-vn','NUM',15,13,null,$b$Lĕ rngôch bunuyh ƀon lah nơm mra ƀư tĭng nâm nau vay aơ dôl nhhơr du ndơ nhhơr ăn ŭnh sa, geh n'hôl ƀâu kah ma Yêhôva.$b$,false),
('bunong-vn','NUM',15,14,null,$b$Tơ lah du huê bu năch gŭ njơh ƀât lât ndrel ma khân may, mâu lah tơ lah geh du huê gŭ ta nklang khân may tâm lĕ rngôch rô̆ khân may, jêh ri păng gay nhhơr du ndơ nhhơr ăn ŭnh sa, n'hôl ƀâu kah ma Yêhôva ăn phung ƀư nâm bu khân may ƀư.$b$,false),
('bunong-vn','NUM',15,15,null,$b$Ma phung tâm rƀŭn mra geh du nau vay ma khân may jêh ri ma phung bu năch gŭ njơh ƀât lât ndrel ma khân may, du nau vay gŭ mro mrăng tâm lĕ rngôch rô̆ khân may; nơm gŭ ƀât lât mra jêng nâm bu khân may jêng ta năp Yêhôva.$b$,false),
('bunong-vn','NUM',15,16,null,$b$Du nau vay jêh ri du nau ntăm mra di ma khân may jêh ri ma bu năch gŭ njơh ƀât lât ndrel ma khân may.”$b$,true),
('bunong-vn','NUM',15,17,null,$b$Yêhôva lah ma Y-Môis,$b$,false),
('bunong-vn','NUM',15,18,null,$b$“Lah hom ma phung ƀon lan Israel, Tơ lah khân may tât tâm n'gor bri gâp njŭn khân may lăp,$b$,false),
('bunong-vn','NUM',15,19,null,$b$jêh ri tơ lah khân may sa piăng let n'gor bri nây, ăn khân may nhhơr du ndơ nhhơr ma Yêhôva.$b$,false),
('bunong-vn','NUM',15,20,null,$b$Khân may sŏk bơh rnih ntơm sa ơm lơn ê hŏ môi, ăn khân may nhhơr du glo ƀănh jêng ndơ nhhơr; khân may mra nhhơr păng jêng ndơ nhhơr bơh ntŭk mprah ba.$b$,true),
('bunong-vn','NUM',15,21,null,$b$Ntơm bơh rô̆ aơ tât rô̆ ô klak, khân may mra nhhơr ma Yêhôva du ndơ nhhơr rnih ê hŏ môi khân may ntơm sa ơm lơn.$b$,true),
('bunong-vn','NUM',15,22,null,$b$“Ƀiă lah tơ lah khân may ƀư tih jêh ri mâu ƀư tĭng ndô̆ ôh lĕ rngôch nau ntĭnh aơ Yêhôva ngơi jêh ma Y-Môis,$b$,true),
('bunong-vn','NUM',15,23,null,$b$lĕ rngôch nau Yêhôva ntĭnh jêh ma khân may đah Y-Môis ntơm bơh nar Yêhôva ăn jêh nau ntĭnh jêh ri du nar kăndơ̆ tâm lĕ rngôch rô̆ khân may,$b$,false),
('bunong-vn','NUM',15,24,null,$b$tơ lah bu ƀư tih jêh ma nau mâu mra ŭch ôh, phung tâm rƀŭn mâu gĭt ôh nau nây, lĕ rngôch phung tâm rƀŭn mra nhhơr du mlâm ndrôk nkuăng rah jêng ndơ nhhơr gŭch, n'hôl ƀâu kah ma Yêhôva, ndrel ma ndơ nhhơr rnih muy jêh ri ndơ nhhơr nhêt tĭng nâm nau vay, jêh ri du mlâm be nkuăng jêng ndơ nhhơr chuai yor nau tih.$b$,false),
('bunong-vn','NUM',15,25,null,$b$Kôranh ƀư brah mra ƀư nau chuai ăn kloh nau tih ma lĕ rngôch phung ƀon lan Israel tâm rƀŭn, jêh ri khân păng mra geh nau yô̆ an, yor lah khân păng ƀư tih jêh ma nau vĭ, jêh ri khân păng djôt leo jêh ndơ khân păng nhhơr, du ndơ nhhơr ăn ŭnh sa ma Yêhôva, jêh ri ndơ khân păng nhhơr yor nau tih khân păng ta năp Yêhôva yor nau tih khân păng vĭ.$b$,false),
('bunong-vn','NUM',15,26,null,$b$Mra geh nau yô̆ an ma lĕ rngôch phung ƀon lan Israel tâm rƀŭn jêh ri ma bunuyh bu năch gŭ njơh ƀât lât ta nklang khân păng, yor lah lĕ rngôch phung ƀon lan tih jêh yor nau vĭ nây.$b$,false),
('bunong-vn','NUM',15,27,null,$b$“Tơ lah du huê bunuyh lĕ lăn ƀư tih ma nau mâu mra ŭch ôh, ăn păng nhhơr du mlâm be me geh du năm deh jêng ndơ nhhơr chuai yor nau tih.$b$,false),
('bunong-vn','NUM',15,28,null,$b$Jêh ri kôranh ƀư brah mra ƀư nau ăn kloh nau tih ta năp Yêhôva ma bunuyh ƀư nau tih vĭ, tơ lah păng lĕ lăn ƀư tih ma nau mâu ŭch, gay ƀư nau ăn kloh nau tih ma păng; jêh ri păng mra geh nau yô̆ an.$b$,false),
('bunong-vn','NUM',15,29,null,$b$Khân may mra geh du nau vay ma nơm lĕ lăn ƀư tih ma nau mâu ŭch ma bunuyh ƀon lan nơm tâm phung ƀon lan Israel, jêh ri ma bunuyh bu năch gŭ njơh ƀât lât ta nklang khân păng.$b$,false),
('bunong-vn','NUM',15,30,null,$b$Ƀiă lah nơm ƀư ma nau ŭch tâm rdâng, gĭt lah păng jêng bunuyh ƀon lan nơm mâu lah nơm gŭ njơh ƀât lât, suai rak ma Yêhôva, nơm nây ăn bu ƀư ngroh lơi bơh nklang phung ƀon lan păng.$b$,false),
('bunong-vn','NUM',15,31,null,$b$Yor lah păng tâm rmot ma nau Yêhôva ngơi, jêh ri rlau nau Păng ntĭnh nơm nây ăn bu ƀư ngroh lơi; nau kue păng mra tŭp ma păng.”$b$,false),
('bunong-vn','NUM',15,32,null,$b$Dôl phung ƀon lan Israel gŭ tâm bri rdah, khân păng saơ du huê bunuyh dônh long nar Saƀat.$b$,true),
('bunong-vn','NUM',15,33,null,$b$Phung saơ păng gŭ dônh long njŭn leo păng ma Y-Môis jêh ri Y-Arôn, jêh ri ma lĕ rngôch phung tâm rƀŭn.$b$,false),
('bunong-vn','NUM',15,34,null,$b$Bu krŭng păng, yor lah ê hŏ nanê̆ ôh moh bu mra ƀư ma păng.$b$,false),
('bunong-vn','NUM',15,35,null,$b$Yêhôva lah ma Y-Môis, “Bunuyh aơ ăn bu nkhĭt; ăn lĕ rngôch phung tâm rƀŭn klŭp lŭ ta păng ta pa dih mpâr.”$b$,false),
('bunong-vn','NUM',15,36,null,$b$Jêh ri lĕ rngôch phung tâm rƀŭn njŭn păng luh du bơh nhuang ntŭk rmlak, jêh ri klŭp nkhĭt păng ma lŭ, tĭng nâm Yêhôva ntĭnh jêh ma Y-Môis.$b$,true),
('bunong-vn','NUM',15,37,null,$b$Yêhôva lah ma Y-Môis:$b$,true),
('bunong-vn','NUM',15,38,null,$b$“Ngơi hom ma phung ƀon lan Israel, jêh ri ăn khân păng ƀư grong ta bôl n'har ao khân păng tâm lĕ rngôch rô̆ khân păng, jêh ri ăn khân păng dơm du rtai rse ĭr ta grong ta bôl n'har ao khân păng.$b$,false),
('bunong-vn','NUM',15,39,null,$b$Ndơ nây mra jêng ma khân may du ntŭk grong prăp uănh jêh ri kah gĭt ma lĕ rngôch nau Yêhôva ntĭnh, jêh ri mâu tĭng ndô̆ ôh nau nuih n'hâm jêh ri măt khân may nơm, ndơ ntrôl khân may tĭng nau khân may nơm kơnh.$b$,false),
('bunong-vn','NUM',15,40,null,$b$Pô ri khân may mra kah gĭt jêh ri ƀư lĕ rngôch nau gâp ntĭnh, jêh ri jêng kloh ueh ma Brah Ndu khân may.$b$,false),
('bunong-vn','NUM',15,41,null,$b$Gâp jêng Brah Ndu khân may nơm njŭn khân may du luh jêh tă bơh n'gor bri Êjipt, gay jêng Brah Ndu khân may. Gâp jêng Yêhôva, Brah Ndu khân may.”$b$,false),
('bunong-vn','NUM',16,1,null,$b$Y-Kôrê kon bu klâu Y-Ishar, Sau Y-Kôhat, se Y-Lêvi, jă ndrel Y-Dathan jêh ri Y-Abiram, phung kon bu klâu Y-Êliap, ndrel ma Y-Ôn kon bu klâu Y-Pêlet, phung sau Y-Ruben,$b$,true),
('bunong-vn','NUM',16,2,null,$b$sŏk âk bunuyh jêh ri dâk ta năp Y-Môis ndrel ma phung bar rhiăng prăm jât nuyh phung kôranh tâm phung Israel tâm rƀŭn, phung bu hŏ săch jêh, phung geh lư n'găr.$b$,false),
('bunong-vn','NUM',16,3,null,$b$Khân păng tâm rƀŭn ndrel tâm rdâng đah Y-Môis jêh ri Y-Arôn, jêh ri lah ma khân păng, “Khân may ƀư jêh rmeh ir! Yor lah lĕ rngôch phung tâm rƀŭn jêng kloh ueh, ăp nơm khân păng, jêh ri Yêhôva gŭ ta nklang khân păng. Pô ri mâm khân may tâm n'hao khân may nơm ta klơ lơn ma phung Yêhôva tâm rƀŭn?”$b$,false),
('bunong-vn','NUM',16,4,null,$b$Tơ lah Y-Môis tăng nau nây păng chŭn muh măt ta neh,$b$,true),
('bunong-vn','NUM',16,5,null,$b$jêh ri păng lah ma Y-Kôrê jêh ri ma lĕ rngôch phung păng, “Ôi taơ Yêhôva mra tâm mpơl mbu nơm jêng ndơ păng, jêh ri mbu nơm jêng kloh ueh, jêh ri ăn nơm nây hăn dăch păng, nơm păng mra săch păng mra ăn hăn dăch păng.$b$,false),
('bunong-vn','NUM',16,6,null,$b$Ƀư hom nau aơ: Sŏk hom khăl su ndơ ƀâu kah, Y-Kôrê jêh ri lĕ rngôch phung păng.$b$,false),
('bunong-vn','NUM',16,7,null,$b$Ôi taơ dơm ŭnh tâm khăl nây jêh ri dơm ndơ ƀâu kah tâm nây pa năp Yêhôva, jêh ri nơm Yêhôva mra săch jêng nơm kloh ueh. Khân may ƀư jêh rmeh ir, Hơi phung kon bu klâu Lêvi!”$b$,true),
('bunong-vn','NUM',16,8,null,$b$Yêhôva lah ma Y-Kôrê, “Iăt hom, hơi phung kon bu klâu Lêvi:$b$,false),
('bunong-vn','NUM',16,9,null,$b$Di lĕ jêng du nau jê̆ ir ma khân may nau Brah Ndu phung Israel săch jêh khân may bơh phung Israel tâm rƀŭn, gay njŭn khân may dăch păng, gay ƀư kan tâm ngih bok Yêhôva, jêh ri gŭ ngao ta năp phung tâm rƀŭn gay pah kan ma khân păng;$b$,false),
('bunong-vn','NUM',16,10,null,$b$jêh ri nau păng ăn may hăn dăch păng, jêh ri lĕ rngôch phung oh nâu may phung kon bu klâu Lêvi ndrel ma may? Jêh ri khân may joi pah kan ma kôranh brah lĕ?$b$,false),
('bunong-vn','NUM',16,11,null,$b$Yor nây may jêh ri lĕ rngôch phung tâm rƀŭn ndrel ma may rgum gay ŭch tâm rdâng đah Yêhôva ro. Mbu Y-Arôn jêng kŏ tât khân may ngơi ƀrôk tâm rdâng đah păng?”$b$,false),
('bunong-vn','NUM',16,12,null,$b$Y-Môis prơh bu hăn kuăl Y-Dathan jêh ri Y-Abiram phung kon bu klâu Y-Êliap; jêh ri khân păng lah, “Hên mâu mra văch ôh.$b$,true),
('bunong-vn','NUM',16,13,null,$b$Di lĕ jêng du nau jê̆ nau may ăn hên du luh bơh n'gor geh ndơ sông sa nhêt rmeh rmai, gay ŭch nkhĭt hên tâm bri rdah, gay njêng may nơm kôranh hên?$b$,true),
('bunong-vn','NUM',16,14,null,$b$Jêh ri may mâu njŭn hên lăp ôh tâm du n'gor bri geh ndơ sông sa nhêt rmeh rmai, mâu lĕ ŭch ăn ma hên mir jêh ri tơm play kriăk ƀâu jêng ndơ ndơn drăp. May ŭch rloch găr măt phung hên. Hên mâu mra văch ôh.”$b$,true),
('bunong-vn','NUM',16,15,null,$b$Y-Môis ji nuih ngăn, jêh ri lah ma Yêhôva, “Lơi ta yơk ôh ma ndơ khân păng nhhơr. Gâp mâu mâp sŏk tă bơh khân păng du mlâm seh bri ôh, jêh ri gâp mâu mâp ƀư nau mhĭk ôh ma du huê khân păng.”$b$,true),
('bunong-vn','NUM',16,16,null,$b$Y-Môis lah ma Y-Kôrê, “Ăn may jêh ri lĕ rngôch phung ndrel ma may mpơl khân may nơm pa năp Yêhôva ôi taơ, may, khân păng, jêh ri Y-Arôn.$b$,true),
('bunong-vn','NUM',16,17,null,$b$Ăn ăp nơm sŏk khăl su ndơ ƀâu kah păng, jêh ri dơm ndơ ƀâu kah tâm nây, jêh ri ăp nơm khân may leo khăl su ndơ ƀâu kah păng ta năp Yêhôva, bar rhiăng prăm jât mlâm khăl su ndơ ƀâu kah, nđâp may jêh ri Y-Arôn, ăp nơm leo khăl su ndơ ƀâu kah păng.”$b$,false),
('bunong-vn','NUM',16,18,null,$b$Pô ri ăp nơm khân păng sŏk khăl su ndơ ƀâu kah păng, dơm ŭnh tâm nây, jêh ri dơm ndơ ƀâu kah tâm nây, jêh ri khân păng dâk ta mpông ngih bok tâm rƀŭn ndrel ma Y-Môis jêh ri Y-Arôn.$b$,false),
('bunong-vn','NUM',16,19,null,$b$Jêh ri Y-Kôrê tâm rƀŭn lĕ rngôch phung ƀon lan tâm rdâng đah khân păng ta mpông ngih bok tâm rƀŭn. Jêh ri nau chrêk ma lơp Yêhôva tâm mpơl ma lĕ rngôch phung tâm rƀŭn.$b$,true),
('bunong-vn','NUM',16,20,null,$b$Yêhôva lah ma Y-Môis jêh ri Y-Arôn,$b$,false),
('bunong-vn','NUM',16,21,null,$b$“Tâm nkhah hom khân may nơm đah phung tâm rƀŭn aơ, gay ma gâp dơi ƀư rai khân păng ƀât lât dơm.”$b$,false),
('bunong-vn','NUM',16,22,null,$b$Khân păng chŭn muh măt ta neh jêh ri lah, “Hơi Brah Ndu, Brah Ndu ma huêng lĕ rngôch nglay săk, du huê bunuyh ƀư tih jêh ri may ji nuih nđâp ma lĕ rngôch bunuyh tâm rƀŭn lĕ?$b$,true),
('bunong-vn','NUM',16,23,null,$b$Yêhôva lah ma Y-Môis,$b$,false),
('bunong-vn','NUM',16,24,null,$b$“Lah hom ma phung tâm rƀŭn, Du hom khân may ngai bơh ngih Y-Kôrê, Y-Dathan jêh ri Y-Abiram.”$b$,false),
('bunong-vn','NUM',16,25,null,$b$Jêh nây Y-Môis dâk hăn ma Y-Dathan jêh ri Y-Abiram; jêh ri phung bu bŭnh bu ranh phung Israel tĭng ndô̆ păng.$b$,true),
('bunong-vn','NUM',16,26,null,$b$Păng lah ma phung tâm rƀŭn, “Gâp vơl dăn ma khân may du hom tă bơh ngih bok phung janh ƀai aơ, jêh ri lơi pah bi ôh du ntil ndơ bơh ndô ndơ khân păng, klach lah khân may roh hêt ndrel ma lĕ rngôch nau tih khân păng.”$b$,false),
('bunong-vn','NUM',16,27,null,$b$Pô ri khân păng du ngai bơh ngih Y-Kôrê, Y-Dathan jêh ri Y-Abiram. Pô nây Y-Dathan jêh ri Y-Abiram luh dâk ta mpông ngih bok khân păng, ndrel ma ur khân păng, phung kon bu klâu khân păng, jêh ri kon jê̆ khân păng.$b$,false),
('bunong-vn','NUM',16,28,null,$b$Y-Môis lah, “Pô aơ khân may mra gĭt năl ma Yêhôva prơh gâp hăn ăn ƀư lĕ kan aơ, jêh ri nau nây mâu di tĭng nâm gâp nơm ŭch ôh.$b$,false),
('bunong-vn','NUM',16,29,null,$b$Tơ lah phung aơ khĭt nâm bu lĕ rngôch phung bunuyh êng khĭt, mâu lah tơ lah tât ma khân păng nâm bu vay tât ma lĕ rngôch bunuyh, pô nây Yêhôva mâu mra prơh ôh gâp hăn.$b$,true),
('bunong-vn','NUM',16,30,null,$b$Ƀiă lah tơ lah Yêhôva ƀư du nau mhe, jêh ri neh hă mbung păng jêh ri rvăn ndrêh khân păng ndrel ma lĕ rngôch ndô ndơ khân păng, jêh nây khân păng trŭnh tâm ƀon phung khĭt, pô ri khân may mra gĭt ma phung aơ tâm rmot jêh ma Yêhôva.$b$,false),
('bunong-vn','NUM',16,31,null,$b$Lah lĕ lôch jêh Y-Môis ngơi nau aơ, neh tâm dâng khân păng đang ro;$b$,true),
('bunong-vn','NUM',16,32,null,$b$Jêh ri neh hă mbung păng rvăn lơi khân păng, ndrel ma ngih khân păng jêh ri lĕ rngôch bunuyh Y-Kôrê jêh ri lĕ rngôch ndô ndơ khân păng.$b$,false),
('bunong-vn','NUM',16,33,null,$b$Pô ri khân păng dôl hôm e rêh nđâp lĕ rngôch ndô ndơ khân păng trŭnh tâm ƀon phung khĭt; jêh ri neh njĭr tay ta klơ khân păng; jêh nây khân păng rai lôch tă bơh nklang phung tâm rƀŭn.$b$,false),
('bunong-vn','NUM',16,34,null,$b$Lĕ rngôch phung Israel gŭ jŭm nchuăt du tăng khân păng nter, yor lah khân păng lah, “Klach lah neh rvăn rhôp he!”$b$,true),
('bunong-vn','NUM',16,35,null,$b$Jêh nây ŭnh luh tă bơh Yêhôva su phung bar rhiăng prăm jât nuyh bu klâu nhhơr ndơ ƀâu kah.$b$,false),
('bunong-vn','NUM',16,36,null,$b$Yêhôva lah ma Y-Môis:$b$,false),
('bunong-vn','NUM',16,37,null,$b$“Lah hom ma Y-Êlêasar kon bu klâu Y-Arôn kôranh ƀư brah, ăn păng sŏk khăl su ndơ ƀâu kah bơh nau ŭnh sa, jêh ri leo ŭnh nây ăn ngai. Yor lah khăl su ndơ ƀâu kah nây jêng kloh ueh.$b$,false),
('bunong-vn','NUM',16,38,null,$b$Khăl su ndơ ƀâu kah phung bunuyh ƀư tih jêh ri kŏ tât roh nau rêh khân păng; pô ri ăn bu chiăr tât tep jêng ndơ nkŭm nơng, yor lah khân păng nhhơr ndơ nây pa năp Yêhôva; yor nây khăl nây jêng kloh ueh jêh. Pô ri khân păng jêng du ndơ tâm mbên ma phung ƀon lan Israel.”$b$,false),
('bunong-vn','NUM',16,39,null,$b$Pô nây Y-Êlêasar kôranh ƀư brah sŏk khăl kông su ndơ ƀâu kah, ndơ phung ŭnh sa nhhơr jêh; jêh ri bu chiăr ndơ nây jêng ndơ prăp nkŭm nơng,$b$,true),
('bunong-vn','NUM',16,40,null,$b$gay jêng du ndơ kah gĭt ma phung ƀon lan Israel, gay ma mâu geh ôh du huê nơm mâu jêng tă bơh phung kon sau Y-Arôn, mra hăn dăch nơng su ndơ ƀâu kah ta năp Yêhôva, klach lah jêng nâm bu Y-Kôrê jêh ri phung ndrel ma păng tĭng nâm Yêhôva lah jêh ma Y-Môis.$b$,false),
('bunong-vn','NUM',16,41,null,$b$Ƀiă lah ôi taơ lĕ rngôch phung ƀon lan Israel tâm rƀŭn ngơi ƀrôk tâm rdâng đah Y-Môis jêh ri Y-Arôn lah, “Khân may nkhĭt jêh ri ƀon lan Yêhôva.”$b$,true),
('bunong-vn','NUM',16,42,null,$b$Tơ lah phung ƀon lan dôl tâm rƀŭn ŭch tâm rdâng đah Y-Môis jêh ri Y-Arôn, khân păng rle ma ngih bok tâm rƀŭn; jêh ri saơ, tŭk nkâm ngih bok jêh ri nau chrêk ma lơp Yêhôva tâm mpơl.$b$,false),
('bunong-vn','NUM',16,43,null,$b$Y-Môis jêh ri Y-Arôn tât pa năp ngih bok tâm rƀŭn,$b$,true),
('bunong-vn','NUM',16,44,null,$b$jêh ri Yêhôva lah ma Y-Môis,$b$,false),
('bunong-vn','NUM',16,45,null,$b$“Du hom tă bơh nklang phung tâm rƀŭn aơ, gay gâp dơi su khân păng ƀât lât dơm.” Khân păng chŭn muh măt ta neh.$b$,false),
('bunong-vn','NUM',16,46,null,$b$Y-Môis lah ma Y-Arôn, “Sŏk hom khăl su ndơ ƀâu kah may, dơm ŭnh tă bơh nơng tâm nây, jêh ri dơm ndơ ƀâu kah tâm nây, djôt leo gơnh ma phung tâm rƀŭn jêh ri ƀư nau chuai ăn kloh nau tih khân păng; yor lah nau ji nuih luh jêh tă bơh Yêhôva, nau tât mhĭk ntơm jêh.”$b$,false),
('bunong-vn','NUM',16,47,null,$b$Pô ri Y-Arôn sŏk ndơ nây tĭng nâm Y-Môis lah jêh, jêh ri păng nchuăt ta nklang phung tâm rƀŭn; jêh ri aơ, nau tât mhĭk ntơm jêh ta nklang phung ƀon lan. Păng dơm ndơ ƀâu kah tâm nây jêh ri ƀư nau chuai ăn kloh nau tih ma phung ƀon lan.$b$,true),
('bunong-vn','NUM',16,48,null,$b$Păng dâk ta vah vang phung khĭt jêh ri phung rêh; jêh ri nau tât mhĭk rlu ro.$b$,true),
('bunong-vn','NUM',16,49,null,$b$Phung khĭt jêh yor nau Y-Kôrê.$b$,true),
('bunong-vn','NUM',16,50,null,$b$Y-Arôn plơ̆ sĭt ma Y-Môis ta mpông ngih bok tâm rƀŭn jêh ri nau tât mhĭk rlu.$b$,false),
('bunong-vn','NUM',17,1,null,$b$Yêhôva lah ma Y-Môis,$b$,true),
('bunong-vn','NUM',17,2,null,$b$“Lah hom ma phung ƀon lan Israel, jêh ri sŏk tă bơh khân păng du mlâm mâng jra, du mlâm ma ăp ndŭl mpôl khân păng, tă bơh lĕ rngôch kôranh tĭng nâm ndŭl mpôl tơm khân păng, geh jât ma bar mlâm mâng jra. Chih amoh săk ăp nơm ta mâng jra păng,$b$,false),
('bunong-vn','NUM',17,3,null,$b$jêh ri chih amoh Y-Arôn ta mâng jra Lêvi. Yor lah mra geh du mlâm mâng jra ma ăp nơm kôranh noi deh khân păng.$b$,false),
('bunong-vn','NUM',17,4,null,$b$Jêh ri ăn may dơm mâng nây tâm ngih bok tâm rƀŭn ta năp nau mbơh, ntŭk gâp tâm mâp đah may.$b$,true),
('bunong-vn','NUM',17,5,null,$b$Mâng jra bunuyh gâp săch mra luh kao; pô ri gâp mra ăn dŭt ta năp gâp nau phung ƀon lan Israel ngơi ƀrôk tâm rdâng đah may.”$b$,false),
('bunong-vn','NUM',17,6,null,$b$Y-Môis ngơi ma phung ƀon lan Israel, jêh ri lĕ rngôch kôranh khân păng ăn mâng jra ma păng, du mlâm ăp nơm kôranh tĭng nâm ndŭl mpôl tơm khân păng, geh jât ma bar mlâm mâng; jêh ri mâng jra Y-Arôn gŭ ndrel ma mâng khân păng.$b$,false),
('bunong-vn','NUM',17,7,null,$b$Y-Môis dơm lĕ rngôch mâng nây ta năp Yêhôva tâm ngih bok nau mbơh.$b$,false),
('bunong-vn','NUM',17,8,null,$b$Kah ôi taơ, tơ lah Y-Môis lăp tâm ngih bok nau mbơh geh saơ ta mâng jra Y-Arôn mpeh phung Lêvi chăt nkeh luh dang kao: Păng geh pŭn jêh ri luh du kao, jêh nây geh play amandê dŭm.$b$,true),
('bunong-vn','NUM',17,9,null,$b$Jêh ri Y-Arôn sŏk ngluh pa dih ta năp Yêhôva, lĕ rngôch mâng jra leo ma phung ƀon lan Israel. Khân păng uănh, jêh ri ăp nơm sŏk pơih mâng khân păng nơm.$b$,false),
('bunong-vn','NUM',17,10,null,$b$Yêhôva lah ma Y-Môis, “Sŏk tay hom mâng jra Y-Arôn dơm tay pa năp hip nau mbơh, gay prăp jêng du ndơ nau tâm mbên ma phung tâm rdâng, gay ma may ƀư dŭt nau khân păng ngơi ƀrôk tâm rdâng đah gâp, klach lah khân păng nkhĭt.”$b$,false),
('bunong-vn','NUM',17,11,null,$b$Pô ri Y-Môis ƀư di tĭng nâm nau Yêhôva hŏ ntĭnh jêh ma păng.$b$,true),
('bunong-vn','NUM',17,12,null,$b$Phung ƀon lan Israel lah ma Y-Môis, “Aơ hên khĭt, hên rai lôch, hên rai lôch lĕ ro!$b$,false),
('bunong-vn','NUM',17,13,null,$b$Ăp nơm mbu moh hăn dăch ma ngih bok Yêhôva mra khĭt. Mâm lĕ rngôch hên mra khĭt lĕ ƀơh?”$b$,false),
('bunong-vn','NUM',18,1,null,$b$Pô nây, Yêhôva lah ma Y-Arôn: “May, phung kon bu klâu may jêh ri noi deh may ndrel ma may mra anh nau tih yor ma jrô kloh ueh; bi ma may jêh ri ma phung kon bu klâu may mra anh nau tih yor kan kôranh ƀư brah khân may.$b$,true),
('bunong-vn','NUM',18,2,null,$b$Ăn njŭn phung oh nâu may tâm ban đŏng ndrel ma may, mpôl Lêvi, jêng noi deh may, gay ma khân păng tâm rnglăp đah may, jêh ri pah kan ma may; ƀiă lah may jêh ri phung kon bu klâu may dơi gŭ pa năp ngih bok nau mbơh.$b$,false),
('bunong-vn','NUM',18,3,null,$b$Khân păng mra kơl kan may jêh ri ƀư lĕ kan di ma ngih bok; ƀiă lah khân păng mâu dơi hăn dăch ma ndơ dŏng tâm jrô kloh ueh mâu lah ma nơng ôh, klach lah khân păng jêh ri may khĭt.$b$,false),
('bunong-vn','NUM',18,4,null,$b$Khân păng mra tâm rnglăp đah may, jêh ri pah kan ma ngih bok tâm rƀŭn; ma lĕ rngôch kan tâm ngih bok; jêh ri mâu hôm geh nơm êng dơi văch dăch ôh.$b$,false),
('bunong-vn','NUM',18,5,null,$b$Khân may mra pah kan ma jrô kloh ueh jêh ri pah kan ma nơng, gay mâu hôm geh ôh nau ji nuih tât ma phung Israel.$b$,false),
('bunong-vn','NUM',18,6,null,$b$Aơ gâp hŏ săch jêh phung oh nâu may phung Lêvi tă bơh ta nklang phung ƀon lan Israel; khân păng jêng du ndơ ăn ma may, prăp an jêh ma Yêhôva, gay pah kan tâm ngih bok tâm rƀŭn.$b$,false),
('bunong-vn','NUM',18,7,null,$b$Ƀiă lah may jêh ri phung kon bu klâu may mra pah kan kôranh ƀư brah khân may ma lĕ rngôch nau di ma nơng jêh ri ndơ tâm trôm bok nching; jêh ri khân may mra pah kan. Gâp ăn kan kôranh ƀư brah khân may nâm bu du ndơ ăn, jêh ri mbu bunuyh êng văch dăch pah kan nây bu mra nkhĭt.”$b$,false),
('bunong-vn','NUM',18,8,null,$b$Yêhôva lah ma Y-Arôn, “Aơ, gâp ăn jêh ma may moh ndơ prăp jêh tă bơh ndơ bu nhhơr ma gâp, lĕ rngôch ndơ phung ƀon lan Israel prăp an jêh; gâp ăn jêh ndơ nây jêng kô̆ ma may jêh ri ma phung kon bu klâu may, jêng nau di gŭ mro mrăng.$b$,true),
('bunong-vn','NUM',18,9,null,$b$Aơ mra jêng ndơ may tă bơh ndơ kloh ueh ngăn bu prăp jêh mâu geh su ôh, ăp ndơ khân păng nhhơr, ăp ndơ nhhơr rnih muy khân păng, ăp ndơ nhhơr chuai yor nau tih khân păng, jêh ri ăp ndơ nhhơr yor nau rlau nau vay khân păng; ndơ khân păng nhhơr ma gâp kloh ueh ngăn ma may jêh ri ma phung kon bu klâu may.$b$,true),
('bunong-vn','NUM',18,10,null,$b$May mra sa ndơ nây tâm du ntŭk kloh ueh ngăn; ăp nơm bu klâu dơi sa ndơ nây; ndơ nây jêng kloh ueh ma may.$b$,true),
('bunong-vn','NUM',18,11,null,$b$Aơ tâm ban đŏng jêng ndơ may, ndơ nhhơr tă bơh ndơ khân păng ăn, lĕ rngôch ndơ nhhơr ryeng bơh phung ƀon lan Israel; gâp ăn ndơ nây ma may, ma phung kon bu klâu may jêh ri phung kon bu ur may ndrel ma may, jêng nau di gŭ ƀa ƀơ;$b$,false),
('bunong-vn','NUM',18,12,null,$b$ăp nơm mbu moh jêng kloh tâm ngih may mra nhhơr ma Yêhôva, lĕ rngôch dak play ôlivơ ueh lơn, lĕ rngôch dak play kriăk ƀâu jêh ri ba ueh ngăn ngên, play dak bôk khân păng ăn ma Yêhôva.$b$,false),
('bunong-vn','NUM',18,13,null,$b$Play dŭm ntơm sa ơm tâm lĕ rngôch play tă tâm neh khân păng, ndơ nây khân păng djôt leo ma Yêhôva mra jêng ndơ may; ăp nơm mbu jêng kloh tâm ngih may dơi sa ndơ nây,$b$,true),
('bunong-vn','NUM',18,14,null,$b$Moh ndơ phung Israel prăp an jêh mra jêng ndơ may.$b$,false),
('bunong-vn','NUM',18,15,null,$b$Lĕ rngôch kon deh bôk rah, ăp ndơ deh ntơm sa ơm, ndơ nây khân păng nhhơr ma Yêhôva, mra jêng ndơ may; ƀiă lah may mra tâm chuai kon bunuyh bu deh ntơm sa ơm, jêh ri may ăt mra tâm chuai đŏng kon ntơm sa ơm mpô mpa mâu kloh.$b$,false),
('bunong-vn','NUM',18,16,null,$b$May mra tâm nal rnoh tâm chuai khân păng jêng Sêkel prăk tĭng nâm sêkel tâm jrô kloh ueh, ndơ nây jêng bar jât gêra (may mra tâm chuai khân păng tơ lah khân păng lĕ geh jêh tâm du khay).$b$,false),
('bunong-vn','NUM',18,17,null,$b$Ƀiă lah may mâu mra tâm chuai ôh ndrôk kon bôk rah, biăp kon bôk rah, mâu lah be kon ntơm sa ơm; khân păng jêng kloh ueh. May mra nsrih mham khân păng ta klơ nơng, jêh ri gŭch ngi khân păng jêng ndơ nhhơr ăn ŭnh sa, n'hôl ƀâu kah ma Yêhôva.$b$,true),
('bunong-vn','NUM',18,18,null,$b$Ƀiă lah puăch khân păng mra prăp ma may, nâm bu nting bong nuih bu ryeng jêh, jêh ri nglu pa ma prăp ma may.$b$,false),
('bunong-vn','NUM',18,19,null,$b$Lĕ rngôch ndơ nhhơr kloh ueh phung ƀon lan Israel nhhơr ma Yêhôva, gâp ăn ma may, ma phung kon bu klâu may jêh ri phung kon bu ur ndrel ma may, jêng nau di gŭ ƀa ƀơ. Nau nây jêng nau tâm rnglăp geh boh gŭ n'ho ro ta năp Yêhôva prăp ma may jêh ri phung kon sau may ndrel ma may.”$b$,true),
('bunong-vn','NUM',18,20,null,$b$Yêhôva lah ma Y-Arôn, “May mâu mra geh drăp ndơn chăm ôh tâm n'gor bri khân păng, du kô̆ kŏ mâu geh lĕ ta nklang khân păng; gâp yơh jêng kô̆ prăp ma may jêh ri drăp ndơn may ta nklang phung ƀon lan Israel.$b$,true),
('bunong-vn','NUM',18,21,null,$b$“Gâp jêng drăp ndơn ăn ma phung Lêvi lĕ rngôch du kô̆ tâm jât bơh phung Israel, mplơ̆ ma nau kan khân păng ƀư, kan khân păng ƀư tâm ngih bok tâm rƀŭn.$b$,false),
('bunong-vn','NUM',18,22,null,$b$Ntơm bơh aơ tât ô klak phung ƀon lan Israel mâu dơi văch dăch ôh ngih bok tâm rƀŭn, klach lah khân păng kăr nau tih jêh ri khĭt.$b$,true),
('bunong-vn','NUM',18,23,null,$b$Ƀiă lah phung Lêvi mra pah kan tâm ngih bok tâm rƀŭn, jêh ri khân păng mra anh nau kue khân păng. Nau nây mra jêng du nau vay gŭ ƀa ƀơ tâm lĕ rngôch rô̆ khân may; khân păng mâu mra geh drăp ndơn ôh ta nklang phung ƀon lan Israel.$b$,false),
('bunong-vn','NUM',18,24,null,$b$Yor lah du kô̆ tâm jât tă bơh phung ƀon lan Israel, ndơ khân păng leo njŭn jêng ndơ nhhơr ma Yêhôva, gâp ăn jêh jêng drăp ndơn ma phung Lêvi; Yor ri gâp lah jêh yor khân păng, khân păng mâu geh drăp ndơn ta nklang phung ƀon lan Israel.”$b$,true),
('bunong-vn','NUM',18,25,null,$b$Yêhôva lah ma Y-Môis:$b$,true),
('bunong-vn','NUM',18,26,null,$b$“Ăn may lah ma phung Lêvi, ‘Tơ lah khân may sŏk bơh phung ƀon lan Israel ndơ du kô̆ tâm jât nây.$b$,false),
('bunong-vn','NUM',18,27,null,$b$Jêh ri ndơ khân may nhhơr mra kơp ma khân may nâm bu ba ntŭk mprah ba, nâm bu dak play kriăk ƀâu rmeh ler bơh ntŭk bu păt dak.$b$,true),
('bunong-vn','NUM',18,28,null,$b$Pô ri khân may tâm ban đŏng mra leo du ndơ nhhơr ma Yêhôva bơh lĕ rngôch ndô ndơ du kô̆ tâm jât khân may sŏk dơn jêh bơh phung ƀon lan Israel jêh ri ndơ nây ndơ khân may hŏ nhhơr jêh ma Yêhôva, khân may mra ăn ma Y-Arôn kôranh ƀư brah.$b$,false),
('bunong-vn','NUM',18,29,null,$b$Tă bơh lĕ rngôch ndơ bu ăn ma khân may, khân may mra leo lĕ rngôch ndơ nhhơr jêng di ma Yêhôva, lĕ rngôch ndơ ueh ngăn ngên bơh ndơ nây, ăn kô̆ kloh ueh bơh ndơ nây!$b$,false),
('bunong-vn','NUM',18,30,null,$b$Yor nây ăn may lah ma khân păng, “Tơ lah khân may lĕ nhhơr jêh ndơ ueh ngăn ngên bơh ndơ nây, bi ndơ hôm bu mra kơp ma phung Lêvi nâm bu play bơh ntŭk mprah ba, jêh ri nâm bu play bơh ntŭk păt dak play kriăk ƀâu.$b$,false),
('bunong-vn','NUM',18,31,null,$b$Khân may dơi sa ndơ nây tâm moh ntŭk khân may ŭch, may jêh ri phung bunuyh ƀon lan may; yor lah nây jêng nau nkhôm mplơ̆ ma kon may ƀư tâm ngih bok tâm rƀŭn.$b$,true),
('bunong-vn','NUM',18,32,null,$b$Khân may mâu mra anh ôh nau nây, tơ lah lĕ jêh khân may nhhơr ndơ ueh ngăn bơh ndơ nây. Lơi ta khân may ƀư ƀơ̆ ôh ndơ kloh ueh phung ƀon lan Israel, klach lah khân may khĭt.”$b$,false),
('bunong-vn','NUM',19,1,null,$b$Yêhôva lah ma Y-Môis jêh ri Y-Arôn,$b$,true),
('bunong-vn','NUM',19,2,null,$b$“Aơ jêng nau ntĭnh bơh nau vay Yêhôva ăn jêh: Ngơi hom ma phung ƀon lan Israel ăn khân păng têk leo ma may du mlâm ndrôk me guh mâu geh ntŭk mhĭk, mâu geh ntŭk kuet rôi ôh, jêh ri mâu mâp nđuih mâng mbăk ôh.$b$,false),
('bunong-vn','NUM',19,3,null,$b$Jao ndrôk nây ma kôranh ƀư brah Y-Êlêasar jêh ri ăn bu têk leo păng rlet pa dih mpâr, jêh ri sreh ndrôk nây ta năp păng.$b$,false),
('bunong-vn','NUM',19,4,null,$b$Kôranh ƀư brah Y-Êlêasar mra sŏk ƀa ƀă mham ndrôk mbŭk ma nglau ti păng, nsrih pơh tơ̆ mham nây pa năp ngih bok tâm rƀŭn.$b$,false),
('bunong-vn','NUM',19,5,null,$b$Bu mra gŭch ndrôk me ta năp măt păng; bu mra gŭch ntâu păng, puăch păng, jêh ri mham păng ndrel ma ek păng.$b$,false),
('bunong-vn','NUM',19,6,null,$b$Jêh nây, kôranh ƀư brah mra sŏk tơm si sêdar, n'ha hisôp, jêh ri ndơ chăng gŭr, jêh ri mƀăr ndơ nây ta nklang ndrôk dôl hit ŭnh.$b$,true),
('bunong-vn','NUM',19,7,null,$b$Jêh ri kôranh ƀư brah mra pih bok ao păng jêh ri ŭm tâm dak, jêh nau nây păng dơi sĭt ma nhuang ntŭk; jêh ri kôranh ƀư brah jêng ƀơ̆ tât kêng măng;$b$,false),
('bunong-vn','NUM',19,8,null,$b$Nơm gŭch ndrôk me druh nây mra pih bok ao păng jêh ri ŭm tâm dak, mra jêng ƀơ̆ tât kêng măng.$b$,false),
('bunong-vn','NUM',19,9,null,$b$Du huê bu klâu kloh mra dônh kuak buh ndrôk me druh nkhŭt pa dih mpâr, tâm ntŭk kloh; bu mra prăp buh nây ma phung ƀon lan Israel tâm rƀŭn prăp gay ƀư dak jut tho nau ƀơ̆ : Nây jêng du nau nhhơr chuai yor nau tih.$b$,false),
('bunong-vn','NUM',19,10,null,$b$Mbu nơm dônh kuak buh ndrôk me druh nây mra pih bok ao păng, jêh ri jêng ƀơ̆ tât kêng măng. Aơ jêng nau vay gŭ ƀa ƀơ ma phung ƀon lan Israel, jêh ri ma bu năch nơm gŭ njơh ƀât lât ta nklang khân păng.$b$,true),
('bunong-vn','NUM',19,11,null,$b$“Mbu nơm pah bi săk jăn du huê bunuyh khĭt mra jêng ƀơ̆ tâm pơh nar.$b$,true),
('bunong-vn','NUM',19,12,null,$b$Păng mra ƀư kloh păng nơm ma dak nây ta nar năng pe jêh ri nar năng pơh. Pô nây păng mra jêng kloh; ƀiă lah tơ lah păng mâu ƀư kloh ôh păng nơm ta nar năng pe jêh ri nar năng pơh, păng mâu mra jêng kloh ôh.$b$,true),
('bunong-vn','NUM',19,13,null,$b$Mbu nơm pah bi săk jăn du huê bunuyh lĕ khĭt jêh, jêh ri mâu ƀư kloh ôh păng nơm, ƀư ƀơ̆ ngih bok Yêhôva; nơm nây ăn bu ƀư rai lơi bơh phung Israel; yor lah dak ma nau ƀư kloh mâu mâp nsrih ôh ta klơ păng, păng mra jêng ƀơ̆ ; nau ƀơ̆ păng hôm e gŭ ta păng.$b$,true),
('bunong-vn','NUM',19,14,null,$b$“Aơ jêng nau vay tơ lah du huê bunuyh khĭt tâm ngih bok: Ăp nơm mbu nơm lăp tâm ngih bok, jêh ri ăp nơm mbu nơm gŭ tâm ngih bok mra jêng ƀơ̆ tâm pơh nar.$b$,true),
('bunong-vn','NUM',19,15,null,$b$Lĕ rngôch glah mâu kŭp jêng ƀơ̆ .$b$,true),
('bunong-vn','NUM',19,16,null,$b$Tâm mir, mbu nơm pah bi du huê bunuyh mra sreh ma mpiăt đao, du huê phan, du mlâm nting bunuyh, mâu lah môch mra jêng ƀơ̆ tâm pơh nar.$b$,false),
('bunong-vn','NUM',19,17,null,$b$Ma nơm jêng ƀơ̆ jêh ri bu mra sŏk buh ndơ nhhơr gŭch gay chuai yor nau tih, ăn tâm du mlâm yăng jêh ri tŏ dak ler tât klơ.$b$,false),
('bunong-vn','NUM',19,18,null,$b$Pô nây, du huê bunuyh kloh mra sŏk n'ha hisôp jêh ri mbŭk păng tâm dak nây, jêh ri mbrih păng ta klơ ngih bok, ta klơ lĕ rngôch ndơ dŏng, ta klơ bunuyh gŭ ta nây, ta klơ nơm pah bi jêh nting mâu lah du huê bunuyh bu nkhĭt, mâu lah săk bunuyh khĭt, mâu lah môch.$b$,true),
('bunong-vn','NUM',19,19,null,$b$Nar năng pe jêh ri nar năng pơh, du huê bunuyh kloh nsrih dak nây ta klơ bunuyh ƀơ̆ , jêh ri nar năng pơh bunuyh kloh mra ƀư kloh an păng, jêh ri bunuyh jêng kloh mra pih bok ao păng, jêh ri ŭm tâm dak, jêh nây dăch kêng măng păng mra jêng kloh.$b$,false),
('bunong-vn','NUM',19,20,null,$b$“Ƀiă lah bunuyh jêng ƀơ̆ jêh, mâu dơi ƀư kloh ăn păng nơm ôh, nơm nây ăn bu ngroh lơi păng bơh nklang phung tâm rƀŭn, yor lah păng lĕ ƀư ƀơ̆ jrô kloh ueh Yêhôva; yor lah dak ma nau ƀư kloh bu mâu mâp nsrih ôh ta klơ păng, păng jêng ƀơ̆ .$b$,false),
('bunong-vn','NUM',19,21,null,$b$Nau nây mra jêng ma khân păng du nau vay gŭ ƀa ƀơ. Mbu nơm nsrih dak ma nau ƀư kloh mra pih bok ao păng; jêh ri mbu nơm pah bi dak ma nau ƀư kloh mra jêng ƀơ̆ tât kêng măng.$b$,false),
('bunong-vn','NUM',19,22,null,$b$Moh ndơ nơm ƀơ̆ pah bi jêh mra jêng ƀơ̆ ; jêh ri mbu nơm pah bi ndơ nây mra jêng ƀơ̆ tât kêng măng.”$b$,false),
('bunong-vn','NUM',20,1,null,$b$Lĕ rngôch phung ƀon lan Israel tâm rƀŭn lăp tâm bri rdah Sin khay nguay, jêh ri phung ƀon lan njơh ta Kadês. Ta nây H'Miriam khĭt, jêh ri bu tâp brôi păng ta nây.$b$,true),
('bunong-vn','NUM',20,2,null,$b$Pô ri, mâu geh ôh dak ma phung tâm rƀŭn, jêh ri khân păng dâk ndrel tâm rdâng đah Y-Môis jêh ri Y-Arôn.$b$,true),
('bunong-vn','NUM',20,3,null,$b$Phung ƀon lan tâm rlăch đah Y-Môis, lah, “Ueh jêh tơ lah hên khĭt ndrel ma phung oh nâu hên khĭt jêh ta năp Yêhôva.$b$,false),
('bunong-vn','NUM',20,4,null,$b$Mâm may njŭn jêh phung Yêhôva tâm rƀŭn tâm bri rdah aơ, gay ăn hên khĭt ta aơ, hên jêh ri mpô mpa rong hên?$b$,false),
('bunong-vn','NUM',20,5,null,$b$Jêh ri mâm may ngluh hên tă bơh n'gor bri Êjipt, gay njŭn hên tât ntŭk mhĭk aơ? Aơ jêng ntŭk bu mâu dơi tuch ba ôh, tăm tơm play rvi, tăm tơm play kriăk ƀâu, tăm tơm play pôm gra nat ôh; jêh ri mâu geh ôh dak nhêt?”$b$,false),
('bunong-vn','NUM',20,6,null,$b$Jêh nây Y-Môis jêh ri Y-Arôn du bơh phung tâm rƀŭn hăn rlet mpông ngih bok tâm rƀŭn, jêh ri chŭn muh măt khân păng ta neh. Jêh ri nau chrêk ma lơp Yêhôva tâm mpơl ma khân păng.$b$,false),
('bunong-vn','NUM',20,7,8,$b$“Sŏk hom mâng jra may, jêh ri tâm rƀŭn phung ƀon lan, may jêh ri Y-Arôn nâu may, ngơi ma lŭ ta năp măt khân păng gay ma păng luh dak; pô ri may mra ăn dak luh tă bơh lŭ hoch ăn phung ƀon lan jêh ri mpô mpa rong khân păng nhêt.”$b$,false),
('bunong-vn','NUM',20,9,null,$b$Pô nây, Y-Môis djôt mâng jra bơh ta năp măt Yêhôva nting jêh ma păng.$b$,false),
('bunong-vn','NUM',20,10,null,$b$Y-Môis jêh ri Y-Arôn tâm rƀŭn phung ƀon lan tât pa năp lŭ, jêh ri păng lah ma khân păng, “Iăt hom, hơi phung tâm rdâng; hên mra ăn luh dak tă bơh lŭ aơ ma khân may mâm dơi lĕ?”$b$,false),
('bunong-vn','NUM',20,11,null,$b$Y-Môis yơr ti păng jêh ri dong ta lŭ bar tơ̆ ma mâng jra păng, jêh ri dak luh âk ngăn, phung tâm rƀŭn nhêt, jêh ri mpô mpa rong khân păng nhêt đŏng.$b$,false),
('bunong-vn','NUM',20,12,null,$b$Pô nây, Yêhôva lah ma Y-Môis jêh ri Y-Arôn, “Yor lah khân may mâu geh chroh ma gâp, gay yơk ma nau kloh ueh gâp ta năp măt phung ƀon lan Israel, yor nây khân may mra njŭn phung tâm rƀŭn aơ lăp tâm n'gor bri gâp ăn jêh ma khân păng.”$b$,false),
('bunong-vn','NUM',20,13,null,$b$Aơ jêng dak Mêriba, ta nây phung ƀon lan Israel tâm rlăch đah Yêhôva, jêh ri Yêhôva tâm mpơl Păng nơm jêng kloh ueh ta nklang khân păng.$b$,false),
('bunong-vn','NUM',20,14,null,$b$Tă bơh ƀon Kadês Y-Môis prơh hăn phung mbơh ma hađăch n'gor Êđôm, “Pô aơ oh may Israel lah, May gĭt jêh lĕ rngôch nau rêh ni tât ma hên:$b$,true),
('bunong-vn','NUM',20,15,null,$b$Nau phung chô che hên trŭnh hăn jêh ma n'gor bri Êjipt, jêh ri hên gŭ ta n'gor bri Êjipt jŏ năm; jêh ri phung Êjipt ƀư ma nau dăng đah hên.$b$,false),
('bunong-vn','NUM',20,16,null,$b$Phung nter vơl ma Yêhôva, Păng tăng bâr hên jêh ri păng prơh du huê tông mpăr ueh jêh ri njŭn hên du luh bơh n'gor bri Êjipt; jêh ri hên gŭ ta ƀon Kaldês, du rplay ƀon ta n'har bri neh may.$b$,true),
('bunong-vn','NUM',20,17,null,$b$Aƀaơ ri ăn hên hăn rgăn bri may. Hên mâu mra hăn rgăn ta mir mâu lah ta lôk mir play kriăk ƀâu ôh, mâu lĕ hên mra nhêt dak tă bơh du ntu dak; hên mra njŏ rŏ trong toyh hađăch, hên mâu mra teng pa chiau pa ma ôh tât hên rgăn lĕ n'gor bri may.”$b$,false),
('bunong-vn','NUM',20,18,null,$b$Ƀiă lah Êđôm lah ma păng, “May mâu dơi rgăn ôh, lah sŏl hăn rgăn gâp mra luh chuă ma đao tâm lơh đah may.”$b$,false),
('bunong-vn','NUM',20,19,null,$b$Phung ƀon lan Israel lah ma păng, “Hên mra hăn hao njŏ rŏ trong toyh, jêh ri tơ lah hên jêh ri mpô mpa rong hên nhêt dak may, pô ri hên mra ăn prăk. Dăn knŏng hăn rgăn dơm.”$b$,false),
('bunong-vn','NUM',20,20,null,$b$Ƀiă lah Êđôm lah, “May mâu dơi rgăn ôh!” Jêh ri phung Êđôm ndrel ma phung bunuyh âk jêh ri ndrel ma phung ktang luh du tâm rdâng đah khân păng.$b$,false),
('bunong-vn','NUM',20,21,null,$b$Pô ri Êđôm mâu dơi ăn phung ƀon lan Israel hăn rgăn bri păng; jêh ri phung Israel der du bơh khân păng.$b$,false),
('bunong-vn','NUM',20,22,null,$b$Lĕ rngôch tâm rƀŭn phung ƀon lan Israel dâk hăn bơh ƀon Kadês jêh ri tât ta yôk Hor.$b$,true),
('bunong-vn','NUM',20,23,null,$b$Yêhôva lah ma Y-Môis jêh ri Y-Arôn ta yôk Hor ta n'har bri Êđôm,$b$,false),
('bunong-vn','NUM',20,24,null,$b$“Y-Arôn mra khĭt jêh ri hăn gŭ ndrel ma phung che păng; păng mâu dơi lăp ôh tâm n'gor bri gâp ăn jêh ma phung ƀon lan Israel, yor lah khân may tâm rdâng jêh đah nau gâp ntĭnh ta dak Mêriba.$b$,false),
('bunong-vn','NUM',20,25,null,$b$Sŏk Y-Arôn jêh ri Y-Êlêasar kon bu klâu păng, jêh ri njŭn khân păng ta yôk Hor.$b$,false),
('bunong-vn','NUM',20,26,null,$b$Doh lơi bok ao Y-Arôn jêh ri ăn nsoh bok ao nây ma Y-Êlêasar kon bu klâu păng. Y-Arôn mra khĭt ta nây jêh ri bu mra tâm rƀŭn păng ndrel ma phung che păng.$b$,false),
('bunong-vn','NUM',20,27,null,$b$Y-Môis ƀư tĭng nâm nau Yêhôva ntĭnh jêh, jêh ri hao yôk Hor ta năp măt lĕ rngôch phung tâm rƀŭn.$b$,false),
('bunong-vn','NUM',20,28,null,$b$Y-Môis doh bok ao Y-Arôn jêh ri ăn nsoh bok ao nây ma Y-Êlêasar kon bu klâu păng; jêh ri Y-Arôn khĭt ta nây ta klơ mpư̆ yôk. Jêh nây Y-Môis jêh ri Y-Êleasar trŭnh tă bơh yôk.$b$,false),
('bunong-vn','NUM',20,29,null,$b$Tơ lah lĕ rngôch phung tâm rƀŭn gĭt Y-Arôn lĕ khĭt jêh, lĕ rngôch ngih Israel nhhiăng nhĭm ma Y-Arôn tâm pe jât nar.$b$,false),
('bunong-vn','NUM',21,1,null,$b$Tơ lah hađăch Arat, bunuyh n'gor Kanaan, gŭ mpeh bri rđŭng, tăng jêh ma Israel văch tĭng trong hăn n'hut văch tât ta trong Atharim, păng tâm lơh đah Israel jêh ri nhŭp khân ô băl ƀa ƀă jêng bu nă.$b$,true),
('bunong-vn','NUM',21,2,null,$b$Israel ƀư nau ton đah Yêhôva “Jêh ri lah, “Tơ lah n'hêl nanê̆ may jao phung ƀon lan aơ tâm ti gâp, gâp mra ƀư rai lĕ rngôch khân păng.”$b$,false),
('bunong-vn','NUM',21,3,null,$b$Yêhôva tăng nau phung Israel jêh ri phung Kanaan ma khân păng. Khân păng ƀư rai lĕ phung ƀon lan nđâp ƀon toyh khân păng; pô nây bu ntơ ntŭk nây Horma.$b$,false),
('bunong-vn','NUM',21,4,null,$b$Tă bơh yôk Hor khân păng dâk hăn tĭng trong Dak Mƀŭt Chăng gay ndăch n'gor bri Êđôm. Ta nklang trong phung ƀon lan mâu hôm dơi nsrôih ôh.$b$,true),
('bunong-vn','NUM',21,5,null,$b$Pô nây, phung ƀon lan ngơi tâm rdâng đah Brah Ndu jêh ri Y-Môis, lah: “Mâm khân may njŭn hên du luh bơh n'gor bri Êjipt ăn khĭt tâm bri rdah? Yor lah ta aơ mâu geh ôh ndơ sông sa, jêh ri dak nhêt, jêh nây hên tâm rmot ma ndơ sông sa dơm dam aơ.”$b$,false),
('bunong-vn','NUM',21,6,null,$b$Jêh ri Yêhôva prơh hăn bêh ŭnh lăp ta nklang phung ƀon lan, jêh ri chôk phung ƀon lan, pô nây âk ngăn phung ƀon lan Israel khĭt.$b$,true),
('bunong-vn','NUM',21,7,null,$b$Phung ƀon lan hăn tât ma Y-Môis jêh ri lah, “Hên lĕ ƀư tih jêh, yor lah hên ngơi tâm rdâng đah Yêhôva jêh ri đah may. Mbơh sơm hom ma Yêhôva gay ma păng sŏk lơi bêh aơ bơh hên.” Pô ri Y-Môis mbơh sơm an ma phung ƀon lan.$b$,false),
('bunong-vn','NUM',21,8,null,$b$Jêh ri Yêhôva lah ma Y-Môis “Ăn may ƀư du mlâm bêh ŭnh jêh ri mƀăk păng ta klơ mâng ndăl; ăp nơm mbu bêh chôk jêh, jêh ri n'gơr uănh ma ndơ nây, păng mra rêh.”$b$,true),
('bunong-vn','NUM',21,9,null,$b$Pô nây Y-Môis ƀư du mlâm bêh kông jêh ri mƀăk păng ta klơ ndăl; tơ lah mbu nơm lĕ bêh chôk jêh dơi n'gơr uănh bêh kông, pô ri dơi rêh.$b$,true),
('bunong-vn','NUM',21,10,null,$b$Jêh nây, phung ƀon lan Israel dâk hăn jêh ri njơh ta Ôbôt.$b$,true),
('bunong-vn','NUM',21,11,null,$b$Khân păng dâk hăn tă bơh Ôbôt jêh ri njơh ta I-yê-Abarim tâm bri rdah pa năp n'gor Môap mpeh luh nar.$b$,false),
('bunong-vn','NUM',21,12,null,$b$Tă bơh ntŭk nây khân păng dâk hăn jêh ri njơh tâm rlŭng Sêret.$b$,true),
('bunong-vn','NUM',21,13,null,$b$Tă bơh ntŭk nây khân păng dâk hăn jêh ri njơh mpeh kăl tê̆ Arnôn, dak krong nây gŭ tâm bri rdah luh bơh n'gor Amôrit; yor lah dak krong Arnôn jêng dak krong n'gor Môap, vah vang n'gor Môap đah phung Amôrit.$b$,false),
('bunong-vn','NUM',21,14,null,$b$Yor nây, bu chih jêh tâm ndrom sămƀŭt Nau Yêhôva Tâm Lơh, “Vahep gŭ tâm Supha, jêh ri rlŭng dak krong Arnôn,$b$,false),
('bunong-vn','NUM',21,15,null,$b$jêh ri kơh rlŭng tât ma n'har Ar, jêh nây rđâl đah n'har n'gor Môap.”$b$,false),
('bunong-vn','NUM',21,16,null,$b$Tă bơh ntŭk nây khân păng hăn tât ta Bêr, nây jêng ndrâm ntu dak Yêhôva ngơi jêh ma Y-Môis, “Tâm rƀŭn hom phung ƀon lan gŭ rgum, jêh ri gâp mra ăn dak ma khân păng.”$b$,true),
('bunong-vn','NUM',21,17,null,$b$Nôk nây phung Israel mprơ nau aơ: “Hơi ndrâm ntu, luh hom dak! Mprơ hom ma păng!$b$,false),
('bunong-vn','NUM',21,18,null,$b$Ndrâm ntu phung kon hađăch hŏ kuyh jêh, phung kôranh toyh tâm phung ƀon lan hŏ kuyh jêh, ma mâng hađăch jêh ri mâng jra khân păng.” Tă bơh bri rdah khân păng n'ho hăn ma Matana;$b$,false),
('bunong-vn','NUM',21,19,null,$b$tă bơh Matana tât ma Nahalich tât ma Bamôt;$b$,false),
('bunong-vn','NUM',21,20,null,$b$tă bơh Bamôt tât ma rlŭng tâm n'gor Môap dăch mpư̆ yôk Pisga mpeh bri rdah.$b$,false),
('bunong-vn','NUM',21,21,null,$b$Israel prơh bunuyh mbơh ma Y-Sihôn hađăch Amôrit, lah:$b$,true),
('bunong-vn','NUM',21,22,null,$b$“Ăn gâp rgăn n'gor bri may; hên mâu mra teng lăp ôh tâm mir mâu lah tâm lôk mir play kriăk ƀâu, ăt hên mâu mra nhêt đŏng dak ndrâm ntu may; hên mra hăn tĭng ƀoi trong toyh hađăch kŏ tât hên dơi rgăn jêh n'gor may.”$b$,false),
('bunong-vn','NUM',21,23,null,$b$Ƀiă lah Y-Sihôn mâu ăn ôh Israel hăn rgăn n'gor păng. Păng rgum lĕ rngôch phung ƀon lan păng jêh ri chuă tâm rdâng đah phung Israel tâm bri rdah, jêh ri păng văch ma ƀon Jahas jêh ri tâm lơh đah phung Israel.$b$,false),
('bunong-vn','NUM',21,24,null,$b$Israel sreh păng ma đao jêh ri pit in bri păng ntơm bơh dak krong Arnôn tât ma dak krong Jabôk, tât ma n'gor bri phung Amôn; yor lah n'har bri phung Amôn jêng nâp ktang.$b$,true),
('bunong-vn','NUM',21,25,null,$b$Israel sŏk gro lĕ rngôch ƀon toyh aơ, jêh ri Israel gŭ tâm lĕ rngôch ƀon toyh phung Amôrit, tâm ƀon toyh Hêsbôn jêh ri tâm lĕ rngôch ƀon jê̆ jê̆ păng.$b$,false),
('bunong-vn','NUM',21,26,null,$b$Yor lah ƀon Hêsbôn jêng ƀon toyh ma Y-Sihôn hađăch phung Amôrit, jêng hađăch hŏ tâm lơh jêh đah hađăch lor pa năp Môap, jêh ri pit in lĕ neh păng tât dak krong Arnôn.$b$,false),
('bunong-vn','NUM',21,27,null,$b$Yor nây phung bunuyh lah, “Văch ma ƀon Hêsbôn! Ƀon toyh Y-Sihôn dơi ndâk njêng jêh ri nâp ktang!$b$,true),
('bunong-vn','NUM',21,28,null,$b$Yor lah geh ŭnh luh du tă bơh ƀon Hêsbôn, mpiăt ŭnh bơh ƀon Sihôn. Ŭnh nây sa jêh ƀon Ar tâm n'gor Môap, lĕ rngôch phung kôranh gŭ tâm ntŭk klơ dor dak krong Arnôn.$b$,false),
('bunong-vn','NUM',21,29,null,$b$Rêh ni ngăn ma may, Hơi Môap! May lĕ rai lôch jêh, Hơi phung ƀon lan Kêmôs. Păng hŏ ăn jêh phung kon bu klâu păng jêng phung nchuăt du, jêh ri phung kon bu ur păng jêng bună, ma Y-Sihôn, du huê hađăch phung Amôrit.$b$,true),
('bunong-vn','NUM',21,30,null,$b$Pô nây phung kon sau păng lĕ rai lôch jêh ntơm bơh ƀon Hêsbôn tât ma ƀon Dibôn, jêh ri hên ƀư rai jêh tât ta Nôpha, kŏ tât ta ƀon Mêdêba.”$b$,false),
('bunong-vn','NUM',21,31,null,$b$Pô ri phung Israel gŭ tâm n'gor Amôrit.$b$,true),
('bunong-vn','NUM',21,32,null,$b$Y-Môis prơh hăn bunuyh uănh n'hut ƀon Jaser; jêh ri khân păng sŏk lĕ ƀon jê̆ jê̆ păng jêh ri mprơh phung Amôrit gŭ ta nây.$b$,true),
('bunong-vn','NUM',21,33,null,$b$Khân păng plơ̆ ndăch hăn trong mpeh n'gor Basan; jêh ri Y-Ôk hađăch n'gor Basan luh chuă tâm lơh đah khân păng ndrel ma lĕ rngôch phung ƀon lan păng, ŭch tâm lơh ta ƀon Êdrei:$b$,true),
('bunong-vn','NUM',21,34,null,$b$Ƀiă lah Yêhôva lah ma Y-Môis, “Lơi klach ôh ma păng, yor lah gâp lĕ jao jêh păng, jêh ri lĕ rngôch phung ƀon lan păng, nđâp bri păng tâm ti may; ăn may ƀư ma păng nâm bu may hŏ ƀư jêh ma Y-Sihôn hađăch phung Amôrit, nơm gŭ ta ƀon Hêsbôn.”$b$,false),
('bunong-vn','NUM',21,35,null,$b$Pô ri khân păng sreh ô băl, phung kon bu klâu ô băl, jêh ri lĕ rngôch phung ƀon lan ô băl, kŏ tât mâu hôm geh ntŭk du huê bunuyh dơi klaih ôh ma ô băl, jêh ri khân păng pit in n'gor bri păng nây.$b$,false),
('bunong-vn','NUM',22,1,null,$b$Jêh nây, phung ƀon lan Israel dâk hăn jêh ri njơh ta neh lâng n'gor Môap kăl tê̆ dak krong Yurdan tâm tra đah Yêrikô.$b$,true),
('bunong-vn','NUM',22,2,null,$b$Y-Balak kon bu klâu Y-Siphôr saơ jêh lĕ nau phung Israel ƀư ma phung Amôtir.$b$,false),
('bunong-vn','NUM',22,3,null,$b$Phung Môap klach ngăn ma phung ƀon lan Israel yor lah khân păng âk ngăn. Phung Môap djoh nuih n'hâm yor klach ma phung ƀon lan Israel.$b$,false),
('bunong-vn','NUM',22,4,null,$b$Phung Môap lah ma phung bu bŭnh bu ranh n'gor Madian, “Aƀaơ ri phung âk aơ mra sa lĕ rngôch ndơ gŭ jŭm he nâm bu ndrôk sa gơ̆ tâm mir.” Pô ri Y-Balak kon bu klâu Y-Siphôr hađăch n'gor Môap rnôk nây$b$,false),
('bunong-vn','NUM',22,5,null,$b$prơh hăn phung mbơh ma Y-Balaam kon bu klâu Y-Bêôr ta ƀon Pêthôr dăch Dak krong, tâm n'gor phung che păng, gay kuăl păng, lah, “Aơ, du phung ƀon lan du luh jêh bơh n'gor bri Êjipt; khân păng nkŭm lam neh ntu, jêh ri khân păng gŭ dăch mpeh gâp.$b$,false),
('bunong-vn','NUM',22,6,null,$b$Văch rak rtăp hom ma phung ƀon lan aơ, yor lah khân păng jêng ktang lơn ma gâp. Klăp lah gâp mra dơi đah khân păng jêh ri mprơh khân păng du luh bơh n'gor; yor lah gâp gĭt mbu nơm may mât ton geh nau mât ton ngăn, jêh ri mbu nơm may rak rtăp geh nau rak rtăp ngăn.”$b$,false),
('bunong-vn','NUM',22,7,null,$b$Pô ri phung bu bŭnh bu ranh n'gor Môap jêh ri phung bu bŭnh bu ranh n'gor Madian dâk hăn djôt leo ndơ nkhôm ma phung n'hŭm. Khân păng tât ma Y-Balaam jêh ri nkoch bri nau Y-Balak ntĭnh.$b$,false),
('bunong-vn','NUM',22,8,null,$b$Y-Balaam lah ma khân păng, “Bêch hom ta aơ măng aơ jêh ri gâp mra plơ̆ lah ma khân may tĭng nâm Yêhôva ngơi ma gâp.” Pô ri phung kôranh n'gor Môap gŭ ndrel ma Y-Balaam.$b$,true),
('bunong-vn','NUM',22,9,null,$b$Brah Ndu văch ma Y-Balaam jêh ri lah, Mbu phung bu klâu ndrel ma may?”$b$,false),
('bunong-vn','NUM',22,10,null,$b$Y-Balaam lah ma Brah Ndu, Y-Balak kon bu klâu Y-Siphôr hađăch n'gor Môap prơh khân ô băl hăn ma gâp, lah,$b$,true),
('bunong-vn','NUM',22,11,null,$b$“Aơ, du phung ƀon lan du luh bơh n'gor bri Êjipt jêh ri nkŭm lam neh ntu. Aƀaơ ri văch rak rtăp hom ma khân păng; klăp lah gâp mra dơi tâm lơh đah khân păng jêh ri mprơh lơi khân păng.”$b$,false),
('bunong-vn','NUM',22,12,null,$b$Brah Ndu lah ma Y-Balaam, “Lơi may hăn ndrel ma phung nây ôh; lơi may rak rtăp ôh ma phung ƀon lan aơ, yor lah khân păng jêng phung geh jêh nau mât ton.”$b$,false),
('bunong-vn','NUM',22,13,null,$b$Pô nây Y-Balaam kah rngăl ôi jêh ri lah ma phung kôranh tă bơh Y-Balak, “Sĭt hom rlet ma n'gor bri khân may nơm, yor lah Yêhôva dun jêh mâu ăn ôh gâp hăn ndrel ma khân may.”$b$,false),
('bunong-vn','NUM',22,14,null,$b$Pô ri phung kôranh n'gor Môap dâk sĭt rlet ma Y-Balak jêh ri lah, “Y-Balaam dun mâu văch ôh ndrel ma hên.”$b$,false),
('bunong-vn','NUM',22,15,null,$b$Du tơ̆ đŏng Y-Balak prơh hăn phung kôranh âk lơn jêh ri phung bunuyh bu yơk lơn ma phung pa năp.$b$,false),
('bunong-vn','NUM',22,16,null,$b$Khân păng tât ma Y-Balaam jêh ri lah ma păng, “Pô aơ Y-Balaam kon bu klâu Y-Siphôr lah, ‘Lơi ăn geh ôh nau buay văch ma gâp;$b$,false),
('bunong-vn','NUM',22,17,null,$b$yor lah n'hêl nanê̆ gâp mra ƀư ma nau yơk toyh ma may, jêh ri moh nau may lah ma gâp, gâp mra ƀư. Văch rak rtăp hom ma phung ƀon lan aơ.”$b$,false),
('bunong-vn','NUM',22,18,null,$b$Ƀiă lah Y-Balaam plơ̆ lah ma phung ntuh bâr Y-Balak. Nđâp tơ lah Y-Balak ăn ma gâp ngih păng bêng ma prăp jêh ri mah kđôi, gâp mâu dơi rlau ôh nau Yêhôva Brah Ndu gâp ntĭnh, gay ƀư du nau kan jê̆ mâu lah toyh.$b$,false),
('bunong-vn','NUM',22,19,null,$b$Ƀiă lah gâp dăn ma khân may gŭ ta aơ măng aơ tâm ban đŏng, gay ma gâp dơi gĭt moh nau Yêhôva mra lah đŏng ma gâp.”$b$,false),
('bunong-vn','NUM',22,20,null,$b$Brah Ndu tât ma Y-Balaam dôl măng jêh ri lah ma păng, “Tơ lah phung bu klâu aơ văch gay ŭch kuăl may, dâk hăn hom ndrel ma khân păng, ƀiă lah ăn may ƀư knŏng moh nau gâp mra ntĭnh ma may.”$b$,false),
('bunong-vn','NUM',22,21,null,$b$Pô ri Y-Balaam kah rngăl ôi, dăp ưn seh bri păng, jêh ri hăn ndrel ma phung kôranh n'gor Môap.$b$,true),
('bunong-vn','NUM',22,22,null,$b$Ƀiă lah Brah Ndu hao ji nuih yor nau păng hăn; jêh ri Tông mpăr ueh Yêhôva dâk ta trong nking nau păng hăn. Y-Balaam ncho seh bri, jêh ri bar hê oh mon păng hăn ndrel ma păng.$b$,false),
('bunong-vn','NUM',22,23,null,$b$Seh bri saơ Tông mpăr ueh Yêhôva dâk ta trong djôt đao rnglay tâm ti păng; jêh ri seh bri teng trong lăp tâm mir. Y-Balaam dong seh bri gay juet mplơ̆ rlet ma trong.$b$,false),
('bunong-vn','NUM',22,24,null,$b$Jêh ri Tông mpăr ueh Yêhôva dâk tâm trong jê̆ vah vang lôk mir play kriăk ƀâu, geh n'gar bar đah ding.$b$,false),
('bunong-vn','NUM',22,25,null,$b$Tơ lah seh bri saơ Tông mpăr ueh Yêhôva ô băl mpet đah n'gar jêh ri geh rchiăt jâng Y-Balaam đah n'gar; pô nây Y-Balaam dong đŏng ô băl.$b$,false),
('bunong-vn','NUM',22,26,null,$b$Jêh nây Tông mpăr ueh hăn pa năp jêh ri gŭ ntŭk huêt, mâu geh ôh trong der mpeh pa ma mâu lah mpeh pa chiau.$b$,false),
('bunong-vn','NUM',22,27,null,$b$Tơ lah seh bri saơ Tông mpăr ueh Yêhôva, ô băl chon mon păn tâm dâng Y-Balaam; jêh ri Y-Balaam hao ji nuih, jêh ri păng dong seh bri ma mâng păng.$b$,false),
('bunong-vn','NUM',22,28,null,$b$Nôk nây Yêhôva pơk trôm mbung seh bri, jêh ri lah ma Y-Balaam, “Moh gâp ƀư ma may dĭng may dong gâp pe tơ̆ ma aơ?”$b$,false),
('bunong-vn','NUM',22,29,null,$b$Y-Balaam lah ma seh bri, “Yor lah may mưch ir ma gâp. Tơ lah gâp geh đao tâm ti gâp, lĕ gâp nkhĭt jêh may.”$b$,true),
('bunong-vn','NUM',22,30,null,$b$Seh bri lah ma Y-Balaam, “Mâu di hĕ gâp jêng seh may, may ncho gâp du bông nau rêh may tât ma nar aơ? Gâp lĕ mơng ƀư pô aơ đŏng ma may?” Păng lah, “Mâu ôh.”$b$,false),
('bunong-vn','NUM',22,31,null,$b$Nôk nây Yêhôva pơk măt Y-Balaam jêh ri Y-Balaam saơ Tông mpăr ueh Yêhôva dâk ta trong, djôt đao rnglay tâm ti păng. Y-Balaam kŭnh bôk jêh ri chŭn muh măt ta neh.$b$,true),
('bunong-vn','NUM',22,32,null,$b$Tông mpăr ueh Yêhôva lah ma păng, “Mâm may dong seh bri may pe tơ̆ jêh? Aơ, gâp văch gay nking may, yor lah trong may jêng kue ngăn ta năp gâp;$b$,false),
('bunong-vn','NUM',22,33,null,$b$jêh ri seh bri saơ gâp jêh ri der pa năp gâp pe tơ̆ ma aơ. Tơ lah ô băl mâu der ôh ma gâp, n'hêl nanê̆ aƀaơ hŏ nkhĭt jêh may jêh ri ăn ô băl dơi rêh.”$b$,false),
('bunong-vn','NUM',22,34,null,$b$Jêh ri Y-Balaam lah ma Tông mpăr ueh Yêhôva, “Gâp hŏ ƀư tih jêh, yor lah gâp mâu gĭt ôh may dâk jêh tâm trong gay ŭch nking gâp. Pô nây aƀaơ tơ lah nau nây jêng mhĭk ta năp măt may, gâp mra plơ̆ sĭt ro yơh.”$b$,false),
('bunong-vn','NUM',22,35,null,$b$Tông mpăr ueh Yêhôva lah ma Y-Balaam, “Hăn hom may ndrel ma phung bu klâu nây; ƀiă lah ăn may ngơi knŏng nau gâp ntĭnh ma may.” Pô ri Y-Balaam n'ho hăn ndrel ma phung kôranh Y-Balak.$b$,false),
('bunong-vn','NUM',22,36,null,$b$Tơ lah Y-Balak tăng ma Y-Balaam tât jêh, păng luh tâm mâp đah ô băl ta ƀon Môap ta dak krong Arnôn jêng bôl dŭt n'har bri.$b$,true),
('bunong-vn','NUM',22,37,null,$b$Y-Balak lah ma Y-Balaam, “Mâu di hĕ gâp prơh hăn jêh bunuyh kuăl may? Mâm dĭng may mâu văch ôh ma gâp? Gâp mâu dơi hĕ ƀư nau yơk ma may?”$b$,false),
('bunong-vn','NUM',22,38,null,$b$Y-Balaam lah ma Y-Balak, “Aơ, gâp văch jêh ma may. Gâp geh lĕ nau dơi ngơi ƀa ƀă nau aƀaơ ri? Nau ngơi Brah Ndu dơm tâm trôm mbung gâp, nau nây gâp mra ngơi.”$b$,false),
('bunong-vn','NUM',22,39,null,$b$Jêh ri Y-Balaam hăn ndrel ma Y-Balak, jêh ri khân păng tât ta Kiriat-Husôt.$b$,false),
('bunong-vn','NUM',22,40,null,$b$Y-Balak ƀư brah ma ndrôk jêh ri biăp, jêh ri nây njuăl ndơ nây ma Y-Balaam jêh ri phung kôranh ndrel ma păng.$b$,false),
('bunong-vn','NUM',22,41,null,$b$Kah ôi taơ Y-Balak njŭn Y-Balaam ăn păng hăn ta Bamôt-Baal, jêh ri bơh ntŭk nây Y-Balaam saơ ƀa ƀă phung ƀon lan dăch lơn.$b$,false),
('bunong-vn','NUM',23,1,null,$b$Y-Balaam lah ma Y-Balak, “Ndâk hom ta aơ ma gâp pơh mlâm nơng, jêh ri ta aơ nkra ma gâp pơh mlâm ndrôk nkuăng jêh ri pơh mlâm biăp nkuăng.”$b$,true),
('bunong-vn','NUM',23,2,null,$b$Y-Balak ƀư tĭng nâm Y-Balaam lah jêh; jêh ri Y-Balak ndrel Y-Balaam nhhơr du mlâm ndrôk nkuăng jêh ri du mlâm biăp nkuăng ta klơ ăp nơng.$b$,true),
('bunong-vn','NUM',23,3,null,$b$Y-Balaam lah ma Y-Balak, “Dâk ta meng ndơ may nhhơr gŭch, jêh ri gâp mra hăn; klăp lah Yêhôva mra văch tâm mâp ma gâp, jêh ri moh nau păng mra tâm mpơl ma gâp, gâp mra mbơh ma may.” Jêh ri păng hăn leo klơ yôk jêng ntŭk hil.$b$,false),
('bunong-vn','NUM',23,4,null,$b$Brah Ndu tâm mâp đah Y-Balaam jêh ri Y-Balaam lah ma păng, “Gâp ndâk jêh pơh mlâm nơng jêh ri gâp nhhơr jêh du mlâm ndrôk nkuăng jêh ri du mlâm biăp nkuăng tâm ăp nơng.”$b$,true),
('bunong-vn','NUM',23,5,null,$b$Yêhôva dơm nau ngơi tâm trôm mbung Y-Balaam, jêh ri lah, “Plơ̆ tay đŏng ma Y-Balak jêh ri ngơi pô aơ.”$b$,false),
('bunong-vn','NUM',23,6,null,$b$Păng plơ̆ sĭt tay ma Y-Balak; aơ, Y-Balak jêh ri lĕ rngôch phung kôranh n'gor Môap dâk ta meng ndơ păng nhhơr gŭch.$b$,false),
('bunong-vn','NUM',23,7,null,$b$Y-Balaam mbơh nau tâm mpơl păng geh jêh, lah: “Tă bơh n'gor Aram Y-Balak ăn gâp văch, hađăch n'gor Môap ăn gâp văch tă bơh yôk pa lơ. ‘Văch rak rtăp hom ma phung Yakôp; văch hom, ngơi mhĭk ma phung Israel!’$b$,true),
('bunong-vn','NUM',23,8,null,$b$Mâm gâp dơi rak rtăp ma phung Brah Ndu mâu mâp rak rtăp ôh? Mâm gâp dơi ngơi mhĭk ma phung Yêhôva mâu mâp ngơi mhĭk ôh?$b$,false),
('bunong-vn','NUM',23,9,null,$b$Yor lah bơh klơ mpư̆ yôk gâp saơ păng, tă bơh gôl yôk gâp uănh păng; aơ, du phung ƀon lan gŭ êng, jêh ri mâu kơp ôh păng nơm ndrel ma phung mpôl băl bunuyh!$b$,false),
('bunong-vn','NUM',23,10,null,$b$Mbu dơi kơp ndruyh phung Yakôb, mâu lah kơp du kô̆ tâm puăn phung Israel? Ăn gâp khĭt ma nau khĭt phung sŏng, jêh ri ăn nau rai lôch gâp jêng nâm bu păng!”$b$,false),
('bunong-vn','NUM',23,11,null,$b$Y-Balak lah ma Y-Balaam, “Moh may ƀư jêh ma gâp? Gâp sŏk may ăn may rak rtăp ma phung rlăng gâp, jêh ri aơ, may knŏng mât ton ma khân păng.”$b$,false),
('bunong-vn','NUM',23,12,null,$b$Păng plơ̆ lah, “Gâp mâu mra njrăng hĕ gay ngơi moh nau Yêhôva dơm jêh tâm trôm mbung gâp?”$b$,false),
('bunong-vn','NUM',23,13,null,$b$Y-Balak lah ma păng, “Văch ndrel ma gâp hăn ntŭk êng, tă bơh ntŭk nây may dơi saơ khân păng; may mra saơ đơ phung dăch lơn, jêh ri mâu mra saơ ôh lĕ rngôch khân păng. Ta nây may mra rak rtăp hom khân păng.”$b$,false),
('bunong-vn','NUM',23,14,null,$b$Pô nây, păng leo Y-Balaam tât ta mir Y-Sôphim, klơ mpư̆ yôk Pisga, jêh ri ndâk pơh mlâm nơng jêh ri nhhơr du mlâm ndrôk nkuăng jêh ri du mlâm biăp nkuăng ta klơ ăp nơng.$b$,true),
('bunong-vn','NUM',23,15,null,$b$Y-Balaam lah ma Y-Balak, “Dâk ta aơ meng ndơ may nhhơr gŭ dôl gâp tâm mâp ma Yêhôva ta ri.”$b$,false),
('bunong-vn','NUM',23,16,null,$b$Yêhôva tâm mpơl đah Y-Balaam jêh ri dơm nau ngơi tâm trôm mbung păng, lah, “Plơ̆ sĭt hom ma Y-Balak jêh ri ngơi pô aơ.”$b$,false),
('bunong-vn','NUM',23,17,null,$b$Păng plơ̆ sĭt ma Y-Balak, jêh ri aơ păng dâk kêng meng ndơ păng nhhơr gŭch ndrel ma phung kôranh n'gor Môap. Y-Balak lah ma păng, “Moh nau Yêhôva hŏ ngơi?”$b$,false),
('bunong-vn','NUM',23,18,null,$b$Y-Balaam mbơh nau tâm mpơl păng geh jêh, lah, “Dâk hom, Hơi Y-Balak jêh ri iăt hom! Rkêng tôr hom ma gâp, Hơi kon bu klâu Y-Siphôr:$b$,true),
('bunong-vn','NUM',23,19,null,$b$Brah Ndu mâu jêng du huê bunuyh ôh dĭng păng ngơi mƀruh, mâu lah du huê kon bu klâu bunuyh ôh kŏ tât păng rgâl nau păng mĭn. Moh nau păng lah jêh, mâu hĕ păng mra ƀư ăn tât nau nây?$b$,false),
('bunong-vn','NUM',23,20,null,$b$Aơ, gâp sŏk dơn jêh nau ntĭnh ăn mât ton. Păng mât ton jêh, gâp mâu dơi rgâl nau nây ôh!$b$,true),
('bunong-vn','NUM',23,21,null,$b$Păng mâu saơ ôh nau jêr tâm phung Yakôb mâu lĕ păng saơ nau uh ah tâm phung Israel? Yêhôva Brah Ndu khân păng gŭ ndrel ma khân păng, jêh ri nau hađăch troh rhơn gŭ ta nklang khân păng.$b$,false),
('bunong-vn','NUM',23,22,null,$b$Brah Ndu njŭn khân păng du luh bơh n'gor bri Êjipt; Păng jêng nau ktang ma khân păng nâm bu krŭp.$b$,false),
('bunong-vn','NUM',23,23,null,$b$Mâu geh nau ngơi n'hŭm-chrâng ôh dơi tâm rdâng đah phung Yakôb; mâu geh kan n'hŭm ôh dơi tâm rdâng đah phung Israel, uănh kan khlay ngăn ngên Brah Ndu ƀư jêh!’$b$,false),
('bunong-vn','NUM',23,24,null,$b$Aơ du phung ƀon lan dâk nâm bu du mlâm yau mŭr me, jêh ri khân păng du dâk nâm bu du mlâm yau mŭr nkuăng. Păng mâu kuen ôh tât păng kăp sa hêk mpa mơ păng kuen, jêh ri djrêp jêh dak mham mpa păng hŏ nkhĭt.”$b$,false),
('bunong-vn','NUM',23,25,null,$b$Y-Balak lah ma Y-Balaam, “Lơi rak rtăp ôh ma khân păng, mâu lĕ mât ton ma khân păng.”$b$,false),
('bunong-vn','NUM',23,26,null,$b$Ƀiă lah Y-Balaam plơ̆ lah ma Y-Balak, “Mâu di hĕ nau gâp mbơh ma may, ‘Lĕ moh nau Yêhôva hŏ lah, gâp mra ƀư nau nây?”$b$,false),
('bunong-vn','NUM',23,27,null,$b$Y-Balak lah ma Y-Balaam, Văch hom, gâp mra njŭn may ma ntŭk êng; klăp lah ƀư maak ma Brah Ndu tơ lah may dơi rak rtăp ma khân păng tă bơh ntŭk nây.”$b$,false),
('bunong-vn','NUM',23,28,null,$b$Pô ri Y-Balak njŭn Y-Balaam ta klơ mpư̆ yôk Pêôr mpeh bri rdah,$b$,false),
('bunong-vn','NUM',23,29,null,$b$Y-Balaam lah ma Y-Balak, “Ndâk hom ta aơ ma gâp pơh mlâm nơng jêh ri nkra ta aơ ma gâp pơh mlâm ndrôk nkuăng jêh ri pơh mlâm biăp nkuăng.”$b$,false),
('bunong-vn','NUM',23,30,null,$b$Y-Balak ƀư tĭng nâm Y-Balaam lah jêh, jêh ri du mlâm biăp nkuăng ta klơ ăp nơng.$b$,true),
('bunong-vn','NUM',24,1,null,$b$Tơ lah Y-Balaam saơ Yêhôva maak mât ton ma phung Israel, păng mâu hôm hăn ôh nâm bu sa ơm gay saơ nau tâm mbên, ƀiă lah păng rle muh măt păng mpeh bri rdah.$b$,true),
('bunong-vn','NUM',24,2,null,$b$Y-Balaam n'gơr uănh jêh ri saơ Israel gŭ njơh tĭng nâm băl khân păng êng êng. Jêh ri Huêng Brah Brah Ndu văch gŭ ta păng.$b$,false),
('bunong-vn','NUM',24,3,null,$b$Păng mbơh nau tâm mpơl păng geh jêh, lah, “Nau Y-Balaam kon bu klâu Y-Bêôr ngơi,$b$,false),
('bunong-vn','NUM',24,4,null,$b$nau ngơi tă bơh nơm tăng jêh nau Brah Ndu ngơi, nơm saơ jêh nau tâm saơ bơh Nơm Geh Lĕ Nau Brah, nơm cha lôt, geh măt lin jêh:$b$,false),
('bunong-vn','NUM',24,5,null,$b$Hơi Y-Yakôb, ueh ngăn ngih bok may, Hơi Y-Israel, ueh ngăn ntŭk may gŭ njơh!$b$,false),
('bunong-vn','NUM',24,6,null,$b$Păng nđah huy nâm bu rlŭng yôk, nâm bu n'gar trao ta meng kơh dak krong nâm bu tơm si alôê Yêhôva hŏ tăm, nâm bu tơm si sêdar ta meng n'hor dak.$b$,false),
('bunong-vn','NUM',24,7,null,$b$Dak mra ler pa dih tă trôm thŭng dâng khân păng, jêh ri ntil khân păng mra gŭ tâm âk ntŭk geh dak tŏ. Hađăch khân păng mra jêng toyh lơn ma Y-Agak, jêh ri ƀon bri hađăch khân păng mra văch ma hao.$b$,false),
('bunong-vn','NUM',24,8,null,$b$Brah Ndu njŭn khân păng du luh tă bơh n'gor Êjipt; Păng jêng nau ktang ma khân păng nâm bu krŭp. Khân păng mra kăp sa hêk phung mpôl bunuyh rlăng ma khân păng, jêh ri mra ƀư chah nting khân păng ăn hăch rhên, jêh ri sôr khân ô băl ma hăr khân păng.$b$,false),
('bunong-vn','NUM',24,9,null,$b$Khân păng rmiăt, khân păng păn nâm bu du mlâm yau mŭr nkuăng, mâu lĭn đŏng nâm bu du mlâm yau mŭr me; mbu nơm mra rbĭch khân păng? Ueh ngăn ma mbu nơm mra ăn nau ueh lăng ma may; rak rtăp hom ma mbu nơm mra rak rtăp ma may.”$b$,false),
('bunong-vn','NUM',24,10,null,$b$Y-Balak hao ji nuih ma Y-Balaam, jêh ri tap ti hâu ngăn ma Y-Balaam jêh ri lah: “Gâp kuăl jêh may gay ăn may rak rtăp ma phung rlăng, jêh ri may nkhơng mât ton ma khân păng pe tơ̆ jêh ma aơ.$b$,true),
('bunong-vn','NUM',24,11,null,$b$Yor nây aƀaơ ri dâk hăn hom may rlet ma ntŭk may nơm. Gâp lah jêh, ‘Gâp mra yơk ma may nanê̆ ngăn, ƀiă lah Yêhôva kân may sŏk dơn ro$b$,false),
('bunong-vn','NUM',24,12,null,$b$Y-Balaam lah ma Y-Balak, “Gâp mâu hĕ geh lah ma phung ntuh bâr may văch tât jêh ma gâp.$b$,false),
('bunong-vn','NUM',24,13,null,$b$‘Nđâp tơ lah Y-Balak mra ăn ma gâp ngih păng bêng ma prăk jêh ri mah, gâp mâu dơi ƀư rlau ir ôh ma nau Yêhôva ngơi jêh, ŭch ƀư ueh gĭt lah mhĭk tĭng nâm nau ŭch ƀư ueh gĭt lah mhĭk tĭng nâm nau gâp nơm ŭch; moh nau Yêhôva ngơi, gâp mra ngơi nau nây’?$b$,false),
('bunong-vn','NUM',24,14,null,$b$Aơ, aƀaơ ri, gâp plơ̆ sĭt ma phung ƀon lan gâp nơm. Văch hom, gâp mra mbơh ma may moh nau phung ƀon lan aơ mra ƀư ma phung ƀon lan may du nar kăndơ̆ .”$b$,false),
('bunong-vn','NUM',24,15,null,$b$Păng mbơh nau tâm mpơl păng geh jêh, lah: “Nau Y-Balaam kon bu klâu Y-Bêôr ngơi, nau ngơi tă bơh bunuyh geh măt lin jêh,$b$,false),
('bunong-vn','NUM',24,16,null,$b$Nau ngơi tă bơh nơm iăt nau Brah Ndu ngơi, jêh ri gĭt vât nau Nơm Ta Klơ Dŭt Prêh blau mĭn nơm saơ nau tâm saơ tă bơh Nơm Geh Lĕ Nau Brah, nơm cha lôt, ƀiă lah geh măt lin jêh.$b$,false),
('bunong-vn','NUM',24,17,null,$b$Gâp saơ păng, ƀiă lah mâu di aƀaơ ri ôh; gâp uănh păng, ƀiă lah mâu di gŭ dăch ôh du rplay mănh mra luh bơh phung Yakôb, jêh ri du mlâm mâng hađăch mra luh bơh phung Israel. Păng mra ntâp rho ndăr kleng n'gor Môap, tă bôk aơ rho bôk ri, jêh ri ăn cha lôt lĕ rngôch phung bunuyh brơl ir aơ.$b$,false),
('bunong-vn','NUM',24,18,null,$b$Bu mra mprơh phung Êđôm bơh n'gor păng, tâm ban đŏng bu mra mprơh phung Sêir, phung rlăng păng, dôl phung Israel ƀư ma nau janh ktang.$b$,true),
('bunong-vn','NUM',24,19,null,$b$Du huê bơh phung Yakôb mra chiă uănh jêh ri mra ƀư rai mbu nơm hôm klen tă klaih bơh ƀon toyh”$b$,false),
('bunong-vn','NUM',24,20,null,$b$Jêh ri Y-Balaam uănh ma Y-Amalek jêh ri mbơh nau tâm mpơl păng geh jêh, lah, “Phung Amalek jêng phung mpôl mrô nguay tâm phung mpôl bunuyh, ƀiă lah dăch kêng dŭt khân păng mra rai.”$b$,false),
('bunong-vn','NUM',24,21,null,$b$Y-Balaam uănh ma phung Kênit jêh ri mbơh nau tâm mpơl păng geh jêh, lah, “Ntŭk may gŭ jêng nâp jêh ri rsuăn may gŭ ta klơ lŭ,$b$,false),
('bunong-vn','NUM',24,22,null,$b$ƀiă lah phung Kênit mra rai ndah nâm jŏ phung Asus njŭn leo mra jêng bună?”$b$,false),
('bunong-vn','NUM',24,23,null,$b$Y-Balaam mbơh nau tâm mpơl păng geh jêh, lah, Vơ! Mbu mra hôm e rêh tơ lah Brah Ndu ƀư nau aơ?$b$,true),
('bunong-vn','NUM',24,24,null,$b$Ƀiă lah mra geh âk kŭmpăn mra văch bơh n'gor Kitim jêh ri mra ăn rêh ni phung Asur jêh ri phung Êber; jêh nây nđâp khân păng nơm đŏng mra rai.”$b$,false),
('bunong-vn','NUM',24,25,null,$b$Jêh ta nây; Y-Balaam dâk jêh ri plơ̆ sĭt rlet ma ntŭk păng nơm; jêh ri tâm ban đŏng Y-Balak dâk hăn trong păng nơm.$b$,false),
('bunong-vn','NUM',25,1,null,$b$Dôl phung Israel gŭ ta Sitim phung ƀon lan ntơm ƀư tâm dŏng tĭr đah phung kon bu ur Môap.$b$,true),
('bunong-vn','NUM',25,2,null,$b$Phung bu ur aơ jă phung ƀon lan Israel ma nau ƀư brah ma phung brah khân păng, jêh ri phung ƀon lan sông sa jêh ri chon mbah pa năp brah khân păng.$b$,false),
('bunong-vn','NUM',25,3,null,$b$Pô ri Israel tâm rnglăp đah brah Baal-Pêôr. Jêh ri Yêhôva hao ji nuih ma Israel.$b$,false),
('bunong-vn','NUM',25,4,null,$b$Yêhôva lah ma Y-Môis, “Nhŭp lĕ rngôch phung kôranh tâm phung ƀon lan, jêh ri yông khân păng ta nklang duh nar ta năp Yêhôva, gay ma nau Yêhôva ji nuih dơi aih du bơh Israel.”$b$,false),
('bunong-vn','NUM',25,5,null,$b$Y-Môis lah ma kôranh phat dôih Israel, “Ăn ăp nơm khân may nkhĭt phung bu klâu păng phung tâm rnglăp đah brah Baal Pêôr.”$b$,false),
('bunong-vn','NUM',25,6,null,$b$Aơ, du huê bu klâu tâm phung ƀon lan Israel văch jêh ri djôt leo du huê bu ur Madian ma phung tâm ngih păng ta năp măt Y-Môis jêh ri ta năp măt lĕ rngôch phung ƀon lan Israel tâm rƀŭn, dôl khân păng gŭ nhĭm ta mpông ngih bok tâm rƀŭn,$b$,true),
('bunong-vn','NUM',25,7,null,$b$Tơ lah Y-Phinêas kon bu klâu Y-Êlêasar, sau kôranh ƀư brah Y-Arôn, saơ nau nây, păng dâk cha lơi phung tâm rƀŭn jêh ri sŏk du n'gâr tak tâm ti păng,$b$,false),
('bunong-vn','NUM',25,8,null,$b$tĭng ƀoi bu klâu Israel tâm trôm jrô păng, jêh ri ntâp lĕ bar hê khân păng, bu klâu Israel jêh ri bu ur, rho bluh săk jăn bu ur nây. Pô ri nau tât mhĭk lĕ rlu jêh ta nklang phung ƀon lan Israel.$b$,false),
('bunong-vn','NUM',25,9,null,$b$Ƀiă lah phung lĕ khĭt jêh yor nau tât mhĭk nây geh bar rmưn puăn rbăn bunuyh.$b$,false),
('bunong-vn','NUM',25,10,null,$b$Yêhôva lah ma Y-Môis,$b$,false),
('bunong-vn','NUM',25,11,null,$b$“Y-Phinêas kon bu klâu Y-Êlêasar, sau kôranh ƀư brah Y-Arôn, lĕ ăn rŭch lơi jêh nau gâp ji nuih ma phung ƀon lan Israel, yor lah păng geh nau grang nâm bu gâp ta nklang khân păng, pô nây gâp mâu ƀư rai ôh phung ƀon lan Israel tâm nau gâp grang.$b$,false),
('bunong-vn','NUM',25,12,null,$b$Yor nây lah hom, ‘Aơ gâp ăn ma păng nau gâp tâm rnglăp ma nau đăp mpăn.$b$,true),
('bunong-vn','NUM',25,13,null,$b$Nau nây mra prăp ma păng jêh ri ma phung kon sau păng ô klak pa kơi păng, nau tâm rnglăp ma kan kôranh ƀư brah gŭ mro mrăng, yor lah păng geh nau khŏm nsrôih yor Brah Ndu păng, jêh ri ƀư nau tâm chuai ăn kloh nau tih ma phung ƀon lan Israel.”$b$,false),
('bunong-vn','NUM',25,14,null,$b$Amoh săk bu klâu Israel bu nkhĭt jêh ndrel ma bu ur Madian, jêng Y-Simri, kon bu klâu Y-Salu, kôranh ma du noi deh tâm mpôl Simêôn.$b$,true),
('bunong-vn','NUM',25,15,null,$b$Bu ur Madian bu nkhĭt jêh, amoh păng H'Kôsbi kon bu ur Y-Sur, kôranh ma phung mpôl noi deh tơm tâm phung Madian.$b$,true),
('bunong-vn','NUM',25,16,null,$b$Yêhôva lah ma Y-Môis:$b$,true),
('bunong-vn','NUM',25,17,null,$b$“Ƀư rkhŭk hom phung Madian jêh ri nkhĭt khân păng.$b$,false),
('bunong-vn','NUM',25,18,null,$b$Yor lah khân păng ƀư nau rkhŭk jêh ma khân may ma nau khân păng blau plĕch, ma nau nây khân păng ndơm khân may tâm nau brah Pêôr, jêh ri tâm nau đah H'Kôsbi kon bu ur du huê kôranh Madian, yuh khân păng, nơm bu nkhĭt tâm nar geh nau ji tưp yor nau ma brah Pêôr.”$b$,true),
('bunong-vn','NUM',26,1,null,$b$Lĕ rngơt jêh nau khĭt ji tưp, Yêhôva lah ma Y-Môis jêh ri Y-Êlêasar kon bu klâu Y-Arôn, kôranh ƀư brah.$b$,true),
('bunong-vn','NUM',26,2,null,$b$“Ƀư hom nau kơp lĕ rngôch phung ƀon lan Israel tâm rƀŭn ntơm bơh nơm geh bar jât năm leo klơ, tĭng nâm noi deh khân păng, lĕ rngôch phung Israel dơi hăn ma nau tâm lơh.”$b$,false),
('bunong-vn','NUM',26,3,null,$b$Y-Môis jêh ri kôranh Ƀư brah Y-Êlêasar ngơi ma khân păng tâm neh lâng n'gor Môap dăch dak krong Yurdan tâm tra năp đah ƀon Yêrikô, lah,$b$,false),
('bunong-vn','NUM',26,4,null,$b$‘Ƀư hom nau kơp phung ƀon lan ntơm bơh nơm geh bar jât năm leo klơ; tĭng nâm Yêhôva ntĭnh jêh ma Y-Môis, jêh ri phung Israel hŏ du luh jêh tă bơh n'gor bri Êjipt:$b$,false),
('bunong-vn','NUM',26,5,null,$b$Y-Ruben, kon bôk rah ma Y-Israel, phung kon bu klâu Y-Ruben: Jêng Y-Hanôk; tă bơh păng geh luh mpôl Hanôk; tă bơh Y-Palu geh luh phung mpôl băl Palu;$b$,false),
('bunong-vn','NUM',26,6,null,$b$tă bơh Y-Hêsron geh luh phung mpôl băl Hêron; tă bơh Y-Karmi geh luh phung mpôl băl Karmi;$b$,false),
('bunong-vn','NUM',26,7,null,$b$Aơ jêng phung mpôl Ruben, jêh ri rnoh kơp khân păng geh puăn rmưn pe rbăn pe jât nuyh.$b$,false),
('bunong-vn','NUM',26,8,null,$b$Phung kon bu klâu Y-Palu: Jêng Y-Êliap.$b$,false),
('bunong-vn','NUM',26,9,null,$b$Phung kon bu klâu Y-Êliap: Jêng Y-Nêmuel, Y-Dathan jêh ri Y-Abiram. Aơ yơh Y-Dathan jêh ri Y-Abiram amoh bu săch jêh bơh phung rgum ŭch tâm rdâng đah Y-Môis jêh ri Y-Arôn, yor mpôl ndrel ma Y-Kôrê, tơ lah khân păng tâm rdâng đah Yêhôva.$b$,false),
('bunong-vn','NUM',26,10,null,$b$Nây, tơ lah neh hă trôm mbung păng rvăn khân păng ndrel ma Y-Kôrê, kŏ tât phung nây khĭt, tơ lah dôl ŭnh sa bar rhiăng prăm jât nuyh bu klâu; khân păng leo ƀư pô nây.$b$,false),
('bunong-vn','NUM',26,11,null,$b$Ƀiă lah mpôl Y-Kôrê mâu khĭt lĕ ôh.$b$,true),
('bunong-vn','NUM',26,12,null,$b$Phung kon bu klâu Y-Simêôn tĭng nâm mpôl khân păng: Tă bơh Y-Nêmuel deh luh phung mpôl băl Nêmuel; tă bơh Y-Jamin deh luh phung mpôl băl Jamin; tă bơh Y-Jakin deh luh phung mpôl băl Jakin;$b$,true),
('bunong-vn','NUM',26,13,null,$b$tă bơh Y-Sêra deh luh phung mpôl băl Sêra; tă bơh Y-Sal deh luh phung mpôl băl Y-sal.$b$,false),
('bunong-vn','NUM',26,14,null,$b$Aơ jêng phung mpôl Simêôn, geh bar rmưn bar rbăn bar rhiăng nuyh.$b$,true),
('bunong-vn','NUM',26,15,null,$b$Phung kon bu klâu Y-Gat tĭng nâm phung mpôl băl khân păng: Tă bơh Y-Sêphôn deh luh phung mpôl băl Sêphôn; tă bơh Y-Hagi deh luh phung mpôl băl Hagi; tă bơh Y-Suni deh luh phung mpôl băl Suni;$b$,false),
('bunong-vn','NUM',26,16,null,$b$tă bơh Y-Ôsni deh luh phung mpôl băl Ôsni; tă bơh Y-Êri deh luh phung mpôl băl Êri;$b$,false),
('bunong-vn','NUM',26,17,null,$b$tă bơh Y-Arôt deh luh phung mpôl băl Arôt; tă bơh Y-Arêli deh luh mpôl băl Arêli;$b$,false),
('bunong-vn','NUM',26,18,null,$b$aơ phung mpôl phung kon bu klâu Y-Gat, tĭng rnoh kơp khân păng, geh puăn rmưn prăm rhiăng nuyh.$b$,false),
('bunong-vn','NUM',26,19,null,$b$Phung kon bu klâu Y-Yuđa: Jêng Y-Êr jêh ri Y-Ônan; ƀiă lah Y-Êr jêh ri Y-Ônan lĕ khĭt jêh tâm n'gor Kanaan.$b$,false),
('bunong-vn','NUM',26,20,null,$b$Aơ phung kon bu klâu Y-Yuđa tĭng nâm mpôl băl khân păng: Tă bơh Y-Sêla deh luh phung mpôl băl Sêla; tă bơh Y-Pêres deh luh phung mpôl băl Pêres; tă bơh Y-Sêra deh luh phung mpôl băl Sêra.$b$,true),
('bunong-vn','NUM',26,21,null,$b$Phung kon bu klâu Y-Pêres: Tă bơh Y-Hêsron deh luh phung mpôl băl Hêsron; tă bơh Y-Hamul deh luh phung mpôl băl Hamul.$b$,false),
('bunong-vn','NUM',26,22,null,$b$Aơ phung mpôl Yuđa tĭng nâm rnoh kơp khân păng, geh pơh rmưn prao rbăn prăm rhiăng nuyh.$b$,false),
('bunong-vn','NUM',26,23,null,$b$Phung kon bu klâu Y-Isakar tĭng nâm mpôl băl khân păng: Tă bơh Y-Tôla deh luh phung mpôl băl Tôla; tă bơh Y-Puva deh luh phung mpôl băl Puva;$b$,false),
('bunong-vn','NUM',26,24,null,$b$tă bơh Y-Jasup deh luh phung mpôl băl Jasup; tă bơh Y-Simrôn deh luh phung mpôl băl Simrôn.$b$,false),
('bunong-vn','NUM',26,25,null,$b$Aơ phung mpôl băl Y-Isakar tĭng nâm rnoh kơp khân păng, geh prao rmưn puăn rbăn pe rhiăng nuyh.$b$,false),
('bunong-vn','NUM',26,26,null,$b$Phung kon bu klâu Y-Sabulôn tĭng nâm mpôl băl khân păng: Tă bơh Y-Sêret deh luh phung mpôl băl Sêret; tă bơh Y-Êlon deh luh phung mpôl băl Êlon; tă bơh Y-Jahlêel deh luh phung mpôl băl Jahlêel.$b$,false),
('bunong-vn','NUM',26,27,null,$b$Aơ phung mpôl Sabulôn tĭng nâm rnoh kơp khân păng, geh prao rmưn prăm rhiăng nuyh.$b$,false),
('bunong-vn','NUM',26,28,null,$b$Phung kon bu klâu Y-Yôsep tĭng nâm phung mpôl băl khân păng: Y-Manasê jêh ri Y-Êphraim.$b$,false),
('bunong-vn','NUM',26,29,null,$b$Phung kon bu klâu Y-Manasê: Tă bơh Y-Makir deh luh phung mpôl băl Makir; Y-Makir jêng mbơ̆ ma Y-Galaat; tă bơh Y-Galaat deh luh phung mpôl băl Galaat.$b$,true),
('bunong-vn','NUM',26,30,null,$b$Aơ phung kon bu klâu Y-Galaat: Tă bơh Y-Iêser deh luh phung mpôl băl Iêser; tă bơh Y-Hêlek deh luh phung mpôl băl Hêlak;$b$,true),
('bunong-vn','NUM',26,31,null,$b$tă bơh Y-Ariel deh luh phung mpôl băl Ariel; tă bơh Y-Sichem deh luh phung mpôl băl Sichem;$b$,false),
('bunong-vn','NUM',26,32,null,$b$tă bơh Y-Sêmida deh luh phung mpôl băl Sêmida; tă bơh Y-Hêpher deh luh phung mpôl băl Hêpher.$b$,false),
('bunong-vn','NUM',26,33,null,$b$Jêh ri Y-Sêlôpêhat kon bu klâu Y-Hêpher mâu geh ôh kon bu klâu, ƀiă lah geh dơm phung kon bu ur. Amoh phung kon bu ur Y-Sêlôpêhat: H'Mahla, H'Nôa, H'Hôgla, H'Milka, jêh ri H'Tirsa.$b$,true),
('bunong-vn','NUM',26,34,null,$b$Aơ jêng phung mpôl Manasê, rnoh kơp khân păng geh prăm rmưn bar rbăn pơh rhiăng nuyh.$b$,false),
('bunong-vn','NUM',26,35,null,$b$Aơ phung kon bu klâu Y-Êphraim tĭng nâm mpôl băl khân păng: Tă bơh Y-Suthêla deh luh phung mpôl băl Suthêla; tă bơh Y-Bêker deh luh phung mpôl băl Bêker; tă bơh Y-Tahan deh luh phung mpôl băl Tahan.$b$,true),
('bunong-vn','NUM',26,36,null,$b$Aơ phung kon bu klâu Y-Suthêla: Tă bơh Y-Êran deh luh phung mpôl băl Êran.$b$,true),
('bunong-vn','NUM',26,37,null,$b$Aơ phung kon bu klâu Y-Yôsep tĭng nâm phung mpôl khân păng.$b$,true),
('bunong-vn','NUM',26,38,null,$b$Phung kon bu klâu Y-Benjamin tĭng nâm phung mpôl băl khân păng: Tă bơh Y-Bêla deh luh phung mpôl băl Bêla; tă bơh Y-Asbel deh luh phung mpôl băl Asbel; tă bơh Y-Ahiram deh luh phung mpôl băl Ahiram;$b$,false),
('bunong-vn','NUM',26,39,null,$b$tă bơh Y-Sêphupham deh luh phung mpôl băl Sêphupham; tă bơh Y-Hupham deh luh phung mpôl băl Hupham.$b$,false),
('bunong-vn','NUM',26,40,null,$b$Phung kon bu klâu Y-Bêla: Y-Ardơ jêh ri Y-Naman. Tă bơh Y-Ardơ deh luh phung mpôl băl Ardơ; tă bơh Y-Naman deh luh phung mpôl băl Naman;$b$,false),
('bunong-vn','NUM',26,41,null,$b$Aơ phung kon bu klâu Y-Benjamin tĭng nâm phung mpôl băl khân păng; jêh ri rnoh kơp khân păng geh puăn rmưn prăm rbăn prao rhiăng nuyh.$b$,false),
('bunong-vn','NUM',26,42,null,$b$Aơ phung kon bu klâu Y-Dan tĭng nâm phung mpôl băl khân păng: Tă bơh Y-Suham deh luh phung mpôl băl Suham. Aơ phung mpôl Dan tĭng nâm phung mpôl băl khân păng.$b$,false),
('bunong-vn','NUM',26,43,null,$b$Lĕ rngôch mpôl Suham tĭng nâm rnoh kơp khân păng, geh prao rmưn puăn rbăn puăn rhiăng nuyh.$b$,true),
('bunong-vn','NUM',26,44,null,$b$Phung kon bu klâu Y-Aser tĭng nâm phung mpôl băl khân păng: Tă bơh Y-Imna deh luh phung mpôl băl Imna; tă bơh Y-Isvi deh luh phung mpôl băl Imna; tă bơh Y-Isvi deh luh phung mpôl băl Isvi; tă bơh Y-Bêria deh luh phung mpôl băl Bêria.$b$,false),
('bunong-vn','NUM',26,45,null,$b$Phung kon bu klâu Y-Bêria: Tă bơh Y-Hêber deh luh phung mpôl băl Hêber; tă bơh Y-Malkiel deh luh phung mpôl băl Malkiel.$b$,false),
('bunong-vn','NUM',26,46,null,$b$Amoh phung kon bu ur Y-Aser jêng H'Sêra.$b$,false),
('bunong-vn','NUM',26,47,null,$b$Aơ phung mpôl phung kon bu klâu Y-Aser tĭng nâm rnoh kơp khân păng, geh prăm rmưn pe rbăn puăn rhiăng nuyh.$b$,false),
('bunong-vn','NUM',26,48,null,$b$Phung kon bu klâu Y-Naptali tĭng nâm phung mpôl băl khân păng: Tă bơh Y-Jasêel deh luh phung mpôl băl Jasêel; tă bơh Y-Guni deh luh phung mpôl băl Guni;$b$,false),
('bunong-vn','NUM',26,49,null,$b$tă bơh Y-Jêser deh luh phung mpôl băl Jêser tă bơh Y-Silem deh luh phung mpôl băl Silem.$b$,false),
('bunong-vn','NUM',26,50,null,$b$Aơ phung mpôl Y-Naptali tĭng nâm phung mpôl băl khân păng; jêh ri rnoh kơp khân păng geh puăn rmưn prăm rbăn puăn rhiăng nuyh.$b$,false),
('bunong-vn','NUM',26,51,null,$b$Aơ rnoh kơp phung ƀon lan Israel, geh prao rsen du rbăn pơh rhiăng pe jât nuyh.$b$,true),
('bunong-vn','NUM',26,52,53,$b$“Ma phung aơ bu mra tâm pă neh jêng drăp ndơn chăm tĭng nâm rnoh kơp amoh khân păng.$b$,false),
('bunong-vn','NUM',26,54,null,$b$Ma ndŭl mpôl âk may dơi ăn ndơn drăp toyh lơn, ndŭl mpôl rnoh ƀon lan ƀhôi, pô ri dơi ăn ndơn drăp jê̆ lơn. May mra ăn ma ăp ndŭl mpôl ndơn drăp khân păng tĭng nâm rnoh kơp khân păng.$b$,false),
('bunong-vn','NUM',26,55,null,$b$Ƀiă lah may mra tâm pă n'gor neh ma nau tâm nchroh; khân păng mra ndơn drăp tĭng nâm amoh phung ndŭl mpôl noi deh khân păng.$b$,false),
('bunong-vn','NUM',26,56,null,$b$Ăn may tâm pă ndơn drăp khân păng tĭng nâm nau tâm nchroh ƀă di toyh lơn, ƀă di jê̆ lơn.”$b$,false),
('bunong-vn','NUM',26,57,null,$b$Aơ phung Lêvi bu kơp jêh tĭng nâm phung mpôl khân păng: Tă bơh Y-Gersôn deh luh phung mpôl băl Gersôn; tă bơh Y-Kôhat deh luh phung mpôl băl Kôhat; tă bơh Y-Mêrari deh luh phung mpôl băl Mêrari.$b$,true),
('bunong-vn','NUM',26,58,null,$b$Aơ phung mpôl Lêvi: Mpôl phung Lipni; mpôl phung Hêbron; mpôl phung Mahli, mpôl phung Musi, mpôl phung Kôra. Y-Kôhat jêng mbơ̆ ma Y-Amram.$b$,false),
('bunong-vn','NUM',26,59,null,$b$Amoh ur Y-Amram jêng H'Jôkơbet kon bu ur Y-Lêvi, deh tâm n'gor bri Êjipt; jêh ri păng deh đah Y-Amram, Y-Môis, Y-Arôn jêh ri H'Miriam yuh ma khân păng.$b$,true),
('bunong-vn','NUM',26,60,null,$b$Bi Y-Arôn deh Y-Nadap, Y-Abihu, Y-Êlêasar, jêh ri Y-Itham.$b$,false),
('bunong-vn','NUM',26,61,null,$b$Ƀiă lah Y-Napdap jêh ri Y-Abihu khĭt dôl khân păng nhhơr ŭnh bơh ntŭk êng ta năp Yêhôva.$b$,false),
('bunong-vn','NUM',26,62,null,$b$Rnoh kơp khân păng geh bar rmưn pe rbăn nuyh, ăp nơm bu klâu geh du khay leo klơ; bu mâu kơp ôh khân păng geh ndơn drăp yor lah bu mâu ăn ôh ma khân păng ndrel ma phung ƀon lan Israel.$b$,false),
('bunong-vn','NUM',26,63,null,$b$Aơ phung Y-Môis jêh ri Y-Êlêasar kôranh ƀư brah kơp tơ lah khân păng kơp phung ƀon lan Israel tâm neh lâng n'gor Môap dăch dak krong Yurdan tâm tra năp đah ƀon Yêrikô.$b$,true),
('bunong-vn','NUM',26,64,null,$b$Ƀiă lah tâm phung bunuyh aơ mâu geh du huê bunuyh tâm phung Y-Môis jêh ri kôranh ƀư brah Y-Arôn kơp jêh tơ lah khân păng kơp phung ƀon lan Israel tâm bri rdah Sinai.$b$,false),
('bunong-vn','NUM',26,65,null,$b$Yor lah Yêhôva lah jêh yor phung nây, “Khân păng mra khĭt tâm bri rdah.” Mâu geh du huê hôm e ôh tâm phung khân păng, knŏng Y-Kalep kon bu klâu Y-Jêphunê jêh ri Y-Yôsuê kon bu klâu Y-Nun.$b$,false),
('bunong-vn','NUM',27,1,null,$b$Nôk nây phung kon bu ur Y-Sêlôpêhat kon bu klâu Y-Hêpher, sau Y-Hêpher, sau Y-Galaat, se Y-Makir, săn Y-Manasê, tâm mpôl phung kon bu klâu Y-Yôsep, hăn dăch ngih bok. Amoh phung kon bu ur păng: H'Mahla, H'Nôa, H'Hôgla, H'Milka, jêh ri H'Tirsa.$b$,true),
('bunong-vn','NUM',27,2,null,$b$Khân păng dâk pa năp Y-Môis, pa năp Y-Êlêasar kôranh ƀư brah, pa năp phung kôranh, jêh ri pa năp lĕ rngôch phung tâm rƀŭn ta mpông ngih bok tâm rƀŭn, lah,$b$,false),
('bunong-vn','NUM',27,3,null,$b$“Mbơ̆ hên khĭt tâm bri rdah. Păng mâu jêng ôh tâm phung rgum băl ŭch tâm rdâng đah Yêhôva tâm phung Y-Kôrê, ƀiă lah păng khĭt yor nau tih păng nơm; jêh ri păng mâu geh kon bu klâu ôh.$b$,false),
('bunong-vn','NUM',27,4,null,$b$Mâm amoh mbơ̆ hên bu ăn roh lơi bơh phung mpôl băl păng, yor lah păng mâu geh kon bu klâu ôh? Ăn ma hên du gâl neh ta nklang phung oh nâu mbơ̆ hên.”$b$,false),
('bunong-vn','NUM',27,5,null,$b$Y-Môis leo nau khân păng nây tât ta năp Yêhôva,$b$,false),
('bunong-vn','NUM',27,6,null,$b$jêh ri Yêhôva lah ma Y-Môis,$b$,false),
('bunong-vn','NUM',27,7,null,$b$“Phung kon bu ur Y-Sêlôpêhat geh nau găl; may mra ăn ma khân păng du gâl neh jêng drăp ndơn ta nklang phung oh nâu mbơ̆ khân păng, jêh ri ăn ndơn drăp mbơ̆ khân păng, nâm bu ntĭt jao n'ho ma khân păng ro ndơn drăp mbơ̆ khân păng.$b$,false),
('bunong-vn','NUM',27,8,null,$b$Jêh ri ăn may lah ma phung ƀon lan Israel, ‘Tơ lah du huê bunuyh khĭt, mâu geh kon bu klâu ôh, pô ri khân may mra ăn ma phung kon bu ur păng ndơn drăp mbơ̆ khân păng.$b$,false),
('bunong-vn','NUM',27,9,null,$b$Tơ lah păng mâu geh ôh kon bu ur, khân may mra ăn drăp ndơn păng ma phung oh nâu păng.$b$,true),
('bunong-vn','NUM',27,10,null,$b$Tơ lah păng mâu geh ôh oh nâu, khân may mra ăn ma kônh va, oh nâu mbơ̆ păng.$b$,false),
('bunong-vn','NUM',27,11,null,$b$Tơ lah mbơ̆ păng mâu geh ôh oh nâu, khân may mra ăn drăp ndơn păng ma nơm jêng mpôl dăch đah păng, jêh ri păng mra ndơn drăp nây. Nau nây mra jêng du nau vay jêh ri nau ntĭnh ma phung ƀon lan Israel, tĭng nâm Yêhôva ntĭnh jêh ma Y-Môis.’ ”$b$,false),
('bunong-vn','NUM',27,12,null,$b$Yêhôva lah ma Y-Môis, “Hăn hao hom yôk Abarim aơ jêh ri n'gơr uănh n'gor bri gâp ăn jêh ma phung ƀon lan Israel.$b$,true),
('bunong-vn','NUM',27,13,null,$b$Tơ lah jêh may uănh păng, may mra khĭt jêh ri bu mra sĭt nsum ma phung chô che may đŏng nâm bu bu bun nsum jêh nâu may Y-Arôn,$b$,false),
('bunong-vn','NUM',27,14,null,$b$yor lah may tâm rdâng jêh đah nau gâp ngơi tâm bri rdah Sin dôl phung tâm rƀŭn tâm rdâng, yor lah may mâu yơk ôh ma nau kloh ueh gâp ta dak tra măt khân păng.” (Nây jêng dak Mêriba ta Kadês tâm bri rdah Sin).$b$,false),
('bunong-vn','NUM',27,15,16,$b$“Ăn Yêhôva, Brah Ndu ma phung huêng lĕ rngôch bunuyh săch du huê jêng kôranh ma phung tâm rƀŭn,$b$,false),
('bunong-vn','NUM',27,17,null,$b$nơm mra du luh hăn pa năp khân păng, jêh ri lăp tay pa năp khân păng, nơm mra njŭn khân păng luh jêh ri njŭn khân păng lăp; gay ăn phung Yêhôva tâm rgum mâu jêng ôh nâm bu biăp mâu geh rmăk.”$b$,false),
('bunong-vn','NUM',27,18,null,$b$Yêhôva lah ma Y-Môis, “Sŏk hom Y-Yôsuê kon bu klâu Y-Nun, du huê bu klâu geh Huêng Brah tâm păng, jêh ri dra ti may ta păng.$b$,true),
('bunong-vn','NUM',27,19,null,$b$Ăn păng dâk pa năp kôranh ƀư brah Y-Êlêasar jêh ri lĕ rngôch phung tâm rƀŭn, jêh nây may jao kan ma păng ta năp măt khân păng.$b$,false),
('bunong-vn','NUM',27,20,null,$b$May mra ăn ma păng ƀa ƀă nau dơi may, gay ma lĕ rngôch phung ƀon lan Israel tâm rƀŭn tông ma păng.$b$,true),
('bunong-vn','NUM',27,21,null,$b$Păng mra dâk pa năp kôranh ƀư brah Y-Êlêasar, nơm mra ôp yor Y-Yôsuê ma nau phat dôih Urim ta năp Yêhôva; tĭng nâm nau păng ngơi khân păng mra lăp, Y-Yôsuê nđâp lĕ rngôch phung tâm rƀŭn.”$b$,false),
('bunong-vn','NUM',27,22,null,$b$Y-Môis ƀư tĭng nâm nau Yêhôva ntĭnh jêh ma păng. Păng sŏk Y-Yôsuê jêh ri ăn ô băl dâk pa năp kôranh ƀư brah Y-Êlêasar jêh ri lĕ rngôch phung tâm rƀŭn.$b$,false),
('bunong-vn','NUM',27,23,null,$b$Păng dra ti păng ta ô băl jêh ri jao kan ma ô băl tĭng nâm nau Yêhôva ntĭnh jêh ma Y-Môis.$b$,false),
('bunong-vn','NUM',28,1,null,$b$Yêhôva lah ma Y-Môis,$b$,true),
('bunong-vn','NUM',28,2,null,$b$Ntĭnh hom ma phung ƀon lan Israel jêh ri lah ma khân păng, “Ăn khân may njrăng nhhơr ma gâp tâm di yan ndơ nhhơr ăn ŭnh sa, n'hôl ƀâu kah ma gâp.”$b$,false),
('bunong-vn','NUM',28,3,null,$b$Ăn may lah ma khân păng, Aơ ndơ nhhơr ăn ŭnh sa khân may mra nhhơr ma Yêhôva: Ăp nar bar mlâm biăp kon nkuăng du năm deh, mâu geh ntŭk mhĭk ôh, jêng ndơ nhhơr gŭ mro.$b$,false),
('bunong-vn','NUM',28,4,null,$b$May mra nhhơr du mlâm biăp kon nây ơm ôi, jêh ri dăch kêng măng ăn may nhhơr biăp kon nkuăng êng.$b$,false),
('bunong-vn','NUM',28,5,null,$b$Tâm ban đŏng ăn may nhhơr du kô̆ tâm jât êpha rnih muy jêng ndơ nhhơr rnih muy, tâm pot đah du kô̆ tâm puăn hin dak play ôlivơ lĕ păt.$b$,false),
('bunong-vn','NUM',28,6,null,$b$Nây jêng ndơ nhhơr gŭch gŭ mro, bu ntĭnh jêh ta yôk Sinai jêng n'hôl ƀâu kah, ndơ nhhơr ăn ŭnh sa ma Yêhôva.$b$,false),
('bunong-vn','NUM',28,7,null,$b$Ndơ nhhơr nhêt ndrel mra jêng du kô̆ tâm puăn hin ma ăp biăp kon; tâm ntŭk kloh ueh ăn may nkhŭt ndơ nhhơr nhêt dak ndrănh ma Yêhôva.$b$,true),
('bunong-vn','NUM',28,8,null,$b$Du mlâm biăp êng ri ăn may nhhơr dăch kêng măng; nâm bu nhhơr rnih muy ta kêng ôi, jêh ri nâm bu ndơ nhhơr nhêt ndrel, ăn may nhhơr păng jêng ndơ nhhơr ăn ŭnh sa, n'hôl ƀâu kah ma Yêhôva.$b$,false),
('bunong-vn','NUM',28,9,null,$b$“Tâm nar Saƀat ăn may nhhơr bar mlâm biăp kon nkuăng bêng du năm, mâu geh ôh ntŭk mhĭk, jêh ri bar kô̆ tâm jât êpha rnih muy tâm pot đah dak play Ôlivơ jêng ndơ nhhơr rnih muy, ndrel ma ndơ nhhơr nhêt.$b$,true),
('bunong-vn','NUM',28,10,null,$b$Nây jêng muy nhhơr gŭch ăp nar Saƀat, rmeh ma ndơ nhhơr gŭch gŭ mro jêh ri ndơ nhhơr nhêt ndrel.$b$,false),
('bunong-vn','NUM',28,11,null,$b$Ăp tơ̆ bôk khay ăn may nhhơr du ndơ nhhơr gŭch ma Yêhôva: Bar mlâm ndrôk nkuăng rah, du mlâm biăp nkuăng, jêh ri pơh mlâm biăp kon nkuăng bêng du năm mâu geh ôh ntŭk mhĭk;$b$,true),
('bunong-vn','NUM',28,12,null,$b$tâm ban đŏng pe kô̆ tâm jât rnih muy tâm pot đah dak play ôlivơ jêng ndơ nhhơr rnih muy ma ăp mlâm ndrôk nkuăng; jêh ri bar kô̆ tâm jât êpha rnih muy tâm pot đah dak play ôlivơ jêng ndơ nhhơr rnih muy ma du mlâm biăp nkuăng;$b$,false),
('bunong-vn','NUM',28,13,null,$b$jêh ri du kô̆ tâm jât rnih muy tâm pot đah dak play ôlivơ jêng ndơ nhhơr rnih muy ma ăp mlâm biăp kon, prăp ma ndơ nhhơr gŭch n'hôl ƀâu kah, ndơ nhhơr ăn ŭnh sa ma Yêhôva.$b$,false),
('bunong-vn','NUM',28,14,null,$b$Ndơ nhhơr nhêt ndrel mra jêng du n'gul hin dak play kriăk ƀâu ma du mlâm ndrôk nkuăng, du kô̆ tâm pe hin ma du mlâm biăp nkuăng, jêh ri du kô̆ tâm puăn hin ma du mlâm biăp kon; nây jêng ndơ nhhơr gŭch ăp tơ̆ bôk khay tâm du năm.$b$,false),
('bunong-vn','NUM',28,15,null,$b$Ăn may nhhơr tâm ban đŏng ma Yêhôva du mlâm be nkuăng jêng ndơ nhhơr chuai yor nau tih, pa dih ma ndơ nhhơr gŭch gŭ mro ndrel ma ndơ nhhơr nhêt.$b$,false),
('bunong-vn','NUM',28,16,null,$b$“Ta nar jât ma puăn khay nguay jêng Nau Yêhôva Găn.$b$,true),
('bunong-vn','NUM',28,17,null,$b$Ta nar jât ma prăm tâm khay nây jêng du nar nhêt sông; dôl pơh nar khân may mra sa piăng let mâu geh ndrui.$b$,false),
('bunong-vn','NUM',28,18,null,$b$Ta nar ntơm nguay khân may mra geh nau tâm rƀŭn kloh ueh: Khân may mâu dơi ƀư du ntil kan ma nglay săk ôh.$b$,false),
('bunong-vn','NUM',28,19,null,$b$Ƀiă lah mra nhhơr du ndơ ăn ŭnh sa, du ndơ nhhơr gŭch, ma Yêhôva: Bar mlâm ndrôk nkuăng rah, du mlâm biăp nkuăng, jêh ri pơh mlâm biăp kon nkuăng bêng du năm, mâu geh ntŭk mhĭk ôh,$b$,false),
('bunong-vn','NUM',28,20,null,$b$ndrel ma ndơ nhhơr rnih muy tâm pot đah dak play ôlivơ. Khân may mra nhhơr pe kô̆ tâm jât êpha ma du mlâm ndrôk nkuăng, bar kô̆ tâm jât êpha ma du mlâm biăp nkuăng.$b$,false),
('bunong-vn','NUM',28,21,null,$b$Jêh ri du kô̆ tâm jât êpha ma ăp mlâm tâm pơh mlâm biăp kon.$b$,true),
('bunong-vn','NUM',28,22,null,$b$Ăn may nhhơr du mlâm be nkuăng jêng ndơ nhhơr chuai yor nau tih, gay ƀư ăn kloh nau tih khân may.$b$,false),
('bunong-vn','NUM',28,23,null,$b$Khân may mra nhhơr ndơ aơ pa dih ma ndơ nhhơr gŭch ôi, jêng ndơ nhhơr gŭch gŭ mro.$b$,false),
('bunong-vn','NUM',28,24,null,$b$Tâm ban pô nây lĕ ăn may nhhơr ăp nar dôl pơh nar ndơ sông sa jêng ndơ nhhơr ăn ŭnh sa, n'hôl ƀâu kah ma Yêhôva. Ăn khân may nhhơr ndơ nây pa dih ma ndơ nây pa dih ma ndơ nhhơr gŭch gŭ mro jêh ri ndơ nhhơr nhêt ndrel.$b$,false),
('bunong-vn','NUM',28,25,null,$b$Nar năng pơh ăn khân may geh nau tâm rƀŭn kloh ueh; lơi ăn khân may ƀư du ntil kan ma nglay săk ôh.$b$,false),
('bunong-vn','NUM',28,26,null,$b$“Ta nar geh play dak bôk, tơ lah khân may nhhơr ndơ nhhơr rnih muy ba mhe ma Yêhôva ta nar năng nar ver khân may, ăn khân may geh nau tâm rƀŭn kloh ueh; khân may mâu dơi ƀư du ntil kan ma nglay săk ôh,$b$,false),
('bunong-vn','NUM',28,27,null,$b$ƀiă lah nhhơr ndơ nhhơr gŭch, n'hôl ƀâu kah ma Yêhôva: Bar mlâm ndrôk nkuăng rah, du mlâm biăp nkuăng, pơh mlâm biăp kon nkuăng bêng du năm;$b$,false),
('bunong-vn','NUM',28,28,null,$b$jêh ri ndơ muy nhhơr rnih muy tâm pot đah dak play ôlivơ, pe kô̆ tâm jât êpha ma ăp mlâm ndrôk nkuăng, bar kô̆ tâm jât êpha ma du mlâm biăp nkuăng,$b$,false),
('bunong-vn','NUM',28,29,null,$b$du kô̆ tâm jât êpha ma ăp mlâm tâm pơh mlâm biăp kon;$b$,false),
('bunong-vn','NUM',28,30,null,$b$jêh ri du mlâm be nkuăng gay chuai nau ăn kloh nau tih khân may.$b$,false),
('bunong-vn','NUM',28,31,null,$b$Ăn khân may nhhơr ndơ nây pa dih ma ndơ nhhơr gŭch gŭ mro ndrel ma ndơ nhhơr rnih muy. Khân may mra nhhơr ndơ nây ndrel ma ndơ nhhơr nhêt. Njrăng ma ndơ nhhơr nây, mâu geh ntŭk mhĭk ôh.$b$,false);
insert into public.bible_verses (translation_id, book_code, chapter, verse, verse_end, text, para) values
('bunong-vn','NUM',29,1,null,$b$Ta nar nguay khay pơh, khân may mra geh nau tâm rƀŭn kloh ueh; khân may lơi ta ƀư du ntil kan ma nglay săk ôh; jêng du nar ma khân may uh nŭng.$b$,true),
('bunong-vn','NUM',29,2,null,$b$Jêh ri khân may mra nhhơr du ndơ nhhơr gŭch, n'hôl ƀâu kah ma Yêhôva: Du mlâm ndrôk nkuăng rah, du mlâm biăp nkuăng, pơh mlâm biăp kon nkuăng bêng du năm, mâu geh ôh du ntŭk mhĭk,$b$,true),
('bunong-vn','NUM',29,3,null,$b$ndrel ma ndơ nhhơr rnih muy tâm pot đah dak play ôlivơ, pe kô̆ tâm jât êpha ma ndrôk nkuăng nây, bar kô̆ tâm jât êpha ma biăp nkuăng nây,$b$,false),
('bunong-vn','NUM',29,4,null,$b$du kô̆ tâm jât êpha ma ăp mlâm tâm pơh mlâm biăp kon;$b$,false),
('bunong-vn','NUM',29,5,null,$b$ndrel ma be nkuăng jêng ndơ nhhơr chuai yor nau tih, gay ƀư ăn kloh nau tih khân may,$b$,false),
('bunong-vn','NUM',29,6,null,$b$pa dih ma ndơ nhhơr gŭch ta khay mhe ndrel ma ndơ nhhơr rnih muy, jêh ri ndơ nhhơr gŭch gŭ mro, ndrel ma ndơ nhhơr rnih muy ndrel ma ndơ nhhơr nhêt, tĭng nâm nau ntĭnh jêh ma ndơ nây, du nau n'hôl ƀâu kah, du ndơ nhhơr ăn ŭnh sa, ma Yêhôva.$b$,false),
('bunong-vn','NUM',29,7,null,$b$“Ta nar jât khay pơh aơ, ăn khân may geh nau tâm rƀŭn kloh ueh, jêh ri ăn khân may der êng huêng khân may nơm, lơi ta ƀư ôh du ntil kan tâm nglay săk.$b$,true),
('bunong-vn','NUM',29,8,null,$b$Ƀiă lah khân may nhhơr du ndơ nhhơr gŭch ma Yêhôva, jêng n'hôl ƀâu kah: Du mlâm ndrôk nkuăng rah, du mlâm biăp nkuăng, pơh mlâm biăp kon nkuăng bêng du năm, mâu geh ôh ntŭk mhĭk,$b$,false),
('bunong-vn','NUM',29,9,null,$b$ndrel ma ndơ nhhơr rnih muy tâm pot đah dak play ôlivơ, pe kô̆ tâm jât êpha ma ndrôk nkuăng nây, bar kô̆ tâm jât êpha ma biăp nkuăng nây,$b$,false),
('bunong-vn','NUM',29,10,null,$b$du kô̆ tâm jât êpha ma ăp mlâm tâm pơh mlâm biăp kon;$b$,false),
('bunong-vn','NUM',29,11,null,$b$jêh ri du mlâm be nkuăng jêng ndơ nhhơr chuai yor nau tih, pa dih ma ndơ nhhơr chuai yor nau tih tâm nau ăn kloh nau tih, jêh ri ndơ nhhơr gŭch gŭ mro ndrel ma ndơ nhhơr rnih muy, jêh ri ndơ nhhơr nhêt.$b$,false),
('bunong-vn','NUM',29,12,null,$b$“Ta nar jât ma prăm khay pơh ăn khân may geh nau tâm rƀŭn kloh ueh. Lơi ta ƀư ôh du ntil kan tâm nglay săk, jêh ri khân may mra kah gĭt prăp du nau năng ver ăn ma Yêhôva tâm pơh nar.$b$,false),
('bunong-vn','NUM',29,13,null,$b$Khân may mra nhhơr du ndơ nhhơr gŭch, ndơ nhhơr ăn ŭnh sa, n'hôl ƀâu kah ma Yêhôva jât ma pe mlâm ndrôk nkuăng rah, bar mlâm biăp nkuăng, jât ma puăn mlâm biăp kon nkuăng bêng du năm mâu geh ôh ntŭk mhĭk,$b$,true),
('bunong-vn','NUM',29,14,null,$b$ndrel ma ndơ nhhơr rnih muy tâm pot đah dak play ôlivơ, pe kô̆ tâm jât êpha ma ăp mlâm tâm jât ma pe mlâm ndrôk nkuăng, bar kô̆ tâm jât êpha ma ăp mlâm tâm bar mlâm biăp nkuăng,$b$,false),
('bunong-vn','NUM',29,15,null,$b$jêh ri du kô̆ tâm jât êpha ma ăp mlâm tâm jât ma puăn mlâm biăp kon;$b$,false),
('bunong-vn','NUM',29,16,null,$b$jêh ri du mlâm be nkuăng jêng ndơ nhhơr chuai yor nau tih, pa dih ma ndơ nhhơr gŭch gŭ mro, ndrel ma ndơ nhhơr rnih muy jêh ri ndơ nhhơr nhêt.$b$,false),
('bunong-vn','NUM',29,17,null,$b$“Ta nar năng bar, khân may mra nhhơr jât ma bar mlâm ndrôk nkuăng rah, bar mlâm biăp nkuăng, jât ma puăn mlâm biăp kon nkuăng bêng du năm mâu geh ôh ntŭk mhĭk,$b$,false),
('bunong-vn','NUM',29,18,null,$b$ndrel ma ndơ nhhơr rnih muy jêh ri ndơ nhhơr nhêt ma lĕ rngôch ndrôk nkuăng, ma biăp nkuăng, jêh ri ma biăp kon tĭng rhui ndah âk mlâm khân păng tĭng nâm nau ntĭnh,$b$,false),
('bunong-vn','NUM',29,19,null,$b$tâm ban đŏng du mlâm be nkuăng jêng ndơ nhhơr chuai yor nau tih, pa dih ma ndơ nhhơr gŭch gŭ mro, ndrel ma ndơ nhhơr rnih muy jêh ri ndơ nhhơr nhêt.$b$,false),
('bunong-vn','NUM',29,20,null,$b$“Ta nar năng pe khân may mra nhhơr jât ma nguay mlâm ndrôk nkuăng, bar mlâm biăp nkuăng, jât ma puăn mlâm biăp kon nkuăng bêng du năm mâu geh ôh ntŭk mhĭk;$b$,false),
('bunong-vn','NUM',29,21,null,$b$ndrel ma ndơ nhhơr rnih muy jêh ri ndơ nhhơr nhêt ma ndrôk nkuăng, ma biăp nkuăng, jêh ri ma biăp kon tĭng rhui ndah mlâm khân păng tĭng nâm nau ntĭnh;$b$,false),
('bunong-vn','NUM',29,22,null,$b$tâm ban đŏng du mlâm be nkuăng jêng ndơ nhhơr chuai yor nau tih, pa dih ma ndơ nhhơr gŭch gŭ mro, ndrel ma ndơ rnih muy jêh ri ndơ nhhơr nhêt.$b$,false),
('bunong-vn','NUM',29,23,null,$b$“Ta nar năng puăn khân may mra nhhơr jât mlâm ndrôk nkuăng, bar mlâm biăp nkuăng, jât ma puăn mlâm biăp kon nkuăng bêng du năm mâu geh ôh ntŭk mhĭk,$b$,false),
('bunong-vn','NUM',29,24,null,$b$ndrel ma ndơ nhhơr rnih muy jêh ri ndơ nhhơr nhêt ma ndrôk nkuăng, ma biăp nkuăng, jêh ri ma biăp kon tĭng rhui ndah mlâm khân păng tĭng nâm nau ntĭnh;$b$,false),
('bunong-vn','NUM',29,25,null,$b$tâm ban đŏng du mlâm be nkuăng jêng ndơ nhhơr chuai yor nau tih, pa dih ma ndơ nhhơr gŭch gŭ mro, ndrel ma ndơ nhhơr rnih muy jêh ri ndơ nhhơr nhêt.$b$,false),
('bunong-vn','NUM',29,26,null,$b$“Ta nar năng prăm khân may mra nhhơr sĭn mlâm ndrôk nkuăng, bar mlâm biăp nkuăng, jât ma puăn mlâm biăp kon nkuăng bêng du năm mâu geh ôh ntŭk mhĭk,$b$,false),
('bunong-vn','NUM',29,27,null,$b$ndrel ma ndơ nhhơr rnih muy jêh ri ndơ nhhơr nhêt ma ndrôk nkuăng, ma biăp nkuăng jêh ri ma biăp kon tĭng rhui ndah mlâm khân păng tĭng nâm nau ntĭnh,$b$,false),
('bunong-vn','NUM',29,28,null,$b$tâm ban đŏng du mlâm be nkuăng jêng ndơ nhhơr chuai yor nau tih, pa dih ma ndơ nhhơr gŭch gŭ mro, ndrel ma ndơ nhhơr rnih muy jêh ri ndơ nhhơr nhêt.$b$,false),
('bunong-vn','NUM',29,29,null,$b$“Ta nar năng prao khân may mra nhhơr pham mlâm ndrôk nkuăng, bar mlâm biăp nkuăng, jât ma puăn mlâm biăp kon nkuăng bêng du năm mâu geh ôh ntŭk mhĭk,$b$,false),
('bunong-vn','NUM',29,30,null,$b$ndrel ma ndơ rnih muy jêh ri ndơ nhhơr nhêt ma ndrôk nkuăng, ma biăp nkuăng, jêh ri ma biăp kon tĭng rhui ndah mlâm khân păng tĭng nâm nau ntĭnh;$b$,false),
('bunong-vn','NUM',29,31,null,$b$tâm ban đŏng du mlâm be nkuăng jêng ndơ nhhơr chuai yor nau tih, pa dih ma ndơ nhhơr gŭ mro, ndrel ma ndơ nhhơr nhêt.$b$,false),
('bunong-vn','NUM',29,32,null,$b$“Ta nar năng pơh khân may mra nhhơr pơh mlâm ndrôk nkuăng, bar mlâm biăp nkuăng, jât ma puăn mlâm biăp kon nkuăng bêng du năm mâu geh ôh ntŭk mhĭk,$b$,true),
('bunong-vn','NUM',29,33,null,$b$ndrel ma ndơ nhhơr rnih muy jêh ri nhhơ nhhơr nhêt ma ndrôk nkuăng, ma biăp nkuăng, jêh ri ma biăp kon tĭng rhui ndah mlâm khân păng tĭng nâm nau ntĭnh;$b$,false),
('bunong-vn','NUM',29,34,null,$b$tâm ban đŏng du mlâm be nkuăng jêng ndơ nhhơr chuai yor nau tih, pa dih ma ndơ nhhơr gŭch gŭ mro, ndrel ma ndơ nhhơr rnih muy jêh ri ndơ nhhơr nhêt.$b$,false),
('bunong-vn','NUM',29,35,null,$b$“Ta nar năng pham khân may mra geh nau tâm rƀŭn geh nau yơk. Lơi ta ƀư ôh du ntil kan ma nglay săk.$b$,true),
('bunong-vn','NUM',29,36,null,$b$Ƀiă lah khân may mra nhhơr du ndơ nhhơr gŭch, jêng ndơ nhhơr ăn ŭnh sa, n'hôl ƀâu kah ma Yêhôva: Du mlâm ndrôk nkuăng, du mlâm biăp nkuăng, pơh mlâm biăp kon nkuăng bêng du năm mâu geh ôh ntŭk mhĭk;$b$,false),
('bunong-vn','NUM',29,37,null,$b$ndrel ma ndơ nhhơr rnih muy jêh ri ndơ nhhơr nhêt ma ndrôk nkuăng nây, ma biăp nkuăng nây, jêh ri ma lĕ rngôch biăp kon tĭng rhui ndah mlâm khân păng tĭng nâm nau ntĭnh;$b$,false),
('bunong-vn','NUM',29,38,null,$b$tâm ban đŏng du mlâm be nkuăng jêng ndơ nhhơr chuai yor nau tih, pa dih ma ndơ nhhơr gŭch gŭ mro, ndrel ma nhhơr rnih muy jêh ri ndơ nhhơr nhêt.$b$,false),
('bunong-vn','NUM',29,39,null,$b$“Ndơ nây khân may mra nhhơr ma Yêhôva ta nar năng khân may tâm nal jêh, pa dih ma ndơ nhhơr khân may ăn nanê̆ nau ton jêh ri ndơ khân may nhhơr ma nuih n'hâm lŏng, ma ndơ khân may nhhơr gŭch, ma ndơ khân may nhhơr rnih muy, ma ndơ khân may nhhơr nhêt, jêh ri ma ndơ khân may nhhơr ma nau đăp mpăn.”$b$,true),
('bunong-vn','NUM',29,40,null,$b$Y-Môis mbơh ma phung ƀon lan Israel lĕ rngôch nau di tĭng nâm Yêhôva ntĭnh jêh ma păng.$b$,true),
('bunong-vn','NUM',30,1,null,$b$Y-Môis lah ma phung ƀon lan Israel lĕ nau Yêhôva hŏ ngơi jêh ma păng.$b$,true),
('bunong-vn','NUM',30,2,null,$b$Y-Môis lah ma phung kôranh ma phung ndŭl mpôl Israel, “Aơ nau Yêhôva hŏ ntĭnh jêh:$b$,true),
('bunong-vn','NUM',30,3,null,$b$Tơ lah du huê bu klâu ƀư jêh nau ton ma Yêhôva, mâu lah ton sơm ma nau ăn ndơ ton, păng mâu dơi rlau ôh nau păng ngơi; ăn păng ƀư ăn lĕ tĭng nâm nau păng hŏ ngơi.$b$,false),
('bunong-vn','NUM',30,4,null,$b$Tơ lah du huê bu ur ƀư nau ton ma Yêhôva jêh ri tâm nkol ma ndơ ton dôl hôm e tâm ngih mbơ̆ păng nôk păng druh mom,$b$,false),
('bunong-vn','NUM',30,5,null,$b$jêh ri mbơ̆ păng tăng jêh nau păng ton, ndơ păng ton tâm nkol jêh ma păng nơm, jêh ri mbơ̆ păng mâu ngơi ôh ma păng; pô ri lĕ rngôch nau păng ton mra hôm e, jêh ri lĕ rngôch ndơ păng ton tâm nkol jêh ma păng nơm mra hôm e.$b$,false),
('bunong-vn','NUM',30,6,null,$b$Ƀiă lah tơ lah mbơ̆ păng tâm mpơl nau păng mâu dơn ta nar păng tăng nau nây, nau păng ton jêh, jêh ri ndơ păng ton tâm nkol jêh ma păng nơm mâu mra hôm e ôh. Yêhôva mra yô̆ an ma păng, yor lah mbơ̆ păng dun jêh ma păng.$b$,false),
('bunong-vn','NUM',30,7,null,$b$Tơ lah bu ur nây gŭ sai jêh, dôl păng geh nau ton mâu lah ma nau ngơi mâu mĭn luh tă trôm mbung păng, ma nau nây păng tâm nkol jêh păng nơm,$b$,false),
('bunong-vn','NUM',30,8,null,$b$jêh ri tơ lah sai păng tăng nau nây, jêh ri tơ lah ô băl mâu ngơi ôh ma păng ta nar ô băl tăng nau nây; pô nây nau păng ton jêh mra hôm e, jêh ri ndơ păng ton tâm nkol jêh ma păng nơm mra hôm e.$b$,false),
('bunong-vn','NUM',30,9,null,$b$Ƀiă lah tơ lah ta nar sai păng tăng nau nây ô băl tâm mprơh nau mâu dơn, pô ri ô băl mra ngroh lơi nau păng ton jêh, jêh ri nau păng ngơi mâu mĭn tă bơh trôm mbung păng, ma nau nây păng geh nau tâm nkol jêh păng nơm; jêh ri Yêhôva mra yô̆ ma păng.$b$,false),
('bunong-vn','NUM',30,10,null,$b$Ƀiă lah nau ton du huê bu ur ndrô khĭt sai mâu lah du huê bu ur bu cha lơi jêh, moh nau păng tâm nkol jêh păng nơm mra hôm e.$b$,false),
('bunong-vn','NUM',30,11,null,$b$Tơ lah păng ƀư nau ton tâm ngih sai păng, mâu lah tâm nkol ma păng nơm ma ndơ ton ndrel ma nau ton săk,$b$,false),
('bunong-vn','NUM',30,12,null,$b$jêh ri sai păng tăng nau nây jêh ri mâu ngơi ôh ma păng, jêh ri mâu dun ôh ma păng; pô ri lĕ rngôch nau păng lĕ ton jêh mra hôm e, jêh ri lĕ rngôch ndơ ton păng tâm nkol jêh păng nơm mra hôm e.$b$,false),
('bunong-vn','NUM',30,13,null,$b$Ƀiă lah tơ lah sai păng ngroh lơi nau nây nar ô băl tăng, pô ri lĕ rngôch nau păng ngơi di ma nau păng ton mâu lah di ma ndơ păng ton mâu mra hôm e ôh; sai păng ngroh jêh nau nây, jêh ri Yêhôva mra yô̆ an ma păng.$b$,false),
('bunong-vn','NUM',30,14,null,$b$Sai păng dơi ƀư nâp mâu lah ngroh lĕ rngôch nau păng ton jêh ri lĕ rngôch nau păng ton tâm nkol ƀư rêh ni huêng păng nơm.$b$,false),
('bunong-vn','NUM',30,15,null,$b$Ƀiă lah tơ lah sai păng mâu ngơi ma păng ăp nar pô nây, ô băl ƀư nâp lĕ rngôch nau păng ton jêh mâu lah lĕ rngôch ndơ ton păng ƀư jêh. Ô băl ƀư nâp jêh nau nây, yor lah ô băl mâu ngơi ôh ma păng ta nar ô băl tăng nau nây.$b$,true),
('bunong-vn','NUM',30,16,null,$b$Ƀiă lah tơ lah ô băl ngroh nau nây jêh ô băl tăng, pô ri ô băl mra anh nau kue păng.”$b$,false),
('bunong-vn','NUM',30,17,null,$b$Nây nau vay Yêhôva ntĭnh jêh ma Y-Môis nâm bu nau ndrăng ur sai, jêh ri ndrăng mbơ̆ đah kon bu ur păng dôl ô băl gŭ druh mom tâm ngih mbơ̆ păng.$b$,true),
('bunong-vn','NUM',31,1,null,$b$Yêhôva lah ma Y-Môis,$b$,true),
('bunong-vn','NUM',31,2,null,$b$“Yor phung ƀon lan Israel har plơng hom ma phung Madian. Jêh nau nây bu mra ăn may hăn gŭ ndrel ma phung che may.”$b$,false),
('bunong-vn','NUM',31,3,null,$b$Y-Môis lah ma phung ƀon lan, “Ăn ndơ tâm lơh ma phung bu klâu ta nklang khân may, gay ma khân păng dơi hăn tâm lơh đah phung Madian, gay ăn tât nau Yêhôva har plơng ma phung Madian.$b$,true),
('bunong-vn','NUM',31,4,null,$b$Ăn may prơh hăn du rbăn nuyh bu klâu tă bơh ăp mpôl Israel ma nau tâm lơh.”$b$,false),
('bunong-vn','NUM',31,5,null,$b$Pô ri tâm âk rbăn phung Israel bu săch du rbăn nuyh tă bơh ăp mpôl, geh du rmưn bar rbăn nuyh djôt ndơ tâm lơh.$b$,false),
('bunong-vn','NUM',31,6,null,$b$Y-Môis prơh hăn khân păng ma nau tâm lơh, du rbăn nuyh tă bơh ăp mpôl, ndrel ma Y-Phinêas kon bu klâu kôranh ƀư brah Y-Êlêasar djôt leo ndrel ma păng ndơ dŏng ma jrô kloh ueh jêh ri nŭng uh gay ngloh.$b$,false),
('bunong-vn','NUM',31,7,null,$b$Khân păng tâm lơh đah phung Madian tĭng nâm nau Yêhôva ntĭnh jêh ma Y-Môis, jêh ri khân păng nkhĭt lĕ rngôch phung bu klâu.$b$,false),
('bunong-vn','NUM',31,8,null,$b$Khân păng nkhĭt phung hađăch Madian ndrel ma phung khân păng hŏ nkhĭt jêh, prăm nuyh hađăch Madian amoh: Y-Êwi, Y-Rêkem, Y-Sur, Y-Hur jêh ri Y-Rêba. Khân păng nkhĭt đŏng Y-Balaam kon bu klâu Y-Bêôr ma mpiăt đao.$b$,true),
('bunong-vn','NUM',31,9,null,$b$Phung ƀon lan Israel veng leo jêng bu nă phung bu ur Madian jêh ri phung kon se jê̆ khân păng; jêh ri khân păng sŏk gro lĕ rngôch ndrôk, biăp jêh ri lĕ rngôch drăp ndơ khân păng.$b$,false),
('bunong-vn','NUM',31,10,null,$b$Khân păng su ma ŭnh lĕ rngôch ƀon toyh khân păng gŭ, nđâp lĕ rngôch ntŭk khân păng njơh,$b$,true),
('bunong-vn','NUM',31,11,null,$b$jêh ri sŏk djôt lĕ rngôch ndơ sŏk gro, lĕ rngôch drăp tă bơh bunuyh jêh ri mpôl mpa rong.$b$,false),
('bunong-vn','NUM',31,12,null,$b$Pô nây khân păng djôt leo phung bu nă, ndơ sŏk gro, jêh ri drăp ndơ ma Y-Môis, ma kôranh ƀư brah Y-Êlêasar, jêh ri ma phung ƀon lan Israel tâm rƀŭn ta ntŭk njơh tâm neh lâng n'gor Môap dăch dak krong Yurdan tâm tra đah Yêrikô.$b$,false),
('bunong-vn','NUM',31,13,null,$b$Y-Môis, kôranh ƀư brah Y-Êlêasar, jêh ri lĕ rngôch phung kôranh phung tâm rƀŭn luh hăn tâm mâp đah khân păng ta pa dih mpâr.$b$,false),
('bunong-vn','NUM',31,14,null,$b$Y-Môis nuih ma phung kôranh ta han, phung kôranh ma rbăn nuyh jêh ri phung kôranh ma rhiăng nuyh sĭt tă tâm lơh.$b$,false),
('bunong-vn','NUM',31,15,null,$b$Y-Môis lah ma khân păng, “Khân may ŭch om lĕ rngôch phung bu ur hôm rêh lĕ?$b$,false),
('bunong-vn','NUM',31,16,null,$b$Aơ, jêng phung tĭng nau Y-Balaam nchră ăn phung ƀon lan Israel ƀư brah mbah rup tâm kan brah Pêôr, ƀư nau tâm dŏng tĭr ta năp măt Yêhôva, yor nây nau ji khĭt ntưp tât ma phung Yêhôva tâm rƀŭn.$b$,false),
('bunong-vn','NUM',31,17,null,$b$Pô nây aƀaơ ri nkhĭt lơi lĕ rngôch phung bu klâu tâm phung kon se jê̆, jêh ri nkhĭt lơi lĕ rngôch bu ur lĕ tă mâp bêch jêh ndrel bu klâu.$b$,true),
('bunong-vn','NUM',31,18,null,$b$Ƀiă lah prăp om rêh ma khân may nơm lĕ rngôch phung bu ur druh ê hŏ gĭt ôh bêch ndrel bu klâu.$b$,false),
('bunong-vn','NUM',31,19,null,$b$Ăn khân may gŭ bêch pa dih nhuang ntŭk rmlak tâm pơh nar. Mbu nơm tâm phung khân may nkhĭt jêh du huê bunuyh, jêh ri mbu nơm pah bi jêh du huê bunuyh nkhĭt, ƀư kloh khân may nơm jêh ri bu nă khân may ta nar năng pe jêh ri nar năng pơh.$b$,false),
('bunong-vn','NUM',31,20,null,$b$Ăn khân may ƀư kloh lĕ rngôch bok ao, lĕ rngôch ndơ ƀư ma ntâu, lĕ rngôch ndơ ƀư ma rsau be, jêh ri lĕ rngôch ndơ ƀư ma tơm si.”$b$,false),
('bunong-vn','NUM',31,21,null,$b$Kôranh ƀư brah Y-Êlêasar lah ma phung bu klâu hăn jêh ma nau tâm lơh, “Aƀaơ nau ntĭnh tâm nau vay Yêhôva ăn jêh ma Y-Môis,$b$,false),
('bunong-vn','NUM',31,22,null,$b$knŏng mah, prăk, kông, loih, thau jêh ri ndrak,$b$,false),
('bunong-vn','NUM',31,23,null,$b$lĕ rngôch ndơ dơi gŭ tâm ŭnh khân may mra ăn nklang ŭnh, jêh ri khân păng mra srŏng jêng kloh. Ƀiă lah ăn khân may dŏng dak tôl mblai ăn kloh; jêh ri lĕ rngôch ndơ mâu dơi gŭ ôh tâm ŭnh, ăn khân may trăm păng tâm dak.$b$,false),
('bunong-vn','NUM',31,24,null,$b$Ăn khân may pih bok ao khân may ta nar năng pơh jêh ri khân may mra jêng kloh; jêh nau nây mơ khân may dơi lăp tâm ntŭk rmlak.”$b$,false),
('bunong-vn','NUM',31,25,26,$b$“Ăn may, kôranh ƀư brah Y-Êlêasar, jêh ri phung kôranh ma noi deh phung tâm rƀŭn kơp ndơ bu geh sŏk gro jêh bơh bunuyh jêh ri bơh mpô mpa rong;$b$,false),
('bunong-vn','NUM',31,27,null,$b$jêh ri tâm pă ndơ sŏk gro tâm bar kô̆ , ndrăng phung hăn jêh ma nau tâm lơh jêh ri ăn lĕ rngôch phung tâm rƀŭn.$b$,false),
('bunong-vn','NUM',31,28,null,$b$Ăn may riu bơh phung ta han hăn tâm lơh du rnoh jêng pi ma Yêhôva, nguay tâm prăm rhiăng, bunuyh, ndrôk, seh bri, jêh ri biăp.$b$,false),
('bunong-vn','NUM',31,29,null,$b$Sŏk tă bơh ndơ n'gul ma phung ta han nây, jêh ri ăn ma kôranh ƀư brah Y-Êlêasar jêng ndơ nhhơr ma Yêhôva.$b$,false),
('bunong-vn','NUM',31,30,null,$b$Tă bơh ndơ n'gul ma phung ƀon lan Israel ăn may sŏk tâm prăm jât, bunuyh, ndrôk, seh bri, biăp jêh ri lĕ rngôch mpô mpa, jêh ri ăn ndơ nây ma phung Lêvi phung geh kan ndrel ngih bok Yêhôva.”$b$,false),
('bunong-vn','NUM',31,31,null,$b$Y-Môis jêh ri kôranh ƀư brah Y-Êlêasar ƀư tĭng nâm nau Yêhôva ntĭnh jêh ma Y-Môis.$b$,false),
('bunong-vn','NUM',31,32,null,$b$Jêh ri drăp ndơ hôm tă bơh ndơ sŏk gro phung tâm lơh sŏk jêh, geh: Prăm rsen pơh rmưn rbăn mlâm biăp me,$b$,true),
('bunong-vn','NUM',31,33,null,$b$pơh rmưn bar rbăn mlâm ndrôk nkuăng,$b$,false),
('bunong-vn','NUM',31,34,null,$b$prao rmưn du rbăn mlâm seh bri nkuăng,$b$,false),
('bunong-vn','NUM',31,35,null,$b$jêh ri pe rmưn bar rbăn bunuyh bu ur lĕ rngôch, bu ur ê hŏ mâp ôh bêch ndrel bu klâu.$b$,false),
('bunong-vn','NUM',31,36,null,$b$Du kô̆ n'gul jêng ndơ ma phung hăn tâm lơh geh pe rsen pe rmưn pơh rbăn prăm rhiăng mlâm biăp me,$b$,true),
('bunong-vn','NUM',31,37,null,$b$jêh ri pi ma Yêhôva geh prao rhiăng pơh jât ma prăm mlâm;$b$,false),
('bunong-vn','NUM',31,38,null,$b$pe rmưn prao rbăn mlâm ndrôk, chê̆ pi ma Yêhôva geh pơh rmưn jât ma bar mlâm;$b$,false),
('bunong-vn','NUM',31,39,null,$b$pe rbăn prăm rhiăng mlâm seh bri nkuăng, jêh ri chê̆ pi ma Yêhôva prao jât ma nguay mlâm;$b$,false),
('bunong-vn','NUM',31,40,null,$b$du rmưn prao rbăn bunuyh, jêh ri chê̆ pi ma Yêhôva geh pe jât ma bar bunuyh.$b$,false),
('bunong-vn','NUM',31,41,null,$b$Y-Môis jao ma Y-Êlêasar, kôranh ƀư brah, jêng ndơ pi nhhơr ma Yêhôva, tĭng nâm Yêhôva hŏ ntĭnh jêh ma Y-Môis.$b$,false),
('bunong-vn','NUM',31,42,null,$b$Du kô̆ n'gul di ma phung ƀon lan Israel Y-Môis rnglah êng prăp ma phung hăn tâm lơh$b$,true),
('bunong-vn','NUM',31,43,null,$b$du kô̆ n'gul di ma phung tâm rƀŭn geh pe rsen pe rmưn pơh rbăn prăm rhiăng mlâm biăp me;$b$,false),
('bunong-vn','NUM',31,44,null,$b$pe rmưn prao rbăn mlâm ndrôk nkuăng,$b$,false),
('bunong-vn','NUM',31,45,null,$b$pe rmưn prăm rhiăng mlâm seh bri,$b$,false),
('bunong-vn','NUM',31,46,null,$b$jêh ri du rmưn prao rbăn bunuyh$b$,false),
('bunong-vn','NUM',31,47,null,$b$tă bơh kô̆ n'gul di ma phung ƀon lan Israel, Y-Môis sŏk nguay tă bơh ăp prăm jât, bunuyh jêh ri mpô mpa rong, jêh ri ăn ma phung Lêvi phung pah kan ndrel ngih bok Yêhôva; tĭng nâm Yêhôva ntĭnh jêh ma Y-Môis.$b$,false),
('bunong-vn','NUM',31,48,null,$b$Phung kôranh ma âk rbăn nuyh ta han, phung kôranh ma rbăn nuyh, jêh ri phung kôranh ma rhiăng nuyh hăn dăch Y-Môis,$b$,false),
('bunong-vn','NUM',31,49,null,$b$jêh ri lah ma Y-Môis, “Phung oh mon may kơp jêh phung bu klâu tâm lơh tâm dâng nau hên mât, jêh ri mâu geh ôh du huê roh măt tă bơh hên.$b$,false),
('bunong-vn','NUM',31,50,null,$b$Jêh ri hên djôt leo jêh ndơ nhhơr ma Yêhôva moh ndơ ăp nơm bu klâu saơ, ndơ ma mah, kông ta ti, rgên chrăk, mblo tôr, jêh ri nhong, gay ŭch ƀư ăn kloh nau tih hên ta năp Yêhôva.”$b$,false),
('bunong-vn','NUM',31,51,null,$b$Y-Môis jêh ri kôranh ƀư brah Y-Êlêasar sŏk dơn tă bơh khân păng mah nây, jêh ri lĕ rngôch drăp bu tŏ njêng jêh.$b$,true),
('bunong-vn','NUM',31,52,null,$b$Lĕ rngôch mah ndơ nhhơr bu nhhơr jêh ma Yêhôva, tă bơh phung kôranh ma rbăn bunuyh, jêh ri phung kôranh ma rhiăng bunuyh, geh du rmưn prao rbăn pơh rhiăng prăm jât Sêkel.$b$,false),
('bunong-vn','NUM',31,53,null,$b$(Phung bu klâu tâm lơh sŏk jêh ndơ sŏk gro, ăp nơm ma păng nơm).$b$,true),
('bunong-vn','NUM',31,54,null,$b$Y-Môis jêh ri kôranh ƀư brah Y-Êlêasar sŏk dơn mah tă bơh phung kôranh ma rbăn bunuyh jêh ri kôranh ma rhiăng bunuyh, jêh ri djôt leo ndơ nay ma ngih bok tâm rƀŭn, jêng ndơ kah gĭt ma phung ƀon lan Israel ta năp Yêhôva.$b$,false),
('bunong-vn','NUM',32,1,null,$b$Phung kon bu klâu Ruben jêh ri phung kon bu klâu Gat geh âk ndrôk biăp; khân păng saơ n'gor Jaser jêh ri n'gor Galaat jêng ntŭk ueh ma ndrôk biăp.$b$,true),
('bunong-vn','NUM',32,2,null,$b$Pô ri phung kon bu klâu Gat jêh ri phung kon bu klâu Ruben văch lah ma Y-Môis, ma kôranh ƀư brah Y-Êlêasar, jêh ri ma phung kôranh phung tâm rƀŭn.$b$,true),
('bunong-vn','NUM',32,3,null,$b$“Ƀon Atarôt, Ƀon Dibôn, ƀon Jaser, ƀon Nimra, ƀon Hêsbôn, ƀon Êlêaleh, ƀon Jaser, ƀon Nimra, ƀon Hêsbôn, ƀon Êlêaleh, ƀon Sêgam, ƀon Nêbô, jêh ri ƀon Bêôn,$b$,false),
('bunong-vn','NUM',32,4,null,$b$n'gor nây Yêhôva lơh dơi jêh ta năp phung Israel tâm rƀŭn, jêng du n'gor bri ma ndrôk biăp; jêh ri phung oh mon may geh âk ndrôk biăp.”$b$,false),
('bunong-vn','NUM',32,5,null,$b$Khân păng lah, “Tơ lah hên geh nau yô̆ ta năp măt may, ăn n'gor aơ jêng ndơ ma phung oh mon may; lơi ăn hên rgăn ôh dak krong Yurdan.”$b$,false),
('bunong-vn','NUM',32,6,null,$b$Ƀiă lah Y-Môis lah ma phung kon bu klâu Gat jêh ri phung kon bu klâu Ruben, “Phung oh nâu khân may mâu hĕ mra hăn tâm lơh, bi khân may mâm dĭng gŭ ta aơ?$b$,true),
('bunong-vn','NUM',32,7,null,$b$Mâm khân may ăn rdja nuih phung ƀon lan Israel ma nau hăn rgăn ma n'gor bri Yêhôva ăn jêh ma khân păng?$b$,true),
('bunong-vn','NUM',32,8,null,$b$Pô nây phung mbơ̆ khân may lĕ ƀư đŏng tâm ban pô nây tơ lah gâp prơh khân păng hăn ntơm bơh Kadês-Barnê gay uănh n'hut n'gor bri.$b$,false),
('bunong-vn','NUM',32,9,null,$b$Yor lah khân păng hăn hao tât ta rlŭng Êskôl jêh ri saơ n'gor bri, khân păng ƀư rdja nuih phung ƀon lan Israel ma nau lăp tâm n'gor bri Yêhôva ăn jêh ma khân păng.$b$,false),
('bunong-vn','NUM',32,10,null,$b$Jêh ri Yêhôva hao ji nuih nar nây, jêh ri Păng sơm ton lah,$b$,true),
('bunong-vn','NUM',32,11,null,$b$“N'hêl nanê̆ mâu geh ôh du huê tâm phung bunuyh du luh jêh tă bơh n'gor bri Êjipt, ntơm bơh phung geh bar jât năm leo klơ, mra saơ n'gor gâp sơm ton jêh gay ăn ma Y-Abraham, ma Y-Isăk, jêh ri ma Y-Yakôb, yor lah khân păng mâu tĭng ndô̆ ôh gâp ma lĕ nuih n'hâm;$b$,false),
('bunong-vn','NUM',32,12,null,$b$mâu geh nơm êng ôh knŏng Y-Kalep kon bu klâu Y-Jêphunê bunuyh Kênisit, jêh ri Y-Yôsuê kon bu klâu Y-Nun, yor lah khân păng tĭng ndô̆ jêh Yêhôva ma lĕ nuih n'hâm!$b$,false),
('bunong-vn','NUM',32,13,null,$b$Jêh ri Yêhôva hao ji nuih ma phung Israel, jêh ri Păng ăn ma khân păng nsong mblêng tâm bri rdah tâm puăn jât năm kŏ tât lĕ rô̆ phung ƀư nau mhĭk ta năp măt Yêhôva lĕ rai lôch jêh.$b$,false),
('bunong-vn','NUM',32,14,null,$b$Jêh ri aơ, khân may thoi tay mbơ̆ khân may, jêng du phung bunuyh tih, gay n'hao tay nau duh Yêhôna ji nuih ma phung Israel!$b$,false),
('bunong-vn','NUM',32,15,null,$b$Yor lah tơ lah khân may cha lơi mâu hôm ŭch tĭng ndô̆ ôh păng, pô ri păng mra cha lơi tay khân păng tâm bri rdah, jêh ri khân may mra ƀư rai lĕ rngôch phung ƀon lan aơ.”$b$,true),
('bunong-vn','NUM',32,16,null,$b$Pô ri khân păng hăn dăch ma Y-Môis jêh ri lah: “Hên mra ƀư n'gar ta aơ ma ndrôk biăp hên, jêh ri ƀon toyh ma phung kon jê̆ hên,$b$,false),
('bunong-vn','NUM',32,17,null,$b$ƀiă lah hên mra djôt ndơ tâm lơh, gay ŭch hăn pa năp phung ƀon lan Israel kŏ tât hên njŭn jêh khân păng ma ntŭk ăn khân păng. Jêh ri phung kon jê̆ hên mra gŭ tâm ƀon toyh geh mpêr nâp yor phung gŭ tơm tâm n'gor bri.$b$,false),
('bunong-vn','NUM',32,18,null,$b$Hên mâu mra sĭt ôh ma ngih vâl hên tât phung Israel sŏk dơn jêh ăp nơm drăp ndơn păng.$b$,false),
('bunong-vn','NUM',32,19,null,$b$Yor lah hên mâu mra ndơn drăp ôh ndrel ma khân păng mpeh kăl tê̆ dak krong Yurdan. Mpeh pa lơ.”$b$,false),
('bunong-vn','NUM',32,20,null,$b$Pô ri Y-Môis lah ma khân păng, “Tơ lah khân may ƀư pô nây, tơ lah khân may djôt ndơ tâm lơh gay hăn ma nau tâm lơh ta năp Yêhôva,$b$,false),
('bunong-vn','NUM',32,21,null,$b$Jêh ri ăp nơm bu klâu djôt ndơ tâm lơh tâm phung khân may mra rgăn dak krong Yurdan ta năp Yêhôva tât păng mprơh jêh phung rlăng bơh ta năp păng,$b$,false),
('bunong-vn','NUM',32,22,null,$b$jêh ri n'gor nây lăp khân may ta năp Yêhôva; jêh nau nây khân may dơi plơ̆ sĭt đŏng jêh ri jêng kon me ta năp Yêhôva jêh ri phung Israel; jêh ri n'gor aơ mra jêng ndơ khân may ta năp Yêhôva.$b$,false),
('bunong-vn','NUM',32,23,null,$b$Ƀiă lah tơ lah khân may mâu mra ƀư pô nây ôh, ta aơ khân may ƀư tih đah Yêhôva; jêh ri ăn khân may gĭt ngăn nau tih khân may mra tâm mpơl.$b$,false),
('bunong-vn','NUM',32,24,null,$b$Ƀư hom âk rplay ƀon toyh ma phung kon jê̆ khân may, jêh ri âk nŭng n'gar ma biăp khân may, jêh ri ƀư hom moh nau khân may ton jêh.”$b$,false),
('bunong-vn','NUM',32,25,null,$b$Phung kon bu klâu Gat jêh ri phung kon bu klâu Ruben lah ma Y-Môis, “Phung oh mon may mra ƀư tĭng nâm nau may ntĭnh.$b$,true),
('bunong-vn','NUM',32,26,null,$b$Phung kon jê̆ hên, ur hên, biăp hên, jêh ri lĕ rngôch ndrôk hên mra hôm e ta aơ tâm ƀon toyh n'gor Galaat,$b$,false),
('bunong-vn','NUM',32,27,null,$b$ƀiă lah phung oh mon may mra rgăn kăl tê̆, ăp nơm bu klâu djôt ndơ tâm lơh, kâp tâm lơh ta năp Yêhôva, tĭng nâm kôranh hên ntĭnh.”$b$,false),
('bunong-vn','NUM',32,28,null,$b$Pô ri Y-Môis ăn nau ntĭnh di ma khân păng ma kôranh ƀư brah Y-Êlêasar, ma Y-Yôsuê kon bu klâu Y-Nun, jêh ri ma phung kôranh ndŭl mpôl phung ƀon lan Israel.$b$,false),
('bunong-vn','NUM',32,29,null,$b$Y-Môis lah ma khân păng, “Tơ lah phung kon bu klâu Gat jêh ri phung kon bu klâu Ruben, ăp nơm djôt ndơ tâm lơh kâp tâm lơh ta năp Yêhôva mra rgăn ndrel ma khân may dak krong Yurdan jêh ri n'gor nây mra lăp khân may, pô ri khân may mra ăn ma khân păng n'gor Galaat jêng drăp ndơn ma khân păng chăm.$b$,false),
('bunong-vn','NUM',32,30,null,$b$Ƀiă lah tơ lah khân may djôt ndơ tâm lơh, khân păng mra geh drăp ndơn ndrel ma khân may ta n'gor Kanaan.”$b$,false),
('bunong-vn','NUM',32,31,null,$b$Phung kon bu klâu Gat jêh ri phung kon bu klâu Ruben plơ̆ lah, “Tĭng nâm nau Yêhôva lah jêh ma phung oh mon may, pô nây hên mra ƀư.$b$,false),
('bunong-vn','NUM',32,32,null,$b$Hên mra rgăn djôt ndơ lơh ta năp Yêhôva lăp tâm n'gor Kanaan, jêh ri ndơ hên geh jêng drăp ndơn hên mra hôm e ndrel ma hên kơh aơ dak krong Yurdan.”$b$,false),
('bunong-vn','NUM',32,33,null,$b$Y-Môis ăn ma khân păng, ma phung kon bu klâu Gat jêh ri ma phung kon bu klâu Ruben, jêh ri ma du n'gul mpôl Manasê, kon bu klâu Y-Yôsep, ƀon bri hađăch Y-Sihôn hađăch phung Amôrit, jêh ri ƀon bri hađăch Y-Ôk hađăch n'gor Basan, n'gor jêh ri lĕ rngôch ƀon toyh păng ndrel ma mir khân păng, ƀon toyh văr jŭm n'gor.$b$,false),
('bunong-vn','NUM',32,34,null,$b$Phung kon bu klâu Gat ndâk ƀon Dibôn, ƀon Astarôt, ƀon Arôer.$b$,false),
('bunong-vn','NUM',32,35,null,$b$Ƀon Astarôt-Sôpan, ƀon Jaser, ƀon Jôgbêha,$b$,true),
('bunong-vn','NUM',32,36,null,$b$ƀon Bênimra, jêh ri ƀon Bêt- Haran, ƀon toyh geh mpêr nâp jêh ri n'gar biăp.$b$,false),
('bunong-vn','NUM',32,37,null,$b$Phung kon bu klâu Ruben ndâk ƀon Hêsbôn, ƀon Êlêaleh, ƀon Kiriatam,$b$,false),
('bunong-vn','NUM',32,38,null,$b$ƀon Nêbô, jêh ri ƀon Baal-Mêôn (amoh lĕ rngôch ƀon aơ khân păng tâm rgâl) jêh ri ƀon Sip ma; jêh ri khân păng ăn amoh êng ma lĕ rngôch ƀon toyh khân păng ndâk jêh$b$,false),
('bunong-vn','NUM',32,39,null,$b$Phung kon bu klâu Makir kon bu klâu Manasê hăn ma n'gor Galaat jêh ri sŏk păng, jêh ri mprơh phung Amôrit gŭ jêh ta nây.$b$,false),
('bunong-vn','NUM',32,40,null,$b$Y-Môis ăn n'gor Galaat ma Y-Makir kon bu klâu Y-Manasê, jêh ri păng gŭ ta nây.$b$,true),
('bunong-vn','NUM',32,41,null,$b$Y-Jar kon bu klâu Y-Manasê hăn sŏk ƀon jê̆ khân păng, jêh ri ntơ amoh khân păng ƀon Havôt-Jar.$b$,true),
('bunong-vn','NUM',32,42,null,$b$Y-Nôba hăn sŏk ƀon Kênat jêh ri ƀon jê̆ păng, jêh ri ntơ amoh păng ƀon Nôba tĭng nâm amoh păng nơm.$b$,false),
('bunong-vn','NUM',33,1,null,$b$Aơ jêng lĕ ntŭk njơh ma phung ƀon lan Israel hăn nsong, tơ lah khân păng du luh tă bơh n'gor bri Êjipt tĭng nâm phung ta han khân păng tâm dâng nau Y-Môis jêh ri Y-Arôn mât uănh.$b$,true),
('bunong-vn','NUM',33,2,null,$b$Y-Môis chih ntŭk khân păng ntơm nsong, du rơh, du rơh, tĭng nâm nau Yêhôva ntĭnh; jêh ri aơ jêng ntŭk khân păng ƀư rmlak tĭng nâm nau hăn nsong khân păng.$b$,false),
('bunong-vn','NUM',33,3,null,$b$Khân păng du luh bơh ƀon Ramse tâm khay nguay, nar jât ma prăm tâm khay nguay, jêng nar pa kơi jêh nau nhêt sa Găn phung ƀon lan Israel luh ma nau dơi ta năp măt lĕ rngôch phung Êjipt,$b$,false),
('bunong-vn','NUM',33,4,null,$b$dôl phung Êjipt gŭ tâp lĕ rngôch kon khân păng deh dak bôk phung Yêhôva nkhĭt jêh ta nklang khân păng; Yêhôva phat dôih tâm ban đŏng ma phung brah khân păng.$b$,false),
('bunong-vn','NUM',33,5,null,$b$Pô ri phung ƀon lan Israel dâk hăn tă bơh ƀon Ramse njơh ta Sukôt.$b$,false),
('bunong-vn','NUM',33,6,null,$b$Khân păng dâk hăn ntơm bơh Sukôt jêh ri njơh ta Êtam gŭ ta bôl bri rdah.$b$,false),
('bunong-vn','NUM',33,7,null,$b$Khân păng dâk hăn ntơm bơh Êtam jêh ri ndăch mpeh pa kơi tât ta Pihahirôt mpeh pa lơ Baal-Sêphon; jêh ri khân păng njơh pa năp Mikdôl.$b$,false),
('bunong-vn','NUM',33,8,null,$b$Khân păng dâk hăn tra năp Hahirôt jêh ri rgăn ta nklang dak mƀŭt lăp tâm bri rdah, jêh ri khân păng hăn pe nar trong tâm bri rdah Êtam, jêh ri njơh ta Mara.$b$,false),
('bunong-vn','NUM',33,9,null,$b$Khân păng dâk hăn tă bơh Mara jêh ri tât ta Êlim; ta Êlim geh jât ma bar tu dak jêh ri pơh jât tơm play đung, khân păng gŭ njơh ta nây.$b$,true),
('bunong-vn','NUM',33,10,null,$b$Khân păng dâk hăn bơh Êlim jêh ri njơh dăch Dak Mƀŭt Chăng.$b$,false),
('bunong-vn','NUM',33,11,null,$b$Khân păng dâk hăn bơh Dak Mƀŭt Chăng jêh ri njơh tâm bri rdah Sin.$b$,false),
('bunong-vn','NUM',33,12,null,$b$Khân păng dâk hăn bơh bri rdah Sin jêh ri njơh ta Dôphka.$b$,false),
('bunong-vn','NUM',33,13,null,$b$Khân păng dâk hăn bơh Dôphka jêh ri njơh ta Alus.$b$,true),
('bunong-vn','NUM',33,14,null,$b$Khân păng dâk hăn bơh Alus jêh ri njơh ta Rêphidim, ta nây mâu geh ôh dak nhêt ma phung ƀon lan.$b$,false),
('bunong-vn','NUM',33,15,null,$b$Khân păng dâk hăn bơh Rêphidim jêh ri njơh tâm bri rdah Sinai.$b$,true),
('bunong-vn','NUM',33,16,null,$b$Khân păng dâk hăn bơh bri rdah Sinai jêh ri njơh ta Kibrôt-Hatava.$b$,false),
('bunong-vn','NUM',33,17,null,$b$Khân păng dâk hăn bơh Kibrôt-Hatava jêh ri njơh ta Hasêrôt.$b$,false),
('bunong-vn','NUM',33,18,null,$b$Khân păng dâk hăn bơh Hasêrôt jêh ri njơh ta Ritma.$b$,true),
('bunong-vn','NUM',33,19,null,$b$Khân păng dâk hăn bơh Ritma jêh ri njơh ta Rimôn. Pêres.$b$,false),
('bunong-vn','NUM',33,20,null,$b$Khân păng dâk hăn bơh Rimôn-Pêres jêh ri njơh ta Lipna.$b$,true),
('bunong-vn','NUM',33,21,null,$b$Khân păng dâk hăn bơh Lipna jêh ri njơh ta Risa.$b$,false),
('bunong-vn','NUM',33,22,null,$b$Khân păng dâk hăn bơh Risa jêh ri njơh ta Kêlêhata jêh ri njơh ta yôk Sêpher.$b$,false),
('bunong-vn','NUM',33,23,null,$b$Khân păng dâk hăn bơh Kê-lê-ha-ta jêh ri njơh ta yôk Si-pher$b$,false),
('bunong-vn','NUM',33,24,null,$b$Khân păng dâk hăn bơh yôk Sêpher jêh ri njơh ta Harada.$b$,false),
('bunong-vn','NUM',33,25,null,$b$Khân păng dâk hăn bơh Harada jêh ri njơh ta Makhêlôt.$b$,false),
('bunong-vn','NUM',33,26,null,$b$Khân păng dâk bơh Makhêlôt jêh ri njơh ta Tahat.$b$,true),
('bunong-vn','NUM',33,27,null,$b$Khân păng dâk hăn bơh Tahat jêh ri njơh ta Têra.$b$,false),
('bunong-vn','NUM',33,28,null,$b$Khân păng dâk hăn bơh Têra jêh ri njơh ta Mitka.$b$,false),
('bunong-vn','NUM',33,29,null,$b$Khân păng dâk hăn bơh Mitka jêh ri njơh ta Hasmôna.$b$,false),
('bunong-vn','NUM',33,30,null,$b$Khân păng dâk hăn bơh Hasmôra jêh ri njơh ta Môsêrôt.$b$,true),
('bunong-vn','NUM',33,31,null,$b$Khân păng dâk hăn bơh Mêsêrôt jêh ri njơh ta Bênêjakan.$b$,false),
('bunong-vn','NUM',33,32,null,$b$Khân păng dâk hăn bơh Bênêjakan jêh ri khân păng njơh ta Hôrhagitgat.$b$,false),
('bunong-vn','NUM',33,33,null,$b$Khân păng dâk hăn bơh Hôrhagitgat jêh ri njơh ta Jôtbata.$b$,false),
('bunong-vn','NUM',33,34,null,$b$Khân păng dâk hăn bơh Jôtbata jêh ri njơh ta Abrôna.$b$,true),
('bunong-vn','NUM',33,35,null,$b$Khân păng dâk hăn bơh Abrôna jêh ri khân păng njơh ta Gêber.$b$,false),
('bunong-vn','NUM',33,36,null,$b$Khân păng dâk hăn bơh Gêber jêh ri njơh tâm bri rdah Sin (jêng Kadês).$b$,true),
('bunong-vn','NUM',33,37,null,$b$Khân păng dâk hăn bơh Kadês jêh ri njơh ta yôk Hor ta bôl n'har bri n'gor Êđôm.$b$,false),
('bunong-vn','NUM',33,38,null,$b$Y-Arôn kôranh ƀư brah hao ta klơ yôk Hor tĭng nâm nau Yêhôva ntĭnh jêh ri păng khĭt ta nây tâm năm rơh puăn jât jêh phung Israel du luh bơh n'gor Êjipt, ta nar tal nguay khay prăm.$b$,true),
('bunong-vn','NUM',33,39,null,$b$Y-Arôn geh du rhiăng bar jât ma pe năm tơ lah păng khĭt ta klơ yôk Hor.$b$,false),
('bunong-vn','NUM',33,40,null,$b$Hađăch ƀon Arat, bunuyh n'gor Kanaan, nơm gŭ tâm n'gor Rđŭng tâm n'gor bri Kanaan tăng lư nau phung ƀon lan Israel văch tât.$b$,false),
('bunong-vn','NUM',33,41,null,$b$Khân păng dâk hăn bơh Yôk Hor jêh ri njơh ta Samôna.$b$,true),
('bunong-vn','NUM',33,42,null,$b$Khân păng dâk hăn bơh Salmôna jêh ri njơh ta Punon.$b$,false),
('bunong-vn','NUM',33,43,null,$b$Khân păng dâk hăn bơh Punon jêh ri njơh ta Ôbôt.$b$,false),
('bunong-vn','NUM',33,44,null,$b$Khân păng dâk hăn bơh Ôbôt jêh ri njơh ta I-yê-Abarim ta neh n'gor Môap.$b$,false),
('bunong-vn','NUM',33,45,null,$b$Khân păng dâk hăn bơh I-yê-Abarim jêh ri njơh ta Dibôn-Gat.$b$,true),
('bunong-vn','NUM',33,46,null,$b$Khân păng dâk hăn bơh Dibôn-Gat jêh ri njơh ta Almôn-Diblatam.$b$,false),
('bunong-vn','NUM',33,47,null,$b$Khân păng dâk hăn bơh Almôn-Diblatam jêh ri njơh ta yôk Abarim pa năp Nêbô.$b$,false),
('bunong-vn','NUM',33,48,null,$b$Khân păng dâk hăn bơh yôk Abarim jêh ri njơh tâm neh lâng n'gor Môap dăch dak krong Yurdan tâm tra đah ƀon Yêrikô.$b$,false),
('bunong-vn','NUM',33,49,null,$b$Khân păng njơh dăch dak krong Yurdan ntơm bơh Bet-Jêsamôt tât ta Abel-Sitim tâm neh lâng n'gor Môap.$b$,false),
('bunong-vn','NUM',33,50,null,$b$Yêhôva lah ma Y-Môis tâm neh lâng n'gor Môap dăch dak krong Yurdan tâm tra đah ƀon Yêrikô,$b$,true),
('bunong-vn','NUM',33,51,null,$b$“Lah hom ma phung ƀon lan Israel, Tơ lah khân may rgăn dak krong Yurdan lăp tâm n'gor Kanaan,$b$,false),
('bunong-vn','NUM',33,52,null,$b$nôk nây ăn khân may mprơh lĕ rngôch bunuyh gŭ tâm n'gor ntơm bơh pa năp khân may, Jêh ri ƀư rai lĕ rngôch lŭ khân păng tor jêh rup, jêh ri ƀư rai lĕ rngôch rup khân păng tŏ, jêh ri ƀư rai lĕ rngôch ntŭk prêh klơ khân păng.$b$,false),
('bunong-vn','NUM',33,53,null,$b$Ăn khân may sŏk jêng ndơ khân may nơm n'gor bri nây jêh ri gŭ tâm păng ro, yor lah gâp ăn jêh n'gor bri nây ma khân may ăn jêng ndơ ma khân may nơm.$b$,false),
('bunong-vn','NUM',33,54,null,$b$Ăn khân may ndơn n'gor bri nây ma nau tâm nchroh tĭng nâm mpôl khân may, Ma ăp mpôl âk lơn ăn khân may ăn drăp ndơn toyh, jêh ri ma mpôl djê̆ ăn khân may ăn drăp ndơn jê̆ lơn; ta ntŭk nau tâm nchroh di ma du huê bunuyh, ta nây mra jêng ndơ păng. Khân may mra ndơn tĭng nâm mpôl phung noi deh khân may.$b$,false),
('bunong-vn','NUM',33,55,null,$b$Ƀiă lah tơ lah khân may mâu mprơh ôh phung gŭ tâm n'gor ntơm bơh pa năp khân may, pô nây đơ phung khân păng khân may hôm e om mra jêng nâm bu ndơ tôt măt khân may, jêh ri lok krĕ ta pŭng vĕ khân may, jêh ri khân păng mra ƀư rkhŭk khân păng tâm n'gor bri khân may mra gŭ.$b$,true),
('bunong-vn','NUM',33,56,null,$b$Jêh ri gâp mra ƀư ma khân may nâm bu gâp mĭn jêh ŭch ƀư ma khân păng.$b$,true),
('bunong-vn','NUM',34,1,null,$b$Yêhôva lah ma Y-Môis,$b$,true),
('bunong-vn','NUM',34,2,null,$b$“Ntĭnh hom ma phung ƀon lan Israel jêh ri lah ma khân păng. Tơ lah khân may lăp jêh tâm n'gor Kanaan (n'gor aơ mra tŭp ma khân may jêng drăp ndơn, Lĕ n'gor Kanaan)$b$,false),
('bunong-vn','NUM',34,3,null,$b$mpeh rđŭng mra ntơm bơh bri rdah Sin n'gŏ n'har bri n'gor Êđôm, jêh ri n'har rđŭng khân may mra ntơm bơh bôl Dak Mƀŭt Chăng pa lơ.$b$,false),
('bunong-vn','NUM',34,4,null,$b$N'har mra ndăch mpeh rđŭng Kadês-Barnê; ntơm bơh nây păng n'ho tât ta Hasar-Adar n'ho tât ta Asmôn,$b$,false),
('bunong-vn','NUM',34,5,null,$b$n'har bri mra ndăch ntơm bơh Asmôn tât ta N'hor Dak Êjipt jêh ri lôch ta dak mƀŭt.$b$,false),
('bunong-vn','NUM',34,6,null,$b$“Ta n'har bri pa dâng mra geh Dak Mƀŭt Toyh jêh ri kơh păng; nây mra jêng n'har bri khân may pa dâng.$b$,false),
('bunong-vn','NUM',34,7,null,$b$“Aơ mra jêng n'har bri khân may mpeh ma Dor: Ntơm bơh Dak Mƀŭt Toyh khân may mra tâm chor (tâm nal) n'har tât ta yôk Hor;$b$,true),
('bunong-vn','NUM',34,8,null,$b$ntơm bơh yôk Hor khân may mra tâm chor n'har bri tât ta ntŭk lăp ƀon Hamat, jêh ri ta bôl n'har bri mra tât ta Sêdat.$b$,false),
('bunong-vn','NUM',34,9,null,$b$Jêh ri n'har n'ho hăn tât ta Siphrôn jêh nây n'har mra n'hot hăn tât ta Hasar-Ênan. Nây mra jêng n'har bri khân may mpeh dor.$b$,false),
('bunong-vn','NUM',34,10,null,$b$“Ăn khân may tâm nal n'har pa lơ ntơm bơh Hasar-Ênan tât ta Sêpham;$b$,false),
('bunong-vn','NUM',34,11,null,$b$n'har mra trŭnh bơh Sêpham tât ta Ribla mpeh pa lơ Ain; jêh ri n'har mra tât ta kơh dak mƀŭt Kinêret ta pa lơ;$b$,false),
('bunong-vn','NUM',34,12,null,$b$jêh ri n'har mra tât ta dak krong Yurdan, jêh ri bôl n'har bri mra tât ta Dak Mƀŭt Boh. Nây mra jêng n'gor bri khân may ndrel ma n'har păng văr jŭm nây.”$b$,false),
('bunong-vn','NUM',34,13,null,$b$Y-Môis ntĭnh ma phung ƀon lan Israel, lah, “Aơ n'gor bri khân may mra ndơn chăm ma nau tâm nchroh, bri Yêhôva ntĭnh jêh gay ăn ma sĭn ndŭl mpôl jêh ri n'gul ndŭl mpôl;$b$,true),
('bunong-vn','NUM',34,14,null,$b$Yor lah ndŭl mpôl phung kon bu klâu Ruben tĭng nâm noi deh khân păng jêh ri phung kon bu klâu Gat tĭng nâm noi deh khân păng sŏk dơm jêh drăp ndơn khân păng, jêh ri tâm ban đŏng n'gul mpôl Manasê.$b$,false),
('bunong-vn','NUM',34,15,null,$b$Phung bar ndŭl mpôl nây jêh ri n'gul ndŭl mpôl sŏk dơn jêh drăp ndơn kăl aơ dak krong Yurdan mpeh pa năp tâm tra đah ƀon Yêrikô, mpeh ma pa lơ, mpeh luh nar.”$b$,false),
('bunong-vn','NUM',34,16,null,$b$Yêhôva lah ma Y-Môis:$b$,true),
('bunong-vn','NUM',34,17,null,$b$“Aơ amoh phung bu klâu mra tâm pă n'gor bri ma khân may jêng drăp ndơn gŭ chăm: Y-Êlêasar kôranh ƀư brah jêh ri Y-Yôsuê kon bu klâu Y-Nun.$b$,false),
('bunong-vn','NUM',34,18,null,$b$Ăn may sŏk du huê kôranh ma ăp mpôl gay tâm pă n'gor bri jêng drăp ndơn.$b$,false),
('bunong-vn','NUM',34,19,null,$b$Aơ amoh phung bu klâu nây bơh ndŭl mpôl Yuđa, Y-Kalep kon bu klâu Y-Jêphunê;$b$,false),
('bunong-vn','NUM',34,20,null,$b$bơh ndŭl mpôl phung kon bu klâu Simêôn, Y-Sêmuel kon bu klâu Y-Amihut;$b$,false),
('bunong-vn','NUM',34,21,null,$b$bơh ndŭl mpôl Benjamin, Y-Êlidat kon bu klâu Y-Kis lon;$b$,false),
('bunong-vn','NUM',34,22,null,$b$bơh phung kon bu klâu Dan du huê kôranh, Y-Buki kon bu klâu Y-Jôgli;$b$,false),
('bunong-vn','NUM',34,23,null,$b$bơh phung kon bu klâu Yôsep, bơh ndŭl mpôl phung kon bu klâu Manasê du huê kôranh, Y-Haniel kon bu klâu Y-Êphôt;$b$,false),
('bunong-vn','NUM',34,24,null,$b$bơh ndŭl mpôl phung kon bu klâu Êphraim du huê kôranh Y-Kemuel kon bu klâu Y-Siptan;$b$,false),
('bunong-vn','NUM',34,25,null,$b$bơh ndŭl mpôl phung kon bu klâu Sabulôn du huê kôranh Y-Êlisaphan kon bu klâu Y-Parnak;$b$,false),
('bunong-vn','NUM',34,26,null,$b$bơh ndŭl mpôl phung kon bu klâu Isakar du huê kôranh Y-Paltiel kon bu klâu Y-Asan;$b$,false),
('bunong-vn','NUM',34,27,null,$b$bơh ndŭl mpôl phung kon bu klâu Aser du huê kôranh Y-hihut kon bu klâu Y-Sêlômi;$b$,false),
('bunong-vn','NUM',34,28,null,$b$bơh ndŭl mpôl phung kon bu klâu Naptali du huê kôranh Y-Pêdahel kon bu klâu Y-Amihut.$b$,false),
('bunong-vn','NUM',34,29,null,$b$Ma phung aơ Yêhôva ntĭnh ăn tâm pă drăp ndơn ma phung ƀon lan Israel tâm n'gor Kanaan.”$b$,false),
('bunong-vn','NUM',35,1,null,$b$Yêhôva lah ma Y-Môis tâm neh lâng n'gor Môap dăch dak krong Y-Yurdan mpeh pa năp tâm tra đah ƀon Yêrikô,$b$,true),
('bunong-vn','NUM',35,2,null,$b$“Ntĭnh hom ma phung ƀon lan Israel gay ma khân păng ăn ma phung Lêvi bơh drăp ndơn khân păng geh ƀa ƀă ƀon toyh ăn khân păng dơi gŭ; jêh ri khân may mra ăn ma phung Lêvi ntŭk ndrêch gơ̆ jŭm ƀon toyh.$b$,false),
('bunong-vn','NUM',35,3,null,$b$Khân păng mra geh ƀon toyh nây dơi gŭ, jêh ri ntŭk ndrêch gơ̆ mra prăp ăn ndrôk, ma mpô mpa rong, jêh ri ma lĕ rngôch mpô mpa khân păng.$b$,true),
('bunong-vn','NUM',35,4,null,$b$Ntŭk gơ̆ ndrêch jŭm văr ƀon toyh khân păng mra ăn ma phung Lêvi ntơm bơh mpêr ƀon toyh mpeh pa dih du rbăn hăt văr jŭm.$b$,false),
('bunong-vn','NUM',35,5,null,$b$Khân may mra veh ta pa dih ƀon toyh bar rbăn hăt mpeh pa lơ, bar rbăn hăt mpeh rđŭng, bar rbăn hăt mpeh pa dâng, jêh ri bar rbăn hăt mpeh dor; ƀon ton mra jêng ta nklang. Ntŭk aơ mra prăp ma khân păng jêng ndrêch gơ̆ ma ƀon toyh khân păng.$b$,false),
('bunong-vn','NUM',35,6,null,$b$Lĕ rngôch ƀon toyh khân may ăn phung Lêvi mra jêng prao rplay ƀon prăp ma nau du krap, ntŭk nây khân may mra ăn ma nơm nkhĭt bunuyh dơi du krap, jêh ri rmeh ma nây khân may mra ăn tay puăn jât ma bar rplay ƀon toyh.$b$,false),
('bunong-vn','NUM',35,7,null,$b$Lĕ rngôch ƀon toyh khân may ăn ma phung Lêvi mra jêng puăn jât ma pham rplay ƀon, ndrel ma ndrêch gơ̆ khân păng.$b$,true),
('bunong-vn','NUM',35,8,null,$b$Bi ma ƀon toyh khân may mra ăn tă bơh ndơ phung ƀon lan Israel, tă bơh ndŭl mpôl geh âk khân may mra sŏk âk lơn, jêh ri tă bơh ndŭl mpôl geh djê̆, khân may mra sŏk djê̆ lơn; ăp ndŭl mpôl mra ăn ƀon toyh khân păng ma phung Lêvi veh tĭng nâm drăp ndơn khân păng geh jêh.”$b$,true),
('bunong-vn','NUM',35,9,null,$b$Yêhôva lah ma Y-Môis,$b$,true),
('bunong-vn','NUM',35,10,null,$b$“Lah hom ma phung ƀon lan Israel, Tơ lah khân may rgăn dak krong Yurdan lăp tâm n'gor Kanaan,$b$,false),
('bunong-vn','NUM',35,11,null,$b$nôk nây ăn khân may săch ƀon toyh mra jêng ma khân may ntŭk du krap ma khân may nơm, gay ma nơm nkhĭt bunuyh ma nau mâu mra ŭch ôh dơi du krap ta nây.$b$,false),
('bunong-vn','NUM',35,12,null,$b$Ƀon toyh nây mra jêng ma khân may ntŭk du krap bơh nơm har plơng, gay ma nơm nkhĭt bunuyh mâu mra khĭt ôh tât păng dâk ta năp nau phung tâm rƀŭn phat dôih.$b$,true),
('bunong-vn','NUM',35,13,null,$b$Ƀon toyh khân may ăn mra jêng prao rplay ƀon toyh prăp ma nau du krap.$b$,false),
('bunong-vn','NUM',35,14,null,$b$Khân may mra ăn pe rplay ƀon toyh kăl tê̆ dak krong Yurdan, jêh ri rplay ƀon toyh tâm n'gor Kanaan, prăp jêng ƀon ma nau du krap.$b$,true),
('bunong-vn','NUM',35,15,null,$b$Prao rplay ƀon toyh aơ mra prăp ma nau du krap ma phung ƀon lan Israel, ma nơm bu năch, jêh ri ma nơm gŭ njơh ƀât lât ta nklang khân păng, gay ma mbu nơm nkhĭt bunuyh mâu geh mra ŭch ôh dơi du krap ta nây.$b$,true),
('bunong-vn','NUM',35,16,null,$b$“Ƀiă lah tơ lah păng dong ô băl ma ndơ loih, pô nây ô băl khĭt ro, păng jêng nơm nkhĭt bunuyh; nơm nkhĭt bunuyh nây ăn bu nkhĭt lơi.$b$,true),
('bunong-vn','NUM',35,17,null,$b$Jêh ri tơ lah păng ndâm ô băl ma lŭ, ma ndơ nây bu dơi khĭt, jêh ri ô băl khĭt ro, păng jêng nơm nkhĭt bunuyh; nơm nkhĭt bunuyh nây ăn bu nkhĭt lơi.$b$,false),
('bunong-vn','NUM',35,18,null,$b$Mâu lah tơ lah păng dong ô băl ma ndơ tơm si, ma ndơ nây bu dơi khĭt, jêh ri ô băl khĭt ro, păng jêng nơm nkhĭt bunuyh; nơm khĭt bunuyh nây ăn bu nkhĭt ro.$b$,true),
('bunong-vn','NUM',35,19,null,$b$Nơm har plơng ma mham mra nkhĭt nơm nkhĭt bunuyh nây; tơ lah păng mâp đah ô băl, păng mra nkhĭt lơi ô băl.$b$,false),
('bunong-vn','NUM',35,20,null,$b$Tơ lah geh du huê bunuyh yor nuih n'hâm tâm rkeh tĭng ntâp du huê bunuyh êng, mâu lah klŭp ma du mlâm ndơ geh ta păng, jêh ri yor ndơ nây păng khĭt ro;$b$,true),
('bunong-vn','NUM',35,21,null,$b$mâu lah yor ma nau tâm rmot păng đŏl thŭk đah ti, pô nây păng khĭt ro, pô ri nơm thŭk nây ăn bu nkhĭt lơi; păng jêng nơm nkhĭt bunuyh; nơm har plơng ma mham mra nkhĭt lơi nơm nkhĭt bunuyh tơ lah mâp đah păng.$b$,false),
('bunong-vn','NUM',35,22,null,$b$“Ƀiă lah tơ lah mâu geh ma nau tâm rkel ôh. Ô băl geh klŭp du mlâm ndơ ta păng mâu geh kâp ta trong ôh,$b$,true),
('bunong-vn','NUM',35,23,null,$b$mâu lah dŏng du mlâm lŭ, ma ndơ nây bu khĭt, klŭp geh ta păng jêh ri mâu yŏng năm saơ păng ôh, pô ri păng khĭt ro, nđâp tơ lah păng mâu jêng rlăng ô băl ôh, jêh ri ô băl mâu joi ƀư ôh nau mhĭk ma păng;$b$,false),
('bunong-vn','NUM',35,24,null,$b$pô ri phung tâm rƀŭn mra phat dôih ndrăng nơm nkhĭt bunuyh jêh ri nơm har plơng ma mham tĭng nâm nau ntĭnh aơ.$b$,false),
('bunong-vn','NUM',35,25,null,$b$Jêh ri phung tâm rƀŭn mra koh dŏng nơm nkhĭt bunuyh bơh ti nơm har plơng ma mham, jêh ri phung tâm rƀŭn mra ăn păng sĭt ma ƀon păng du krap, ntŭk păng du krap jêh, jêh ri păng njrăng gŭ ta nây kŏ tât kôranh ƀư brah toyh nơm bu tŏ jêh dak ƀâu kah khĭt.$b$,false),
('bunong-vn','NUM',35,26,null,$b$Ƀiă lah tơ lah nơm nkhĭt bunuyh hăn luh pa dih n'har ƀon du krap ntŭk păng gŭ krap jêh,$b$,false),
('bunong-vn','NUM',35,27,null,$b$jêh ri nơm har plơng ma mham saơ pa dih n'har ƀon păng gŭ krap, jêh ri nơm har plơng ma mham nkhĭt lơi nơm nkhĭt bunuyh, păng mâu mra jêng tih ma mham ôh.$b$,false),
('bunong-vn','NUM',35,28,null,$b$Yor lah bunuyh nây mra hôm e tâm ƀon păng du krap kŏ tât kôranh ƀư brah toyh khĭt; nơm nkhĭt bunuyh dơi sĭt ma neh jêng ndơ păng.$b$,false),
('bunong-vn','NUM',35,29,null,$b$“Nau aơ mra jêng ma khân may nau vay jêh ri nau ntĭnh tâm lĕ rngôch rô̆ khân may, tâm lĕ rngôch ntŭk khân may gŭ.$b$,true),
('bunong-vn','NUM',35,30,null,$b$Tơ lah du huê nkhĭt bunuyh, nơm nkhĭt bunuyh nây bu mra nkhĭt lơi păng tơ lah geh phung mbơh n'hêl nanê̆; ƀiă lah bu mâu dơi nkhĭt ôh tơ lah geh knŏng du huê nơm mbơh.$b$,false),
('bunong-vn','NUM',35,31,null,$b$Khân may mâu dơi sŏk dơn ôh rnoh tâm chuai nau rêh ma du huê nkhĭt bu nuyh, nơm jêng tih jêh yor nkhĭt bu; ƀiă lah ăn bu nkhĭt lơi păng.$b$,false),
('bunong-vn','NUM',35,32,null,$b$Jêh ri khân may mâu mra sŏk dơn ôh rnoh tâm chuai ma nơm du ma ƀon du krap, gay ma păng dơi sĭt tay gŭ tâm neh n'gor lor ma kôranh ƀư brah toyh khĭt.$b$,false),
('bunong-vn','NUM',35,33,null,$b$Khân may lơi ƀư ƀơ̆ ôh n'gor khân may gŭ; yor lah mham ƀư ƀơ̆ neh n'gor, tơ lah mâu geh ôh nau ƀư kloh neh yor mham nkhŭt ta nây, knŏng đah mham nơm nkhŭt mham dơm dơi chuai n'gor.$b$,false),
('bunong-vn','NUM',35,34,null,$b$Pô nây, lơi ăn ƀơ̆ ôh neh khân may gŭ, tâm neh nây gâp nơm gŭ; yor lah gâp Yêhôva gŭ ta nklang phung ƀon lan Israel.”$b$,true),
('bunong-vn','NUM',36,1,null,$b$Pô ri, phung kôranh noi deh Galaat, jêng phung kon bu klâu Y-Makir, sau Y-Manasê, tâm noi kon sau Yôsep, hăn dăch jêh ri ngơi ta năp Y-Môis jêh ri ta năp phung kôranh mât uănh, phung kôranh ma ndŭl mpôl phung ƀon lan Israel.$b$,true),
('bunong-vn','NUM',36,2,null,$b$Khân păng lah, “Yêhôva ntĭnh jêh ma kôranh gâp ăn n'gor bri aơ jêng drăp ndơn gŭ chăm ma phung ƀon lan Israel ma nau tâm nchroh. Jêh ri Yêhôva ntĭnh jêh ma kôranh gâp ăn drăp ndơn Y-Sêlôpêhat nâu hên ma phung kon bu ur păng.$b$,true),
('bunong-vn','NUM',36,3,null,$b$Ƀiă lah tơ lah khân păng gŭ sai đah du huê bu klâu tâm mpôl băl êng tâm phung ƀon lan Israel, drăp ndơn khân păng mra sŏk tă bơh drăp ndơn phung chô che hên, jêh ri ntop đŏng ma drăp ndơn mpôl băl sai phung bu ur nây. Pô ri bu mra sŏk ndơ nây tă bơh kô̆ drăp ndơn hên.$b$,true),
('bunong-vn','NUM',36,4,null,$b$Jêh ri tơ lah tât năm Jubili ma phung ƀon lan Israel, nôk nây drăp ndơn khân păng mra ntop đŏng ma drăp ndơn mpôl băl sai phung bu ur nây, jêh ri drăp ndơn khân păng bu mra sŏk tă bơh drăp ndơn ndŭl mpôl chô che hên.”$b$,false),
('bunong-vn','NUM',36,5,null,$b$Y-Môis ntĭnh jêh ma phung ƀon lan Israel tĭng nâm nau Yêhôva ngơi, lah, “Ndŭl mpôl phung kon bu klâu Yôsep geh nau găl.$b$,false),
('bunong-vn','NUM',36,6,null,$b$Aơ jêng nau Yêhôva ntĭnh di ma phung kon bu ur Y-Sêlôpêhat, ‘Ăn khân păng gŭ sai mbu nơm khân păng ŭch; knŏng khân păng dơi gŭ sai tâm ndŭl mpôl noi khân păng.$b$,false),
('bunong-vn','NUM',36,7,null,$b$Drăp ndơn phung ƀon lan Israel bu mâu dơi jao tă bơh du ndŭl mpôl ma du ndŭl mpôl êng ôh; yor lah ăp nơm phung ƀon lan Israel mra gŭ tâm ntŭk drăp ndơn ndŭl mpôl noi păng.$b$,false),
('bunong-vn','NUM',36,8,null,$b$Ăp nơm kon bu ur nơm geh du kô̆ drăp ndơn tâm du ndŭl mpôl phung ƀon lan Israel mra jêng ur ma du huê tă bơh du rnăk vâl tâm ndŭl mpôl chô che păng, gay ma ăp nơm phung ƀon lan Israel dơi geh drăp ndơn chô che păng.$b$,false),
('bunong-vn','NUM',36,9,null,$b$Pô ri drăp ndơn bu mâu dơi jao ôh tă bơh du ndŭl mpôl ăn ma du ndŭl mpôl êng; yor lah ăp ndŭl mpôl phung Israel mra gŭ tâm ntŭk drăp ndơn khân păng nơm.$b$,false),
('bunong-vn','NUM',36,10,null,$b$Phung kon bu ur Y-Sêlôpêhat ƀư tĭng nâm nau Yêhôva ntĭnh jêh ma Y-Môis;$b$,false),
('bunong-vn','NUM',36,11,null,$b$Yor lah H'Mahla, H'Tirsa, H'Hôgla, jêh ri H'Nôa, phung kon bu ur Y-Sêlôpêhat, gŭ sai jêh đah bu klâu phung kon bu klâu oh nâu mbơ̆ khân păng.$b$,false),
('bunong-vn','NUM',36,12,null,$b$Khân păng gŭ sai đah phung mpôl phung kon bu klâu Y-Manasê, kon bu klâu Y-Yôsep, jêh ri drăp ndơn khân păng hôm e tâm ndŭl mpôl chô che khân păng.$b$,false),
('bunong-vn','NUM',36,13,null,$b$Nây jêng nau ntĭnh jêh ri nau vay Yêhôva ăn đah Y-Môis mbơh ma phung ƀon lan Israel tâm neh lâng n'gor Môap dăch dak krong Yurdan tâm tra đah ƀon Yêrikô.$b$,false);
