insert into public.bible_verses (translation_id, book_code, chapter, verse, verse_end, text, para) values
('bunong-vn','DEU',1,1,null,$b$Aơ jêng nau Y-Môis ngơi ma lĕ rngôch phung Israel đah tê̆ dak krong Yurdan, tâm bri rdah, tâm rlŭng Arabah mơ pa Supha, vah vang Paran, Tôphel, Laban, Hasêrôt jêh ri Disahap.$b$,true),
('bunong-vn','DEU',1,2,null,$b$Geh jât nar hăn bơh Hôrep njŏ trong yôk Sêir tât ta Kadês Barnê.$b$,false),
('bunong-vn','DEU',1,3,null,$b$Tâm năm tal puăn jât, ta nar nguay khay jât ma nguay Y-Môis ngơi ma phung ƀon lan Israel tĭng nâm lĕ rngôch nau Yêhôva ăn jêh ma păng, ntăm ma khân păng,$b$,false),
('bunong-vn','DEU',1,4,null,$b$jêh păng dơi đah Y-Sihôn hađăch phung Amôrit gŭ ta ƀon Hêsbôn, jêh ri Y-Ôk hađăch n'gor Basan gŭ ta ƀon Astarôt jêh ri ta ƀon Êdrei.$b$,false),
('bunong-vn','DEU',1,5,null,$b$Đah tê̆ dak krong Yurdan tâm n'gor Môap, Y-Môis ntơm rblang nau vay nây, lah:$b$,true),
('bunong-vn','DEU',1,6,null,$b$“Yêhôva Brah Ndu he lah jêh ma he ta Hôrep, ‘Găp jêh khân may gŭ tâm yôk aơ.$b$,false),
('bunong-vn','DEU',1,7,null,$b$Plơ̆ du hom, hăn hom ta n'gor klơ dor phung Amôrit jêh ri lĕ rngôch phung chiau meng khân păng tâm rlŭng Arabah, ta n'gor klơ dor jêh ri n'gor neh lâng, ta n'gor Nêgep, jêh ri ta kơh dak mƀŭt, n'gor phung Kanaan, jêh ri ta n'gor Liban, kŏ tât ta kơh dak krong toyh, dak krong Ơphrat.$b$,false),
('bunong-vn','DEU',1,8,null,$b$Aơ, gâp rdâk an jêh n'gor bri ta năp khân may; lăp jêh ri sŏk hom n'gor Yêhôva ton sơm jêh ma phung che khân may, ma Y-Abraham, ma Y-Isăk, jêh ri ma Y-Yakôb, gay ăn ma khân păng jêh ri ma phung kon sau pa kơi ma khân păng.’ Nau Njêng Phung Kôranh Phat Dôih$b$,false),
('bunong-vn','DEU',1,9,null,$b$Dôl nây gâp lah ma khân may, “Gâp mâu dơi ôh êng gâp anh khân may.$b$,false),
('bunong-vn','DEU',1,10,null,$b$Yêhôva Brah Ndu khân may ƀư bĭk rơ̆ jêh khân may, jêh ri aơ, nar aơ khân may jêng âk tâm ban ma mănh klơ trôk.$b$,false),
('bunong-vn','DEU',1,11,null,$b$Dăn ma Yêhôva Brah Ndu phung che khân may ƀư bĭk khân may jêng âk lơn du rbăn tơ̆ , jêh ri mât ton nau ueh uĭn ma khân may tĭng nâm păng ton jêh ma khân may!$b$,false),
('bunong-vn','DEU',1,12,null,$b$Mâm gâp dơi tuy êng gâp rplay jâk khân may jêh ri nau khân may tâm rlăch?$b$,false),
('bunong-vn','DEU',1,13,null,$b$Săch hom phung blau mĭn, gĭt rbăng jêh ri rgăn jêh âk nau tât, tĭng nâm ndŭl mpôl khân may, jêh ri gâp mra njêng khân păng kôranh ma khân may.$b$,false),
('bunong-vn','DEU',1,14,null,$b$Jêh ri khân may plơ̆ lah ma gâp. Nau may ngơi nây jêng ueh ăn hên ƀư.$b$,false),
('bunong-vn','DEU',1,15,null,$b$Pô ri gâp sŏk phung kôranh bơh ndŭl mpôl khân may, phung blau mĭn jêh ri rgăn âk nau tât jêh ri tâm dơm khân păng jêng kôranh ma khân may, kôranh ma rbăn, kôranh ma rhiăng kôranh ma prăm jât, jêh ri kôranh ma jât nuyh, jêh ri kôranh chiă uănh tâm phung ndŭl mpôl khân may.$b$,false),
('bunong-vn','DEU',1,16,null,$b$Dôl nây gâp ntăm ma phung kôranh phat dôih khân may. “Gŭ iăt hom nau ndrăng phung oh nâu khân may jêh ri phat hom dôih ma nau sŏng ma du huê bunuyh đah oh nâu păng mâu lah bunuyh bu năch gŭ ndrel ma păng.$b$,true),
('bunong-vn','DEU',1,17,null,$b$Lơi gŭ du ding ôh tâm nau phat dôih, ăn khân may iăt nau nơm jê̆ nđâp nau nơm toyh lĕ; lơi klach ôh ma muh măt bunuyh, yor lah nau phat dôih jêng kan Brah Ndu. Jêh ri dôih jêr ir ma khân may, ăn khân may ndơp ma gâp, jêh ri gâp mra iăt nau nây.’$b$,false),
('bunong-vn','DEU',1,18,null,$b$Dôl nây gâp ntăm jêh ma khân may lĕ rngôch nau khân may mra ƀư.$b$,false),
('bunong-vn','DEU',1,19,null,$b$“He hăn tă bơh Hôrep jêh ri he rgăn lĕ bri rdah toyh jêh ri djơh mhĭk khân may saơ jêh, njŏ trong mơ pa n'gor klơ dor phung Amôrit, tĭng nâm Yêhôva Brah Ndu he ntăm jêh ma he;$b$,true),
('bunong-vn','DEU',1,20,null,$b$jêh ri gâp lah ma khân may, “Khân may tât jêh ta n'gor klơ dor phung Amôrit, n'gor Yêhôva Brah Ndu he ăn jêh ma he.$b$,false),
('bunong-vn','DEU',1,21,null,$b$Aơ Yêhôva Brah Ndu khân may rdâk jêh n'gor ta năp khân may; hao sŏk hom tĭng nâm Yêhôva Brah Ndu phung che khân may mbơh jêh ma khân may; lơi klach mâu lah rdja nuih n'hâm ôh.$b$,true),
('bunong-vn','DEU',1,22,null,$b$Jêh ri lĕ rngôch khân may văch ta gâp jêh ri lah: ‘Ăn njuăl bunuyh lor ma he, gay ma khân păng uănh nhhol an ma he n'gor nây, jêh ri ăn khân păng mbơh ma he trong he mra hăn hao jêh ri ƀon he mra lăp.’$b$,false),
('bunong-vn','DEU',1,23,null,$b$Nau nây gâp mĭn jêh ueh, jêh ri gâp săch jât ma bar nuyh bu klâu tâm phung khân may, du huê bu klâu tâm ăp ndŭl mpôl.$b$,false),
('bunong-vn','DEU',1,24,null,$b$Khân păng plơ̆ hăn hao ta n'gor klơ dor, jêh ri tât ta rlŭng Y-Êskôl jêh ri chop nhhol păng.$b$,false),
('bunong-vn','DEU',1,25,null,$b$Khân păng sŏk djôt tâm ti khân păng ƀa ƀă play tâm n'gor nây jêh ri djôt păng ma he, jêh ri sĭt mbơh ma he jêh ri lah: ‘N'gor Yêhôva Brah Ndu he ăn ma he jêng ueh.’$b$,false),
('bunong-vn','DEU',1,26,null,$b$“Ƀiă lah khân may mâu ŭch hăn hao ôh, ƀiă lah khân may tâm rdâng đah nau Yêhôva Brah Ndu khân may ntăm.$b$,false),
('bunong-vn','DEU',1,27,null,$b$Jêh ri khân may ngơi ƀrôk tâm ngih bok khân may, jêh ri lah: “Yor lah Yêhôva tâm rmot ma he, pô ri păng njŭn he luh bơh n'gor Êjipt, gay jao he tâm ti phung Amôrit, gay ƀư rai he.$b$,false),
('bunong-vn','DEU',1,28,null,$b$Ta ntŭk he mra hăn hao? Phung oh nâu he ƀư rdja nuih n'hâm he, lah: “Phung ƀon lan nây jêng toyh lơn jêh ri jong lĭng juat lơn ma he; ƀon khân păng toyh jêh ri bât pêr nâp prêh tâm trôk, rmeh ma nây hên saơ phung kon bu klâu Anak ta nây.”$b$,false),
('bunong-vn','DEU',1,29,null,$b$Jêh ri gâp lah jêh ma khân may, ‘Lơi khân may krit jêh ri klach ma khân păng ôh.$b$,true),
('bunong-vn','DEU',1,30,null,$b$Yêhôva Brah Ndu khân may, nơm hăn lor ma khân may, păng nơm mra tâm lơh an ma khân may, nâm bu păng ƀư jêh ma khân may tâm n'gor Êjipt ta năp măt khân may,$b$,false),
('bunong-vn','DEU',1,31,null,$b$jêh ri tâm bri rdah, ntŭk khân may saơ jêh nau Yêhôva Brah Ndu khân may chông khân may nâm bu du huê bu klâu chông kon bu klâu păng, tâm lĕ rngôch trong khân may hăn jêh kŏ khân may tât ta ntŭk aơ.’$b$,false),
('bunong-vn','DEU',1,32,null,$b$Ƀiă lah nđâp nau ngơi nây kđôi lĕ, khân may mâu chroh ôh ma Yêhôva Brah Ndu khân may,$b$,false),
('bunong-vn','DEU',1,33,null,$b$nơm hăn lor ma khân may ta trong ŭch joi du ntŭk prăp rdâk ngih bok khân may, tâm ŭch dôl măng gay ntĭm trong ma khân may mra hăn, jêh ri tâm ndâr tŭk dôl nar.$b$,false),
('bunong-vn','DEU',1,34,null,$b$Yêhôva tăng nau khân may ngơi păng ji nuyh jêh ri ton pô aơ!$b$,true),
('bunong-vn','DEU',1,35,null,$b$‘Mâu geh du huê bu klâu bơh rnôk tih mhĭk aơ mra saơ n'gor ueh gâp ton jêh ŭch ăn ma phung che khân may,$b$,false),
('bunong-vn','DEU',1,36,null,$b$knŏng Y-Kalep kon bu klâu Y-Jêphunê; păng mra saơ n'gor nây, jêh ri gâp mra ăn ma păng jêh ri ma phung kon păng n'gor păng jot jêh, yor lah păng tĭng ndô̆ Yêhôva ma lĕ nuih n'hâm!$b$,false),
('bunong-vn','DEU',1,37,null,$b$Yêhôva ji nuih ma gâp tâm ban lĕ yor khân may, jêh ri lah: ‘May mâu mra lăp n'gor nây ôh.$b$,false),
('bunong-vn','DEU',1,38,null,$b$Y-Yôsuê kon bu klâu Y-Nun, nơm gŭ râng ta năp may, păng mra lăp n'gor nây; tâm n'hao nuih păng, yor lah păng mra ăn phung Israel dơn n'gor nây.$b$,true),
('bunong-vn','DEU',1,39,null,$b$Jêh ri phung kon jê̆ khân may, khân may lah jêh mra jêng mpa ndơm, jêh ri phung kon khân may, nar aơ ê mâp gĭt năl nau ueh mâu lah nau mhĭk; mra lăp tâm n'gor nây; gâp mra ăn n'gor nây ma khân păng; jêh ri mra pha khân păng.$b$,false),
('bunong-vn','DEU',1,40,null,$b$Ƀiă lah bi ma khân may, plơ̆ hom, jêh ri nsong tâm bri rdah ma pa Dak Mƀŭt Chăng.’$b$,false),
('bunong-vn','DEU',1,41,null,$b$“Jêh ri khân may plơ̆ lah ma gâp, ‘Hên ƀư tih jêh đah Yêhôva; hên mra hăn hao jêh ri tâm lơh di tĭng nâm Yêhôva Brah Ndu he ntăm jêh ma he.’ Jêh ri ăp nơm bu klâu tâm phung khân may djôt ndơ tâm lơh păng, jêh ri mĭn mra nơih hăn hao ta n'gor klơ dor.$b$,false),
('bunong-vn','DEU',1,42,null,$b$Yêhôva lah ma gâp: ‘Lah hom ma khân păng. Lơi hăn hao mâu lah tâm lơh ôh, yor lah gâp mâu gŭ ta nklang khân may; klach lah dơi phung rlăng đah khân may.’$b$,false),
('bunong-vn','DEU',1,43,null,$b$Pô ri gâp ngơi đah may, jêh ri khân may mâu gŭ iăt ôh; ƀiă lah khân may tâm rdâng jêh đah nau Yêhôva ntăm, jêh ri ma nau rôih nko khân may hăn hao ta n'gor klơ dor.$b$,false),
('bunong-vn','DEU',1,44,null,$b$Dôl nây phung Amôrit, phung gŭ tâm n'gor klơ dor nây, luh tâm rdâng đah khân may jêh ri tĭng khân may tâm ban ma sŭt, jêh ri ƀư rai khân may tâm Sêir tât ta Hôrma.$b$,false),
('bunong-vn','DEU',1,45,null,$b$Jêh ri khân may sĭt nhĭm ta năp Yêhôva; ƀiă lah Yêhôva mâu gŭ iăt bâr khân may mâu lah rkêng tôr ma khân may ôh.$b$,false),
('bunong-vn','DEU',1,46,null,$b$Yor nây khân may ăt hôm gŭ ta Kadês âk nar, khân may ăt gŭ ta nây jŏ.$b$,false),
('bunong-vn','DEU',2,1,null,$b$“Pô ri luh plơ̆ jêh ri nsong tâm bri rdah mơ pa Dak Mƀŭt Chăng tĭng nâm Yêhôva mbơh jêh ma gâp; jêh ri dôl âk nar hên ndăch yôk Sêir.$b$,true),
('bunong-vn','DEU',2,2,null,$b$Jêh ri Yêhôva lah ma gâp.$b$,true),
('bunong-vn','DEU',2,3,null,$b$‘Gâp jêh khân may ndăch n'gor yôk aơ; plơ̆ hom mơ pa klơ dor.$b$,false),
('bunong-vn','DEU',2,4,null,$b$Ntăm ma phung ƀon lan. Khân may dăch rgăn n'gor phung oh nâu khân may phung kon bu klâu Y-Êsau, phung gŭ tâm n'gor Sêir; jêh ri khân păng mra klach ma khân may. Pô ri njrăng hom khân may;$b$,false),
('bunong-vn','DEU',2,5,null,$b$lơi tâm rlăch đah khân păng ôh; yor lah gâp mâu mra ăn ôh ma khân may du nkô̆ neh khân păng dơm dam, nđâp ntŭk ma mpang jâng khân may jot mâu lĕ, yor lah gâp ăn jêh yôk Sêir jêng drăp ndơn ma Y-Êsau.$b$,false),
('bunong-vn','DEU',2,6,null,$b$Khân may mra rvăt ndơ sông sa bơh khân păng ma prăk, pô ri mơ khân may dơi geh sông sa, jêh ri khân may mra rvăt dak bơh ma khân păng ma prăk, pô ri mơ khân may dơi nhêt.$b$,false),
('bunong-vn','DEU',2,7,null,$b$Yor lah Yêhôva Brah Ndu khân may mât ton nau ueh uĭn jêh ma khân may tâm lĕ rngôch kan ti khân may ƀư. Păng gĭt nal jêh nau khân may nsong rgăn bri dah toyh aơ; dôl puăn jât năm aơ Yêhôva Brah Ndu khân may gŭ ndrel ma khân may jêh; khân may mâu pưt du ndơ ôh.’$b$,false),
('bunong-vn','DEU',2,8,null,$b$Pô ri he mra hăn, du bơh phung oh nâu he phung kon bu klâu Y-Êsau, phung gŭ tâm n'gor Sêir, du bơh trong rlŭng Arabah bơh Êlat jêh ri Esiôn Gêber.” Jêh ri he plơ̆ jêh ri hăn leo ta bri rdah n'gor Môap.$b$,false),
('bunong-vn','DEU',2,9,null,$b$Yêhôva lah jêh ma gâp, ‘Lơi ƀư jêr ma phung Môap mâu lah tâm lơh đah khân păng ôh, yor lah gâp mâu mra ăn ma khân may ôh du nkô̆ neh khân păng jêng ndơ khân may, yor lah gâp ăn jêh ƀon Ar jêng ndơ ma phung kon bu klâu Y-Lot.’$b$,true),
('bunong-vn','DEU',2,10,null,$b$(Phung Ênim gŭ ta nây lor, jêng du phung ƀon lan toyh jêh ri âk, jong lĭng nâm du phung Anak;$b$,false),
('bunong-vn','DEU',2,11,null,$b$nâm bu phung Anak bu gĭt năl khân păng ma amoh Rêphaim, ƀiă lah phung Môap rnha ma khân păng Ênim.$b$,false),
('bunong-vn','DEU',2,12,null,$b$Phung Hôrit tâm ban lĕ gŭ kăl e ri tâm n'gor Sêir, ƀiă lah phung kon bu klâu Y-Êsau nsot lơi khân păng ƀư rai lơi khân ô băl ta năp khân păng, jêh ri gŭ ta ntŭk khân ô băl; nâm bu phung Israel ƀư jêh ma n'gor jêng ndơ khân păng, n'gor Yêhôva ăn jêh ma khân păng)$b$,true),
('bunong-vn','DEU',2,13,null,$b$‘Aƀaơ aơ, dâk rgăn hom n'hor dak Sêret.’ Pô ri he rgăn n'hor dak Sêret.$b$,false),
('bunong-vn','DEU',2,14,null,$b$Nau jŏ he du bơh Kadês Barnê, kŏ tât he rgăn dak n'hor Sêret geh jêh pe jât ma nguay năm, kŏ tât lĕ rnôk nây, nâm bu ntĭt phung tâm lơh rai lôch jêh bơh nkual, tĭng nâm Yêhôva ton jêh.$b$,true),
('bunong-vn','DEU',2,15,null,$b$Yor lah nanê̆ ti Yêhôva tâm rdâng đah khân păng gay ƀư rai khân păng bơh nkual tât khân păng rai lôch lĕ.$b$,false),
('bunong-vn','DEU',2,16,null,$b$“Pô ri tơ lah lĕ rngôch phung bu klâu tâm lơh rai lôch jêh ri khĭt jêh bơh ta nklang phung ƀon lan,$b$,true),
('bunong-vn','DEU',2,17,null,$b$Yê-hô-va lah ma gâp,$b$,false),
('bunong-vn','DEU',2,18,null,$b$‘Nar aơ khân may mra rgăn n'har neh n'gor Môap ta ƀon Ar;$b$,false),
('bunong-vn','DEU',2,19,null,$b$jêh ri tơ lah khân may tât êp n'har phung kon bu klâu Amôn, lơi ƀư jêr ma khân păng mâu lah rlăch đah khân păng ôh, yor lah gâp mâu mra ăn ma khân may ôh du nkô̆ n'gor phung kon bu klâu Amôn jêng ndơ khân may, yor lah gâp ăn jêh n'gor nây ma phung kon bu klâu Y-Lot jêng ndơ khân păng.’$b$,false),
('bunong-vn','DEU',2,20,null,$b$(N'gor nây tâm ban lĕ bu gĭt jêng n'gor phung Rêphaim; phung Rêphaim gŭ ta nây kăl e ri, ƀiă lah phung Amôn rnha khân păng Samsumim,$b$,false),
('bunong-vn','DEU',2,21,null,$b$du phung ƀon lan toyh jêh ri âk, jong lĭng nâm bu phung Anak; ƀiă lah Yêhôva ƀư rai khân păng ta năp phung Amôn; jêh ri phung Amôt nsot khân păng jêh ri gŭ tâm ntŭk khân păng;$b$,false),
('bunong-vn','DEU',2,22,null,$b$nâm bu Yêhôva ƀư an jêh ma phung kon bu klâu Y-Êsau, phung gŭ tâm n'gor Sêir, tơ lah păng ƀư rai phung Hôrit ta năp khân păng, jêh ri khân păng nsot phung Hôrit jêh ri gŭ tâm ntŭk phung Hôrit tât ta nar aơ.$b$,false),
('bunong-vn','DEU',2,23,null,$b$Bi ma phung Avim phung gŭ tâm ƀon jê̆ jê̆ tât ta ƀon Gaxa, phung Kaptôrim, phung luh tă bơh Kaptôr, ƀư rai khân păng jêh ri gŭ tâm ntŭk khân păng).$b$,false),
('bunong-vn','DEU',2,24,null,$b$‘Dâk hom, jêh ri hăn rgăn krong Ârnôn, Aơ gâp jao jêh tâm ti may Y-Sihôn, du huê Amôrit, hađăch ƀon Hêsbôn, jêh ri n'gor păng. Ntơm sŏk hom jêh ri tâm lơh đah păng.$b$,false),
('bunong-vn','DEU',2,25,null,$b$Nar aơ gâp mra ntơm ăn nau bu krit jêh ri klach ma khân may tât ta phung ƀon lan gŭ tâm dâng lam trôk, phung mra iăt nau bu nkoch bri ma khân may, mra râm sâr jêh ri rngot klâng yor khân may.’ ”$b$,false),
('bunong-vn','DEU',2,26,null,$b$“Pô ri gâp njuăl hăn bơh bri rdah Kêdêmôt phung mbơh ma Y-Y-Sihôn hađăch ƀon Hêsbôn ma nau ngơi ma nau đăp mpăn, lah:$b$,true),
('bunong-vn','DEU',2,27,null,$b$‘Ăn gâp rgăn n'gor may, gâp mra hăn knŏng njŏ trong, gâp mâu mra teng pa ma mâu lah teng pa chiau.$b$,false),
('bunong-vn','DEU',2,28,null,$b$Ăn may tăch ma prăk ndơ sông sa ma gâp gay ma gâp dơi sông sa, jêh ri ăn dak ma gâp tâm rgâl đah prăk gay ma gâp dơi nhêt; knŏng ăn jâng gâp rgăn,$b$,false),
('bunong-vn','DEU',2,29,null,$b$tâm ban ma phung kon bu klâu Y-Êsau gŭ tâm n'gor Sêir jêh ri phung Môap gŭ tâm n'gor Ar ƀư jêh ma gâp, tât gâp rgăn dak krong Yurdan lăp n'gor Yêhôva Brah Ndu hên ăn jêh ma hên.’$b$,false),
('bunong-vn','DEU',2,30,null,$b$Ƀiă lah Y-Y-Sihôn hađăch ƀon Hêsbôn mâu ăn hên rgăn êp păng ôh; yor lah Yêhôva Brah Ndu khân may ƀư dăng nau mĭn păng jêh ri ƀư nâp nuih n'hâm păng, gay jao păng tâm ti khân may nâm bu tât nar aơ.$b$,false),
('bunong-vn','DEU',2,31,null,$b$Yêhôva lah ma gâp, ‘Aơ gâp ntơm jao ma may Y-Sihôn jêh ri n'gor păng; ntơm sŏk lơi, gay ma khân may dơi gŭ tâm n'gor păng.’$b$,true),
('bunong-vn','DEU',2,32,null,$b$Dôl nây Y-Sihôn luh tâm mâp đah he, phung ndrel ma lĕ rngôch phung ƀon lan păng, gay tâm lơh ta ƀon Jahas.$b$,false),
('bunong-vn','DEU',2,33,null,$b$Yêhôva Brah Ndu he jao jêh păng ma he; jêh ri he dơi đah păng, jêh ri phung kon bu klâu păng, jêh ri lĕ rngôch phung ƀon lan păng.$b$,true),
('bunong-vn','DEU',2,34,null,$b$Dôl nây hên sŏk lĕ rngôch ƀon toyh păng jêh ri ƀư rai lĕ ƀhiau lĕ rngôch ƀon toyh, phung bu klâu, phung bu ur jêh ri phung kon se jê̆; hên mâu om du huê hôm ôh.$b$,false),
('bunong-vn','DEU',2,35,null,$b$Knŏng he sŏk pit ma he nơm mpô mpa rong ndrel ma ndô ndơ bơh ƀon toyh he sŏk jêh.$b$,false),
('bunong-vn','DEU',2,36,null,$b$Ntơm bơh ƀon Arôer gŭ ta kơh rlŭng n'hor dak Arnôn jêh ri bơh ƀon toyh gŭ tâm rlŭng tât ta Galaat, mâu geh du rplay ƀon toyh jêng prêh ir ma he ôh. Yêhôva Brah Ndu he jao lĕ tâm ti he.$b$,false),
('bunong-vn','DEU',2,37,null,$b$Knŏng neh phung kon bu klâu Amôn khân may mâu mâp hăn dăch ôh, nâm bu ntĭt lĕ rngôch kơh dak krong Jabôk jêh ri ƀon toyh tâm n'gor klơ dor, jêh ri ta ntŭk Yêhôva Brah Ndu he buay jêh he.$b$,false),
('bunong-vn','DEU',3,1,null,$b$Dôl nây he plơ̆ jêh ri hao njŏ trong n'gor Basan; jêh ri Y-Ôk hađăch n'gor Basan luh tâm rdâng đah he, păng ndrel ma lĕ rngôch phung ƀon lan păng gay tâm lơh ta ƀon Êdrei.$b$,true),
('bunong-vn','DEU',3,2,null,$b$Ƀiă lah Yêhôva lah ma gâp, ‘Lơi klach ma păng, yor lah gâp jao păng jêh ri lĕ rngôch phung ƀon lan păng nđâp n'gor păng tâm ti may; may mra ƀư ma păng nâm bu may ƀư jêh ma Y-Sihôn hađăch phung Amôrit, nơm gŭ ta ƀon Hêsbôn.’$b$,false),
('bunong-vn','DEU',3,3,null,$b$Pô ri Yêhôva Brah Ndu he jao jêh tâm ti he nđâp ma Y-Ôk hađăch n'gor Basan jêh ri lĕ rngôch phung ƀon lan păng. He ƀư ma păng kŏ mâu hôm om du huê.$b$,false),
('bunong-vn','DEU',3,4,null,$b$Dôl nây he sŏk lĕ ƀon toyh păng mâu geh du rplay ƀon toyh ôh he ê sŏk ndơ khân păng prao jât rplay ƀon toyh, lĕ n'gor Argôp, ƀon bri hađăch Y-Ôk tâm n'gor Basan.$b$,false),
('bunong-vn','DEU',3,5,null,$b$Lĕ rngôch ƀon toyh nây geh pêr nâp, prêh, mpông pêr, mâng nđăng, rmeh lơn ma nây geh âk rplay ƀon mâu geh pêr ôh.$b$,false),
('bunong-vn','DEU',3,6,null,$b$He ƀư rai khân păng lĕ ƀhiau, tâm ban ma he ƀư jêh ma Y-Sihôn hađăch ƀon Hêsbôn, ƀư rai lĕ rngôch ƀon toyh, phung bu klâu, phung bu ur, jêh ri phung kon se jê̆.$b$,false),
('bunong-vn','DEU',3,7,null,$b$Ƀiă lah lĕ rngôch mpô mpa rong jêh ri ndô ndơ bơh ƀon toyh he pit in jêng ndơ he.$b$,false),
('bunong-vn','DEU',3,8,null,$b$Pô ri tâm rnôk nây he sŏk n'gor bơh ti bar hê hađăch phung Amôrit gŭ đah tê̆ dak krong Yurdan, ntơm bơh rlŭng n'hor dak Arnôn tât ta yôk Hêrmôn,$b$,true),
('bunong-vn','DEU',3,9,null,$b$(phung Sidôn rnha Sirion ma Hermôn, jêh ri phung Amôrit rnha ma păng Sênir),$b$,false),
('bunong-vn','DEU',3,10,null,$b$lĕ rngôch ƀon toyh tâm neh lâng klơ dor, lĕ rngôch n'gor Galaat, jêh ri lĕ rngôch n'gor Basan tât ta ƀon Salêka jêh ri ƀon Êdrei, ƀon toyh tâm ƀon bri hađăch Y-Ôk tâm n'gor Basan.$b$,false),
('bunong-vn','DEU',3,11,null,$b$(Yor lah knŏng Y-Ôk hađăch n'gor Basan hôm bơh ndŭl mpôl Rêphaim; aơ sưng păng bêch, păng jêng du rplay sưng bêch loih; mâu di hĕ păng gŭ ta ƀon Raba, ƀon toyh phung Amôn? Jong sưng nây geh sĭn hăt, jêh ri dĭ păng puăn hăt, tĭng nâm hăt bu veh).$b$,true),
('bunong-vn','DEU',3,12,null,$b$“Dôl nây tơ lah he sŏk n'gor nây jêng ndơ he, gâp ăn ma phung Ruben jêh ri ma phung Gat neh ntơm bơh ƀon Arôer njŏ kơh rlŭng n'hor dak Armôn, jêh ri n'gul n'gor klơ dor Galaat ndrel ma lĕ rngôch ƀon toyh păng.$b$,true),
('bunong-vn','DEU',3,13,null,$b$Kô̆ n'gor Galaat ăt hôm, jêh ri lĕ n'gor Basan, ƀon bri hađăch Y-Ôk, nâm bu ntĭt lĕ n'gor Argôp, gâp ăn ma n'gul ndŭl mpôl Manasê. (Glom n'gor Basan nây bu rnha n'gor Rêphaim,$b$,false),
('bunong-vn','DEU',3,14,null,$b$Y-Jar du huê ndŭl mpôl Manasê sŏk lĕ n'gor Argôp, nâm bu ntĭt n'gor Basan tât ta n'har phung Gêsurit jêh ri phung Makatit, jêh ri rnha ma ƀon jê̆ jê̆ ma amoh păng nơm. Havôt Jar nâm bu nar aơ).$b$,false),
('bunong-vn','DEU',3,15,null,$b$Gâp ăn n'gor Ga-la-at ma Kir.$b$,false),
('bunong-vn','DEU',3,16,null,$b$Ma phung Ruben jêh ri ma phung Gat gâp ăn neh bơh n'gor Galaat tât ta rlŭng n'hor dak Arnôn, ta nklang rlŭng jêng n'har, kŏ tât ta dak krong Jabôk, n'har n'gor phung Amôn;$b$,true),
('bunong-vn','DEU',3,17,null,$b$nđâp rlŭng Arabah ndrel ma dak krong Yurdan jêng n'har bơh Kinêret tât ta dak mƀŭt rlŭng Arabah, Dak Mƀŭt Boh, ta njâng yôk Pisga mơ pa lơ.$b$,false),
('bunong-vn','DEU',3,18,null,$b$“Dôl nây gâp ntăm ma khân may, lah: ‘Yêhôva Brah Ndu khân may jao jêh n'gor aơ jêng ndơ khân may; lĕ rngôch phung ta han janh khân may mra rgăn djôt leo ndơ tâm lơh ta năp phung oh nâu khân may, phung ƀon lan Israel.$b$,true),
('bunong-vn','DEU',3,19,null,$b$Ƀiă lah phung ur khân may, phung kon jê̆ khân may, jêh ri mpô mpa rong khân may (gâp gĭt khân may geh âk mpô mpa rong) mra ăt hôm tâm ƀon toyh gâp ăn jêh ma khân may,$b$,false),
('bunong-vn','DEU',3,20,null,$b$kŏ tât Yêhôva ăn jêh nau rlu ma phung oh nâu khân may, tâm ban ma khân may, jêh ri khân păng tâm ban lĕ gŭ tâm n'gor Yêhôva Brah Ndu khân may ăn jêh ma khân păng đah tê̆ dak krong Yurdan; jêh ri ăp nơm khân may mra sĭt ta neh păng nơm, neh nây gâp ăn jêh ma khân may.$b$,false),
('bunong-vn','DEU',3,21,null,$b$Dôl nây gâp ntăm jêh ma Y-Yôsuê. Măt may saơ jêh lĕ nau Yêhôva Brah Ndu may ƀư jêh ma bar hê hađăch aơ; tâm ban pô nây lĕ Yêhôva mra ƀư ma lĕ rngôch ƀon bri hađăch khân may mra rgăn lăp.$b$,true),
('bunong-vn','DEU',3,22,null,$b$Lơi klach ma khân păng ôh; yor lah Yêhôva Brah Ndu khân may tâm lơh an ma khân may.’ Yêhôva Mâu Ăn Y-Môis Lăp N'gor Kanaan ôh.$b$,false),
('bunong-vn','DEU',3,23,null,$b$“Dôl nây gâp vơh vơl ma Yêhôva, lah:$b$,true),
('bunong-vn','DEU',3,24,null,$b$“Ơ Kôranh Brah Yêhôva, may knŏng ntơm tâm mpơl ma tông mpăr may nau may jêng toyh jêh ri ti nau brah may, yor lah, mbu brah ta klơ trôk mâu lah ta neh ntu dơi ƀư kan jêh ri nau khlay yom tâm ban ma may?$b$,false),
('bunong-vn','DEU',3,25,null,$b$Gâp dăn ma may, ăn gâp rgăn jêh ri saơ n'gor ueh đah tê̆ dak krong Yurdan, n'gor klơ dor ueh nây, jêh ri n'gor Liban?$b$,false),
('bunong-vn','DEU',3,26,null,$b$Ƀiă lah Yêhôva ji nuih ma gâp yor khân may jêh ri mâu iăt nau gâp ôh. Yêhôva lah ma gâp, ‘Ăn may kơp nau aơ găp jêh ma may, lơi hôm ngơi nau aơ ma gâp ôh.$b$,false),
('bunong-vn','DEU',3,27,null,$b$Hao hom ta kô yôk Pisga jêh ri n'gơr măt may mơ pa dâng, mơ pa klơ yôk, mơ pa rđŭng, jêh ri mơ pa lơ, jêh ri uănh ma măt may, yor lah may mâu mra rgăn ôh dak krong Yurdan aơ.$b$,false),
('bunong-vn','DEU',3,28,null,$b$Ƀiă lah ntăm hom ma Y-Yôsuê, n'hao nuih păng jêh ri ƀư ktang păng, yor lah păng mra rgăn ta năp phung ƀon lan aơ, jêh ri păng mra ăn bu sŏk pha n'gor may mra saơ.$b$,false),
('bunong-vn','DEU',3,29,null,$b$Pô ri he mra gŭ tâm rlŭng tâm tra đah Betpêôr.$b$,true),
('bunong-vn','DEU',4,1,null,$b$“Aƀaơ aơ, Ơ phung Israel, gŭ iăt hom nau vay jêh ri nau ntăm gâp nti khân may, jêh ri ƀư tĭng ndô̆ nau nây; gay ma khân may dơi gŭ rêh jêh ri lăp n'gor Yêhôva Brah Ndu ma phung che khân may ăn ma khân may.$b$,true),
('bunong-vn','DEU',4,2,null,$b$Lơi ta khân may ntop ôh ma nau ngơi gâp ntăm jêh ma khân may, mâu lĕ dơi săch lơi păng; gay ma khân may dơi djôt prăp nau Yêhôva Brah Ndu khân may ntăm nau nây gâp ntăm ma khân may.$b$,false),
('bunong-vn','DEU',4,3,null,$b$Măt khân may saơ jêh moh Yêhôva ƀư jêh ta Baal Pêôr; yor lah Yêhôva Brah Ndu khân may ƀư rai jêh bơh nklang khân may lĕ rngôch bunuyh tĭng ndô̆ jêh Baal Pêôr.$b$,true),
('bunong-vn','DEU',4,4,null,$b$Ƀiă lah khân may phung gŭ rjăp đah Yêhôva Brah Ndu khân may ăt hôm rêh nar aơ.$b$,false),
('bunong-vn','DEU',4,5,null,$b$Aơ, gâp nti jêh ma khân may nau vay jêh ri nau ntăm tĭng nâm Yêhôva Brah Ndu gâp ntăm jêh ma gâp, gay ma khân may ƀư nau nây tâm n'gor khân may mra lăp sŏk.$b$,false),
('bunong-vn','DEU',4,6,null,$b$Djôt prăp hom jêh ri kơt ƀư tĭng nâm nau nây; yor lah nau nây jêng nau blau mĭn jêh ri nau gĭt rbăng khân may ta năp phung ƀon lan, tơ lah khân păng tăng lĕ rngôch nau vay aơ jêh ri lah. ‘Nanê̆ phung ndŭl mpôl toyh aơ jêng du phung ƀon lan gĭt mĭn?$b$,true),
('bunong-vn','DEU',4,7,null,$b$Yor lah mbu ndŭl mpôl toyh geh brah gŭ dăch khân păng tâm ban ma Yêhôva Brah Ndu he gŭ dăch he ăp tơ̆ he kuăl mbơh sơm ma păng?$b$,true),
('bunong-vn','DEU',4,8,null,$b$Jêh ri mbu ndŭl mpôl toyh geh nau vay jêh ri nau ntăm sŏng nâm bu lĕ rngôch nau vay aơ gâp tâm mpơl ta năp khân may nar aơ?$b$,false),
('bunong-vn','DEU',4,9,null,$b$“Knŏng njrăng hom jêh ri chiă uănh huêng khân may ma nau gơih, klach lah khân may chuêl lơi ndơ măt khân may saơ jêh, jêh ri klach lah khân păng lah du tă bơh nuih n'hâm khân may dôl lĕ nar khân may gŭ rêh; nti hom nau nây ma kon khân may jêh ri ma phung sau khân may$b$,true),
('bunong-vn','DEU',4,10,null,$b$moh nau tât ta nar khân may gŭ râng ta năp Yêhôva Brah Ndu khân may ta yôk Hôrep, tơ lah Yêhôva lah ma gâp, gay gâp dơi ăn khân păng iăt nau gâp ngơi, pô ri khân păng dơi nti klach yơk ma gâp lĕ rngôch nar khân may gŭ rêh ta neh ntu, jêh ri gay ma khân păng dơi nti nau nây ma phung kon khân păng.$b$,false),
('bunong-vn','DEU',4,11,null,$b$Khân may văch êp jêh ri gŭ râng ta njâng yôk, dôl ŭnh sa yôk kŏ pa trôk, nkŭm ma nau ngo, ma ndâr, jêh ri ma nau rngot.$b$,false),
('bunong-vn','DEU',4,12,null,$b$Dôl nây Yêhôva ngơi ma khân may ta nklang ŭnh. Khân may tăng bâr păng ngơi, ƀiă lah mâu saơ rup săk jăn păng ôh; geh knŏng bâr ngơi.$b$,false),
('bunong-vn','DEU',4,13,null,$b$Jêh ri Yêhôva mbơh ma khân may nau păng tâm rnglăp, nau păng ntăm jêh ăn khân may kơt ƀư, nâm bu ntĭt jât ntil nau ntăm; jêh ri păng chih nau nây ta bar plơp kađar lŭ.$b$,false),
('bunong-vn','DEU',4,14,null,$b$Dôl nây Yêhôva ntăm ma gâp sâm nti khân may nau vay, jêh ri nau ntăm, gay ma khân may ƀư tĭng kơt nau nây tâm n'gor khân may mra rgăn sŏk.$b$,true),
('bunong-vn','DEU',4,15,null,$b$“Pô ri njrăng hom ma khân may nơm. Yor lah khân may mâu saơ ôh rup săk jăn ta nar Yêhôva ngơi ma khân may ta yôk Hôrep bơh ta nklang ŭnh,$b$,true),
('bunong-vn','DEU',4,16,null,$b$njrăng hom klach lah khân may ƀư nau tih mhĭk dôl ƀư rup trah ma khân may nơm, nâm bu rup mpa, nâm bu rup bu klâu mâu lah bu ur,$b$,false),
('bunong-vn','DEU',4,17,null,$b$tâm ban ma rup mpa gŭ ta neh ntu, tâm ban ma rup sĭm geh năr mpăr tâm trôk,$b$,false),
('bunong-vn','DEU',4,18,null,$b$tâm ban ma mpa vơr ma ndŭl ta klơ neh, tâm ban ma rup ka gŭ tâm dak tâm dâng neh.$b$,false),
('bunong-vn','DEU',4,19,null,$b$Njrăng hom khân may, klach lah n'gơr măt mơ pa trôk jêh ri khân may saơ nar, khay, jêh ri mănh, lĕ rngôch phung ta han tâm trôk, khân may geh nau nchâp jêh ri mbah yơk ma ndơ nây jêh ri rhŏ kan ma khân păng, mpa nây Yêhôva Brah Ndu khân may ăn jêh ma lĕ rngôch phung ƀon lan gŭ tâm dâng lĕ trôk.$b$,false),
('bunong-vn','DEU',4,20,null,$b$Ƀiă lah Yêhôva sŏk jêh khân may, jêh ri njŭn khân may luh tă ŭnh năk loih, bơh n'gor Êjipt, ăn jêng du phung ƀon lan jêng ndơ păng nơm, tâm ban ma khân may jêng nar aơ.$b$,false),
('bunong-vn','DEU',4,21,null,$b$Jêh ri Yêhôva ji nuih ma gâp yor khân may, jêh ri păng ton ma gâp mâu mra rgăn dak krong Yurdan ôh, jêh ri gâp mâu mra lăp ôh tâm n'gor ueh Yêhôva Brah Ndu khân may ăn ma khân may jêng drăp ndơn chăm.$b$,false),
('bunong-vn','DEU',4,22,null,$b$Yor lah gâp mra khĭt tâm n'gor aơ, gâp mâu dơi rgăn dak krong Yurdan ôh; ƀiă lah khân may mra rgăn jêh ri sŏk jêng ndơ khân may nơm n'gor ueh nây.$b$,false),
('bunong-vn','DEU',4,23,null,$b$Njrăng hom ma khân may nơm, klach lah khân may chuêl nau tâm rnglăp Yêhôva Brah Ndu khân may ƀư jêh đah khân may, jêh ri ƀư rup trah nâm bu rup mpa Yêhôva Brah Ndu khân may buay jêh.’$b$,false),
('bunong-vn','DEU',4,24,null,$b$Yêhôva Brah Ndu khân may jêng rlô ŭnh hôm sa jêh ri Brah Ndu blau ntôn.$b$,false),
('bunong-vn','DEU',4,25,null,$b$“Tơ lah khân may geh kon jêh ri sau se, jêh ri khân may jêng ranh jêh tâm n'gor, tơ lah khân may ƀư nau tih mhĭk dôl ƀư rup trah nâm bu rup mpa, jêh ri moh jêng mhĭk ta năp măt Yêhôva Brah Ndu khân may ăn nsônh păng ji nuih,$b$,true),
('bunong-vn','DEU',4,26,null,$b$nar aơ gâp kuăl trôk jêh ri neh ntu jêng mpa mbơh tâm rdâng đah khân may ma nau khân may gơnh roh lĕ bơh n'gor khân may mra rgăn dak krong Yurdan sŏk jêng ndơ khân may. Khân may mâu mra gŭ jŏ ta nây ôh, ƀiă lah khân may mra rai lĕ ƀhiau,$b$,false),
('bunong-vn','DEU',4,27,null,$b$Jêh ri Yêhôva mra ƀư nhhơt khân may ta nklang phung ndŭl mpôl bunuyh, jêh ri khân may mra ăt hôm knŏng djê̆ dơm ta nklang phung ndŭl mpôl bunuyh ntŭk Yêhôva mra nsot khân may.$b$,false),
('bunong-vn','DEU',4,28,null,$b$Jêh ri ta nây khân may mra pah kan ma phung brah ƀư ma si jêh ri lŭ, kan ti bunuyh ƀư, mâu blau saơ, mâu blau tăng, mâu blau sông sa ôh, mâu lĕ blau ƀâu.$b$,false),
('bunong-vn','DEU',4,29,null,$b$Ƀiă lah bơh ntŭk nây khân may joi Yêhôva Brah Ndu khân may, jêh ri khân may mra saơ păng tơ lah khân may joi păng ma lĕ nuih n'hâm jêh ri lĕ huêng khân may,$b$,false),
('bunong-vn','DEU',4,30,null,$b$Dôl khân may geh nau rêh ni, jêh ri lĕ rngôch mpa aơ mra tât ma khân may tâm nar lôch dŭt, khân may mra plơ̆ tay ma Yêhôva Brah Ndu khân may jêh ri tông bâr păng.$b$,false),
('bunong-vn','DEU',4,31,null,$b$Yor lah Yêhôva Brah Ndu khân may jêng Brah Ndu gĭt yô̆, păng mâu mra lơi khân may mâu lah ƀư rai khân may mâu lah chuêl ôh nau păng tâm rnglăp đah phung che khân may păng ton jêh ma khân păng.$b$,false),
('bunong-vn','DEU',4,32,null,$b$“Ôp hom aƀaơ ma rnôk rlau jêh, geh lor ma khân may ntơm bơh nar Brah Ndu rhăk njêng bunuyh ta neh ntu, jêh ri ôp bơh bôl dŭt trôk ma du ntŭk dŭt trôk êng, gĭt lah geh nau toyh nâm bu mâp tât jêh mâu lah bu mâp tăng jêh.$b$,true),
('bunong-vn','DEU',4,33,null,$b$Mâp geh lĕ du phung ƀon lan tăng bâr brah ngơi bơh tâm nklang ŭnh nâm bu khân may hŏ tăng jêh, jêh ri ăt hôm rêh?$b$,false),
('bunong-vn','DEU',4,34,null,$b$Mâu lah mâp geh lĕ du huê brah rlong văch sŏk ma păng nơm du mpôl băl bunuyh bơh tâm nklang du mpôl băl êng ma nau tâm rlong, ma nau tâm mbên, ma kan khlay yom, jêh ri ma nau tâm lơh, ma ti brah jêh ri yơr jêh, jêh ri ma nau ƀư klach toyh nâm bu lĕ rngôch nau Yêhôva Brah Ndu khân may ƀư jêh ma khân may tâm n'gor Êjipt ta năp măt khân may?$b$,false),
('bunong-vn','DEU',4,35,null,$b$Bu tâm mpơl jêh ma khân may nau nây, gay ma khân may dơi gĭt Yêhôva jêng Brah Ndu, mâu hôm geh nơm êng ôh.$b$,false),
('bunong-vn','DEU',4,36,null,$b$Bơh trôk păng ăn khân may tăng bâr păng ŭch nti đăp khân may; jêh ri ta neh ntu păng ăn khân may saơ ŭnh toyh păng, jêh ri khân may tăng bâr păng tă bơh tâm nklang ŭnh toyh.$b$,false),
('bunong-vn','DEU',4,37,null,$b$Jêh ri yor lah păng rŏng ma phung che khân may jêh ri săch phung kon sau khân păng, pa kơi khân păng, jêh ri njŭn khân may luh tă bơh n'gor Êjipt ma nau păng gŭ ndrel,$b$,true),
('bunong-vn','DEU',4,38,null,$b$ma nau brah toyh păng, dôl nsot phung ndŭl mpôl bunuyh ta năp khân may toyh lơn jêh ri ktang lơn ma khân may, gay njŭn khân may lăp gay ăn n'gor khân păng jêng drăp ndơn chăm ma khân may nâm bu tât jêh ta nar aơ.$b$,false),
('bunong-vn','DEU',4,39,null,$b$Pô ri ăn khân may gĭt nar aơ, jêh ri djôt prăp hom tâm nuih n'hâm khân may Yêhôva Brah Ndu tâm trôk ta klơ jêh ri ta neh ntu tâm dâng; mâu hôm geh nơm êng ôh.$b$,false),
('bunong-vn','DEU',4,40,null,$b$Yor nây ăn khân may djôt prăp nau vay păng jêh ri nau păng ntăm gâp ăn jêh ma khân may nar aơ, gay ma nau ueh tât ma khân may jêh ri ma phung kon khân may pa kơi, jêh ri gay ma khân may ƀư jŏ nar khân may tâm Yêhôva Brah Ndu khân may ăn ma khân may n'ho ro.”$b$,true),
('bunong-vn','DEU',4,41,null,$b$Dôl nây Y-Môis prăp pe ƀon toyh mơ pa lơ dak krong Yurdan,$b$,true),
('bunong-vn','DEU',4,42,null,$b$gay ma nơm nkhĭt bunuyh dơi du krap ta nây, nơm nkhĭt chiau meng păng ma nau mâu ŭch ôh, mâu mâp ƀư rlăng đah ô băl ôh bơh sa ơm, jêh ri gay ma dôl du ma du rplay tâm ƀon nây păng dơi tâm rklaih nau rêh păng;$b$,false),
('bunong-vn','DEU',4,43,null,$b$ƀon Bêser gŭ tâm bri rdah ta neh lâng klơ dor prăp ma phung Ruben, ƀon Ramôt tâm n'gor Galaat prăp ma phung Gat jêh ri ƀon Gôlan tâm n'gor Basan prăp ma phung Manasê.$b$,false),
('bunong-vn','DEU',4,44,null,$b$Aơ jêng nau vay Y-Môis mpơl ta năp phung kon Israel.$b$,true),
('bunong-vn','DEU',4,45,null,$b$Aơ jêng nau mbơh nau vay, jêh ri nau ntăm Y-Môis ngơi jêh ma phung kon Israel, dôl khân păng luh bơh n'gor Êjipt.$b$,false),
('bunong-vn','DEU',4,46,null,$b$Đah rĭ kơh dak krong Yurdan tâm rlŭng tâm ta đah Bet Pêôr, tâm n'gor Y-Sihôn hađăch phung Amôrit, nơm gŭ ta ƀon Hêsbôn, Y-Môis jêh ri phung kon Israel tâm lơh dơi jêh đah păng dôl khân păng luh bơh n'gor Êjipt.$b$,false),
('bunong-vn','DEU',4,47,null,$b$Khân păng sŏk pha n'gor nây jêh ri n'gor Y-Ôk hađăch n'gor Basan, bar hê hađăch phung Amôrit gŭ mpeh đah rĭ dak krong Yurdan mơ pa lơ;$b$,false),
('bunong-vn','DEU',4,48,null,$b$bơh ƀon Arôer njŏ kơh rlŭng n'hor dak Arnôn tât ta yôk Siriôn (nâm bu ntĭt Hermôn).$b$,false),
('bunong-vn','DEU',4,49,null,$b$Ndrel ma nđâp lĕ rlŭng Arabah mơ pa lơ dak krong Yurdan tât ta dak mƀŭt Arabah ta jêng yôk Pisga.$b$,false),
('bunong-vn','DEU',5,1,null,$b$Y-Môis kuăl rgum lĕ rngôch phung ƀon lan Israel jêh ri lah ma khân păng, “Iăt hom, Hơi Israel, nau vay jêh ri nau ntĭnh gâp ngơi ăn khân may tăng nar aơ, ăn khân may nti jêh ri njrăng tâm nau tông nau nây.$b$,true),
('bunong-vn','DEU',5,2,null,$b$Yêhôva he ƀư jêh đah he du nau tâm rnglăp ta Yôk Hôrep.$b$,false),
('bunong-vn','DEU',5,3,null,$b$Mâu di ôh đah phung chô che he Yêhôva hŏ ƀư nau tâm rnglăp aơ, ƀiă lah nđâp lĕ rngôch phung he ta aơ hôm e rêh nar aơ.$b$,false),
('bunong-vn','DEU',5,4,null,$b$Yêhôva hŏ ngơi jêh đah khân may tâm thâng muh măt ta yôk bơh ta nklang ŭnh,$b$,false),
('bunong-vn','DEU',5,5,null,$b$dôl gâp gŭ vah vang Yêhôva đah khân may, gay mbơh ma khân may nau Yêhôva ngơi; yor lah khân may klach ma ŭnh, jêh ri mâu hao ôh ta klơ yôk. Păng lah:$b$,false),
('bunong-vn','DEU',5,6,null,$b$Gâp jêng Yêhôva Brah Ndu may, hŏ tŏk ngluh may bơh n'gor bri Êjipt, bơh ngih jêng dĭk nă.$b$,false),
('bunong-vn','DEU',5,7,null,$b$Lơi ta kơt brah êng ôh ta năp gâp.$b$,true),
('bunong-vn','DEU',5,8,null,$b$Lơi may ƀư ôh ma may nơm rup trah, mâu lah rup kơt mpa tâm trôk ta klơ, mâu lah ta neh ntu tâm dâng, mâu lah tâm dak tâm dak tâm dâng neh.$b$,true),
('bunong-vn','DEU',5,9,null,$b$Lơi ta may chon mbah ôh ma ndơ nây mâu lah rhŏ ma khân păng; yor lah gâp yơh Yêhôva Brah Ndu may jêng Brah Ndu blau ntôn, tâm rmal nau kue phung mbơ̆ khân păng tât sau tât se nôk rô̆ rơh pe jêh ri rơh puăn ma phung tâm rmot đah gâp,$b$,true),
('bunong-vn','DEU',5,10,null,$b$ƀiă lah tâm mpơl nau yô̆ ma âk rbăn bunuyh phung rŏng ma gâp jêh ri djôt prăp nau gâp ntĭnh.$b$,false),
('bunong-vn','DEU',5,11,null,$b$Lơi ta ngơi pâl amoh săk Yêhôva Brah Ndu may blă blơ ôh; yor lah Yêhôva mâu mra cha lơi mâu tâm rmal lĕ nơm dŏng amoh păng blă blơ.$b$,true),
('bunong-vn','DEU',5,12,null,$b$Ăn may kah gĭt nar rlu, gay prăp păng kloh ueh tĭng nâm Yêhôva Brah Ndu may ntĭnh jêh ma may.$b$,true),
('bunong-vn','DEU',5,13,null,$b$Ăn khân may ƀư lĕ kan ma khân may nơm tâm prao nar;$b$,false),
('bunong-vn','DEU',5,14,null,$b$ƀiă lah nar pơh jêng nar rlu prăp ma Yêhôva Brah Ndu may. Tâm nar nây khân may mâu dơi pah kan ôh, khân may nđâp ma kon bu ur bu klâu, dĭk bu ur bu klâu, mâu lah ndrôk rpu khân may, jêh ri bunăch bunĭng gŭ tâm ƀon khân may mâu dơi lĕ ƀư du ntil kan tâm nar pơh nây.$b$,false),
('bunong-vn','DEU',5,15,null,$b$Ăn may kah gĭt may jêng jêh bună tâm n'gor Êjipt jêh ri Yêhôva Brah Ndu may leo may du luh jêh bơh ntŭk nây ma ti brah yơr jêh; yor nây Yêhôva Brah Ndu may ntĭnh jêh ma may ăn kah gĭt prăp nar rlu.$b$,false),
('bunong-vn','DEU',5,16,null,$b$Yơk hom ma me mbơ̆ may, tĭng nâm Yêhôva Brah Ndu may ntĭnh jêh ma may, gay ma may dơi rêh jŏ năm tâm bri Brah Ndu, kôranh brah khân may, hŏ ăn jêh ma khân may.$b$,true),
('bunong-vn','DEU',5,17,null,$b$Lơi ta nkhĭt bu.$b$,true),
('bunong-vn','DEU',5,18,null,$b$Lơi ta văng tĭr.$b$,true),
('bunong-vn','DEU',5,19,null,$b$Lơi ta ntŭng.$b$,true),
('bunong-vn','DEU',5,20,null,$b$Lơi ta ngơi nchơt ma phung chiau meng khân may.$b$,true),
('bunong-vn','DEU',5,21,null,$b$Lơi ta kơnh ngih vâl bu, jêh ri mâu lĕ dơi kơnh ma ur bu, dĭk bu, seh bu, ndrôk bu, mâu lah moh ntil êng jêng ndơ khân păng.$b$,true),
('bunong-vn','DEU',5,22,null,$b$“Nau aơ Yêhôva ngơi ma lĕ rngôch phung khân may tâm rƀŭn ta yôk ta nklang ŭnh, bơh ndâr tŭk, jêh ri bơh nau rngot, ma bâr huy ktang; jêh ri păng mâu hôm ntop ôh. Păng nchih nau nây ta bar plơp kađar lŭ jêh ri ăn ma gâp.$b$,true),
('bunong-vn','DEU',5,23,null,$b$“Tơ lah khân may tăng bâr bơh ta nklang nau ngo, dôl yôk geh ŭnh sa, khân may văch êp gâp, lĕ rngôch phung kôranh ndŭl mpôl khân may jêh ri phung bu ranh khân may;$b$,true),
('bunong-vn','DEU',5,24,null,$b$jêh ri khân may lah: ‘Aơ, Yêhôva Brah Ndu he tâm mpơl jêh ma he nau chrêk rmah păng jêh ri nau toyh păng, jêh ri he tăng jêh bâr păng tă bơh tâm nklang ŭnh; nar aơ he saơ Brah Ndu ngơi đah bunuyh jêh ri bunuyh ăt hôm rêh.$b$,false),
('bunong-vn','DEU',5,25,null,$b$Yor nây aƀaơ aơ, mâm ƀư he khĭt? Yor lah ŭnh toyh aơ mra sa he; tơ lah he tăng bâr Yêhôva Brah Ndu he, he mra khĭt yơh.$b$,true),
('bunong-vn','DEU',5,26,null,$b$Yor lah mbu nâm tâm lĕ rngôch ƀiă lah tăng jêh bâr Brah Ndu rêh gŭ ngơi tă tâm nklang ŭnh nâm bu phung he jêh ri ăt hôm rêh?$b$,true),
('bunong-vn','DEU',5,27,null,$b$Ăn may hăn êp jêh ri iăt lĕ nau Yêhôva Brah Ndu he mra lah; jêh ri ngơi ma hên lĕ rngôch nau Yêhôva Brah Ndu mra ngơi ma may, jêh ri hên mra iăt jêh ri ƀư tĭng nau nây.’$b$,true),
('bunong-vn','DEU',5,28,null,$b$“Yêhôva iăt nau khân may ngơi tơ lah khân may ngơi ma gâp; jêh ri Yêhôva lah ma gâp: ‘Gâp tăng jêh nau phung ƀon lan aơ ngơi, nau khân păng ngơi ma may; di jêh nau khân păng ngơi.$b$,false),
('bunong-vn','DEU',5,29,null,$b$Ơ, gay ma khân păng geh ƀa ƀơ nuih n'hâm tâm ban pô nây, gay klach yơk ma gâp jêh ri djôt prăp lĕ nau gâp ntăm, gay ma nau tât ma khân păng jêh ri phung kon khân păng jêng ueh n'ho ro!$b$,false),
('bunong-vn','DEU',5,30,null,$b$Hăn hom, lah ma khân păng, “Sĭt hom ta ngih bok khân may.”$b$,false),
('bunong-vn','DEU',5,31,null,$b$Bi may, dâk gŭ râng hom êp gâp ta aơ, jêh ri gâp mra mbơh ma may lĕ rngôch nau ntăm, nau vay, jêh ri nau huêng brah may mra nti ma khân păng; gay ma khân păng kơt ƀư nau nây tâm n'gor khân may sŏk pha.”$b$,false),
('bunong-vn','DEU',5,32,null,$b$Yor nây ăn khân may njrăng ƀư tĭng nâm mâm Yêhôva Brah Ndu ntăm jêh ma khân may, lơi teng pa ma mâu lah pa chiau ôh.$b$,true),
('bunong-vn','DEU',5,33,null,$b$Ăn khân may hăn tâm lĕ rngôch trong Brah Ndu khân may ntăm jêh ma khân may, gay ma khân may dơi gŭ rêh, gay ma nau tât ma khân may jêng ueh, jêh ri gay ma khân may dơi gŭ jŏ tâm n'gor khân may mra sŏk pha.$b$,false),
('bunong-vn','DEU',6,1,null,$b$“Aơ nau ntăm, nau vay, jêh ri nau vay huêng brah Yêhôva Brah Ndu khân may ntăm jêh ăn gâp nti ma khân may, gay ma khân may kơt ƀư nau nây tâm n'gor khân may mra rgăn sŏk pha;$b$,true),
('bunong-vn','DEU',6,2,null,$b$gay ma khân may dơi klach yơk ma Yêhôva Brah Ndu khân may, khân may phung kon bu klâu khân may, jêh ri kon sau khân may, dôl djôt prăp lĕ rngôch nau vay jêh ri nau păng ntăm, nau nây gâp ntăm ma khân may, lĕ rngôch nar khân may gŭ rêh; jêh ri gay ƀư jŏ lơn nar khân may mra gŭ rêh.$b$,false),
('bunong-vn','DEU',6,3,null,$b$Iăt hom, Ơ phung Israel, jêh ri njrăng an ƀư tĭng kơt nau nây; gay ma nau tât ma khân may jêng ueh, jêh ri khân may dơi jêng bĭk âk, tĭng nâm Yêhôva Brah Ndu phung che khân may ton jêh ma khân may tâm du rplay n'gor geh ndơ sông sa nhêt âk rmeh.$b$,false),
('bunong-vn','DEU',6,4,null,$b$Iăt hom, Ơ phung Israel: Yêhôva Brah Ndu he jêng knŏng nguay Yêhôva;$b$,true),
('bunong-vn','DEU',6,5,null,$b$jêh ri ăn khân may rŏng ma Yêhôva Brah Ndu khân may ma lĕ nuih n'hâm khân may, ma lĕ huêng khân may, jêh ri ma lĕ nuih n'hâm ktang khân may.$b$,false),
('bunong-vn','DEU',6,6,null,$b$Jêh ri nau ngơi aơ gâp ntăm ma khân may nar aơ mra gŭ tâm nuih n'hâm khân may.$b$,false),
('bunong-vn','DEU',6,7,null,$b$Ăn khân may nti nau nây ma nau gơih ma phung kon khân may jêh ri ăn khân păng ngơi ma nau nây dôl khân may gŭ tâm ngih khân may, dôl khân may sak nsong, dôl khân may gŭ bêch, jêh ri dôl khân may dâk.$b$,false),
('bunong-vn','DEU',6,8,null,$b$Ăn khân may kât nau nây nâm bu du nau tâm mbên ta ti khân may, jêh ri nau nây mra gŭ ta ndăr kleng vah vang măt khân may,$b$,false),
('bunong-vn','DEU',6,9,null,$b$Ăn khân may chih nau nây mbong mpông ngih khân may jêh ri ta mpông pêr khân may.$b$,false),
('bunong-vn','DEU',6,10,null,$b$“Tơ lah Yêhôva Brah Ndu khân may njŭn khân may lăp tâm n'gor păng ton jêh ma phung che khân may, ma Y-Abraham, ma Y-Isăk, jêh ri ma Y-Yakôb, ŭch ăn ma khân may, geh ƀon toyh jêh ri ueh khân may mâu mâp rdâk ôh,$b$,true),
('bunong-vn','DEU',6,11,null,$b$jêh ri ngih bêng ma ăp ntil ndơ ueh khân may mâu mâp mbêng ôh, ntu dak kuyh jêh khân may mâu mâp kuyh ôh, đang play kriăk ƀâu jêh ri tơm play Ôlivơ khân may mâu mâp tăm ôh. Tơ lah khân may mra sa jêh ri hơm,$b$,false),
('bunong-vn','DEU',6,12,null,$b$njrăng hom klach lah khân may chuêl; Yêhôva, nơm njŭn jêh khân may luh bơh n'gor Êjipt bơh ngih jêng dĭk.$b$,false),
('bunong-vn','DEU',6,13,null,$b$Ăn khân may klach yơk mbah ma Yêhôva Brah Ndu khân may; ăn khân may pah kan ma păng jêh ri ton ma amoh păng.$b$,true),
('bunong-vn','DEU',6,14,null,$b$Lơi ta khân may kơt brah êng ôh, brah phung ƀon lan gŭ jŭm khân may.$b$,true),
('bunong-vn','DEU',6,15,null,$b$Yor lah Yêhôva Brah Ndu khân may ta nklang khân may jêng Brah Ndu blau ntôn; klach lah Yêhôva Brah Ndu khân may duh nuih ji nuih ma khân may, jêh ri păng ƀư rai lơi khân may bơh klơ neh ntu.$b$,false),
('bunong-vn','DEU',6,16,null,$b$Lơi ta khân may rlong uănh Yêhôva Brah Ndu khân may, nâm bu khân may rlong uănh jêh păng ta Masa.$b$,true),
('bunong-vn','DEU',6,17,null,$b$Ăn khân may djôt prăp ma nau gơih nau Yêhôva Brah Ndu khân may ntăm, jêh ri nau păng mbơh, nau vay păng, nau nây păng ntăm jêh ma khân may.$b$,false),
('bunong-vn','DEU',6,18,null,$b$Ăn khân may ƀư meh, nau di jêh ri ueh ta năp măt Yêhôva, gay ma nau tât ma khân may jêng ueh, jêh ri gay ma khân may dơi lăp sŏk pha n'gor ueh Yêhôva ton gay ăn ma phung che khân păng$b$,true),
('bunong-vn','DEU',6,19,null,$b$ma nau khân may nsot lĕ rngôch phung rlăng khân may tă bơh ta năp khân may, tĭng nâm Yêhôva ton jêh.$b$,false),
('bunong-vn','DEU',6,20,null,$b$Tơ lah kon bu klâu khân may ôp ma khân may kăndơ̆ , ‘Nâm bu ntĭt nau mbơh, nau vay, jêh ri nau ntăm Yêhôva Brah Ndu he ntăm jêh ma khân may?’$b$,true),
('bunong-vn','DEU',6,21,null,$b$Pô ri ăn khân may lah ma kon bu klâu khân may. ‘Hên jêng jêh dĭk ma Pharaôn tâm n'gor Êjipt, jêh ri Yêhôva njŭn jêh hên luh bơh n'gor Êjipt ma ti brah;$b$,false),
('bunong-vn','DEU',6,22,null,$b$jêh ri Yêhôva tâm mpơl jêh nau tâm mbên jêh ri nau khlay ngăn, toyh jêh ri rêh ni, ƀư ma n'gor Êjipt, ma Pharaôn jêh ri ma lĕ rngôch ngih păng ta năp măt hên.$b$,false),
('bunong-vn','DEU',6,23,null,$b$Jêh ri păng njŭn leo jêh hên luh bơh nây, gay ma păng njŭn jêh hên lăp jêh ri ăn ma hên n'gor păng ton jêh ma phung che he.$b$,true),
('bunong-vn','DEU',6,24,null,$b$Yêhôva ntăm jêh ma he ăn he ƀư tĭng nâm lĕ rngôch nau vay aơ, ăn klach ma Yêhôva Brah Ndu he, gay jêng ueh ma he ƀa ƀơ, gay ma păng prăp he rêh, nâm bu nar aơ.$b$,true),
('bunong-vn','DEU',6,25,null,$b$Mra jêng nau sŏng srăng ma he tơ lah he njrăng gay ƀư tĭng lĕ rngôch nau ntăm aơ ta năp Yêhôva Brah Ndu he, tĭng nâm nau păng ntăm jêh ma he.’$b$,false),
('bunong-vn','DEU',7,1,null,$b$Tơ lah Yêhôva Brah Ndu khân may njŭn khân may lăp sŏk tâm n'gor khân may dơi sŏk dơn, jêh ri păng mprơh nsot âk phung ndŭl mpôl tă bơh ta năp khân may, phung Hitit, phung Girgasit, phung Amôtit, phung Kanaan, phung Pêrisit, phung Hivit, phung Jêbisit, pơh ndŭl mpôl âk lơn jêh ri ktang lơn ma khân may,$b$,true),
('bunong-vn','DEU',7,2,null,$b$jêh ri tơ lah Yêhôva Brah Ndu mra jao khân păng ma khân may, jêh ri khân may dơi đah khân păng; dôl nây ăn khân may ƀư rai ăn lĕ khân păng; lơi ƀư nau tâm rnglăp đah khân păng ôh, jêh ri lơi tâm mpơl nau yô̆ ma khân păng ôh.$b$,false),
('bunong-vn','DEU',7,3,null,$b$Lơi tâm gŭ ur sai đah khân păng ôh, dôl ăn phung kon bu ur khân may ma phung kon bu klâu khân păng, mâu lah sŏk phung kon bu ur khân păng ma phung kon bu klâu khân may.$b$,false),
('bunong-vn','DEU',7,4,null,$b$Yor lah khân păng mra ăn phung kon bu klâu khân may cha lơi gâp, gay pah kan ma brah êng; pô ri Yêhôva mra duh nuih ji nuih ma khân may, jêh ri păng mra ƀư rai khân may ro.$b$,false),
('bunong-vn','DEU',7,5,null,$b$Ƀiă lah pô aơ ăn khân may ƀư ma khân păng; ăn khân may ƀư rlâm lơi nơng khân păng jêh ri nchah lơi jê̆ jê̆ meh khân păng, jêh ri kăl lơi rup brah Asêrim khân păng, jêh ri su lơi ma ŭnh rup khân păng kach.$b$,false),
('bunong-vn','DEU',7,6,null,$b$Yor lah khân may jêng du phung ƀon lan kloh ueh ma Yêhôva Brah Ndu khân may; Yêhôva Brah Ndu khân may săch jêh khân may gay ma khân may jêng du phung ƀon lan jêng ndơ păng, luh bơh lĕ rngôch phung ƀon lan ta neh ntu aơ.$b$,false),
('bunong-vn','DEU',7,7,null,$b$Mâu di ôh yor lah khân may jêng âk lơn ma phung ƀon lan êng Yêhôva rŏng ma khân may, jêh ri săch jêh khân may, yor lah khân may jêng djê̆ lơn ma lĕ rngôch phung ƀon lan êng;$b$,true),
('bunong-vn','DEU',7,8,null,$b$ƀiă lah yor lah Yêhôva rŏng ma khân may jêh ri djôt prăp nau ton păng ton jêh ma phung che khân may, Yêhôva njŭn jêh khân may luh đah ti brah, jêh ri tâm chuai khân may bơh ngih jêng dĭk, bơh ti Pharaôn hađăch n'gor Êjipt.$b$,false),
('bunong-vn','DEU',7,9,null,$b$Yor nây ăn khân may gĭt Yêhôva Brah Ndu khân may jêng Brah Ndu, Brah Ndu răp jăp, nơm djôt prăp nau păng tâm rnglăp jêh ri nau rŏng răp jăp ma phung rŏng ma păng jêh ri djôt prăp nau păng ntăm, ma du rbăn rnôk,$b$,false),
('bunong-vn','DEU',7,10,null,$b$jêh ri tâm rmal ta năp khân păng nơm phung tâm rmot ma păng; ma nau ƀư rai lơi khân păng; păng mâu njong ôh ƀư ma nơm tâm rmot ma păng, păng mra tâm rmal nơm nây ta năp păng.$b$,false),
('bunong-vn','DEU',7,11,null,$b$Pô ri ăn khân may njrăng ƀư tĭng nâm nau ntăm, nau vay, jêh ri nau vay ntăm gâp ntăm ma khân may nar aơ.$b$,false),
('bunong-vn','DEU',7,12,null,$b$Tơ lah khân may rkêng tôr ma nau ntăm aơ jêh ri djôt prăp jêh ri ƀư tĭng nâm nau nây, Yêhôva Brah Ndu khân may mra djôt prăp ma khân may nau tâm rnglăp jêh ri nau rŏng răp jăp păng ton jêh gay djôt prăp ma phung che khân may.$b$,true),
('bunong-vn','DEU',7,13,null,$b$Păng mra rŏng ma khân may, mât ton nau ueh uĭn ma khân may, jêh ri ƀư bĭk rơ̆ khân may; păng mra mât ton nau ueh uĭn ma phung bơh ndŭl proch khân may, jêh ri play bơh neh khân may, ba khân may, dak play kriăk ƀâu khân may, jêh ri dak play Ôlivơ khân may kon ndrôk jêh ri kon biăp khân may, tâm n'gor păng ton jêh ma phung che khân may gay ăn ma khân may.$b$,false),
('bunong-vn','DEU',7,14,null,$b$Khân may mra geh nau ueh uĭn lơn ma lĕ rngôch phung ƀon lan êng; mâu mra geh bu ur bu klâu ndrô gâng ôh ta nklang khân may, mâu lah ta nklang ndrôk biăp khân may.$b$,false),
('bunong-vn','DEU',7,15,null,$b$Yêhôva mra sŏk lơi bơh khân may lĕ rngôch nau ji; jêh ri păng mâu mra ƀư rêh ni khân may ôh ma du ntil nau ji n'gor Êjipt khân may gĭt năl jêh, ƀiă lah păng mra ntŭp nau ji nây ma lĕ rngôch phung tâm rmot khân may.$b$,false),
('bunong-vn','DEU',7,16,null,$b$Ăn khân may ƀư rai lơi lĕ rngôch ƀon lan Yêhôva Brah Ndu khân may jao jêh ma khân may, lơi ăn ma khân păng ma nau yô̆ ôh; mâu lĕ pah kan ma brah khân păng, yor lah nau nây mra jêng gâng sân ma khân may.$b$,true),
('bunong-vn','DEU',7,17,null,$b$Tơ lah khân may lah tâm nuih n'hâm khân may, ‘Phung ndŭl mpôl aơ toyh lơn ma gâp; mâm ƀư gâp dơi nsot khân păng?’$b$,false),
('bunong-vn','DEU',7,18,null,$b$Lơi klach ma khân păng ôh, ƀiă lah ăn khân may kah gĭt moh Yêhôva Brah Ndu khân may ƀư jêh ma Pharaôn jêh ri ma lĕ n'gor Êjipt,$b$,false),
('bunong-vn','DEU',7,19,null,$b$nau rlong uănh toyh măt khân may saơ jêh, nau tâm mbên, nau khlay ngăn, ti brah, jêh ri nting tur ti yơr jêh, ma nau nây Yêhôva Brah Ndu khân may njŭn leo khân may luh jêh; pô nây lĕ Yêhôva Brah Ndu khân may mra ƀư ma lĕ rngôch phung ƀon lan khân may klach.$b$,false),
('bunong-vn','DEU',7,20,null,$b$Jêh ri Yêhôva Brah Ndu khân may mra njuăl ong ta nklang khân păng kŏ phung hôm jêh ri du krap đah khân may rai yot lĕ.$b$,true),
('bunong-vn','DEU',7,21,null,$b$Lơi klach ma khân păng ôh, yor lah Yêhôva Brah Ndu khân may gŭ ta nklang khân may, Brah Ndu toyh jêh ri geh nau ring rnam.$b$,false),
('bunong-vn','DEU',7,22,null,$b$Yêhôva Brah Ndu khân may mra nsot phung ndŭl mpôl aơ tă bơh ta năp khân may ƀrư̆ ƀrư̆ ; khân may mâu dơi ƀư rai khân păng ro ôh, klach lah mpa bri jêng âk ngăn ma khân may.$b$,false),
('bunong-vn','DEU',7,23,null,$b$Ƀiă lah Yêhôva Brah Ndu khân may, mra jao khân păng ma khân may, jêh ri mra klŭp khân păng tâm nau rŭng răng toyh kŏ khân păng rai lôch lĕ.$b$,false),
('bunong-vn','DEU',7,24,null,$b$Jêh ri păng mra jao phung hađăch khân păng tâm ti khân may, jêh ri khân may mra ƀư roh amoh khân păng tâm dâng trôk; mâu geh du huê mra dơi gŭ tâm rdâng đah khân may ôh, kŏ khân may ƀư rai lĕ khân păng.$b$,false),
('bunong-vn','DEU',7,25,null,$b$Ăn khân may su ma ŭnh rup brah khân păng trah; lơi kơnh ôh ma prăk mâu lah mah bu mblum rup nây, mâu lah sŏk ma khân may nơm, klach lah khân may tŭp tâm dăk sân yor ndơ nây; yor lah ndơ nây jêng ndơ Yêhôva tâm rmot ngăn.$b$,true),
('bunong-vn','DEU',7,26,null,$b$Lơi djôt nglăp tâm ngih khân may ôh, ndơ gâp tâm rmot, jêh ri geh nau rtăp rak nâm bu ndơ nây; ăn khân may tâm rmot ngăn jêh ri ji nuih ma ndơ nây; yor lah ndơ jêng nây jêng ndơ gâp rtăp rak jêh.$b$,false),
('bunong-vn','DEU',8,1,null,$b$Lĕ rngôch nau ntăm gâp ăn jêh ma khân may nar aơ ăn khân may njrăng ma nau ƀư tĭng ndô̆ nau nây, gay ma khân may dơi gŭ rêh jêh ri jêng bĭk rơ̆ , jêh ri lăp sŏk pha n'gor Yêhôva ton jêh gay ăn ma che khân may.$b$,true),
('bunong-vn','DEU',8,2,null,$b$Ăn khân may kah gĭt ma lĕ rngôch trong Yêhôva Brah Ndu khân may njŭn leo khân may dôl tâm jât năm aơ tâm bri rdah, gay ma tông bâr khân may, rlong uănh khân may gay gĭt moh geh tâm nuih n'hâm khân may, gĭt lah khân may mra djôt prăp nau păng ntăm mâu lah mâu.$b$,true),
('bunong-vn','DEU',8,3,null,$b$Păng tâm tông khân may jêh ri ăn khân may ji ngot jêh ri siăm khân may ma mana khân may mâu mâp gĭt năl ôh, mâu lĕ phung che khân may gĭt năl; gay păng dơi ăn khân may gĭt bunuyh mâu gŭ rêh knŏng yor sa piăng let ôh, ƀiă lah bunuyh gŭ rêh yor lĕ rngôch nau ngơi luh bơh mbung Yêhôva.$b$,false),
('bunong-vn','DEU',8,4,null,$b$Bok ao khân may mâu geh mŭnh klôt ôh ta săk jăn khân may, jêh ri jâng khân may mâu môr ôh dôl puăn jât năm aơ.$b$,false),
('bunong-vn','DEU',8,5,null,$b$Ăn khân may gĭt tâm nuih n'hâm khân may, tâm ban ma du huê bu klâu nchroh kon bu klâu păng, pô nây lĕ Yêhôva Brah Ndu khân may nchroh khân may.$b$,false),
('bunong-vn','DEU',8,6,null,$b$Pô ri ăn khân djôt prăp nau ntăm bơh Yêhôva Brah Ndu khân may ma nau hăn tâm trong păng jêh ri ma nau klach yơk mbah ma păng.$b$,true),
('bunong-vn','DEU',8,7,null,$b$Yor lah Yêhôva Brah Ndu khân may gŭ njŭn khân may lăp tâm n'gor ueh, n'gor geh âk n'hor dak, tu dak hoch tâm rlŭng jêh ri mbon,$b$,false),
('bunong-vn','DEU',8,8,null,$b$n'gor geh ba ƀlê jêh ri ba ôrgơ, tơm play kriăk ƀâu, tơm play rvi, jêh ri play pom gra nat, n'gor geh tơm play Ôlivơ jêh ri dak sŭt,$b$,false),
('bunong-vn','DEU',8,9,null,$b$n'gor khân may mra sa piăng let mâu pưt ôh, tâm n'gor nây khân may mâu mra pưt du ntil ndơ ôh, n'gor geh lŭ jêng loih, jêh ri tă bơh mbon khân may dơi nau sŏk kông.$b$,false),
('bunong-vn','DEU',8,10,null,$b$Khân may mra sông sa jêh ri hơm, jêh ri khân may mra tâm rnê ma Yêhôva Brah Ndu khân may yor n'gor ueh păng ăn jêh ma khân may.$b$,false),
('bunong-vn','DEU',8,11,null,$b$Njrăng hom klach lah khân may chuêl Yêhôva Brah Ndu khân may ma nau khân may mâu djôt prăp nau păng ntăm, nau brah păng, jêh ri nau vay păng gâp ntăm ma khân may nar aơ,$b$,true),
('bunong-vn','DEU',8,12,null,$b$klach lah tơ lah khân may sông sa jêh ri hơm, rdâk jêh âk play ngih ueh jêh ri gŭ tâm khân păng,$b$,false),
('bunong-vn','DEU',8,13,null,$b$jêh ri tơ lah ndrôk jêh ri biăp khân may jêng bĭk rơ̆ , jêh ri prăk jêh ri mah khân may hao jêng âk,$b$,false),
('bunong-vn','DEU',8,14,null,$b$dôl nây nuih n'hâm khân may sưr, jêh ri khân may chuêl lơi Yêhôva Brah Ndu khân may, nơm njŭn ngluh khân may bơh n'gor Êjipt bơh ngih jêng dĭk,$b$,false),
('bunong-vn','DEU',8,15,null,$b$nơm njŭn jêh khân may tâm bri rdah toyh jêh ri blach blang, geh bêh ŭnh jêh ri ndŭr vơng, jêh ri neh sơh mâu geh dak ôh, nơm ƀư lah an dak ma khân may bơh lŭ dăng,$b$,false),
('bunong-vn','DEU',8,16,null,$b$nơm siăm khân may tâm bri rdah ma mana phung che khân may mâu mâp gĭt năl ôh, gay ma pa dơi tâm tông bâr khân may jêh ri long uănh khân may, gay ma ƀư ueh ma khân may ta nglĕ dŭt.$b$,false),
('bunong-vn','DEU',8,17,null,$b$Njrăng hom klach khân may lah tâm nuih n'hâm khân may, ‘Nau brah gâp jêh ri nau ktang ti gâp ăn geh jêh nau ndrŏng aơ.’$b$,false),
('bunong-vn','DEU',8,18,null,$b$Ăn khân may kah gĭt ma Yêhôva Brah Ndu khân may, yor lah păng yơh nơm ăn nau dơi geh nau ndrŏng; gay ma păng dơi ăn nanê̆ nau tâm rnglăp păng ton jêh ma phung che khân may, nâm bu nar aơ.$b$,false),
('bunong-vn','DEU',8,19,null,$b$Jêh ri tơ lah khân may chuêl Yêhôva Brah Ndu khân may jêh ri kơt tĭng brah êng pah kan ma khân păng jêh ri yơk mbah ma khân păng, gâp mbơh hâu ngăn nar aơ, nanê̆ khân may mra rai lôch,$b$,true),
('bunong-vn','DEU',8,20,null,$b$Khân may mra rai lôch nâm bu phung mpôl băl Yêhôva ƀư rai lôch ta năp khân may, yor lah khân may mâu mâp tông bâr Yêhôva Brah Ndu khân may ôh.$b$,false),
('bunong-vn','DEU',9,1,null,$b$Gŭ iăt hom, Ơ phung Israel, nar aơ khân may mra rgăn dak krong Yurdan, gay lăp nsot phung ndŭl mpôl toyh lơn jêh ri ktang lơn ma khân may, âk rplay ƀon toyh jêh ri geh pêr mbâl hao tât ta trôk,$b$,true),
('bunong-vn','DEU',9,2,null,$b$du phung ƀon lan toyh jêh ri prêh juat, phung kon bu klâu Y-Anak, phung khân may tăng jêh bu nkoch bri, ‘Mbu dơi gŭ râng ta năp măt phung kon bu klâu Y-Anak?’$b$,false),
('bunong-vn','DEU',9,3,null,$b$Pô ri ăn khân may gĭt nar aơ, nơm rgăn lor ma khân may jêng Yêhôva Brah Ndu khân may tâm ban ma ŭnh dôl hit; păng mra ƀư phung nây jêh ri nglăp phung nây ma khân may; pô ri khân may nsot khân păng jêh ri ăn khân păng rai lôch gơnh, tĭng nâm Yêhôva ton jêh ma khân may.$b$,false),
('bunong-vn','DEU',9,4,null,$b$Lơi lah ôh tâm nuih n'hâm khân may tơ lah jêh Yêhôva Brah Ndu khân may nsot khân păng ta năp khân may, ‘Yor nau sŏng srăng gâp yơh Yêhôva njŭn leo gâp lăp jêh sŏk n'gor aơ: Ƀiă lah yor nau tih ƀai phung ndŭl mpôl aơ yơh Yêhôva hôm nsot khân may bơh ta năp khân may.$b$,true),
('bunong-vn','DEU',9,5,null,$b$Mâu tăp ôh yor nau sŏng srăng khân may mâu lah nau sŏng srăng nuih n'hâm khân may, khân may mra lăp sŏk pha n'gor khân păng; ƀiă lah yor nau ƀai phung ndŭl mpôl aơ Yêhôva Brah Ndu khân may hôm nsot khân may bơh ta năp khân may, jêh ri gay ma păng dơi ƀư nanê̆ nau Yêhôva ton jêh ma phung che khân may, ma Y-Abraham, ma Y-Isăk, jêh ri ma Y-Yakôb.$b$,false),
('bunong-vn','DEU',9,6,null,$b$Pô ri ăn khân may gĭt, mâu di ôh yor nau sŏng srăng khân may Yêhôva Brah Ndu khân may ăn khân may sŏk pha n'gor bri ueh aơ; yor lah khân may jêng du phung ƀon lan dăng bôk.$b$,false),
('bunong-vn','DEU',9,7,null,$b$Ăn khân may kah gĭt jêh ri lơi ta chuêl ôh nau khân may nsônh jêh nuih n'hâm Yêhôva Brah Ndu khân may tâm bri rdah; bơh nar khân may luh bơh n'gor Êjipt kŏ khân may tât ta ntŭk aơ, khân may jêng phung tâm rdâng jêh đah Yêhôva.$b$,true),
('bunong-vn','DEU',9,8,null,$b$Nđâp ma ta yôk Hôrep khân may nsônh nau ji nuih Yêhôva, jêh ri Yêhôva ji nuih ma khân may kŏ păng mĭn ŭch ƀư rai khân may.$b$,false),
('bunong-vn','DEU',9,9,null,$b$Tơ lah gâp hao klơ yôk gay sŏk kađar lŭ, kađar nau tâm rnglăp Yêhôva ƀư jêh đah khân may, gâp gŭ ta klơ yôk puăn jât nar jêh ri puăn jât măng; gâp mâu sa piăng let ôh, mâu lĕ nhêt dak.$b$,true),
('bunong-vn','DEU',9,10,null,$b$Jêh ri Yêhôva ăn ma gâp bar mpơng kađar lŭ nglau ti Brah Ndu nơm chih jêh; jêh ri geh nau chih ta khân păng lĕ rngôch nau Yêhôva ngơi jêh ma khân may ta klơ yôk tâm nklang ŭnh ta nar tâm rƀŭn.$b$,false),
('bunong-vn','DEU',9,11,null,$b$Tăch puăn jât nar jêh ri puăn jât măng Yêhôva ăn ma gâp bar mpơng kađar lŭ, kađar nau tâm rnglăp.$b$,false),
('bunong-vn','DEU',9,12,null,$b$Dôl nây Yêhôva lah ma gâp, ‘Dâk hom may; jŭr gơnh hom bơh ntŭk aơ, yor lah phung ƀon lan may njŭn jêh luh bơh n'gor Êjipt ƀư jêh nau tih mhĭk; khân păng teng gơnh ngăn bơh trong gâp ntăm jêh ma khân păng; khân păng drep chiăr jêh ma khân păng nơm du rup brah.’$b$,true),
('bunong-vn','DEU',9,13,null,$b$Rmeh ma nây Yêhôva lah ma gâp: ‘Gâp saơ jêh phung ƀon lan aơ, aơ jêng du phung ƀon lan dăng bôk.$b$,false),
('bunong-vn','DEU',9,14,null,$b$Lơi kân gâp ôh, gay ma gâp dơi ƀư rai khân păng jêh ri lâm lơi amoh khân păng bơh tâm dâng trôk, jêh ri gâp mra njêng du ndŭl mpôl ktang lơn jêh ri toyh lơn ma khân păng.$b$,false),
('bunong-vn','DEU',9,15,null,$b$Jêh ri gâp plơ̆ jêh ri jŭr bơh yôk dôl ŭnh sa yôk; jêh ri gâp djôt bar pŏk kađar nau tâm rnglăp tâm bar đah ti gâp.$b$,false),
('bunong-vn','DEU',9,16,null,$b$Gâp uănh jêh ri aơ, khân may ƀư tih jêh đah Yêhôva Brah Ndu khân may; jêh ri khân may tŏ chiăr jêh ma khân may nơm du mlâm kon ndrôk, khân may gơnh nkhah du bơh trong Yêhôva ntăm jêh ma khân may.$b$,false),
('bunong-vn','DEU',9,17,null,$b$Pô ri gâp djôt bar pŏk kađar lŭ nây jêh ri klŭp tă bơh bar đah ti gâp, jêh ri ƀư chah lơi ta năp măt khân may.$b$,false),
('bunong-vn','DEU',9,18,null,$b$Jêh ri gâp păn ta năp Yêhôva tâm ban ma tal lor puăn jât nar jêh ri puăn jât măng; gâp mâu mâp sa piăng let ôh, mâu lĕ nhêt dak, yor lĕ nau tih khân may ƀư jêh dôl ƀư nau mhĭk ta năp măt Yêhôva nsônh nau păng ji nuih.$b$,true),
('bunong-vn','DEU',9,19,null,$b$Yor lah gâp klach ma nau Yêhôva ji nuih jêh ri ji nuih ngăn ma khân may, kŏ păng ŭch ƀư rai khân may. Ƀiă lah dôl nây lĕ Yêhôva iăt nau gâp.$b$,false),
('bunong-vn','DEU',9,20,null,$b$Jêh ri Yêhôva ji nuih ngăn ma Y-Arôn kŏ ŭch ƀư rai păng; jêh ri gâp mbơh sơm ma Y-Arôn tâm ban lĕ dôl nây.$b$,false),
('bunong-vn','DEU',9,21,null,$b$Jêh ri gâp djôt mpa tih, kon ndrôk khân may ƀư jêh, du ndơ nây ma ŭnh, nchah lơi păng, kĭn lơi kŏ se kŏ jêng nâm bu ndruyh; jêh ri gâp mƀăr ndruyh nây tâm n'hor dak hoch jŭr tă bơh yôk.$b$,false),
('bunong-vn','DEU',9,22,null,$b$Nđâp ma Tabêra tâm ban lĕ, ta Masa, jêh ri ta Kibrôt Hatava, khân may nsônh nau Yêhôva ji nuih.$b$,true),
('bunong-vn','DEU',9,23,null,$b$Jêh ri tơ lah Yêhôva njuăl khân may bơh Kadês Barnê, lah: ‘Hao hom jêh ri sŏk n'gor gâp ăn jêh ma khân may.’ Dôl nây khân may tâm rdâng đah nau Yêhôva Brah Ndu khân may ntăm, jêh ri mâu chroh ma păng jêh ri mâu tông bâr păng ôh.$b$,false),
('bunong-vn','DEU',9,24,null,$b$Khân may jêng phung tâm rdâng đah Yêhôva ntơm bơh nar gâp gĭt năl khân may.$b$,false),
('bunong-vn','DEU',9,25,null,$b$Pô ri gâp păn ta năp Yêhôva puăn jât nar jêh ri puăn jât măng nây, yor lah Yêhôva lah jêh păng mra ƀư rai khân may.$b$,true),
('bunong-vn','DEU',9,26,null,$b$Jêh ri gâp mbơh sơm ma Yêhôva: ‘Ơ Kôranh Brah, Brah Ndu, lơi ƀư rai ôh phung ƀon lan may jêh ri drăp krâm may, phung may tâm chuai jêh ma nau toyh may, phung may njŭn jêh luh bơh n'gor Êjipt ma ti brah.$b$,false),
('bunong-vn','DEU',9,27,null,$b$Kah gĭt hom ma phung oh mon may Y-Abraham, Y-Isăk jêh ri Y-Yakôb, lơi chrê ôh ma nau dăng bôk phung ƀon lan aơ, ma nau ƀai, jêh ri ma nau tih khân păng,$b$,false),
('bunong-vn','DEU',9,28,null,$b$klach lah n'gor may ăn hên luh jêh mra lah: “Yor lah Yêhôva mâu dơi ôh njŭn khân păng lăp tâm n'gor păng ton jêh ma khân păng, jêh ri yor lah păng tâm rmot ma khân păng njŭn khân păng luh gay ma nkhĭt khân păng tâm bri rdah.”$b$,false),
('bunong-vn','DEU',9,29,null,$b$Yor lah khân păng jêng phung ƀon lan may jêh ri drăp ndơn may, phung may njŭn ngluh jêh ma nau brah toyh jêh ri ma nting tur yơr jêh.’ ”$b$,false),
('bunong-vn','DEU',10,1,null,$b$Dôl nây Yêhôva lah ma gâp: ‘Ăn may trah bar plơp lŭ nâm bu ndơ lor, jêh ri hao văch ta gâp ta klơ yôk, jêh ri ƀư du mlâm hip si.$b$,true),
('bunong-vn','DEU',10,2,null,$b$Gâp mra chih ta plơp lŭ nây nau ngơi geh ta plơp lŭ tal lor may nchah lơi jêh, jêh ri ăn may prăp păng tâm hip.’$b$,false),
('bunong-vn','DEU',10,3,null,$b$Pô ri gâp ƀư hip ma si akasi jêh ri trah bar plơp lŭ nâm bu ndơ lor, jêh ri hao yôk djôt bar plơp nây.$b$,false),
('bunong-vn','DEU',10,4,null,$b$Păng chih ta plơp nây nâm bu nau chih tal lor, jât ntil nau ntăm Yêhôva ngơi jêh ma khân may ta klơ yôk bơh ta nklang ŭnh ta nar tâm rƀŭn; jêh ri Yêhôva ăn plơp lŭ nây ma gâp.$b$,false),
('bunong-vn','DEU',10,5,null,$b$Jêh ri gâp sĭt jŭr bơh yôk jêh ri dơm plơp nây tâm hip gâp ƀư jêh; jêh ri ta nây khân păng gŭ, tĭng nâm Yêhôva ntăm jêh ma gâp.$b$,true),
('bunong-vn','DEU',10,6,null,$b$Phung ƀon lan Israel hăn bơh Bêrôt Bênêja kan tât ta Môsera. Ta nây Y-Arôn khĭt jêh, jêh ri bu tâp păng, jêh ri kon bu klâu păng Y-Êlêasar djôt kan kôranh ƀư brah ntrok ntŭk păng.$b$,true),
('bunong-vn','DEU',10,7,null,$b$Tă bơh ntŭk nây khân păng hăn ta Gugôda, jêh ri tă bơh Gugôda tât ta Jobata, n'gor geh âk n'hor dak.$b$,true),
('bunong-vn','DEU',10,8,null,$b$Dôl nây Yêhôva prăp an ndŭl mpôl Lêvi tung hip nau tâm rnglăp Yêhôva gŭ ta năp Yêhôva, gay pah kan ma păng jêh ri mât ton tâm amoh păng tât ta nar aơ.$b$,false),
('bunong-vn','DEU',10,9,null,$b$Yor nây phung Lêvi mâu geh du kô̆ mâu lah drăp ndơn ndrel ma phung oh nâu khân păng ôh; Yêhôva jêng drăp ndơn khân păng, tĭng nâm Yêhôva Brah Ndu khân may lah ma khân păng.$b$,false),
('bunong-vn','DEU',10,10,null,$b$Gâp gŭ ta klơ yôk nâm bu sa ơm puăn jât nar jêh ri puăn jât măng, jêh ri Yêhôva iăt gâp nôk nây lĕ; Yêhôva mâu ŭch ƀư rai khân may ôh.$b$,true),
('bunong-vn','DEU',10,11,null,$b$Yêhôva lah ma gâp: ‘Dâk hom, hăn ta năp phung ƀon lan gay ma khân păng dơi lăp sŏk pha n'gor gâp ton jêh ma phung che khân păng gay ăn ma khân păng.’$b$,false),
('bunong-vn','DEU',10,12,null,$b$Aƀaơ aơ, Ơ phung Israel, moh nau Yêhôva Brah Ndu khân may ntăm ăn khân may ƀư, knŏng klach yơk ma Yêhôva Brah Ndu khân may, hăn tâm lĕ rngôch trong păng, rŏng ma păng, jêh ri pah kan ma Yêhôva Brah Ndu khân may ma lĕ nuih n'hâm jêh ri ma lĕ huêng khân may,$b$,false),
('bunong-vn','DEU',10,13,null,$b$jêh ri djôt prăp nau ntăm jêh ri nau vay Yêhôva gâp ntăm ma khân may nar aơ, jêng nau ueh ma khân may.$b$,false),
('bunong-vn','DEU',10,14,null,$b$Aơ, trôk jêh ri trôk ma lĕ rngôch trôk, neh ntu jêh ri ndrel ma lĕ rngôch mpa tâm păng jêng ndơ Yêhôva Brah Ndu khân may.$b$,false),
('bunong-vn','DEU',10,15,null,$b$Ƀiă lah Yêhôva ăn nuih n'hâm păng rŏng ma phung che khân may jêh ri săch phung kon sau khân păng pa kơi khân păng, khân may klơ lơn ma lĕ rngôch phung ƀon lan êng, nâm bu nar aơ.$b$,false),
('bunong-vn','DEU',10,16,null,$b$Pô ri ăn khân may koh ntâu nuih n'hâm khân may, jêh ri lơi hôm jêng dăng bôk ôh.$b$,false),
('bunong-vn','DEU',10,17,null,$b$Yor lah Yêhôva Brah Ndu khân may jêng Brah Ndu ma phung brah jêh ri Kôranh Brah ma phung Kôranh, Brah Ndu nơm toyh, nơm brah, jêh ri nơm ƀư rnam (krưp), nơm mâu uănh bunuyh êng êng ôh, jêh ri mâu dơn ôh drăp tâm blŏl.$b$,false),
('bunong-vn','DEU',10,18,null,$b$Păng ƀư nau di ma kon đơi mbơ̆ jêh ri ma bu ur ndrô, rŏng ma bunuyh gŭ jưh ƀât lât, ăn ma bu ndơ sông sa jêh ri bok ao.$b$,false),
('bunong-vn','DEU',10,19,null,$b$Yor ri ăn khân may rŏng ma phung gŭ jưh ƀât lât; yor lah khân may jêng phung gŭ jưh jêh tâm n'gor Êjipt.$b$,false),
('bunong-vn','DEU',10,20,null,$b$Ăn khân may klach yơk ma Yêhôva Brah Ndu khân may; ăn khân may pah kan ma păng jêh ri gŭ êp păng, jêh ri khân may mra ton ma amoh păng.$b$,false),
('bunong-vn','DEU',10,21,null,$b$Yor păng bu tâm rnê khân may, păng jêng Brah Ndu khân may, nơm ƀư jêh ma khân may mpa toyh jêh ri ƀư rnam aơ măt khân may saơ jêh.$b$,true),
('bunong-vn','DEU',10,22,null,$b$Phung che khân may jŭr ta n'gor Êjipt đah pơh jât nuyh; jêh ri aƀaơ aơ Yêhôva Brah Ndu khân may ƀư bĭk jêh khân may jêng âk nâm bu mănh tâm trôk.$b$,false),
('bunong-vn','DEU',11,1,null,$b$Pô ri ăn khân may rŏng ma Yêhôva Brah Ndu khân may jêh ri djôt prăp ƀa ƀơ kan păng, nau vay păng, nau brah păng ăn, jêh ri nau păng ntăm.$b$,true),
('bunong-vn','DEU',11,2,null,$b$Ăn khân may mĭn nar aơ, yor lah gâp mâu gŭ ngơi ôh ma phung kon khân may mâu mâp gĭt năl mâu lah saơ Brah Ndu khân may nau rnam păng, nau toyh păng, ti brah păng jêh ri nting tur păng yơr jêh,$b$,false),
('bunong-vn','DEU',11,3,null,$b$mpa păng tâm mbên jêh ri kan păng ƀư jêh ta n'gor Êjipt ma Pharaôn hađăch n'gor Êjipt jêh ri ma lĕ n'gor păng;$b$,false),
('bunong-vn','DEU',11,4,null,$b$jêh ri nau păng ƀư jêh ma phung ta han Êjipt, ma seh jêh ri ma ndeh seh khân păng, nau păng ăn Dak Mƀŭt Chăng lip khân păng, dôl khân păng tĭng khân may, jêh ri nau Yêhôva ƀư rai lơi khân păng tât ta nar aơ;$b$,false),
('bunong-vn','DEU',11,5,null,$b$nau păng ƀư jêh ma khân may tâm bri rdah kŏ khân may tât ta ntŭk aơ;$b$,false),
('bunong-vn','DEU',11,6,null,$b$nau păng ƀư jêh ma Y-Dathan jêh ri ma Y-Abiram phung kon bu klâu Y-Êliap, sau Y-Ruben nau neh hă trôm mbung păng jêh ri rvăn khân păng, ndrel ma bunuyh tâm ngih khân păng, ngih bok khân păng, jêh ri lĕ rngôch mpa rêh tĭng khân păng ta nklang lĕ rngôch phung Israel;$b$,false),
('bunong-vn','DEU',11,7,null,$b$yor lah măt khân may nơm saơ jêh lĕ rngôch kan toyh Yêhôva ƀư jêh.$b$,false),
('bunong-vn','DEU',11,8,null,$b$Pô ri ăn khân may djôt prăp lĕ nau ntăm gâp ăn ma khân may nar aơ, gay ma khân may dơi jêng ktang, jêh ri lăp sŏk pha n'gor khân may mra rgăn ŭch sŏk,$b$,true),
('bunong-vn','DEU',11,9,null,$b$jêh ri gay ma khân păng dơi gŭ rêh jŏ tâm n'gor Yêhôva ton jêh gay ăn ma phung che khân may jêh ri ma phung kon sau khân păng, n'gor geh ndơ sông sa nhêt rmeh ler.$b$,false),
('bunong-vn','DEU',11,10,null,$b$Yor lah n'gor khân may mra lăp sŏk pha nây mâu geh nâm bu n'gor Êjipt ôh ntŭk khân may luh jêh, ntŭk khân may srih jêh ntil khân may jêh ri djrah dak ma jâng khân may, nâm bu du lôk đang trau.$b$,false),
('bunong-vn','DEU',11,11,null,$b$Ƀiă lah n'gor khân may mra rgăn sŏk pha jêng n'gor klơ dor yôk jêh ri rlŭng, n'gor nhêt dak mih bơh trôk,$b$,false),
('bunong-vn','DEU',11,12,null,$b$n'gor Yêhôva Brah Ndu khân may mât mray, n'gor măt Yêhôva Brah Ndu khân may uănh ƀa ƀơ bơh ntơm sa ơm tât lôch năm.$b$,false),
('bunong-vn','DEU',11,13,null,$b$Tơ lah khân may tông nau gâp ntăm gâp ăn ma khân may nar aơ, rŏng ma Yêhôva Brah Ndu khân may, jêh ri pah kan ma păng ma lĕ nuih n'hâm jêh ri ma lĕ huêng khân may,$b$,true),
('bunong-vn','DEU',11,14,null,$b$Păng mra ăn ma n'gor khân may mih di yăn păng, mih bôk rah jêh ri mih nglĕ dŭt, gay ma khân may dơi bun prăp ba, dak play kriăk ƀâu, jêh ri dak play Ôlivơ khân may.$b$,false),
('bunong-vn','DEU',11,15,null,$b$Păng mra ăn gơ̆ tâm mir khân may prăp ma mpô mpa rong khân may; jêh ri khân may mra sông sa jêh ri hơm.$b$,false),
('bunong-vn','DEU',11,16,null,$b$Njrăng hom klach lah nuih n'hâm khân may tŭp tâm nau ndơm jêh ri khân may nklah du pah kan ma phung brah êng jêh ri mbah yơk ma khân păng,$b$,false),
('bunong-vn','DEU',11,17,null,$b$Jêh ri Yêhôva duh nuih ji nuih ma khân may jêh ri păng chăng mpông trôk, jêh ri mâu geh dak mih ôh, neh mâu ăn play ôh jêh ri khân may rai lôch gơnh bơh n'gor ueh Yêhôva ăn ma khân may.$b$,false),
('bunong-vn','DEU',11,18,null,$b$Pô ri ăn khân may prăp nau ngơi gâp aơ tâm nuih n'hâm khân may jêh ri tâm huêng khân may; ăn khân may kât păng jêng mpa tâm mbên ta ti khân may, jêh ri khân păng mra jêng mpa kât ta ndăr kleng vah vang măt khân may.$b$,true),
('bunong-vn','DEU',11,19,null,$b$Ăn khân may nti nau aơ ma phung kon khân may, gŭ ngơi ma nau aơ dôl khân may gŭ tâm ngih khân may, dôl khân may hăn rŏ trong, dôl khân may lâng săk, jêh ri dôl khân may dâk.$b$,false),
('bunong-vn','DEU',11,20,null,$b$Chih nau nây ta mbong mpông ngih ay may jêh ri ta mpông pêr,$b$,true),
('bunong-vn','DEU',11,21,null,$b$gay ma ay may jêh ri kon sau ay may dơi gŭ jŏ năm tâm bri Brah Ndu hŏ ton jêh ma u che ay may.$b$,false),
('bunong-vn','DEU',11,22,null,$b$Yor lah tơ lah khân may mra njrăng ƀư tĭng ndô̆ lĕ rngôch nau ntăm aơ gâp ntăm ma khân may ƀư, rŏng ma Yêhôva Brah Ndu khân may, hăn tĭng ndô̆ lĕ rngôch trong păng, jêh ri gŭ tâm rnglăp đah păng,$b$,false),
('bunong-vn','DEU',11,23,null,$b$dôl nây Yêhôva mra nsot bơh ta năp khân may lĕ rngôch phung ndŭl mpôl aơ, jêh ri khân may mra nsot phung ndŭl mpôl toyh lơn jêh ri ktang lơn ma khân may.$b$,false),
('bunong-vn','DEU',11,24,null,$b$Lĕ rngôch ntŭk mpang jâng khân may jot mra jêng ndơ khân may; n'har bri khân may mra ntơm bơh bri rdah tât ta n'gor Liban, jêh ri bơh dak krong Dak Krong Ơphrat tât ta dak mƀŭt pa dâng.$b$,false),
('bunong-vn','DEU',11,25,null,$b$Mâu geh du huê mra dơi tâm rdâng đah khân may ôh; Yêhôva Brah Ndu khân may mra dơm nau bu klach ma khân may jêh ri na bu rnam ma khân may tâm lĕ n'gor khân may mra jot, tĭng nâm păng ton jêh ma khân may.$b$,false),
('bunong-vn','DEU',11,26,null,$b$Aơ nar aơ gâp dơm ta năp khân may nau mât ton jêh ri nau rtăp rak:$b$,true),
('bunong-vn','DEU',11,27,null,$b$Nau mât ton nau ntăm Yêhôva Brah Ndu khân may gâp ăn jêh ma khân may nar aơ,$b$,false),
('bunong-vn','DEU',11,28,null,$b$jêh ri nau rtăp rak: Tơ lah khân may tông ma nau ntăm Yêhôva Brah Ndu khân may, ƀiă lah khân may teng tă bơh trong gâp ntăm ma khân may nar aơ, gay tĭng ndô̆ brah êng khân may mâu mâp gĭt năl ôh.$b$,false),
('bunong-vn','DEU',11,29,null,$b$Jêh ri tơ lah Yêhôva Brah Ndu khân may njŭn khân may lăp tâm n'gor khân may mra lăp sŏk pha, ăn khân may dơm nau mât ton ta klơ yôk Gêrasim jêh ri nau rtăp rak ta yôk Êbal.$b$,true),
('bunong-vn','DEU',11,30,null,$b$Mâu di hĕ khân păng gŭ đah tê̆ dak krong Yurdan pa dâng trong mơ pa nar nhâp tâm n'gor phung Kanaan gŭ ta rlŭng Arabah, ta năp ƀon Gilgal dăch tơm si têrêbin Môrê?$b$,false),
('bunong-vn','DEU',11,31,null,$b$Yor lah khân may mra rgăn dak krong Yurdan gay lăp sŏk pha n'gor Yêhôva Brah Ndu khân may ăn ma khân may; jêh ri tơ lah khân may geh n'gor nây jêh ri gŭ tâm păng,$b$,false),
('bunong-vn','DEU',11,32,null,$b$ăn khân may njrăng ƀư tĭng ndô̆ lĕ rngôch nau vay jêh ri nau ntăm gâp tâm mpơl ta năp khân may nar aơ.$b$,false),
('bunong-vn','DEU',12,1,null,$b$Aơ nau vay jêh ri nau ntăm khân may mra njrăng ƀư tĭng ndô̆ tâm n'gor Yêhôva ndŭl mpôl phung che khân may ăn jêh jêng ndơ khân may lĕ rngôch nar khân may gŭ rêh ta klơ neh ntu.$b$,true),
('bunong-vn','DEU',12,2,null,$b$Ăn khân may ƀư rai ngăn lĕ rngôch ntŭk phung ndŭl mpôl khân may mra nsot pah kan jêh ma brah khân păng, ta yôk prêh jêh ri ta klơ mbon jêh ri tâm dâng ăp tơm si ndrêh.$b$,true),
('bunong-vn','DEU',12,3,null,$b$Ăn khân may ƀư rlâm lơi nơng khân păng, jêh ri nchah jê̆ jê̆ meh khân păng jêh ri su ma ŭnh rup brah Asêrim khân păng, ăn khân may kăl lơi rup brah khân păng trah, jêh ri ƀư rai amoh khân păng bơh ntŭk nây.$b$,false),
('bunong-vn','DEU',12,4,null,$b$Lơi ƀư pô nây ôh ma Yêhôva Brah Ndu khân may.$b$,true),
('bunong-vn','DEU',12,5,null,$b$Ƀiă lah ăn khân may joi ntŭk Yêhôva Brah Ndu mra săch ta nklang lĕ rngôch ndŭl mpôl khân may gay dơm amoh păng jêh ri ƀư ntŭk păng gŭ ta nây; ta ntŭk nây yơk khân may mra hăn,$b$,false),
('bunong-vn','DEU',12,6,null,$b$jêh ri ta nây yơh khân may mra njŭn khân may nhhơr gŭch, mpa khân may ƀư brah, mpa du kô̆ tâm jât, jêh ri mpa khân may nhhơr, mpa khân may nhhơr ƀư nanê̆ nau ton, mpa khân may nhhơr ma nuih n'hâm rŏng, jêh ri kon ndrôk jêh ri kon biăp khân may bôk rah.$b$,false),
('bunong-vn','DEU',12,7,null,$b$Ta nây yơh kon biăp khân may bôk rah. Ta nây yơh khân may mra sông sa ta năp Yêhôva Brah Ndu khân may, jêh ri khân may mra hâk răm, khân may jêh ri phung tâm ngih khân may, tâm lĕ rngôch nau khân may ƀư, Yêhôva Brah Ndu khân may ăn jêh nau ueh uĭn ma khân may.$b$,false),
('bunong-vn','DEU',12,8,null,$b$Lơi ƀư ôh nâm bu lĕ rngôch nau he gŭ ƀư ta aơ nar aơ, ăp nơm ƀư tĭng nâm nau păng nơm mĭn ueh.$b$,true),
('bunong-vn','DEU',12,9,null,$b$Yor lah khân may ê tât ôh ma nau rlu jêh ri ma drăp ndơn Yêhôva Brah Ndu khân may ăn ma khân may.$b$,false),
('bunong-vn','DEU',12,10,null,$b$Ƀiă lah tơ lah khân may rgăn dak krong Yurdan jêh ri ăn khân may dơn, jêh ri tơ lah păng ăn ma khân may, pô ri khân may gŭ tâm nau mpăn rlêk,$b$,false),
('bunong-vn','DEU',12,11,null,$b$Pô ri ta ntŭk Yêhôva Brah Ndu khân may mra săch an amoh gŭ, ta nây yơh khân may njŭn lĕ rngôch mpa gâp ntăm ma khân may, mpa khân may nhhơr gŭch, mpa khân may ƀư brah, mpa du kô̆ tâm jât khân may jêh ri mpa khân may nhhơr, jêh ri lĕ rngôch mpa nhhơr ăn ngăn nau khân may ton ma Yêhôva.$b$,false),
('bunong-vn','DEU',12,12,null,$b$Khân may mra maak ta năp Yêhôva Brah Ndu khân may, khân may, phung kon bu klâu khân may, jêh ri phung kon bu ur khân may, phung oh mon bu klâu khân may, phung oh mon bu ur khân may, jêh ri phung Lêvi gŭ tâm ƀon khân may, yor lah khân păng mâu geh kô̆ mâu lah drăp ndơn ndrel ma khân may ôh.$b$,false),
('bunong-vn','DEU',12,13,null,$b$Njrăng hom, lơi nhhơr ôh mpa khân may nhhơr gŭch tâm lĕ rngôch ntŭk khân may saơ.$b$,false),
('bunong-vn','DEU',12,14,null,$b$Ƀiă lah ăn khân may nhhơr mpa nhhơr gŭch ta ntŭk Yêhôva mra săch tâm du ndŭl mpôl khân may, jêh ri ta nây khân may mra ƀư lĕ nau gâp gŭ ntăm ma khân may.$b$,false),
('bunong-vn','DEU',12,15,null,$b$Ƀiă lah tâm ƀon nơm khân may dơi sreh sa mpô mpa tĭng nâm khân may ŭch, tĭng nâm nau ueh uĭn Yêhôva Brah Ndu khân may ăn jêh ma khân may; nơm ƀơ̆ jêh ri nơm kloh dơi sa ndơ nây, tâm ban ma bu sa nkrŏng jêh ri jun.$b$,true),
('bunong-vn','DEU',12,16,null,$b$Knŏng khân may mâu dơi sa mham ôh; ăn khân may nkhŭt lơi păng ta neh nâm bu dak.$b$,false),
('bunong-vn','DEU',12,17,null,$b$Khân may mâu dơi sa ôh tâm ƀon khân may nơm mpa du kô̆ tâm jât bơh ba khân may, mâu lah dak play kriăk ƀâu, mâu lah dak play Ôlivơ, mâu lah kon ndrôk bôk rah mâu lah kon biăp bôk rah khân may, mâu lah mpa khân may nhhơr ƀư nanê̆ nau ton, mâu lah mpa khân may nhhơr;$b$,true),
('bunong-vn','DEU',12,18,null,$b$ƀiă lah khân may mra sa mpa nây ta năp Yêhôva Brah Ndu khân may tâm ntŭk Brah Ndu Yêhôva mra săch khân may, kon bu klâu khân may, kon bu ur khân may, oh mon bu klâu jêh ri oh mon bu ur khân may jêh ri phung Lêvi gŭ tâm ƀon khân may, jêh ri khân may mra răm maak ta năp Yêhôva Brah Ndu khân may tâm lĕ rngôch kan khân may ƀư.$b$,false),
('bunong-vn','DEU',12,19,null,$b$Njrăng hom, lơi dun ma phung Lêvi ôh dôl ndah jŏ jong khân may gŭ tâm n'gor khân may.$b$,false),
('bunong-vn','DEU',12,20,null,$b$Tơ lah Yêhôva Brah Ndu khân may ƀư toyh neh khân may tĭng nâm păng ton jêh ma khân may, jêh ri khân may lah: ‘Gâp mra sa puăch.’ Yor lah hên kơnh ma puăch, khân may dơi sa puăch dŭm khân may ŭch.$b$,true),
('bunong-vn','DEU',12,21,null,$b$Tơ lah ntŭk Yêhôva Brah Ndu khân may săch gay dơm amoh păng ta nây jêng ngai ir đah khân may. Khân may dơi nkhĭt ndrôk mâu lah biăp khân may, ndơ Yêhôva ăn jêh ma khân may, tĭng nâm gâp ntăm jêh ma khân may; jêh ri khân may dơi sa puăch dŭm khân may ŭch tâm ƀon khân may.$b$,false),
('bunong-vn','DEU',12,22,null,$b$Khân may dơi sa păng nâm bu bu sa njoih jêh ri jun; nơm ƀơ̆ jêh ri nơm kloh dơi sa păng tâm ban lĕ.$b$,false),
('bunong-vn','DEU',12,23,null,$b$Knŏng njrăng hom, lơi sa mham ôh, yor lah mham jêng nau rêh, jêh ri khân may mâu dơi sa ôh nau rêh ndrel ma mham.$b$,false),
('bunong-vn','DEU',12,24,null,$b$Lơi sa păng ôh; ăn khân may nkhŭt păng ta neh nâm bu dak.$b$,false),
('bunong-vn','DEU',12,25,null,$b$Lơi sa păng ôh, gay ma lĕ nau tât ma khân may jêh ri phung kon khân may kăndơ̆ jêng ueh dôl khân may ƀư nau di ta năp măt Yêhôva.$b$,false),
('bunong-vn','DEU',12,26,null,$b$Ƀiă lah lah mpa prăp ăn khân may nhhơr ăn nanê̆ nau ton, khân may mra sŏk jêh ri hăn ta ntŭk Yêhôva mra gŭch,$b$,true),
('bunong-vn','DEU',12,27,null,$b$nglay jêh ri mham, ta klơ nơng Yêhôva Brah Ndu khân may; mham mpa khân may ƀư brah ăn khân nkhŭt ta nơng Yêhôva Brah Ndu khân may, ƀiă lah nglay khân may dơi sa.$b$,false),
('bunong-vn','DEU',12,28,null,$b$Njrăng hom gay gŭ iăt lĕ rngôch nau ngơi aơ gâp ntăm ma khân may, gay ma nau mra tât ma khân may jêh ri phung kon khân may kăndơ̆ n'ho ro jêng ueh, dôl khân may ƀư nau ueh jêh ri nau di ta năp măt Yêhôva Brah Ndu khân may.$b$,false),
('bunong-vn','DEU',12,29,null,$b$Tơ Yêhôva Brah Ndu khân may ƀư rai ta năp khân may phung ndŭl mpôl khân may mra nsot, jêh ri khân may nsot khân păng jêh ri gŭ tâm n'gor khân păng,$b$,true),
('bunong-vn','DEU',12,30,null,$b$njrăng hom lơi geh dăk tĭng ndô̆ khân păng ôh jêh khân păng rai ta năp măt khân may, jêh ri lơi ôp ma brah khân păng ôh, ‘Mâm phung ndŭl mpôl aơ pah kan ma brah khân păng? Gay ma gâp dơi ƀư tâm ban lĕ.’$b$,false),
('bunong-vn','DEU',12,31,null,$b$Lơi ƀư ôh tâm ban pô nây ma Yêhôva Brah Ndu khân may; yor lah lĕ rngôch ndơ Yêhôva tâm rmot khân păng ƀư jêh ma brah khân păng; yor lah khân păng gŭch nđâp kon bu klâu jêh ri phung kon bu ur khân păng tâm ŭnh ma brah khân păng.$b$,false),
('bunong-vn','DEU',12,32,null,$b$Lĕ rngôch nau gâp ntăm ma khân may, ăn khân may njrăng ƀư, lơi ntop mâu lah n'hŭch lơi ôh.$b$,true),
('bunong-vn','DEU',13,1,null,$b$Tơ lah du huê kôranh nơm mbơh lor dâk ta nklang khân may, mâu lah du huê mơng mbơi ăn ma khân may du nau mbên mâu lah du nau khlay,$b$,true),
('bunong-vn','DEU',13,2,null,$b$jêh ri nau tâm mbên mâu lah nau khlay păng nkoch bri ma khân may tât ngăn, jêh ri tơ lah păng lah, ‘ăn he tĭng ndô̆ brah êng,’ khân may mâu mâp gĭt năl ôh.$b$,false),
('bunong-vn','DEU',13,3,null,$b$‘Jêh ri ăn he pah kan ma khân păng,’ lơi iăt ôh nau kôranh nơm mbơh lor nây mâu lah nơm mơng mbơi nây ngơi; yor lah Yêhôva Brah Ndu khân may rlong uănh khân may, gay gĭt, gĭt lah khân may rŏng ma Yêhôva Brah Ndu khân may ma lĕ nuih n'hâm jêh ri ma lĕ huêng khân may.$b$,false),
('bunong-vn','DEU',13,4,null,$b$Ăn khân may hăn tĭng ndô̆ Yêhôva Brah Ndu khân may jêh ri klach yơk mbah ma păng, djôt prăp nau păng ntăm jêh ri tông bâr ma păng, jêh ri ăn khân may pah kan ma păng jêh ri gŭ tâm rnglăp đah păng.$b$,false),
('bunong-vn','DEU',13,5,null,$b$Ƀiă lah nkhĭt lơi Kôranh nơm mbơh lor nây mâu lah nơm mơng mbơi nây. Yor lah păng nti jêh nau tâm rdâng đah Yêhôva Brah Ndu khân may, nơm njŭn leo jêh khân may luh bơh n'gor Êjipt jêh ri tâm chuai khân may bơh ngih nau jêng dĭk, gay ăn khân may cha lơi trong Yêhôva Brah Ndu khân may ntăm jêh ăn khân may hăn. Pô ri ăn khân may ƀư kloh nau mhĭk bơh tâm nklang khân may.$b$,false),
('bunong-vn','DEU',13,6,null,$b$Tơ lah oh nâu may kon bu klâu me may mâu lah kon bu klâu may, mâu lah kon bu ur may, mâu lah ur may rŏng, mâu lah băl may nơm jêng nâm bu huêng may nơm ndơm may ma nau ndâp, lah: ‘Ăn he pah kan ma brah êng,’ may mâu lah phung che may mâu gĭt năl ôh,$b$,true),
('bunong-vn','DEU',13,7,null,$b$ƀa ƀă brah phung ndŭl mpôl gŭ jŭm khân may, gĭt lah êp mâu lah ngai đah khân may, bơh dŭt bri neh aơ tât ta dŭt bri neh êng,$b$,false),
('bunong-vn','DEU',13,8,null,$b$lơi tông păng mâu lah gŭ iăt păng ôh, mâu lĕ uănh ma păng ma nau yô̆, mâu lĕ nhhuach ma păng, mâu lĕ pôn păng,$b$,false),
('bunong-vn','DEU',13,9,null,$b$ƀiă lah ăn may nkhĭt lơi păng; ti may nơm mra yơr lor gay nkhĭt păng, jêh ri pa kơi ti lĕ rngôch phung ƀon lan.$b$,false),
('bunong-vn','DEU',13,10,null,$b$Ăn khân may klŭp lŭ nkhĭt lơi păng, yor lah păng joi nau ăn may teng đah Yêhôva Brah Ndu khân may, nơm njŭn khân may luh bơh n'gor Êjipt bơh ngih jêng dĭk.$b$,false),
('bunong-vn','DEU',13,11,null,$b$Pô ri lĕ rngôch phung Israel mra tăng jêh ri klach, jêh ri mâu hôm ƀư ôh nau ƀư tâm ban pô nây ta nklang khân may.$b$,false),
('bunong-vn','DEU',13,12,null,$b$Tơ lah khân may tăng tâm du rplay ƀon toyh khân may Yêhôva Brah Ndu khân may ăn ma khân may gŭ,$b$,true),
('bunong-vn','DEU',13,13,null,$b$nau phung tih mhĭk luh hăn ta nklang khân may jêh ri ndơm phung bunuyh gŭ tâm ƀon toyh nây, lah: “Hăn hom he pah kan ma phung brah êng, ‘Khân may mâu mâp gĭt năl ôh,$b$,false),
('bunong-vn','DEU',13,14,null,$b$pô ri ăn khân may ôp, joi jêh ri sek uănh nanê̆; jêh ri aơ, tơ lah nau nây jêng ngăn jêh ri nanê̆, ndơ gâp tâm rmot nây bu ƀư jêh ta năp khân may,$b$,false),
('bunong-vn','DEU',13,15,null,$b$nanê̆ ăn khân may sreh ma đao gưm bunuyh gŭ tâm ƀon nây, ƀư rai lĕ ƀon nây, lĕ rngôch phung gŭ tâm nây, jêh ri mpô mpa ma măt đao.$b$,false),
('bunong-vn','DEU',13,16,null,$b$Ăn khân may njŭn lĕ rngôch ndơ pit sŏk ta nklang ƀon jêh ri su lơi pa ŭnh ƀon nây, jêh ri lĕ rngôch ndơ sŏk pit jêng ndơ nhhơr gŭch lĕ ma Yêhôva Brah Ndu khân may; păng mra jêng du nku hôm ƀa ƀơ; bu mâu hôm rdâk păng ôh.$b$,false),
('bunong-vn','DEU',13,17,null,$b$Lơi ăn geh du mpa bu prăp ƀư rai mra ăt hôm ta khân may, gay ma Yêhôva cha lơi nau duh nuih, jêh ri tâm mpơl nau yô̆ ma khân may, jêh ri ƀư nau ueh ma khân may, jêh ri ăn khân may jêng bĭk rơ̆ tĭng nâm păng ton jêng ma phung che khân may,$b$,false),
('bunong-vn','DEU',13,18,null,$b$tơ lah khân may tông bâr ma Yêhôva Brah Ndu khân may, djôt prăp lĕ rngôch nau păng ntăm ma khân may nar aơ, jêh ri ƀư nau di ta năp măt Yêhôva Brah Ndu khân may.$b$,false),
('bunong-vn','DEU',14,1,null,$b$Khân may jêng phung kon Yêhôva Brah Ndu; lơi tor săk jăn khân may nơm mâu lah ƀư ntŭk hil ta ndăr kleng yor bunuyh khĭt.$b$,true),
('bunong-vn','DEU',14,2,null,$b$Yor lah khân may jêng du phung ƀon lan kloh ueh ma Yêhôva Brah Ndu khân may, jêh ri Yêhôva săch jêh khân may ăn jêng du phung ƀon lan jêng ndơ păng nơm luh bơh lĕ rngôch phung ƀon lan gŭ ta klơ neh ntu.$b$,false),
('bunong-vn','DEU',14,3,null,$b$Lơi sa ôh du ntil mpa gâp tâm rmot.$b$,true),
('bunong-vn','DEU',14,4,null,$b$Aơ ntil mpô mpa khân may dơi sa: Ndrôk, biăp, be,$b$,true),
('bunong-vn','DEU',14,5,null,$b$jun, njoih, njơn be bri (keh) be yôk, jĭl jêh ri biăp yôk.$b$,false),
('bunong-vn','DEU',14,6,null,$b$Ăp mpa geh nchop tâm nkhah tâm dâng jêh ri klơ ndơl jêh ri blau mƀlah sa gơ̆ đơ mpô mpa khân may dơi sa.$b$,false),
('bunong-vn','DEU',14,7,null,$b$Ƀiă lah đơ mpa mƀlah gơ̆ mâu lah geh nchop tâm nkhah lơi sa ôh mpa aơ seh samô, rpai, sŭk lŭ yor lah khân păng blau mƀlah gơ̆ ƀiă lah mâu geh nchop tâm nkhah ôh, khân păng jêng ƀơ̆ ma khân may.$b$,false),
('bunong-vn','DEU',14,8,null,$b$Jêh ri sŭr, yor lah păng mâu geh nchop tâm nkhah, ƀiă lah mâu blau mƀlah gơ̆ ôh, jêng ƀơ̆ ma khân may. Lơi sa nglay khân păng ôh, jêh ri lơi pah săk jăn păng khĭt ôh.$b$,true),
('bunong-vn','DEU',14,9,null,$b$Aơ lĕ mpa gŭ tâm dak khân may dơi sa ntĭl aơ: Mpa geh rsâng jêh ri nsiap khân may dơi sa.$b$,true),
('bunong-vn','DEU',14,10,null,$b$Jêh ri mpa mâu geh rsâng jêh ri mâu geh nsiap khân may mâu dơi sa ôh; păng jêng ƀơ̆ ma khân may.$b$,false),
('bunong-vn','DEU',14,11,null,$b$Khân may dơi sa lĕ rngôch sĭm och kloh,$b$,true),
('bunong-vn','DEU',14,12,null,$b$ƀiă lah ntil aơ khân may mâu dơi sa ôh; klang grât, klang kok,$b$,false),
('bunong-vn','DEU',14,13,null,$b$klang ƀŭng, klang ntơp tĭng nâm mpôl khân păng;$b$,false),
('bunong-vn','DEU',14,14,null,$b$lĕ rngôch nđak tĭng nâm mpôl khân păng;$b$,false),
('bunong-vn','DEU',14,15,null,$b$sĭm ôtrus, klang kô, sĭm tê văch, klang, tĭng nâm mpôl;$b$,false),
('bunong-vn','DEU',14,16,null,$b$klang kô jê̆ jêh ri klang kô toyh, sĭm njơch dak, jêh ri$b$,false),
('bunong-vn','DEU',14,17,null,$b$sĭm njônh, klang sa puăch ôm, Kômôran,$b$,false),
('bunong-vn','DEU',14,18,null,$b$sĭm kŭk kreo, sĭm ta dak tĭng nâm mpôl khân păng, sĭm rkleh, jêh ri rêt vât.$b$,false),
('bunong-vn','DEU',14,19,null,$b$Lĕ rngôch mpa geh năr vơr ma ndŭl jêng ƀơ̆ ma khân may; bu mâu dơi sa khân păng ôh.$b$,false),
('bunong-vn','DEU',14,20,null,$b$Khân may dơi sa lĕ rngôch sĭm kloh geh năr.$b$,false),
('bunong-vn','DEU',14,21,null,$b$Khân may mâu dơi sa ôh mlâm mpa khĭt êng păng nơm; khân may dơi ăn păng ma bu năch gŭ tâm ƀon khân may, ăn khân păng dơi sa, mâu lah khân may dơi tăch ndơ nây ma du huê bu năch; ƀiă lah khân may jêng du phung ƀon lan kloh ueh ma Yêhôva Brah Ndu khân may. Lơi gâm ôh du mlâm kon be tâm dak toh me păng.$b$,true),
('bunong-vn','DEU',14,22,null,$b$Ăn khân may nhhơr du kô̆ tâm jât bơh lĕ rngôch play geh bơh ntil khân may srih jêh ndơ nây luh tă bơh mir ăp năm.$b$,true),
('bunong-vn','DEU',14,23,null,$b$Jêh ri ta năp Yêhôva Brah Ndu khân may tâm ntŭk păng mra săch. Gay dơm amoh păng gŭ ta nây, khân may mra sa du kô̆ tâm jât ba khân may, dak play kriăk ƀâu khân may, dak play Ôlivơ khân may, jêh ri kon bôk rah ndrôk mâu lah biăp khân may, gay ma khân may dơi nti klach yơk ma Yêhôva Brah Ndu khân may ƀa ƀơ.$b$,false),
('bunong-vn','DEU',14,24,null,$b$Tơ lah Yêhôva Brah Ndu khân may ăn nau ueh uĭn ma khân may, tơ lah trong jêng ngai ir đah khân may, pô ri khân may mâu dơi njŭn mpa du kô̆ tâm jât yor lah ntŭk nây jêng ngai ir ma khân may, ntŭk Yêhôva Brah Ndu khân may mra săch, gay dơm amoh păng ta nây,$b$,false),
('bunong-vn','DEU',14,25,null,$b$pô ri khân may dơi tâm rgâl păng ma prăk jêh ri djôt tâm ti khân may, jêh ri hăn ta ntŭk Yêhôva Brah Ndu khân may mra săch,$b$,false),
('bunong-vn','DEU',14,26,null,$b$jêh ri rvăt ma prăk moh mpa khân may ŭch ndrôk, biăp, dak play kriăk ƀâu, mâu lah dak ndrănh ktang, moh ndơ khân may kơnh ŭch sa; jêh ri khân may mra sa ta nây ta năp Yêhôva Brah Ndu khân may jêh ri răm maak, khân may jêh ri bunuyh tâm ngih khân may.$b$,false),
('bunong-vn','DEU',14,27,null,$b$Lơi dun ôh ma phung Lêvi gŭ tâm ƀon khân may, yor lah khân păng mâu geh du kô̆ neh tâm pă mâu lah drăp ndơn ndrel ma khân may ôh.$b$,false),
('bunong-vn','DEU',14,28,null,$b$Tăch pe năm ăn khân may njŭn lĕ ndơ du kô̆ tâm jât, ndơ khân may geh năm nây, jêh ri bun prăp ndơ nây tâm ƀon khân may.$b$,true),
('bunong-vn','DEU',14,29,null,$b$Phung Lêvi, yor lah khân păng mâu geh kô̆ tâm pă mâu lah drăp ndơn ndrel ma khân may ôh, jêh ri nơm gŭ jưh ƀât, kon đơi mbơ̆ , jêh ri bu ur ndrô khĭt sai gŭ tâm ƀon khân may mra văch sa jêh ri hơm; gay ma Yêhôva Brah Ndu khân may dơi mât ton tâm lĕ rngôch kon ti khân may ƀư.$b$,true),
('bunong-vn','DEU',15,1,null,$b$Ta lôch dŭt ăp năm khân may mra ăn nau mpăn (kon me)$b$,true),
('bunong-vn','DEU',15,2,null,$b$Jêh ri aơ jêng trong ăn mpăn: Ăp nơm tơm rnon mra ăn mpăn moh păng ăn jêh ma nơm chiau meng păng, oh nâu păng, yor lah bu mbơh jêh nau Yêhôva ăn mpăn.$b$,false),
('bunong-vn','DEU',15,3,null,$b$May dơn lah rnon ma bu năch; ƀiă lah moh mpa jêng ndơ may gŭ jêh ndrel ma oh nâu may, may mra ăn mpăn hom.$b$,false),
('bunong-vn','DEU',15,4,null,$b$Ƀiă lah mâu mra geh ôh nau trơi o-ach ta nklang khân may yor Yêhôva mra mât ton nau ueh uĭn ma khân may tâm n'gor Yêhôva Brah Ndu khân may ăn ma khân may sŏk pha jêng drăp ndơn,$b$,false),
('bunong-vn','DEU',15,5,null,$b$Knŏng tơ lah khân may mra tông bâr Yêhôva Brah Ndu khân may, dôl njrăng gay ƀư tĭng ndô̆ lĕ rngôch nau ntăm aơ gâp ntăm ma khân may nar aơ.$b$,false),
('bunong-vn','DEU',15,6,null,$b$Yor lah Yêhôva Brah Ndu khân may mra mât ton nau ueh uĭn ma khân may, tĭng nâm nau păng ton jêh, jêh ri khân may mra ăn ma âk ndŭl mpôl bunuyh chan, ƀiă lah khân may mâu mra chan ndơ bu ôh; jêh ri khân may mra jêng kôranh chiă uănh ma âk ndŭl mpôl bunuyh, ƀiă lah khân păng mâu mra jêng kôranh chiă uănh khân may ôh.$b$,false),
('bunong-vn','DEU',15,7,null,$b$Tơ lah geh ta nklang khân may du huê bunuyh o ach, du huê tâm phung oh nâu khân may tâm ƀon khân may tâm n'gor Yêhôva Brah Ndu khân may ăn ma khân may, lơi ƀư dăng nuih n'hâm mâu lah kuêt mbăt ti ma oh nâu khân may o ach ôh,$b$,true),
('bunong-vn','DEU',15,8,null,$b$ƀiă lah ăn khân may ling ti ma khân păng, jêh ri ăn păng chan ăn rĭng ndơ pưt kƀah, moh ndơ păng ŭch.$b$,false),
('bunong-vn','DEU',15,9,null,$b$Njrăng hom klach lah geh nau mĭn mhĭk tâm nuih n'hâm khân may jêh ri khân may lah, ‘Năm tal pơh, năm ăn mpăn dăch jêh,’ jêh ri khân may uănh ma măt mhĭk ma oh nâu khân may o ach jêh ri khân may mâu ăn du mlâm mpa ma păng ôh, jêh ri khân păng nter ma Yêhôva phong khân may jêh ri nau nây jêng nau tih khân may.$b$,false),
('bunong-vn','DEU',15,10,null,$b$Ăn khân may ăn ma khân ô băl ma nau nơih, jêh ri khân may mâu mra geh nuih n'hâm jâk ôh dôl ăn ma ô băl; yor lah yor nau nây Yêhôva Brah Ndu khân may mra mât ton nau ueh uĭn ma khân may tâm lĕ rngôch kan jêh ri tâm lĕ rngôch nau khân may ƀư.$b$,false),
('bunong-vn','DEU',15,11,null,$b$Yor lah mra geh mro phung o ach tâm n'gor; yor nây gâp ntăm ma khân may, ăn khân may ling ăn toyh ti khân may ma oh nâu khân may, ma nơm pưt mpa jêh ri ma nơm o ach tâm n'gor.$b$,false),
('bunong-vn','DEU',15,12,null,$b$Tơ lah du huê tâm phung oh nâu khân may jêng du huê bu klâu mâu lah bu ur Hêbrơ, bu ŭch tăch jêh păng ma khân may, păng mra pah kan ma khân may prao năm, jêh ri năm tal pơh khân may mra ăn ô băl jêng mpăn kon me ăn ô băl sĭt.$b$,true),
('bunong-vn','DEU',15,13,null,$b$Jêh ri tơ lah khân may ăn ô băl mpăn jêng kon me, khân may mâu dơi ăn ô băl sĭt ti hŏng ôh;$b$,false),
('bunong-vn','DEU',15,14,null,$b$khân may mra ăn mpa ma ô băl ma nau lŏng, biăp may, ba tă bơh ntŭk may blên, dak play kriăk ƀâu tă bơh ntŭk may iet; tĭng nâm Yêhôva Brah Ndu khân may ăn nau ueh uĭn jêh ma khân may, khân may mra ăn ma ô băl.$b$,false),
('bunong-vn','DEU',15,15,null,$b$Ăn khân may kah gĭt nau khân may jêng jêh dĭk tâm n'gor Êjipt, jêh ri Yêhôva Brah Ndu khân may tâm chuai jêh khân may; yor nây nar aơ gâp ntăm ma khân may nau aơ.$b$,false),
('bunong-vn','DEU',15,16,null,$b$Ƀiă lah tơ lah ô băl lah ma khân may, ‘Gâp mâu mra luh du bơh ngih may ôh; yor păng rŏng ma may jêh ri bunuyh tâm ngih may, yor ô băl geh nau ueh gŭ ndrel ma may,$b$,false),
('bunong-vn','DEU',15,17,null,$b$pô ri ăn may sŏk du mlâm nsôch, jêh ri chuh tôr mbŏm tôr ta mpông bloh, jêh ri ô băl mra jêng dĭk may n'ho ro. May mra ƀư tâm ban lĕ ma dĭk bu ur may.$b$,false),
('bunong-vn','DEU',15,18,null,$b$Mâu mra jêng nau jêr ôh ma may tơ lah may ăn ô băl mpăn jêng kon me, yor lah ô băl pah kan jêh ma may prao năm, kan nây khư bar tơ̆ rlau lơn ma kan du huê oh mon nkhôm. Pô ri Yêhôva Brah Ndu khân may mra mât ton nau ueh uĭn ma khân may tâm lĕ rngôch kan khân may ƀư.$b$,false),
('bunong-vn','DEU',15,19,null,$b$Ăn khân may prăp an ma Yêhôva Brah Ndu khân may lĕ rngôch kon nkuăng deh bôk rah tâm ndrôk jêh ri biăp khân may. Lơi dŏng tâm kan ôh ndrôk khân may deh bôk rah, mâu lah kreh rsau biăp khân may deh bôk rah.$b$,true),
('bunong-vn','DEU',15,20,null,$b$Khân may mra sa păng ăp năm, khân may jêh ri bunuyh tâm ngih khân may, ta năp Yêhôva Brah Ndu khân may tâm ntŭk păng mra săch.$b$,false),
('bunong-vn','DEU',15,21,null,$b$Ƀiă lah tơ lah păng geh ntŭk mhĭk, tơ lah păng rvĕn, mâu lah chieh măt, mâu lah tơ lah păng geh nau mhĭk glăm êng, lơi dŏng păng ƀư brah ma Yêhôva Brah Ndu khân may ôh.$b$,false),
('bunong-vn','DEU',15,22,null,$b$Ăn khân may sa păng tâm ƀon khân may, mbu nâm ƀơ̆ nđâp nơm kloh dơi sa păng da dê, nâm bu ur sa nkrŏng jêh ri jun.$b$,false),
('bunong-vn','DEU',15,23,null,$b$Knŏng lơi sa mham păng ôh; ăn khân may nkhŭt lơi mham păng ta neh nâm bu dak.$b$,false),
('bunong-vn','DEU',16,1,null,$b$Ăn khân may kah gĭt prăp khay Abip, jêh ri kah gĭt prăp Nau Găn ma Yêhôva Brah Ndu khân may; yor lah tâm khlay Abip yơh Yêhôva Brah Ndu khân may njŭn khân may luh jêh bơh n'gor Êjipt dôl măng.$b$,true),
('bunong-vn','DEU',16,2,null,$b$Ăn khân may nhhơr mpa ƀư brah Nau Găn ma Yêhôva Brah Ndu khân may, biăp mâu lah ndrôk ta ntŭk Yêhôva mra săch gay ma dơm amoh păng ta nây.$b$,false),
('bunong-vn','DEU',16,3,null,$b$Lơi sa ndrel ôh piăng let geh ndrui; dôl pơh nar ăn khân may sa păng ndrel ma piăng let mâu geh ndrui, piăng let nau rêh ni. Yor lah khân may luh jêh bơh n'gor Êjipt ma nau du ndal yơh gay ma lĕ rngôch nar khân may gŭ rêh khân may dơi kah gĭt ma nar khân may luh bơh n'gor Êjipt.$b$,true),
('bunong-vn','DEU',16,4,null,$b$Lơi ăn bu saơ ôh ndrui ndrel ma khân may tâm lĕ n'gor khân may dôl pơh nar; nglay puăch khân may ƀư brah ta mhaơ nar tal nguay, lơi hôm têm bơh măng tât ôi.$b$,false),
('bunong-vn','DEU',16,5,null,$b$Khân may mâu dơi nhhơr mpa ƀư brah Nau Găn tâm ăp rplay ƀon Yêhôva Brah Ndu khân may ăn jêh ma khân may,$b$,false),
('bunong-vn','DEU',16,6,null,$b$ƀiă lah ta ntŭk Yêhôva Brah Ndu khân may mra săch gay ăn amoh păng gŭ ta nây; ta nây yơh khân may mra nhhơr mpa ƀư brah Nau Găn dôl mhaơ ta nar nhâp, di đah mông khân may luh bơh n'gor Êjipt.$b$,false),
('bunong-vn','DEU',16,7,null,$b$Ăn khân may gâm sa păng ta ntŭk Yêhôva Brah Ndu khân may mra săch; jêh ri ta ôi khân may plơ̆ sĭt ta ngih bok khân may.$b$,false),
('bunong-vn','DEU',16,8,null,$b$Dôl tâm prao nar ăn khân may sa piăng let mâu geh ndrui; jêh ri ta nar pơh mra geh nau tâm rƀŭn ma nau yơk ma Yêhôva Brah Ndu khân may, khân may mâu dơi ƀư du ntil kan ôh nar nây.$b$,false),
('bunong-vn','DEU',16,9,null,$b$Ăn khân may kơp pơh nar pơh; ntơm kơp pơh nar pơh aơ bơh nar khân may ntơm rek ba.$b$,true),
('bunong-vn','DEU',16,10,null,$b$Dôl nây ăn khân may kah gĭt prăp nau Nhêt sông Nar Ver ma Yêhôva Brah Ndu khân may djôt mpa nhhơr tĭng nâm nuih n'hâm ŭch, ndơ nây khân may tĭng nâm Yêhôva Brah Ndu khân may ăn nau ueh uĭn ma khân may.$b$,false),
('bunong-vn','DEU',16,11,null,$b$Jêh ri khân may mra răm maak ta năp Yêhôva Brah Ndu khân may, khân may jêh ri kon bu klâu, bu ur khân may, oh mon bu klâu jêh ri bu ur khân may, phung Lêvi gŭ tâm ƀon khân may, nơm gŭ jưh ƀât lât, kon đơi mbơ̆ , jêh ri bu ur ndrô khĭt sai ta nklang khân may, ta ntŭk Yêhôva Brah Ndu khân may mra săch gay ăn amoh păng gŭ ta nây.$b$,false),
('bunong-vn','DEU',16,12,null,$b$Ăn khân may kah gĭt khân may jêng jêh dĭk tâm n'gor Êjipt, jêh ri ăn khân may njrăng kah gĭt prăp nau vay aơ.$b$,false),
('bunong-vn','DEU',16,13,null,$b$Ăn khân may kah gĭt prăp nau nhêt sông Ngih Ndưp dôl pơh nar, tơ lah khân may njŭn sĭt play bơh ntŭk mprah ba jêh ri ntŭk khân may iet dak play kriăk ƀâu.$b$,true),
('bunong-vn','DEU',16,14,null,$b$Khân may mra răm maak tâm nau khân may nhêt sông, khân may jêh ri kon bu klâu, kon bu ur khân may, phung Lêvi, nơm gŭ jưh ƀât lât, kon đơi mbơ̆ , jêh ri bu ur ndrô khĭt sai gŭ tâm ƀon khân may.$b$,true),
('bunong-vn','DEU',16,15,null,$b$Dôl tâm pơh nar ăn khân may kah gĭt prăp nau nhêt sông ma Yêhôva Brah Ndu khân may, ta ntŭk Yêhôva mra săch yor lah Yêhôva Brah Ndu khân may mra mât ton nau ueh uĭn ma khân may tâm lĕ play khân may geh jêh ri lĕ kan ti khân may ƀư. Pô ri khân may bêng ma nau răm maak ndrel n'grŭp.$b$,false),
('bunong-vn','DEU',16,16,null,$b$Pe tơ̆ ăp năm ăn lĕ rngôch phung bu klâu tâm mpơl ta năp Yêhôva Brah Ndu khân may ta ntŭk păng mra săch; ta nau nhêt sông Piăng Let Mâu Geh Ndrui, ta nar nhêt sông Nar Ver, jêh ri ta nar nhêt sông Ngih Ndưp. Khân păng mâu dơi tâm mpơl ta năp Yêhôva ti hŏng ôh.$b$,false),
('bunong-vn','DEU',16,17,null,$b$Ăp nơm mra nhhơr tĭng nâm păng dơi, tĭng nâm nau ueh uĭn Yêhôva Brah Ndu khân may ăn jêh ma khân may.$b$,false),
('bunong-vn','DEU',16,18,null,$b$Ăn khân may tâm dơm kôranh phat dôih jêh ri phung kôranh chiă uănh tâm lĕ rngôch ƀon Yêhôva Brah Ndu khân may ăn jêh ma khân may, tĭng nâm ndŭl mpôl khân may; jêh ri khân may mra phat dôih phung ƀon lan ma nau sŏng.$b$,true),
('bunong-vn','DEU',16,19,null,$b$Khân may mâu dơi ƀư tih đah nau ngăn, lơi ta tâm pă mpôl, mâu dơn ôh ndơ bu blol, ndơ bu blol njêng chieh măt phung blau mĭn jêh ri ƀư roh nau ngăn ăn ma bunuyh sŏng.$b$,false),
('bunong-vn','DEU',16,20,null,$b$Ăn khân may tĭng ndô̆ nau sŏng jêh ri knŏng nau sŏng, gay ma khân may dơi gŭ rêh jêh ri dơn n'gor Yêhôva Brah Ndu ăn ma khân may.$b$,true),
('bunong-vn','DEU',16,21,null,$b$Lơi tăm du ntil tơm si jêng rup brah Asêrim ôh ta meng nơng khân may mra rdâk ma Yêhôva Brah Ndu khân may.$b$,true),
('bunong-vn','DEU',16,22,null,$b$Jêh ri lơi rdâk meh ôh, ndơ nây Yêhôva Brah Ndu khân may tâm rmot.$b$,false),
('bunong-vn','DEU',17,1,null,$b$Lơi ƀư brah ma Yêhôva Brah Ndu khân may du mlâm ndrôk mâu lah du mlâm biăp geh ntŭk mhĭk mâu lah nau mhĭk êng ôh; yor lah nau nây jêng mpa Yêhôva Brah Ndu khân may tâm rmot.$b$,true),
('bunong-vn','DEU',17,2,null,$b$Tơ lah bu saơ tâm nklang khân may tâm ƀon Yêhôva Brah Ndu khân may, rlau nau păng tâm rnglăp,$b$,true),
('bunong-vn','DEU',17,3,null,$b$hăn pah kan jêh ri mbah yơk ma brah êng, mâu lah ma nar, ma khay mâu lah phung ta han tâm trôk, nau nây gâp buay jêh,$b$,false),
('bunong-vn','DEU',17,4,null,$b$jêh ri bu mbơh ma khân may, jêh ri khân may tăng nau nây; pô ri ăn khân may sek uănh nanê̆; jêh ri tơ lah nau nây jêng ngăn jêh ri nanê̆ nau gâp tâm rmot nây bu ƀư jêh tâm n'gor Israel,$b$,false),
('bunong-vn','DEU',17,5,null,$b$dôl nây ăn khân may ta mpông pêr khân may bu klâu mâu lah bu ur ƀư jêh nau mhĭk nây, jêh ri ăn khân may klŭp lŭ nkhĭt lơi bu klâu mâu lah bu ur nây.$b$,false),
('bunong-vn','DEU',17,6,null,$b$Tơ lah geh nau ngăn bơh bar mâu lah pe nuyh mbơh, nơm khư ma nau khĭt ăn bu nkhĭt yơh; bu mâu dơi nkhĭt ôh du huê bunuyh yor geh nau ngăn bơh du huê bunuyh mbơh.$b$,false),
('bunong-vn','DEU',17,7,null,$b$Ti nơm mbơh mra yơr lor lơn nkhĭt nơm nây, jêh ri pa kơi nây ti lĕ rngôch phung ƀon lan. Pô ri ăn khân may ƀư kloh nau mhĭk bơh tâm nklang khân may.$b$,false),
('bunong-vn','DEU',17,8,null,$b$Tơ lah geh nau tât kŏ bu phat dôih du ntil nau nkhĭt bunuyh jêh ri du ntil nau êng, du ntil nau êng di ma nau vay jêh ri du ntil êng, du ntil nau ƀư sôt jêh ri du ntil êng, du nau tât tâm ƀon khân may jêng jêr ir ma khân may, jêh ri ăn khân may dâk jêh ri hăn ta ntŭk Brah Ndu khân may mra săch.$b$,true),
('bunong-vn','DEU',17,9,null,$b$Ăn khân may hăn ta kôranh phat dôih Lêvi jêh ri ma kôranh Phat dôih djôt kan rnôk nây. Ăn khân may ôp khân păng, jêh ri khân păng mra mbơh an dôih khân may.$b$,false),
('bunong-vn','DEU',17,10,null,$b$Ăn khân may ƀư tĭng nâm bu nau khân păng mra mbơh ma khân may tâm ntŭk Yêhôva mra săch; jêh ri ăn khân may njrăng ƀư kơt lĕ rngôch nau khân păng mra ntăm ma khân may.$b$,false),
('bunong-vn','DEU',17,11,null,$b$Ăn khân may ƀư kơt tĭng nâm nau păng nti khân may jêh ri kơt tĭng nau dôih khân păng ngơi ma khân may; khân may mâu dơi teng ôh bơh nau dôih khân păng mbơh ma khân may, gĭt lah pa ma mâu lah pa chiau.$b$,false),
('bunong-vn','DEU',17,12,null,$b$Bunuyh ƀư ma nau sưr mâu tông ma kôranh ƀư brah nơm gŭ pah kan ta năp Yêhôva Brah Ndu khân may, mâu lah ma kôranh phat dôih, bunuyh nây mra khĭt. Pô ri khân may mra ƀư kloh nau ƀơ̆ bơh n'gor Israel,$b$,false),
('bunong-vn','DEU',17,13,null,$b$jêh ri lĕ rngôch phung ƀon lan mra iăt jêh ri klach, jêh ri mâu hôm ƀư ôh ma nau sưr.$b$,false),
('bunong-vn','DEU',17,14,null,$b$Tơ lah khân may tât ta n'gor Yêhôva Brah Ndu ăn ma khân may jêh ri khân may sŏk pha jêh ri gŭ ta nây, jêh ri lah: ‘Hên mra dơm du huê hađăch chiă uănh hên, tâm ban ma lĕ rngôch phung ndŭl mpôl bunuyh gŭ jŭm hên,’$b$,true),
('bunong-vn','DEU',17,15,null,$b$nanê̆ khân may dơi tâm dơm du huê hađăch chiă uănh khân may nơm Yêhôva Brah Ndu khân may mra săch. Khân may mra tâm dơm du huê hađăch chiă uănh khân may, du huê phung oh nâu khân may; khân may mâu dơi tâm dơm ôh du huê bu năch chiă uănh khân may, nơm mâu jêng oh nâu khân may ôh.$b$,false),
('bunong-vn','DEU',17,16,null,$b$Ƀiă lah păng mâu dơi ƀư geh âk seh ma păng nơm ôh, mâu yor ŭch ntop âk seh njŭn leo phung ƀon lan plơ̆ sĭt ta n'gor Êjipt. Khân may mâu mra plơ̆ sĭt ôh ta trong nây.’$b$,true),
('bunong-vn','DEU',17,17,null,$b$Păng mâu dơi ƀư ăn geh âk ur ma păng nơm ôh, klach lah nuih n'hâm păng plơ̆ mhĭk; mâu lĕ păng dơi bun âk ngăn ngên prăk mâu lah mah ma păng nơm.$b$,false),
('bunong-vn','DEU',17,18,null,$b$Tơ lah păng gŭ ta sưng hađăch tâm ƀon bri hađăch păng, ăn păng kơt chih ma păng nơm tâm du ndrom sămƀŭt nau vay aơ, nau vay aơ phung kôranh phat dôih Lêvi chiă.$b$,false),
('bunong-vn','DEU',17,19,null,$b$Sămƀŭt nau vay mra gŭ ndrel ma păng, jêh ri păng mra uănh păng lĕ rngôch nar păng gŭ rêh, gay ma păng dơi nti klach yơk mbah ma Yêhôva Brah Ndu păng, dôl djôt prăp lĕ rngôch nau ngơi bơh nau vay jêh ri nau ntăm aơ, jêh ri ƀư kơt tĭng nau nây;$b$,true),
('bunong-vn','DEU',17,20,null,$b$gay ma nuih n'hâm păng mâu dơi jêng sưr đah phung oh nâu păng ôh, jêh ri mâu teng ôh đah nau ntăm, gĭt lah pa ma mâu lah pa chiau; pô ri păng dơi gŭ jŏ tâm ƀon bri hađăch păng, păng jêh ri phung kon păng, tâm n'gor Israel.$b$,false),
('bunong-vn','DEU',18,1,null,$b$Phung Kôranh ƀư brah Lêvi, lĕ rngôch ndŭl mpôl Lêvi, mâu mra geh kô̆ tâm pă mâu lah drăp ndơn ndrel ma phung Israel ôh; khân păng mra sa mpa nhhơr ăn ŭnh sa ma Yêhôva, jêh ri mpa jêng ndơ păng tĭng nâm nau vay.$b$,true),
('bunong-vn','DEU',18,2,null,$b$Khân păng mâu mra geh drăp ndơn ôh ta nklang phung oh nâu khân păng; Yêhôva jêng drăp ndơn khân păng, tĭng nâm Yêhôva ton jêh ma khân păng.$b$,false),
('bunong-vn','DEU',18,3,null,$b$Aơ mra jêng mpa bơh phung ƀon lan prăp ma phung kôranh ƀư brah bơh phung nhhơr mpa ƀư brah gĭt lah du mlâm ndrôk mâu lah du mlâm biăp; khân păng mra ăn ma kôranh ƀư brah nglik bar đah bom, jêh ri khŭng.$b$,false),
('bunong-vn','DEU',18,4,null,$b$Khân may mra ăn ma păng rplay khlay bơh ba, dak play kriăk ƀâu, jêh ri dak play Ôlivơ khân may, jêh ri rsau biăp khân may kreh tal lor.$b$,false),
('bunong-vn','DEU',18,5,null,$b$Yor lah Yêhôva Brah Ndu khân may săch jêh bơh lĕ rngôch ndŭl mpôl khân may, gay ma păng gŭ ngao jêh ri pah kan tâm amoh Yêhôva, păng jêh ri phung kon bu klâu păng ƀa ƀơ n'ho ro.$b$,false),
('bunong-vn','DEU',18,6,null,$b$Tâm n'gor Israel tơ lah du huê Lêvi văch tă bơh du rplay ƀon khân may păng gŭ ma ntŭk Yêhôva mra săch,$b$,true),
('bunong-vn','DEU',18,7,null,$b$pô ri păng dơi pah kan tâm amoh Yêhôva Brah Ndu păng, tâm ban ma lĕ rngôch phung Lêvi băl păng, phung gŭ ngao ta nây ŭch pah kan ta năp Yêhôva.$b$,false),
('bunong-vn','DEU',18,8,null,$b$Khân păng mra geh kô̆ mpa sông sa tâm ban, pa dih ma mpa păng geh bơh ndơ păng tăch drăp mbơ̆ păng.$b$,false);
insert into public.bible_verses (translation_id, book_code, chapter, verse, verse_end, text, para) values
('bunong-vn','DEU',18,9,null,$b$Tơ lah khân may lăp tâm n'gor Yêhôva Brah Ndu khân may ăn ma khân may, lơi nti ôh tĭng nau tih mhĭk phung ndŭl mpôl nây ƀư.$b$,true),
('bunong-vn','DEU',18,10,null,$b$Lơi ăn geh ôh ta nklang khân may du huê bunuyh gŭch kon bu klâu mâu lah kon bu ur păng jêng mpa nhhơr, du huê pah kan rƀên, du huê mbơh nau mra tât, nơm sek uănh mănh, du huê n'hŭm,$b$,false),
('bunong-vn','DEU',18,11,null,$b$nơm blau ndơm, nơm ngơi ndrel đah brah, nơm ngơi ndrel đah bunuyh khĭt.$b$,false),
('bunong-vn','DEU',18,12,null,$b$Yor lah bu nâm pah kan aơ jêng nơm Yêhôva tâm rmot; jêh ri yor lĕ rngôch kan păng tâm rmot nây Yêhôva Brah Ndu khân may nsot lĕ rngôch phung ndŭl mpôl nây luh bơh ta năp khân may.$b$,true),
('bunong-vn','DEU',18,13,null,$b$Ăn khân may jêng phung bu mâu dơi nduyh ôh ta năp măt Yêhôva Brah Ndu khân may.$b$,false),
('bunong-vn','DEU',18,14,null,$b$Yor lah phung khân may mra nsot aơ jêng ndŭl mpôl gŭ iăt tă bơh phung mbơh nau mra tât jêh ri ƀư nau rƀên; ƀiă lah bi khân may, Yêhôva Brah Ndu khân may mâu dơn ôh khân may ƀư pô nây.$b$,false),
('bunong-vn','DEU',18,15,null,$b$Yêhôva Brah Ndu khân may mra n'hao ma khân may du huê kôranh nơm mbơh lor tâm ban ma gâp tă bơh tâm nklang khân may, bơh phung oh nâu khân may. Ăn khân may gŭ iăt păng.$b$,true),
('bunong-vn','DEU',18,16,null,$b$Nâm bu khân may dăn jêh ma Yêhôva Brah Ndu khân may ta Hôrep ta nar tâm rƀŭn tơ lah khân may lah: ‘Lơi ăn gâp iăt bâr Yêhôva Brah Ndu gâp, mâu lah uănh ŭnh toyh aơ ôh, klach lah gâp khĭt,’$b$,false),
('bunong-vn','DEU',18,17,null,$b$Brah Yê-hô-va lah ma gâp: ‘Lĕ nau khân păng ngơi jêng di.$b$,false),
('bunong-vn','DEU',18,18,null,$b$Gâp mra n'hao ma khân păng du huê kôranh nơm mbơh lor nâm bu khân may bơh nklang phung oh nâu khân păng; gâp mra dơm nau gâp ngơi tâm mbung păng, jêh ri păng mra ngơi ma khân păng lĕ nau gâp ntăm ma păng.$b$,true),
('bunong-vn','DEU',18,19,null,$b$Mbu nâm mâu gŭ iăt ôh nau gâp nơm mra phat dôih nơm nây.$b$,false),
('bunong-vn','DEU',18,20,null,$b$Ƀiă lah kôranh nơm mbơh lor jan ngơi tâm amoh gâp, nau gâp mâu mâp ntăm ăn păng ngơi ôh, mâu lah ngơi tâm amoh brah êng, nơm mbơh lor nây mra khĭt.’$b$,true),
('bunong-vn','DEU',18,21,null,$b$Tơ lah khân may lah tâm nuih n'hâm khân may, ‘Mâm hên dơi gĭt nau ngơi Yêhôva mâu mâp ngơi ôh?’$b$,false),
('bunong-vn','DEU',18,22,null,$b$Tơ lah du huê kôranh nơm mbơh lor ngơi tâm amoh Yêhôva, tơ lah nau păng ngơi mâu tât ôh mâu lah mâu geh nau ngăn ôh, nây jêng ngơi nau Yêhôva mâu mâp ngơi ôh; kôranh nơm mbơh lor nây ngơi jêh ma nau nklă, lơi klach ma păng ôh.$b$,false),
('bunong-vn','DEU',19,1,null,$b$Tơ lah Yêhôva Brah Ndu khân may ƀư rai phung ndŭl mpôl bunuyh n'gor khân păng Yêhôva Brah Ndu khân may ma khân may, jêh ri khân may nsot gŭ tâm ƀon jêh ri tâm ngih khân păng,$b$,true),
('bunong-vn','DEU',19,2,null,$b$ăn khân may prăp êng pe rplay ƀon ma khân may tâm ntŭk ta nklang n'gor Yêhôva Brah Ndu khân may ăn ma khân may sŏk pha.$b$,false),
('bunong-vn','DEU',19,3,null,$b$Ăn khân ay may ƀư trong ăn ueh tâm n'gor Yê-hô-va Brah Ndu hŏ ăn jêh ma khân may jêh ri prăp êng pe rplay ƀon, pô ri nơm nkhĭt bunuyh dơi du krap ta nây.$b$,true),
('bunong-vn','DEU',19,4,null,$b$Aơ jêng nau nkra kơl ma nơm nkhĭt bunuyh, nơm du krap ta nây dơi rklaih nau rêh păng. Tơ lah ma nau mâu ŭch ôh du huê nkhĭt nơm chiau meng păng mâu mâp jêng rlăng đah păng bơh lor ôh$b$,false),
('bunong-vn','DEU',19,5,null,$b$nâm bu ntĭt tơ lah du huê bu klâu lăp tâm krŏng ndrel ma nơm chiau meng păng ŭch chôk long jêh ri ti păng yat sung ŭch kăl si, jêh ri măt sung rngloh bơh n'gâr geh nơm chiau meng păng kŏ tât khĭt păng dơi du krap tâm du play ƀon aơ, tâm rklaih nau rêh păng;$b$,false),
('bunong-vn','DEU',19,6,null,$b$klach lah nơm har plơng mham ma nau duh nuih tĭng nơm nkhĭt bunuyh nây jêh ri ban păng yor lah trong ngai ir jêh ri ƀư sôt păng kŏ tât khĭt, nđâp tơ lah bu klâu nây mâu khư ma nau khĭt ôh, yor lah păng mâu jêng rlăng đah nơm chiau meng păng lor ôh.$b$,false),
('bunong-vn','DEU',19,7,null,$b$Yor nây gâp ntăm ma khân may. Ăn khân may prăp êng pe rplay ƀon.$b$,false),
('bunong-vn','DEU',19,8,null,$b$Tơ lah Yêhôva Brah Ndu khân may ăn toyh n'har neh khân may tĭng nâm păng ton jêh ma phung che khân may, jêh ri ăn ma khân may lĕ neh păng ton jêh ŭch ăn ma phung che khân may,$b$,true),
('bunong-vn','DEU',19,9,null,$b$tơ lah khân may njrăng gay djôt prăp lĕ rngôch nau ntăm aơ gâp ntăm ma khân may nar aơ, ma nau khân may rŏng ma Yêhôva Brah Ndu khân may jêh ri hăn tĭng ndô̆ trong păng ƀa ƀơ pô ri ăn khân may ntop pe rplay ƀon êng ma pe rplay ƀon aơ,$b$,false),
('bunong-vn','DEU',19,10,null,$b$klach lah bu nkhŭt lơi mham mâu geh tih ôh tâm n'gor khân may Yêhôva Brah Ndu khân may ăn ma khân may lĕ drăp ndơn, pô ri nau tih nkhŭt mham tŭp ta khân may.$b$,false),
('bunong-vn','DEU',19,11,null,$b$Ƀiă lah tơ lah du huê tâm rmot ma nơm chiau meng păng, jêh ri gŭ kâp ô băl, ƀư ma ô băl, jêh ri ƀư sôt ô băl glăm tât khĭt, jêh ri bu klâu nây du lăp tâm du rplay ƀon aơ,$b$,true),
('bunong-vn','DEU',19,12,null,$b$pô ri phung bu bŭnh bu ranh tâm ƀon păng mra njuăl hăn jêh ri sŏk nsĭt păng bơh ntŭk nây, jêh ri jao păng tâm ti nơm har plơng mham, gay ma păng khĭt.$b$,false),
('bunong-vn','DEU',19,13,null,$b$Khân may mâu dơi uănh ma păng ma nau yô̆ ôh, ƀiă lah ăn khân may ƀư kloh nau tih nkhŭt mham nơm mâu tih ôh bơh phung Israel, gay ma lĕ rngôch nau dơi jêng ueh ma khân may.$b$,false),
('bunong-vn','DEU',19,14,null,$b$N'har bri phung kôranh ơm tâm nal jêh tâm ntŭk jêng drăp ndơn khân may mra sŏk pha tâm n'gor Yêhôva Brah Ndu khân may ăn ma khân may sŏk pha, lơi tâm rgâl n'har bri nơm chiau meng khân may ôh.$b$,true),
('bunong-vn','DEU',19,15,null,$b$Du huê nơm mbơh mâu mra dơi ôh đah du huê bu klâu yor du nau tih mâu lah du nau mhĭk êng di ma du ntil nau tih păng ƀư jêh; knŏng đah nau ngăn tă bơh bar hê nơm mbơh mâu lah pe nuyh nơm mbơh nau phong mra jêng ngăn.$b$,true),
('bunong-vn','DEU',19,16,null,$b$Tơ lah du huê nơm mbơh mƀruh dâk ƀư ma du huê bunuyh gay phong nau tih,$b$,true),
('bunong-vn','DEU',19,17,null,$b$phung bar hê geh nau nây mra tâm mpơl ta năp Yêhôva, ta năp phung Kôranh ƀư brah jêh ri phung kôranh phat dôih djôt kan rnôk nây$b$,false),
('bunong-vn','DEU',19,18,null,$b$Phung kôranh phat dôih mra sek uănh nanê̆, jêh ri tơ lah nơm mbơh jêng nơm mbơh mƀruh jêh ri phong jêh ma oh nâu păng ma nau mƀruh,$b$,false),
('bunong-vn','DEU',19,19,null,$b$pô ri ăn khân may ƀư ma păng nâm bu păng mĭn jêh ŭch ƀư ma oh nâu păng; pô ri khân may mra ƀư kloh nau tih tă bơh tâm nklang khân may.$b$,false),
('bunong-vn','DEU',19,20,null,$b$Phung êng mra tăng jêh ri klach, jêh ri mâu hôm ƀư ôh nau tih nâm bu pô nây ta nklang khân may,$b$,false),
('bunong-vn','DEU',19,21,null,$b$Lơi uănh ma nau yô̆ ôh; ăn khân may ƀư nau rêh ma nau rêh, măt ma măt, sêk ma sêk, ti ma ti, jâng ma jâng.$b$,false),
('bunong-vn','DEU',20,1,null,$b$Tơ lah khân may hăn ma nau tâm lơh đah phung rlăng khân may, jêh ri khân may saơ seh, ndeh seh jêh ri du phung ta han âk lơn ma khân may de, lơi klach ma khân păng ôh, yor lah Yêhôva Brah Ndu khân may nơm njŭn khân may luh bơh n'gor Êjipt, gŭ ndrel ma khân may.$b$,true),
('bunong-vn','DEU',20,2,null,$b$Tơ lah khân may hăn dăch ma nau tâm lơh, ăn kôranh ƀư brah hăn ta năp jêh ri ngơi ma phung ƀon lan$b$,true),
('bunong-vn','DEU',20,3,null,$b$jêh ri mra lah ma khân păng: ‘Iăt hom, Ơ phung Israel, nar aơ khân may hăn ma nau tâm lơh đah phung rlăng khân may, lơi ăn nuih n'hâm khân may jêng rdja ôh, lơi klach ôh, lơi râm sâr mâu lah krit rnam ma khân păng ôh;$b$,false),
('bunong-vn','DEU',20,4,null,$b$yor lah Yêhôva Brah Ndu khân may jêng nơm hăn ndrel ma khân may, tâm lơh an đah phung rlăng khân may, gay ăn nau dơi ma khân may.$b$,false),
('bunong-vn','DEU',20,5,null,$b$Jêh ri ăn phung kôranh ta han ngơi ma phung ƀon lan, lah, ‘Mbu nâm rdâk jêh du rplay ngih mhe jêh ri ê nhhơr ôh păng? Ăn păng sĭt ta ngih păng, klach lah păng khĭt tâm nau tâm lơh jêh ri nơm êng nhhơr lơi ngih nây.$b$,true),
('bunong-vn','DEU',20,6,null,$b$Jêh ri mbu nâm tăm jêh đang play kriăk ƀâu jêh ri ê mâp sa ôh play păng? Ăn păng sĭt ta ngih păng, klach lah păng khĭt tâm nau tâm lơh jêh ri nơm êng sa lơi play nây.$b$,false),
('bunong-vn','DEU',20,7,null,$b$Jêh ri mbu nâm hŏ tâm ndrôi jêh đah du huê bu ur jêh ri ê sŏk păng ma ur ôh? Ăn păng sĭt ta ngih păng, klach lah păng khĭt tâm nau tâm lơh, jêh ri nơm êng gŭ lơi ur păng.’$b$,false),
('bunong-vn','DEU',20,8,null,$b$Jêh ri phung kôranh ta han mra ngơi ma phung ƀon lan jêh ri lah. ‘Mbu nâm klach jêh ri n'hŭng? Ăn păng sĭt ta ngih păng, klach lah băl păng ra ai nuih n'hâm tâm ban ma nuih n'hâm păng.’$b$,false),
('bunong-vn','DEU',20,9,null,$b$Tơ lah phung kôranh ta han lôch jêh ngơi ma phung ƀon lan, dôl nây khân păng tâm dơm phung kôranh ta han gai phung ƀon lan.$b$,false),
('bunong-vn','DEU',20,10,null,$b$Tơ lah khân may hăn dăch du rplay ƀon, gay tâm lơh đah ƀon nây, nhhơr nau ngơi ma nau đăp mpăn.$b$,true),
('bunong-vn','DEU',20,11,null,$b$Tơ lah ƀon nây plơ̆ lah ma khân may jêng nau đăp mpăn jêh ri pơk mpông pêr ma khân may, pô ri lĕ rngôch phung ƀon lan gŭ tâm ƀon nây mra jêng dĭk pah kan ma khân may.$b$,false),
('bunong-vn','DEU',20,12,null,$b$Ƀiă lah tơ lah ƀon nây mâu ƀư nau đăp mpăn đah khân may ôh, ƀiă lah tâm lơh đah khân may, pô ri ăn khân may nchueng ƀon nây.$b$,true),
('bunong-vn','DEU',20,13,null,$b$Jêh Yêhôva Brah Ndu khân may jao ƀon nây tâm ti khân may, ăn khân may nkhĭt lơi lĕ rngôch phung bu klâu ma đao,$b$,false),
('bunong-vn','DEU',20,14,null,$b$ƀiă lah khân may mra sŏk ma khân may phung bu ur, phung kon se, mpô mpa rong, jêh ri ăp ntil mpa êng tâm ƀon, lĕ mpa pit sŏk, khân may sŏk jêng ndơ pit sŏk ma khân may nơm; jêh ri khân may mra dŏng mpa pit sŏk bơh phung rlăng khân may.$b$,false),
('bunong-vn','DEU',20,15,null,$b$Tâm ban pô nây khân may mra ƀư ma lĕ rngôch ƀon gŭ ngai ngăn đah khân may mâu di ôh ƀon phung ndŭl mpôl aơ.$b$,true),
('bunong-vn','DEU',20,16,null,$b$Ƀiă lah tâm ƀon phung ndŭl mpôl aơ Yêhôva Brah Ndu khân may ăn ma khân may jêng drăp ndơn, khân may mâu dơi om rêh moh mpa blau suh n'hâm,$b$,false),
('bunong-vn','DEU',20,17,null,$b$ƀiă lah nkhĭt lơi lĕ ƀhiau, phung Hitit, phung Amôrit, phung Kanaan, phung Pêrisit, phung Hivit, jêh ri phung Jêbusit tĭng nâm Yêhôva Brah Ndu khân may ntăm jêh;$b$,false),
('bunong-vn','DEU',20,18,null,$b$gay ma khân păng mâu dơi ôh sâm nti khân may ƀư kơt lĕ rngôch kan tih mhĭk khân păng mâp ƀư jêh tâm nau pah kan ma phung brah khân păng; pô ri khân may ƀư tih đah Yêhôva Brah Ndu khân may.$b$,false),
('bunong-vn','DEU',20,19,null,$b$Tơ lah khân may nchueng du rplay ƀon jŏ nar tâm lơh đah ƀon nây gay nhŭp păng, lơi ƀư rai ma sung ôh tơm si, yor lah khân may dơi sa play păng, ƀiă lah khân may mâu dơi kăl păng ôh. Di lĕ si tâm mir jêng bunuyh khân may ŭch nchueng?$b$,true),
('bunong-vn','DEU',20,20,null,$b$Knŏng tơm si khân may gĭt mâu jêng tơm si bu sa play khân may dơi ƀư rai jêh ri kăl, gay ma khân may dơi rdâk ndơ nchueng ƀon tâm lơh đah khân may, kŏ ƀon nây tŭp.$b$,false),
('bunong-vn','DEU',21,1,null,$b$Tơ lah tâm n'gor Yêhôva Brah Ndu khân may ăn ma khân may sŏk pha bu saơ du huê bunuyh bu nkhĭt jêh gŭ ta mir, jêh ri mâu gĭt ôh mbu nkhĭt păng,$b$,true),
('bunong-vn','DEU',21,2,null,$b$pô ri phung bu ranh jêh ri phung kôranh phat dôih khân may mra hăn veh ndah ngai đah ƀon jŭm nơm bu nkhĭt jêh.$b$,false),
('bunong-vn','DEU',21,3,null,$b$Phung bu ranh ƀon dăch lơn ma nơm bu nkhĭt nây mra sŏk du mlâm ndrôk me druh mâu mâp dŏng kan jêh ri mâu mâp mƀăk n'gŏl.$b$,false),
('bunong-vn','DEU',21,4,null,$b$Phung bu ranh ƀon nây mra têk ndrôk me druh jŭr tâm rlŭng geh dak n'hor, ntŭk bu mâu mâp tăm mâu lĕ bu mâp srih găr, jêh ri tâm rlŭng nây khân păng mra ƀư deh (pă) trô ko ndrôk me druh nây.$b$,false),
('bunong-vn','DEU',21,5,null,$b$Phung kôranh ƀư brah, phung kon bu klâu Lêvi mra hăn êp, yor lah Yêhôva Brah Ndu khân may săch jêh khân păng ăn pah kan ma păng jêh ri ăn khân păng mât ton tâm amoh Yêhôva, jêh ri ma nau khân păng ngơi lĕ nau tâm rlăch jêh ri lĕ nau tâm nhăt mra ƀư lôch.$b$,false),
('bunong-vn','DEU',21,6,null,$b$Lĕ rngôch phung bu ranh ƀon êp lơn đah nơm bu nkhĭt mra rao ti khân păng ta klơ ndrôk me druh bu juet lơi trô ko tâm rlŭng.$b$,true),
('bunong-vn','DEU',21,7,null,$b$Khân păng mra mbơh ngăn. ‘Ti hên mâu mâp nkhŭt ôh mham aơ, măt hên mâu mâp saơ lĕ bu nkhŭt mham aơ.$b$,true),
('bunong-vn','DEU',21,8,null,$b$Ơ Yêhôva yô̆ an ma phung ƀon lan Israel may, phung may chuai jêh, jêh ri lơi kơp nau jêng tih đah mham mâu tih ta nklang phung ƀon lan Israel may; ƀiă lah yô̆ an ma khân păng nau jêng tih đah mham.’$b$,false),
('bunong-vn','DEU',21,9,null,$b$Pô ri khân may mra ƀư kloh nau jêng tih đah mham mâu tih tă tâm nklang khân may, dôl khân may ƀư nau di ta năp măt Yêhôva.$b$,false),
('bunong-vn','DEU',21,10,null,$b$Tơ lah khân may hăn ma nau tâm lơh đah phung rlăng khân may, jêh ri Yêhôva Brah Ndu khân may jao khân păng tâm ti khân may, jêh ri khân may sŏk khân păng jêng bu nă$b$,true),
('bunong-vn','DEU',21,11,null,$b$jêh ri khân may saơ tâm phung bu nă nây du huê bu ur ueh, jêh may kơnh ma păng jêh ri ŭch sŏk păng jêng ur may,$b$,false),
('bunong-vn','DEU',21,12,null,$b$Pô ri ăn may njŭn păng ta ngih may, jêh ri păng mra poih lơi sŏk păng jêh ri koh lơi nheh păng.$b$,false),
('bunong-vn','DEU',21,13,null,$b$Păng mra doh lơi bok ao păng soh dôl jêng bu nă, jêh ri mra gŭ tâm ngih may jêh ri ndrê ndjăng ma mbơ̆ jêh ri ma me păng dôl lĕ tâm du khay. Jêh nau nây may dơi hăn gŭ ndrel păng, jêng sai păng, jêh ri păng mra jêng ur may.$b$,false),
('bunong-vn','DEU',21,14,null,$b$Jêh ri tơ lah may mâu maak đah păng ôh, may dơi cha lơi păng du ta ntŭk păng ŭch, ƀiă lah may mâu dơi tăch păng sŏk prăk ôh, may mâu dơi kơp păng jêng dĭk ôh, yor lah may ƀư bêk jêh păng.$b$,false),
('bunong-vn','DEU',21,15,null,$b$Tơ lah du huê bu klâu geh bar hê ur, păng rŏng ma du huê jêh ri mâu rŏng ôh ma nơm êng, jêh ri khân păng deh kon ma păng, nơm păng rŏng nđâp ma nơm păng mâu rŏng ôh, jêh ri tơ lah kon bu klâu deh bôk rah jêng kon bu ur păng mâu rŏng ôh,$b$,true),
('bunong-vn','DEU',21,16,null,$b$pô ri ta nar păng tâm pă ndơ păng geh jêng drăp ndơn ma phung kon bu klâu păng, păng mâu dơi kơp ôh kon bu klâu bơh ur păng rŏng jêng kon deh bôk rah nsro kon bu klâu ur păng mâu rŏng ôh, nơm jêng kon deh bôk rah.$b$,false),
('bunong-vn','DEU',21,17,null,$b$Ƀiă lah păng mra dơn kon deh bôk rah kon bu klâu bơh bu ur păng mâu rŏng ôh, ma nau păng ăn ma ô băl bar kô̆ bơh lĕ drăp păng geh, yor lah ô băl jêng play lor ma nau maak păng; nau vay jêng nâu ranh pha păng.$b$,false),
('bunong-vn','DEU',21,18,null,$b$Tơ lah du huê bunuyh geh kon bu klâu dăng bôk jêh ri ră tâm rdâng, mâu ŭch tông bâr mbơ̆ mâu lah me păng, jêh ri nđâp tơ lah khân păng nkra păng kđôi lĕ, păng mâu mra tông nau ôh.$b$,true),
('bunong-vn','DEU',21,19,null,$b$Pô ri mbơ̆ mâu lah me păng mra sŏk păng jêh ri njŭn păng ma phung bu ranh ƀon păng ta mpông pêr ntŭk păng gŭ.$b$,false),
('bunong-vn','DEU',21,20,null,$b$Jêh ri khân păng mra lah ma phung bu ranh ƀon păng, ‘Aơ kon bu klâu hên dăng bôk jêh ri ră tâm rdâng, păng mâu ŭch tông bâr hên ôh; păng jêng du huê bunuyh hay sông sa jêh ri mơng nhŭl ndrănh.’$b$,false),
('bunong-vn','DEU',21,21,null,$b$Lĕ rngôch bunuyh tâm ƀon mra klŭp lŭ nkhĭt lơi păng. Tâm ban pô nây khân may mra ƀư kloh nau mhĭk bơh ta nklang khân may; jêh ri lĕ rngôch phung Israel mra iăt jêh ri klach.$b$,false),
('bunong-vn','DEU',21,22,null,$b$Tơ lah du huê bu klâu ƀư nau tih toyh khư khĭt jêh ri bu nkhĭt păng, jêh ri may yơt păng ta tơm si,$b$,true),
('bunong-vn','DEU',21,23,null,$b$lơi cha lat săk jăn khĭt păng bêch măng ôh ta tơm si, ƀiă lah ăn khân may tâp păng nar nây lĕ, yor lah nơm bu yơt jêng nơm Brah Ndu rtăp rak jêh. Lơi ƀư ƀơ̆ ôh n'gor khân may Yêhôva Brah Ndu khân may ăn ma khân may jêng drăp ndơn.$b$,false),
('bunong-vn','DEU',22,1,null,$b$Tơ lah khân may saơ ndrôk mâu lah biăp oh nâu khân may nhhơt bri, lơi ta khân may ƀư nau mâu chrê ôh; ăn khân may têk nsĭt păng ma oh nâu may.$b$,true),
('bunong-vn','DEU',22,2,null,$b$Tơ lah păng mâu gŭ dăch khân may ôh, mâu lah tơ lah khân may mâu gĭt năl păng ôh, ăn khân may têk nsĭt păng ta ngih khân may jêh ri păng mra gŭ tâm ngih khân may tât oh nâu khân may ôp joi păng. Dôl nây khân may mra mplơ̆ păng.$b$,true),
('bunong-vn','DEU',22,3,null,$b$Khân may mra ƀư tâm ban pô nây lĕ ma phung seh bri khân păng, khân may mra ƀư tâm ban pô nây lĕ ma kho ao păng, tâm ban pô nây lĕ khân may mra ƀư ma moh ndơ oh nâu khân may roh jêh, moh ndơ păng roh jêh nây khân may dônh, khân may mâu dơi dun ôh nau kơl păng.$b$,false),
('bunong-vn','DEU',22,4,null,$b$Tơ lah khân may saơ seh bri mâu lah ndrôk oh nâu khân may prah (cha lôt) ta trong, lơi may dun nau kơl khân păng, ăn khân may kơl rdâk ndrôk păng.$b$,false),
('bunong-vn','DEU',22,5,null,$b$Du huê bu ur mâu dơi soh kho ao bu klâu ôh, bu klâu mâu lĕ dơi soh kho ao bu ur; yor lah mbu nâm ƀư nau nây jêng nơm Yêhôva Brah Ndu tâm rmot.$b$,true),
('bunong-vn','DEU',22,6,null,$b$Tơ lah khân may saơ rsuăn sĭm ta klơ tơm si mâu lah ta neh ndrel ma kon mâu lah tăp, jêh ri me gŭ păn ta klơ kon mâu lah tăp, khân may mâu dơi sŏk tăp ndrel ma me ôh.$b$,true),
('bunong-vn','DEU',22,7,null,$b$Ăn khân may ăn me du, ƀiă lah khân may dơi nhŭp kon păng, gay ma lĕ nau tât ma khân may jêng ueh jêh ri khân may dơi gŭ rêh jŏ.$b$,false),
('bunong-vn','DEU',22,8,null,$b$Tơ lah khân may ƀư du rplay ngih mhe ăn khân may ƀư nting n'gong jŭm ndring ngih khân may gay ma khân may mâu dơi ƀư tât nau tih ma mham ta ngih khân may tơ lah geh du huê bunuyh tŭp tă bơh ngih.$b$,true),
('bunong-vn','DEU',22,9,null,$b$Lơi srih ôh tâm đang play kriăk ƀâu khân may ma âk ntil srih klach lah khân may ƀư ƀơ̆ lĕ play ntil khân may srih jêh nđâp ma play bơh đang play kriăk ƀâu khân may.$b$,true),
('bunong-vn','DEU',22,10,null,$b$Lơi kai du mlâm ndrôk jêh ri du mlâm seh bri bar mlâm n'gŏl ndrel.$b$,true),
('bunong-vn','DEU',22,11,null,$b$Lơi soh ôh du blah bok tanh âk ntil ndơ tâm rlŭk, rsau biăp mâu lah ndrel ma mhay.$b$,true),
('bunong-vn','DEU',22,12,null,$b$Ăn khân may chiăk nchiăng brai ta puăn pĭt ao khân may mra soh.$b$,true),
('bunong-vn','DEU',22,13,null,$b$Tơ lah du huê bu klâu sŏk du huê bu ur jêh ri hăn gŭ ndrel ma păng, jêh ri rmot dun ô băl,$b$,true),
('bunong-vn','DEU',22,14,null,$b$jêh ri phong nchơt ma ô băl ƀư nau tih bêk, jêh ri ƀư lư mhĭk amoh ô băl, lah: ‘Gâp sŏk jêh bu ur aơ, tơ lah gâp gŭ đah păng, gâp mâu saơ nau mbên ăn gĭt păng jêng bu ur druh ôh.’$b$,false),
('bunong-vn','DEU',22,15,null,$b$Pô ri mbơ̆ me bu ur druh nây mra sŏk leo ndơ tâm mbên ma nau păng jêng bu ur druh đah phung bu ranh ƀon nây ta mpông pêr.$b$,false),
('bunong-vn','DEU',22,16,null,$b$Mbơ̆ bu ur druh nây lah ma phung bu ranh, ‘Gâp ăn jêh kon bu ur gâp jêng ur ma bu klâu aơ, jêh ri păng tâm rmot dun ô băl;$b$,false),
('bunong-vn','DEU',22,17,null,$b$jêh ri aơ, păng phong nchơt ma ô băl ƀư nau tih ăn bêk, lah: “Gâp mâu saơ ôh tâm kon bu ur may nau tâm mbên păng jêng bu ur druh.” Ƀiă lah ndơ aơ tâm mbên kon bu ur gâp jêng druh.’ Jêh ri khân may mra ling bok ta năp phung bu ranh tâm ƀon.$b$,false),
('bunong-vn','DEU',22,18,null,$b$Pô ri phung bu ranh tâm ƀon nây mra nhŭp bu klâu jêh ri rmal păng.$b$,false),
('bunong-vn','DEU',22,19,null,$b$Khân păng mra kuh bu klâu nây du rhiăng Sêkel prăk, jêh ri ăn ma mbơ̆ bu ur druh nây, yor lah păng ƀư lư mhĭk amoh du huê bu ur druh Israel. Păng ăt mra jêng ur ma bu klâu nây; păng mâu dơi cha lơi ô băl tâm lĕ nar păng gŭ rêh.$b$,false),
('bunong-vn','DEU',22,20,null,$b$Ƀiă lah tơ lah nau nây jêng ngăn, mâu saơ ôh nau tâm mbên bu ur nây jêng druh,$b$,false),
('bunong-vn','DEU',22,21,null,$b$pô ri khân păng mra njŭn leo bu ur druh nây luh ta mpông ngih mbơ̆ păng, jêh ri phung bu klâu ƀon păng mra klŭp nkhĭt păng ma lŭ, yor lah păng ƀư nau rluk tâm n'gor Israel ma nau ƀư nau văng tĭr tâm ngih mbơ̆ păng. Tâm ban pô nây khân may mra ƀư kloh nau tih tă bơh tâm nklang phung khân may.$b$,false),
('bunong-vn','DEU',22,22,null,$b$Tơ lah bu saơ du huê bu klâu bêch đah ur bu, lĕ bar hê khân păng mra khĭt, bu klâu bêch đah bu ur nây jêh ri bu ur nây tâm ban lĕ; tâm ban pô nây ăn khân may ƀư kloh nau mhĭk bơh phung Israel.$b$,true),
('bunong-vn','DEU',22,23,null,$b$Tơ lah geh du huê bu ur druh geh nau tâm mbloh văng jêh, jêh ri du huê bu klâu mâp đah păng tâm ƀon jêh ri bêch ndrel đah păng,$b$,true),
('bunong-vn','DEU',22,24,null,$b$pô ri khân may mra njŭn lĕ bar hê ta mpông pêr ƀon nây, jêh ri khân may mra klŭp nkhĭt khân păng ma lŭ, bu ur druh nây yor păng mâu kuăl dat yor lah păng gŭ tâm ƀon, jêh ri bu klâu nây yor lah păng nsâl lôr ur phung chiau meng păng. Tâm ban pô nây ăn khân may ƀư kloh nau mhĭk tâm nklang khân may.$b$,false),
('bunong-vn','DEU',22,25,null,$b$Ƀiă lah tơ lah tâm mir du huê bu klâu tâm mâp đah du huê bu ur druh mâu geh nau tih khư ma nau khĭt ôh,$b$,false),
('bunong-vn','DEU',22,26,null,$b$yor lah nau nây jêng tâm ban ma du huê bu klâu ƀư ma phung chiau meng păng jêh ri nkhĭt lơi păng,$b$,false),
('bunong-vn','DEU',22,27,null,$b$Yor lah nau nây tâm mâp đah păng tâm mir, jêh ri nđâp tơ lah bu ur druh geh nau tâm mbloh văng nây kuăl dat jêh, ƀiă lah mâu geh nơm koh dŏng păng ôh.$b$,false),
('bunong-vn','DEU',22,28,null,$b$Tơ lah du huê bu klâu tâm mâp đah du huê bu ur ê geh nau tâm mbloh văng, kuăn rdâng păng jêh ri bêch ndrel păng, jêh ri bu ban saơ khân păng,$b$,true),
('bunong-vn','DEU',22,29,null,$b$pô ri bu klâu nơm bêch jêh đah păng mra ăn ma mbơ̆ bu ur druh nây prăm jât Sêkel prăk, jêh ri bu ur nây mra jêng ur păng, yor lah păng sâl lôr ô băl jêh; păng mâu dơi cha lơi ôh lĕ nar păng gŭ rêh.$b$,false),
('bunong-vn','DEU',22,30,null,$b$Du huê bu klâu mâu dơi sŏk ur mbơ̆ păng ôh, mâu lĕ păng suk sôr nah bŭt bu ur nây, nơm nây jêng ur mbơ̆ păng.$b$,true),
('bunong-vn','DEU',23,1,null,$b$Mbu geh tăp chah jêh mâu lah ndơ chrach (cho) bu klâu tăch jêh mâu dơi lăp tâm phung Yêhôva tâm rƀŭn ôh.$b$,true),
('bunong-vn','DEU',23,2,null,$b$Mâu geh du huê kon tĭr dơi lăp tâm phung Yêhôva tâm rƀŭn ôh; nđâp ma sau păng ta tal jât rnôk pa kơi mâu dơi lăp ôh tâm phung Yêhôva tâm rƀŭn.$b$,false),
('bunong-vn','DEU',23,3,null,$b$Mâu geh du huê Amôn mâu lah du huê Môap dơi lăp ôh tâm phung Yêhôva tâm rƀŭn; nđâp ma sau păng ta lal jât rnôk pa kơi mâu dơi lăp n'ho ro ôh tâm phung Yêhôva tâm rƀŭn;$b$,true),
('bunong-vn','DEU',23,4,null,$b$yor lah khân păng mâu mâp văch ôh ma khân may ma piăng let jêh ri dak ta trong dôl khân may luh bơh n'gor Êjipt, jêh ri yor lah khân păng nkhôm Y-Balaam kon bu klâu Bêôr ƀon Pêthôr n'gor Mêsapôtami ăn rtăp rak khân may.$b$,false),
('bunong-vn','DEU',23,5,null,$b$Ƀiă lah Yêhôva Brah Ndu khân may mâu gŭ iăt Y-Balaam ôh; ƀiă lah Yêhôva Brah Ndu khân may rŏng ma khân may, tâm plăch jêh nau rtăp rak jêng nau mât ton ma khân may, yor lah Yêhôva Brah Ndu khân may rŏng ma khân may.$b$,false),
('bunong-vn','DEU',23,6,null,$b$Lơi joi ôh nau đăp mpăn ma khân păng mâu lah nau khân păng hôm jêng hao âk lĕ rngôch rnôk khân may gŭ rêh.$b$,false),
('bunong-vn','DEU',23,7,null,$b$Lơi tâm rmot ôh ma du huê Êđôm, yor lah păng jêng oh nâu khân may. Lơi tâm rmot ôh ma du huê Êjipt yor lah khân may jêng jêh nơm gŭ jưh ƀât lât tâm n'gor păng.$b$,true),
('bunong-vn','DEU',23,8,null,$b$Phung kon khân păng deh ta rnôk tal pe dơi lăp tâm phung Yêhôva tâm rƀŭn.$b$,true),
('bunong-vn','DEU',23,9,null,$b$Tơ lah khân may hăn tâm lơh đah phung rlăng khân may jêh ri gŭ jưh, ăn khân may mât mray khân may nơm ma ăp ntil nau mhĭk.$b$,true),
('bunong-vn','DEU',23,10,null,$b$Tơ lah geh tâm khân may du huê bu klâu jêng ƀơ̆ yor nau tât ma păng dôl măng, pô ri ăn păng du luh bơh nkual, păng mâu dơi lăp tâm nkual ôh;$b$,false),
('bunong-vn','DEU',23,11,null,$b$ƀiă lah tơ lah tât mhaơ, păng mra ŭm tâm dak, jêh ri tơ lah nar nhâp jêh, păng dơi lăp tâm nkual.$b$,false),
('bunong-vn','DEU',23,12,null,$b$Ăn khân may geh du ntŭk pa dih nkual jêh ri khân may mra hăn ta ntŭk nây.$b$,false),
('bunong-vn','DEU',23,13,null,$b$Ăn khân may geh du mlâm mâng ndrel ma nau tâm lơh. Jêh ri tơ lah khân gŭ pa dih khân may mra kuyh ntu ma mâng nây jêh ri plơ̆ brôi lơi ek may.$b$,true),
('bunong-vn','DEU',23,14,null,$b$Yor lah Yêhôva Brah Ndu khân may hăn tâm nklang nkual khân may, gay ma tâm rklaih khân may, jêh ri ŭch jao phung rlăng khân may ta năp khân may, yor nây ăn nkual khân may jêng kloh ueh, gay ma păng mâu saơ ôh du ntil ndơ ƀơ̆ ta nklang khân may, jêh ri du lơi tă bơh khân may.$b$,false),
('bunong-vn','DEU',23,15,null,$b$Khân may mâu dơi jao ôh ma kôranh khân may du huê dĭk du jêh tă bơh kôranh păng ran ma khân may.$b$,true),
('bunong-vn','DEU',23,16,null,$b$Păng mra gŭ ndrel ma khân may ta nklang khân may tâm ntŭk păng mra săch tâm du rplay ƀon khân may ta ntŭk păng mĭn ueh lơn. Khân may mâu dơi tŭn jot ô băl ôh.$b$,false),
('bunong-vn','DEU',23,17,null,$b$Lơi ăn du huê bu ur văng tĭr ôh tâm phung kon bu ur Israel, mâu lĕ ăn geh du huê bu klâu yơk mbah ma kan ka n'hong tâm phung kon bu klâu Israel.$b$,true),
('bunong-vn','DEU',23,18,null,$b$Khân may djôt leo ta ngih Yêhôva Brah Ndu khân may rnoh nkhôm du huê bu ur văng tĭr, mâu lah rnoh du mlâm so jêng rnoh ƀư na nê̆ nau ton; yor lah lĕ bar ndơ nây jêng ndơ Yêhôva Brah Ndu khân may tâm rmot.$b$,true),
('bunong-vn','DEU',23,19,null,$b$Khân may mâu dơi an chan ndơ yor ŭch sa kao bơh ndơ sông sa, sa kao bơh ăp ntil ndơ khân may ăn chan jêh.$b$,true),
('bunong-vn','DEU',23,20,null,$b$Khân may dơi ăn du huê bu năch chan yor ŭch sa kao, ƀiă lah ma nâu khân may mâu mra ăn chan yor ŭch sa kao ôh; gay ma Yêhôva Brah Ndu khân may dơi mât ton nau ueh uĭn ma khân may tâm lĕ rngôch kan khân may ƀư tâm n'gor khân may lăp sŏk pha.$b$,false),
('bunong-vn','DEU',23,21,null,$b$Tơ lah khân may ƀư du nau ton ma Yêhôva Brah Ndu khân may, lơi ƀlao ƀư ăn păng nanê̆ yor lah nanê̆ Yêhôva Brah Ndu khân may mra ăn khân may ƀư nanê̆ jêh ri nau nây mra jêng tih ma khân may.$b$,true),
('bunong-vn','DEU',23,22,null,$b$Ƀiă lah tơ lah khân may mâu ƀư nau ton ôh, nau nây mâu jêng tih ma khân may ôh.$b$,true),
('bunong-vn','DEU',23,23,null,$b$Ăn khân may njrăng nanê̆ nau khân may ngơi jêh, yor lah khân may ton jêh ma nau ŭch ma Yêhôva Brah Ndu moh nau khân may ton jêh ma bâr mbung khân may.$b$,true),
('bunong-vn','DEU',23,24,null,$b$Tơ lah khân may lăp tâm đang play kriăk ƀâu nơm chiau meng khân may, khân may sa play kriăk ƀâu tĭng nâm dơi, ƀiă lah khân may mâu dơi pĕ play jêh ri prăp tâm bai khân may ôh.$b$,true),
('bunong-vn','DEU',23,25,null,$b$Tơ lah khân may lăp tâm mir ba oh nâu, khân may dơi tôch ndrŏng ba ma ti khân may, ƀiă lah khân may mâu dơi dŏng nhuĕ ôh gay rek ba phung chiau meng khân may.$b$,false),
('bunong-vn','DEU',24,1,null,$b$Tơ lah du huê bu klâu sŏk du huê bu ur ƀư ur, tơ lah păng mâu hôm geh nau ueh ma măt păng yor lah păng saơ tâm bu ur nau bêk prêng, jêh ri chih du pŏk sămƀŭt cha lơi păng jêh ri jao sămƀŭt nây ma păng, nsot lơi bơh ngih sai.$b$,true),
('bunong-vn','DEU',24,2,null,$b$Tơ lah păng hăn jêh ri jêng ur ma du huê bu klâu êng,$b$,false),
('bunong-vn','DEU',24,3,null,$b$tơ lah sai pa kơi aơ mâu rŏng ma păng ôh, chih ma păng du pŏk sămƀŭt cha lơi, jêh jao sămƀŭt nây ma păng nsot păng bơh ngih, mâu lah tơ lah sai pa kơi nây, nơm sŏk păng jêng ur khĭt jêh,$b$,false),
('bunong-vn','DEU',24,4,null,$b$pô ri sai tal lor, nơm nsot jêh păng, mâu dơi sŏk bu ur nây jêng ur ôh, jêh bu ur nây jêng ƀơ̆ jêh; yor nau nây jêng nau Yêhôva tâm rmot, jêh ri lơi ƀư tât ôh nau jêng dih ta neh Yêhôva Brah Ndu khân may ăn ma khân may jêng drăp ndơn.$b$,false),
('bunong-vn','DEU',24,5,null,$b$Tơ lah du huê bu klâu mhe tâm gŭ ur sai, păng mâu mra hăn ndrel phung Tahan mâu lah djôt du ntil kan ôh; păng mra gŭ mpăn ta ngih păng dôl tâm du năm, gay geh nau răm maak đah ur păng sŏk jêh.$b$,true),
('bunong-vn','DEU',24,6,null,$b$Bu mâu dơi sŏk ôh du mlâm mpăl mâu lah lŭ mpăl mpeh klơ jêng ndơ ton; yor lah nau nây jêng sŏk du nau rêh jêng ndơ ton.$b$,true),
('bunong-vn','DEU',24,7,null,$b$Tơ lah bu saơ du huê bunuyh ntŭng sŏk du huê oh nâu păng phung ƀon lan Israel. Jêh ri tơ lah păng njêng ô băl jêng du huê dĭk mâu lah tăch ô băl, pô ri nơm ntŭng nây mra khĭt. Pô ri khân may mra ƀư kloh nau mhĭk tâm nklang khân may.$b$,true),
('bunong-vn','DEU',24,8,null,$b$Njrăng hom tâm nau geh phŭng, ăn njrăng ngăn ƀư tĭng nâm lĕ rngôch nau phung kôranh ƀư brah Lêvi mra ntăm gai khân may; tĭng nâm gâp ntăm jêh ma khân păng, pô ri khân may mra ƀư.$b$,true),
('bunong-vn','DEU',24,9,null,$b$Ăn khân may kah gĭt nau Yêhôva Brah Ndu khân may ƀư jêh ma H'Miriam rŏ trong dôl khân păng du luh tă bơh n'gor Êjipt.$b$,false),
('bunong-vn','DEU',24,10,null,$b$Tơ lah khân may ăn nơm chiau meng khân may chan du ntil ndơ, khân may mâu dơi lăp ôh tâm ngih păng gay sŏk ndơ păng ton.$b$,true),
('bunong-vn','DEU',24,11,null,$b$Ăn khân may gŭ pa dih, jêh ri bunuyh khân may ăn chan mra djôt leo ndơ ton ma khân may pa dih.$b$,false),
('bunong-vn','DEU',24,12,null,$b$Tơ lah nơm nây jêng bunuyh o ach khân may mâu dơi bêch ôh tâm ndơ păng nchăm.$b$,false),
('bunong-vn','DEU',24,13,null,$b$Tơ lah nar nhâp, ăn khân may mplơ̆ ndơ nchăm ma păng gay ma păng dơi bêch tâm ao jâr păng jêh ri mât ton ma khân may; nau nây mra jêng nau sŏng srăng ma khân may ta năp Yêhôva Brah Ndu khân may.$b$,false),
('bunong-vn','DEU',24,14,null,$b$Khân may mâu dơi tŭn jot ôh du huê oh mon nkhôm jêng o ach jêh ri pưt mpa, gĭt lah păng jêng du huê oh nâu khân may mâu lah du huê gŭ jưh ƀât lât tâm n'gor jêh ri tâm ƀon khân may.$b$,true),
('bunong-vn','DEU',24,15,null,$b$Ăn khân may ăn nau nkhôm ma păng ta nar păng pah kan, lor ma nar nhâp, yor lah păng jêng o ach, jêh ri kâp gân ma nau nkhôm nây; klach lah păng mra nter ma Yêhôva, jêh ri nau nây jêng tih tâm may.$b$,false),
('bunong-vn','DEU',24,16,null,$b$Bu mâu dơi nkhĭt mbơ̆ yor phung kon ôh; mâu lĕ bu dơi nkhĭt phung kon yor phung mbơ̆ ; bu mra nkhĭt nơm yor nau tih păng nơm.$b$,true),
('bunong-vn','DEU',24,17,null,$b$Khân may mâu dơi ƀư tih nau sŏng ôh ma nơm gŭ jưh ƀât lât mâu lah ma kon đơi mbơ̆ , mâu lah sŏk bok ao bu ur khĭt sai jêng ndơ nchăm.$b$,false),
('bunong-vn','DEU',24,18,null,$b$Ƀiă lah ăn khân may kah gĭt nau khân may jêng jêh dĭk tâm n'gor Êjipt jêh ri Yêhôva Brah Ndu khân may tâm chuai jêh khân may bơh ntŭk nây; yor nây gâp ntăm ma khân may bơh ƀư nau aơ.$b$,false),
('bunong-vn','DEU',24,19,null,$b$Tơ lah khân may roih rek ba tâm mir khân may, jêh ri chuêl du nchăp ba tâm mir, lơi hôm hăn sŏk păng ôh; nchăp ba nây mra prăp ma nơm gŭ jưh ƀât lât, ma kon đơi mbơ̆ , jêh ri ma bu ur ndrô khĭt sai; gay ma Yêhôva Brah Ndu khân may dơi mât ton ma khân may tâm lĕ rngôch kan ti khân may ƀư.$b$,true),
('bunong-vn','DEU',24,20,null,$b$Tơ lah khân may mprah play Ôlivơ, lơi hôm mprah tal bar ôh; play nây mra prăp ma nơm gŭ jưh ƀât lât, ma kon đơi mbơ̆ , jêh ri ma bu ur khĭt sai.$b$,false),
('bunong-vn','DEU',24,21,null,$b$Tơ lah khân may pĕ play bơh đang play kriăk ƀâu khân may, lơi hôm pĕ tal bar ôh; nây mra prăp ma nơm gŭ jưh ƀât lât, ma kon đơi mbơ̆ , jêh ri ma bu ur ndrô khĭt sai.$b$,false),
('bunong-vn','DEU',24,22,null,$b$Ăn khân may kah gĭt ma nau khân may jêng jêh dĭk tâm n'gor Êjipt; yor nây gâp ntăm ma khân may ƀư nau aơ.$b$,false),
('bunong-vn','DEU',25,1,null,$b$Tơ lah geh nau tâm lah tâm djrel ndrăng phung bu klâu jêh ri khân păng hăn ma nau phat dôih, jêh ri phung Kôranh phat dôih mra ngơi an dôih, kơp sŏng bunuyh sŏng jêh ri tâm rmal bunuyh tih.$b$,true),
('bunong-vn','DEU',25,2,null,$b$Tơ lah bu klâu jêng tih jêh ri khư bu dong, kôranh phat dôih mra ăn păng chon mon ta neh ăn bu dong păng ta năp păng dŭm tơ̆ tĭng nâm khư ma nau tih păng.$b$,false),
('bunong-vn','DEU',25,3,null,$b$Bu dơi dong păng puăn jât tong, ƀiă lah mâu dơi rlau ma nây ôh, klach lah tơ lah hôm dong păng âk lơn ma nây, bu ƀư bêk oh nâu khân may ta năp măt khân may.$b$,true),
('bunong-vn','DEU',25,4,null,$b$Lơi put ôh mbung ndrôk gŭ jot ba.$b$,true),
('bunong-vn','DEU',25,5,null,$b$Tơ lah phung oh nâu gŭ rêh ndrel, jêh ri du huê tâm khân păng khĭt mâu geh kon bu klâu ôh, ur nơm khĭt nây mâu hôm dơi gŭ sai tâm ndŭl mpôl êng ôh; oh sai păng mra hăn ta păng jêh ri sŏk păng jêng ur, jêh ri ƀư tĭng nâm nau vay di ma oh sai păng.$b$,true),
('bunong-vn','DEU',25,6,null,$b$Kon bu klâu păng mra deh lor mra geh amoh nâu păng, nơm khĭt jêh, gay ma amoh păng mâu jut ôh bơh phung Israel.$b$,false),
('bunong-vn','DEU',25,7,null,$b$Tơ lah nơm nây mâu ŭch gŭ ur nâu păng ôh, dôl nây ur nâu păng mra hăn ta mpông pêr ta phung bu bŭnh bu ranh jêh ri lah, oh sai gâp dun prăp amoh nâu păng tâm phung Israel; păng mâu ŭch ƀư ôh ma gâp tĭng nâm nau vay di ma du huê oh sai.$b$,true),
('bunong-vn','DEU',25,8,null,$b$Pô ri phung bu bŭnh bu ranh ƀon nây mra kuăl ngơi đah păng; jêh ri tơ lah păng ăt dun, lah: ‘Gâp mâu ŭch gŭ păng ôh.’$b$,false),
('bunong-vn','DEU',25,9,null,$b$Pô ri ur nâu păng mra hăn ta păng ta năp phung bu bŭnh bu ranh, doh lơi ntâu jot tă bơh jâng păng, jêh ri soh dak diu ta muh măt păng, păng mra ngơi lah, ‘Pô nây bu ƀư ma bunuyh mâu ŭch rdâk ngih nâu păng.’$b$,false),
('bunong-vn','DEU',25,10,null,$b$Tâm phung Israel ngih păng bu rnha ngih bunuyh bu doh lơi jêh ntâu jot păng.$b$,false),
('bunong-vn','DEU',25,11,null,$b$Tơ lah du huê bu klâu tâm nhăt đah du huê êng, jêh ri ur du huê văch êp gay ma koh dŏng sai păng bơh ti bu dong păng, jêh ri yơr ti geh nhŭp kuang bu klâu nây,$b$,true),
('bunong-vn','DEU',25,12,null,$b$Pô ri khân may koh lơi ti bu ur nây; lơi uănh păng ma nau yô̆ ôh.$b$,false),
('bunong-vn','DEU',25,13,null,$b$Lơi ăn geh tâm dŭng khân may bar ntil ndơ jâk ôh, du ntil jê̆ jêh ri du ntil toyh.$b$,true),
('bunong-vn','DEU',25,14,null,$b$Lơi ăn geh tâm ngih khân may bar ntil njing ôh du ntil toyh jêh ri du ntil jê̆.$b$,true),
('bunong-vn','DEU',25,15,null,$b$Ăn khân may geh play jâk ăp jêh ri sŏng, ăn khân may geh tâm ban lĕ ndơ veh bêng ăp jêh ri sŏng, gay ma nar khân may gŭ rêh dơi jêng jŏ lơn tâm n'gor Yêhôva ndŭl mpôl khân may ăn ma khân may.$b$,false),
('bunong-vn','DEU',25,16,null,$b$Yêhôva lĕ rngôch mbu nâm ƀư pô nây, ƀư ma nau mâu sŏng jêng nơm Yêhôva Brah Ndu khân may tâm rmot ngăn.$b$,false),
('bunong-vn','DEU',25,17,null,$b$Ăn khân may kah gĭt moh phung Amalek ƀư jêh ma khân may rŏ trong dôl khân may luh bơh n'gor Êjipt.$b$,true),
('bunong-vn','DEU',25,18,null,$b$Nau khân păng tâm lơh đah khân may rŏ trong, dôl khân may jêng huăr jêh ri rgănh, jêh ri ƀư rai lơi lĕ phung tĭng groi kơi khân may; jêh ri păng mâu klach ma Brah Ndu ôh.$b$,false),
('bunong-vn','DEU',25,19,null,$b$Yor nây tơ lah Yêhôva Brah Ndu khân may ăn jêh ma khân may nau rlu bơh lĕ rngôch phung rlăng khân may gŭ jŭm tâm n'gor Yêhôva Brah Ndu khân may ăn jêng drăp ndơn khân may sŏk pha, ăn khân may jut lơi nau kah gĭt ma phung Amalek bơh tâm dâng trôk; lơi chuêl ôh.$b$,false),
('bunong-vn','DEU',26,1,null,$b$Tơ lah khân may lăp jêh tâm n'gor Yêhôva Brah Ndu khân may ăn jêh ma khân may jêng drăp ndơn sŏk pha, jêh ri gŭ tâm păng,$b$,true),
('bunong-vn','DEU',26,2,null,$b$ăn khân may sŏk ƀa ƀă play kao bơh lĕ rngôch play bơh neh, play khân may pĕ tâm n'gor khân may Yêhôva Brah Ndu khân may ăn jêh ma khân may, dơm tâm du mlâm bĭ jêh ri hăn ta ntŭk Yêhôva Brah Ndu khân may mra săch, gay ăn amoh păng gŭ ta nây.$b$,false),
('bunong-vn','DEU',26,3,null,$b$Ăn khân may hăn ta kôranh ƀư brah gŭ ƀư kan dôl nây jêh ri lah ma păng: ‘Gâp mbơh nar aơ ma Yêhôva Brah Ndu may nau gâp lăp jêh tâm n'gor Yêhôva ton jêh ma phung che he gay ăn ma he.’$b$,false),
('bunong-vn','DEU',26,4,null,$b$Pô ri kôranh ƀư brah mra sŏk bĭ bơh ti păng, jêh ri dơm ta năp nơng Yêhôva Brah Ndu khân may.$b$,false),
('bunong-vn','DEU',26,5,null,$b$Khân may mra geh nau ngơi ta năp Yêhôva Brah Ndu khân may: ‘Mbơ̆ gâp jêng du huê bunuyh Aram nsong mblêng; păng jŭr hăn ta n'gor Êjipt jêh ri gŭ jưh ƀât lât ta nây, jêng du phung djê̆; jêh ri ta nây plăch jêng du ndŭl mpôl toyh, ktang jêh ri âk.$b$,true),
('bunong-vn','DEU',26,6,null,$b$Phung Êjipt ƀư brai ma hên jêh ri ƀư rêh ni hên ăn hên ndô nau jêng dĭk dăng ngăn,$b$,true),
('bunong-vn','DEU',26,7,null,$b$Pô ri hên nter nđêng ma Yêhôva Brah Ndu phung che hên, jêh ri Yêhôva tăng bâr hên jêh ri păng saơ nau rêh ni hên, nau ŏk hên jêh ri nau bu tŭn jot hên.$b$,false),
('bunong-vn','DEU',26,8,null,$b$Jêh ri Yêhôva njŭn hên ngluh jêh bơh n'gor Êjipt ma ti brah jêh ri nting tur yơr jêh, ma nau nkrit toyh, ma nau tâm mbên jêh ri nau khlay.$b$,false),
('bunong-vn','DEU',26,9,null,$b$Păng njŭn jêh hên lăp tâm ntŭk aơ jêh ri ăn ma hên n'gor aơ, n'gor geh ndơ sông sa nhêt rmeh ler.$b$,true),
('bunong-vn','DEU',26,10,null,$b$Jêh ri aơ, gâp djôt leo play kao bơh neh, play nây may ăn jêh ma gâp, Ơ Yêhôva.’ Khân may mra dơm păng ta năp Yêhôva Brah Ndu khân may, jêh ri mbah yơk ta năp Yêhôva Brah Ndu khân may.$b$,false),
('bunong-vn','DEU',26,11,null,$b$Jêh ri khân may mra răm maak ndrel ma lĕ rngôch nau ueh Yêhôva Brah Ndu khân may ăn jêh ma khân may, ma khân may jêh ri ma ngih khân may, khân may, phung Lêvi jêh ri nơm gŭ jưh ƀât lât ta nklang khân may.$b$,false),
('bunong-vn','DEU',26,12,null,$b$Tơ lah khân may ƀư lôch jêh nhhơr lĕ rngôch ndơ du kô̆ tâm jât bơh ndơ khân may geh ta năm tal lor, nây jêng năm bu nhhơr ndơ du kô̆ tâm jât, dôl ăn ma phung Lêvi, ma nơm gŭ jưh ƀât lât, ma kon đơi mbơ̆ , jêh ri bu ur ndrô khĭt sai, gay ma khân păng dơi sông sa jêh ri hơm tâm ƀon khân may,$b$,true),
('bunong-vn','DEU',26,13,null,$b$pô ri khân may mra lah ta năp Yêhôva Brah Ndu khân may, ‘Gâp sŏk jêh bơh ngih gâp kô̆ kloh ueh, jêh ri gâp ăn jêh ndơ nây ma phung Lêvi, ma nơm gŭ jưh ƀât lât ma kon đơi mbơ̆ , jêh ri tĭng nâm lĕ nau ntăm may ăn jêh ma gâp; gâp mâu mâp rlau du ntil nau may ntăm ôh; mâu lĕ mâp chuêl khân păng.$b$,false),
('bunong-vn','DEU',26,14,null,$b$Gâp mâu mâp sa ôh ndơ du kô̆ tâm jât dôl gâp gŭ ndrê ndjăng, mâu lah sŏk ndơ nây bơh ngih gâp dôl gâp jêng ƀơ̆ , mâu lah nhhơr păng ma bunuyh khĭt; gâp tông jêh bâr Yêhôva Brah Ndu gâp, gâp ƀư jêh tĭng nâm lĕ nau may ntăm jêh ma gâp.$b$,false),
('bunong-vn','DEU',26,15,null,$b$Mêt uănh hom bơh ntŭk kloh ueh may gŭ, bơh trôk, jêh ri mât ton hom ma phung ƀon lan Israel jêh ri n'gor may ăn jêh ma hên, tĭng nâm may ton jêh ma phung che hên, n'gor geh ndơ sông sa nhêt rmeh ler.’$b$,false),
('bunong-vn','DEU',26,16,null,$b$Nar aơ Yêhôva Brah Ndu khân may ntăm ăn khân may tông nau vay jêh ri nau ntăm aơ; pô ri ăn khân may ƀư tĭng kơt nau nây ma lĕ nuih n'hâm jêh ri ma lĕ huêng khân may.$b$,false),
('bunong-vn','DEU',26,17,null,$b$Nar aơ khân may mbơh jêh Yêhôva Brah Ndu khân may jêh ri khân may ŭch hăn tâm trong păng, jêh ri djôt prăp nau vay păng, nau păng ntăm, nau vay păng ăn, jêh ri tông bâr păng.$b$,false),
('bunong-vn','DEU',26,18,null,$b$Jêh ri nar aơ Yêhôva mbơh jêh ma khân may jêng du phung ƀon lan prăp ma păng nơm, tĭng nâm păng ton jêh ma khân may, jêh ri khân may mra djôt prăp lĕ nau păng ntăm.$b$,false),
('bunong-vn','DEU',26,19,null,$b$Pô ri păng mra n'hao khân may ta klơ lĕ rngôch ndŭl mpôl êng păng rhăk njêng jêh, tâm nau tâm rnê, nau lư n'găr, jêh ri nau yơk, jêh ri khân may mra jêng du phung ƀon lan kloh ueh prăp an ma Yêhôva Brah Ndu khân may, tĭng nâm păng lah jêh.’$b$,true),
('bunong-vn','DEU',27,1,null,$b$Y-Môis jêh ri phung bu bŭnh bu ranh Israel ntăm ma phung ƀon lan lah: “Djôt prăp hom lĕ rngôch nau ntăm gâp ăn ma khân may nar aơ.$b$,true),
('bunong-vn','DEU',27,2,null,$b$“Ta nar khân may rgăn dak krong Yurdan lăp tâm n'gor Yêhôva Brah Ndu khân may ăn ma khân may, ăn khân may rdâk âk lŭ toyh jêh ri mhĭng ma klo.$b$,true),
('bunong-vn','DEU',27,3,null,$b$Ăn khân may chih ta klơ lŭ nây lĕ rngôch rplay ngơi nau vay aơ, tơ lah khân may rgăn lăp n'gor Yêhôva Brah Ndu khân may ăn ma khân may, n'gor geh mpa sông sa nhêt rmeh ler tĭng nâm Yêhôva Brah Ndu phung che khân may ton jêh ma khân may.$b$,false),
('bunong-vn','DEU',27,4,null,$b$Jêh ri tơ lah khân may rgăn jêh dak krong Yurdan, ăn khân may rdâk lŭ aơ tĭng nâm gâp ntăm ma khân may nar aơ ta klơ yôk Êbal jêh ri mhĭng ma klo.$b$,false),
('bunong-vn','DEU',27,5,null,$b$Ta nây ăn khân may rdâk du mlâm nơng ma Yêhôva Brah Ndu khân may, du mlâm nơng ma lŭ; lơi dŏng ndơ loih ôh dôl nkra khân păng.$b$,false),
('bunong-vn','DEU',27,6,null,$b$Ăn khân may ƀư du mlâm nơng ma Yêhôva Brah Ndu khân may ma lŭ tang kră, ê hŏ mâp bu trah ôh, jêh ri ta klơ nơng nây ăn khân may nhhơr mpa nhhơr gŭch ma Yêhôva Brah Ndu khân may.$b$,false),
('bunong-vn','DEU',27,7,null,$b$Ăn khân may nhhơr mpa ƀư brah ma nau đăp mpăn, jêh ri sa ta nây; jêh ri khân may mra răm maak ta năp Yêhôva Brah Ndu khân may.$b$,false),
('bunong-vn','DEU',27,8,null,$b$Ăn khân may chih ma nau ang ngăn ta klơ lŭ aơ lĕ rngôch rplay ngơi nau vay aơ.”$b$,false),
('bunong-vn','DEU',27,9,null,$b$Y-Môis jêh ri phung kôranh ƀư brah Lêvi lah ma lĕ rngôch phung Israel. Gŭ rklăk jêh ri gŭ iăt hom, Ơ phung Israel: “Nar aơ khân may jêng jêh phung ƀon lan Yêhôva Brah Ndu khân may.$b$,true),
('bunong-vn','DEU',27,10,null,$b$Pô ri ăn khân may tông bâr ma Yêhôva Brah Ndu khân may, djôt prăp nau păng ntăm jêh ri nau vay păng gâp ăn jêh ma khân may nar aơ.”$b$,false),
('bunong-vn','DEU',27,11,null,$b$Nar nây lĕ Y-Môis ntăm ma phung ƀon lan lah:$b$,true),
('bunong-vn','DEU',27,12,null,$b$“Tơ lah khân may rgăn jêh dak krong Yurdan, phung aơ mra gŭ râng ta klơ yôk Gêrasim gay mât ton ma phung ƀon lan phung Simêôn, phung Lêvi, phung Yuđa, phung Isakar, phung Yôsep jêh ri phung Benjamin.$b$,false),
('bunong-vn','DEU',27,13,null,$b$Jêh ri phung aơ mra dâk ta klơ yôk Êbal ma nau rtăp rak: Phung Ruben, phung Gad, phung Aser, phung Sabulôn, phung Dan, jêh ri phung Naptali.$b$,false),
('bunong-vn','DEU',27,14,null,$b$Phung Lêvi mra mbơh ma lĕ rngôch bu klâu Israel ma bâr huy ktang.$b$,false),
('bunong-vn','DEU',27,15,null,$b$Rtăp rak lơi ma nơm ƀư rup trah, mâu lah rup tŏ, ndơ Yêhôva tâm rmot ngăn, ndơ ti njêh n'hŭ kon bunuyh ƀư, jêh ri rdâk ndơ nây ma nau ndâp! Jêh ri lĕ rngôch phung ƀon lan mra plơ̆ lah, Amen!$b$,true),
('bunong-vn','DEU',27,16,null,$b$Rtăp rak lơi ma nơm ƀư bêk mbơ̆ me păng jêh ri lĕ rngôch phung ƀon lan mra lah, Amen!$b$,true),
('bunong-vn','DEU',27,17,null,$b$Rtăp rak lơi ma nơm tâm plăch n'har bri nơm chiau meng păng jêh ri lĕ rngôch phung ƀon lan mra lah, Amen!$b$,false),
('bunong-vn','DEU',27,18,null,$b$Rtăp rak lơi ma nơm ƀư chuêl trong du huê bunuyh chieh măt. Jêh ri lĕ rngôch phung ƀon lan mra lah, Amen!$b$,true),
('bunong-vn','DEU',27,19,null,$b$Rtăp rak lơi ma nơm ƀư tih nau sŏng geh ma nơm gŭ jưh ƀât lât, ma kon đơi mbơ̆ , jêh ri ma bu ur ndrô khĭt sai. Jêh ri lĕ rngôch phung ƀon lan mra lah, ‘Amen’$b$,true),
('bunong-vn','DEU',27,20,null,$b$Rtăp rak lơi ma nơm bêch đah ur mbơ̆ păng, yor lah păng suk nơm jêng ndơ mbơ̆ păng. Jêh ri lĕ rngôch phung ƀon lan mra lah, ‘Amen’$b$,false),
('bunong-vn','DEU',27,21,null,$b$Rtăp rak ma nơm bêch đah du ntil mpô mpa. Jêh ri lĕ rngôch phung ƀon lan mra lah, ‘Amen’$b$,false),
('bunong-vn','DEU',27,22,null,$b$Rtăp rak lơi ma nơm bêch ndrel oh, ruh păng, gĭt lah đah kon bu ur mbơ̆ păng mâu lah kon bu ur me păng. Jêh ri lĕ rngôch phung ƀon lan mra lah, ‘Amen’$b$,false),
('bunong-vn','DEU',27,23,null,$b$Rtăp rak ma nơm bêch đah po bu ur păng. Jêh ri lĕ rngôch phung ƀon lan mra lah, ‘Amen’$b$,false),
('bunong-vn','DEU',27,24,null,$b$Rtăp rak lơi ma nơm nkhĭt nơm chiau meng păng ma nau ndâp, Jêh ri lĕ rngôch phung ƀon lan mra lah, ‘Amen’$b$,false),
('bunong-vn','DEU',27,25,null,$b$Rtăp rak lơi ma nơm sŏk dơn drăp bu blŏl gay ma nkhĭt du huê mâu geh nau tih ôh jêh ri lĕ rngôch ƀon lan mra lah, ‘Amen’$b$,false),
('bunong-vn','DEU',27,26,null,$b$Rtăp rak lơi ma nơm mâu ƀư nanê̆ ôh rplay ngơi nau vay aơ ma nau ƀư tĭng kơt khân păng. Jêh ri lĕ rngôch phung ƀon lan mra lah, ‘Amen’$b$,false),
('bunong-vn','DEU',28,1,null,$b$Tơ lah khân may tông bâr ma Yêhôva Brah Ndu khân may dôl njrăng ƀư lĕ rngôch nau păng ntăm gâp ăn ma khân may nar aơ. Yêhôva Brah Ndu khân may mra n'hao ta klơ lĕ rngôch phung ndŭl mpôl ta neh ntu.$b$,true),
('bunong-vn','DEU',28,2,null,$b$Lĕ rngôch nau ueh uĭn aơ mra tât ma khân may jêh ri jêng ndơ khân may tơ lah khân may tông bâr Yêhôva Brah Ndu khân may.$b$,false),
('bunong-vn','DEU',28,3,null,$b$Khân may mra geh nau ueh uĭn tâm ƀon, jêh ri khân may mra geh nau ueh uĭn tâm mir.$b$,true),
('bunong-vn','DEU',28,4,null,$b$Mra geh nau ueh uĭn ma play ndŭl proch khân may, play bơh neh khân may, play bơh mpô mpa khân may ma kon ndrôk khân may, jêh ri ma kon biăp khân may.$b$,false),
('bunong-vn','DEU',28,5,null,$b$Mra geh nau ueh uĭn ma bĭ khân may jêh ri hip khân may mon piăng let.$b$,false),
('bunong-vn','DEU',28,6,null,$b$Khân may mra geh nau ueh uĭn tơ lah khân may lăp, jêh ri khân may mra geh nau ueh uĭn tơ lah khân may luh.$b$,true),
('bunong-vn','DEU',28,7,null,$b$Yêhôva mra ăn phung rlăng dâk ƀư ma khân may roh ta năp khân may; khân păng mra tât ƀư ma khân may bơh du trong, jêh ri du ta năp khân may ma pơh trong.$b$,false),
('bunong-vn','DEU',28,8,null,$b$Yêhôva mra ntăm nau ueh uĭn ma khân may tâm jay khân may, jêh ri tâm lĕ rngôch kan khân may ƀư; păng mra ăn nau ueh uĭn ma khân may tâm n'gor Yêhôva Brah Ndu khân may ăn ma khân may.$b$,false),
('bunong-vn','DEU',28,9,null,$b$Yêhôva mra njêng khân may du phung ƀon lan kloh ueh ma păng nơm, tĭng nâm păng ton jêh ma khân may, tơ lah khân may djôt prăp nau Yêhôva Brah Ndu khân may ntăm jêh ri hăn tâm trong păng.$b$,true),
('bunong-vn','DEU',28,10,null,$b$Lĕ rngôch phung ƀon lan ta neh ntu mra saơ bu rnha ma khân may ma amoh Yêhôva jêh ri khân păng mra klach ma khân may.$b$,false),
('bunong-vn','DEU',28,11,null,$b$Yêhôva mra ăn jêng hao khân may, ăn bĭk rơ̆ play bơh ndŭl proch play bơh mpô mpa rong khân may jêh ri play bơh mpô mpa rong khân may, jêh ri play bơh neh khân may tâm n'gor Yêhôva ton jêh ma phung che khân may ŭch ăn ma khân păng.$b$,true),
('bunong-vn','DEU',28,12,null,$b$Yêhôva mra pơk drăp khlay păng tâm trôk gay ăn dak mih ma n'gor khân may di yăn păng, jêh ri gay ăn nau ueh uĭn ma lĕ rngôch kan ti khân may ƀư jêh ri khân may mra ăn ma âk ndŭl mpôl chan ƀiă lah khân may mâu mra chan ôh.$b$,true),
('bunong-vn','DEU',28,13,null,$b$Yêhôva mra njêng khân may jêng bôk mâu geh chiăng ôh; jêh ri khân may mra hao ƀa ƀơ leo klơ, jêh ri mâu jŭr ôh; tơ lah khân may tông nau Yêhôva Brah Ndu khân may ntăm, gâp ăn jêh ma khân may nar aơ, dôl njrăng kơt ƀư tĭng nâm nau nây,$b$,true),
('bunong-vn','DEU',28,14,null,$b$jêh ri tơ lah khân may mâu teng pa ma mâu lah pa chiau ôh bơh nau ngơi gâp ntăm ma khân may nar aơ, gay tĭng ƀư kơt phung brah êng jêh ri pah kan ma khân păng.$b$,false),
('bunong-vn','DEU',28,15,null,$b$Ƀiă lah tơ lah khân may mâu tông ôh bâr Yêhôva Brah Ndu khân may mâu lah mâu njrăng ƀư lĕ rngôch nau păng ntăm jêh ri lĕ nau vay păng gâp ăn ma khân may nar aơ, pô ri lĕ rngôch nau rtăp rak aơ mra tât ma khân may jêh ri ban khân may.$b$,true),
('bunong-vn','DEU',28,16,null,$b$Khân may mra geh nau rtăp rak tâm ƀon, jêh ri khân may mra geh nau rtăp rak tâm mir.$b$,true),
('bunong-vn','DEU',28,17,null,$b$Bĭ khân may jêh ri hip mon piăng let khân may mra geh nau rtăp rak.$b$,false),
('bunong-vn','DEU',28,18,null,$b$Mra geh nau rtăp rak ma play bơh ndŭl proch khân may, play bơh neh khân may, play bơh ndrôk khân may jêh ri play bơh biăp khân may.$b$,true),
('bunong-vn','DEU',28,19,null,$b$Khân may mra geh nau rtăp rak tơ lah khân may lăp, khân may mra geh nau rtăp rak tơ lah khân may luh.$b$,true),
('bunong-vn','DEU',28,20,null,$b$Yêhôva mra njuăl ma khân may nau rtăp rak, jêh ri nau ƀư uh ah nau rtăp rak, tâm lĕ rngôch kan khân may mĭn ŭch ƀư, kŏ tât khân may rai jêh ri gơnh roh, yor nau ƀai khân may ƀư, yor nau khân may cha lơi gâp jêh.$b$,false),
('bunong-vn','DEU',28,21,null,$b$Yêhôva mra ăn nau ji tâm nkhĭt iang đah khân may kŏ păng ƀư rai lĕ khân may bơh n'gor khân may gŭ lăp gay sŏk pha.$b$,false),
('bunong-vn','DEU',28,22,null,$b$Yêhôva mra dong khân may ma nau ji hiăn (hen), nau ji kăt, nau luh, nau duh ktang, nau sơh kro, nau klêu, jêh ri nau chăt nđo. Nau nây mra tĭng khân may kŏ khân may rai lôch.$b$,false),
('bunong-vn','DEU',28,23,null,$b$Trôk klơ bôk khân may mra jêng tâm ban ma kông jêh ri neh tâm dâng khân may mra jêng tâm ban loih.$b$,false),
('bunong-vn','DEU',28,24,null,$b$Yêhôva mra ăn dak mih ma n'gor khân may plăch jêng rmuy jêh ri ndruyh; ndơ nây mra jŭr bơh trôk tât ta khân may kŏ khân may rai lôch.$b$,false),
('bunong-vn','DEU',28,25,null,$b$Yêhôva mra ăn khân may roh tâm lơh ta năp phung rlăng khân may; khân may mra luh ƀư ma khân păng bơh du trong, jêh ri khân may mra du đah pơh trong ta năp khân păng, jêh ri khân păng mra jêng du mpa nhhu ƀư klach ma lĕ rngôch ƀon bri hađăch ta neh ntu.$b$,true),
('bunong-vn','DEU',28,26,null,$b$Săk jăn khĭt khân may mra jêng mpa sông sa ma lĕ rngôch sĭm tâm trôk jêh ri ma mpa bri ta neh ntu; jêh ri mâu mra geh du huê ntrŭt khân păng du ôh.$b$,false),
('bunong-vn','DEU',28,27,null,$b$Yêhôva mra dong khân may ma eh n'gor Êjipt, nau toh ok dô plach, kuh, jêh ri nau ji chiăt, khân may mâu dơi ƀư bah ôh.$b$,false),
('bunong-vn','DEU',28,28,null,$b$Yêhôva mra dong khân may ma nau rluk, nau chieh măt nau mĭn tâm luk rlăk.$b$,false),
('bunong-vn','DEU',28,29,null,$b$Jêh ri khân may mra joi rơ vơ dôl nklang bôk nar tâm ban ma bunuyh chieh măt joi but rơ vơ tâm nau ngo, jêh ri khân may mâu mra jêng hao ôh tâm trong khân may; jêh ri bu mra tŭn jot khân may, ntŭng ndô ndơ khân may ƀa ƀơ, jêh ri mâu geh du huê bu kơl khân may ôh.$b$,false),
('bunong-vn','DEU',28,30,null,$b$Khân may mra tâm mbloh đah du huê bu ur, ƀiă lah du huê bu klâu êng mra bêch đah păng; khân may mra rdâk du rplay ngih, ƀiă lah khân may mâu mra gŭ ôh tâm ngih nây; khân may mra tăm đang play kriăk ƀâu, ƀiă lah khân may mâu mra sa play păng ôh.$b$,true),
('bunong-vn','DEU',28,31,null,$b$Bu mra seh ndrôk khân may ta năp măt khân may, jêh ri khân may mâu mra sa păng ôh; bu mra nhŭp pit seh bri khân may ta năp muh măt khân may jêh ri bu mâu mra mplơ̆ păng ma khân may ôh; bu mra ăn biăp khân may ma phung rlăng khân may, jêh ri mâu geh nơm mra kơl khân may ôh.$b$,false),
('bunong-vn','DEU',28,32,null,$b$Bu mra jao phung kon bu klâu jêh ri phung kon bu ur khân may ma phung ƀon lan êng dôl măt khân may gŭ kâp uănh jêh ri rngot klâng ma khân păng lĕ nar; jêh ri ti khân may mâu mra geh nau ktang dơi buay nau nây ôh.$b$,false),
('bunong-vn','DEU',28,33,null,$b$Du phung ndŭl mpôl khân may mâu mâp gĭt năl ôh mra sa play bơh neh khân may jêh ri bơh lĕ kan khân may; jêh ri Knŏng bu mra tŭn jot jêh ri blên khân may ƀa ƀơ.$b$,false),
('bunong-vn','DEU',28,34,null,$b$Pô ri khân may mra jêng rluk yor nau măt khân may mra saơ.$b$,false),
('bunong-vn','DEU',28,35,null,$b$Yêhôva mra dong khân may ta kômâk jêh ri ta jâng ma eh ji ngăn, khân may mâu dơi ƀư bah ôh, bơh mpang jâng tât ta klơ bôk khân may.$b$,false),
('bunong-vn','DEU',28,36,null,$b$Yêhôva mra njŭn leo khân may jêh ri hađăch khân may dơm jêh ma khân may nơm ma du ndŭl mpôl khân may mâu lah phung che khân may mâu mâp gĭt năl ôh. Jêh ri ta nây khân may mra pah kan ma phung brah êng ma si jêh ri ma lŭ.$b$,false),
('bunong-vn','DEU',28,37,null,$b$Jêh ri khân may mra jêng du ndơ tâm nhhu jêh ri du nau hôr, du ntil bu djôt bir srơh ta nklang lĕ rngôch phung ƀon lan Yêhôva mra njŭn leo khân may.$b$,false),
('bunong-vn','DEU',28,38,null,$b$Khân may mra njŭn leo âk ntil tuch ta mir khân may, jêh ri mra roih rek djê̆, yor lah krah mra sa păng.$b$,true),
('bunong-vn','DEU',28,39,null,$b$Khân may mra tăm jêh ri nkra đang play kriăk ƀâu, ƀiă lah khân may mâu mra nhêt dak mâu lah pĕ play păng ôh, yor lah ndrŭng mra sa păng.$b$,false),
('bunong-vn','DEU',28,40,null,$b$Khân may mra geh tơm play Ôlivơ tâm lam n'gor khân may, ƀiă lah khân may mâu mra mhĭng dak bơh nây ôh; yor lah play Ôlivơ khân may mra rŭng.$b$,false),
('bunong-vn','DEU',28,41,null,$b$Khân may mra deh ma phung kon bu klâu jêh ri kon bu ur, ƀiă lah khân păng mâu mra jêng ndơ khân may ôh, yor lah khân păng mra hăn jêng bu nă.$b$,false),
('bunong-vn','DEU',28,42,null,$b$Lĕ rngôch tơm si jêh ri play bơh neh khân may mra jêng ndơ krah.$b$,false),
('bunong-vn','DEU',28,43,null,$b$Nơm gŭ jưh ƀât lât ta nklang khân may mra hao klơ lơn ma khân may ƀa ƀơ, jêh ri khân may mra jŭr ƀa ƀơ.$b$,true),
('bunong-vn','DEU',28,44,null,$b$Păng mra ăn khân may chan, ƀiă lah khân may mâu mra ăn păng chan ôh; păng mra jêng bôk jêh ri khân may mra jêng chiăng.$b$,false),
('bunong-vn','DEU',28,45,null,$b$Lĕ rngôch nau rtăp rak aơ mra tât ma khân may tĭng khân may jêh ri ban khân may, kŏ khân may rai lôch, yor lah khân may mâu tông bâr Yêhôva Brah Ndu khân may ôh, gay djôt prăp nau păng ntăm jêh ri nau vay păng ăn jêh ma khân may.$b$,true),
('bunong-vn','DEU',28,46,null,$b$Nau rtăp rak nây mra gŭ ta klơ khân may jêng du nau tâm mbên jêh ri nau khlay, jêh ri gŭ ta klơ phung kon sau khân may ƀa ƀơ n'ho ro.$b$,false),
('bunong-vn','DEU',28,47,null,$b$Yor lah khân may geh lĕ rngôch ndơ rmeh ler, khân may mâu mâp pah kan ma Yêhôva Brah Ndu khân may ma nau răm jêh ri ma nuih n'hâm maak ôh.$b$,true),
('bunong-vn','DEU',28,48,null,$b$Yor ri khân may mra pah kan ma phung rlăng khân may Yêhôva mra njuăl ƀư ma khân may, ma nau ji ngot, nau ji hir, nau rhôk, nau nây nau pưt kƀah lĕ rngôch ndơ. Păng mra dơm rvang loih ta trô ko khân may kŏ păng ƀư rai lơi khân may.$b$,false),
('bunong-vn','DEU',28,49,null,$b$Yêhôva mra njŭn leo du ndŭl mpôl bơh ngai, bơh dŭt bri dŭt neh, ngăch tâm ban ma klang mpăr, du mpôl băl khân may mâu gĭt rbăng nau ngơi ôh ƀư ma khân may,$b$,true),
('bunong-vn','DEU',28,50,null,$b$du ndŭl mpôl geh muh măt dăng, phung mâu mra chrê ôh ma bunuyh ranh mâu lah yô̆ ma phung druh ndăm,$b$,false),
('bunong-vn','DEU',28,51,null,$b$jêh ri mra sa kon ndrôk khân may jêh ri play bơh neh khân may, kŏ khân may rai lôch; phung mâu mra lơi ôh ma khân may ba, dak play kriăk ƀâu, dak play Ôlivơ, kon ndrôk khân may mâu lah kon biăp khân may, kŏ khân păng ăn khân may rai lôch.$b$,false),
('bunong-vn','DEU',28,52,null,$b$Khân păng mra nchueng khân may tâm lĕ rngôch ƀon khân may, kŏ pêr prêh jêh ri nâp khân may rnơm rlâm lam n'gor khân may; jêh ri khân păng mra chueng khân may tâm lĕ rngôch ƀon khân may lam n'gor Yêhôva Brah Ndu khân may ăn jêh ma khân may.$b$,false),
('bunong-vn','DEU',28,53,null,$b$Dôl nau nchueng jêh ri nau uh ah phung rlăng khân may mra ƀư rŭng khân may, khân may mra sa play bơh ndŭl proch khân may nơm, nglay puăch phung kon bu klâu jêh ri kon bu ur khân may. Yêhôva Brah Ndu khân may ăn jêh ma khân may.$b$,false),
('bunong-vn','DEU',28,54,null,$b$Bunuyh ueh lơn tâm phung khân may jêh ri mơng ma nau rdơ̆ rbăn ta nklang khân may mra mbeh ndơ sông sa ma oh nâu păng, ma ur ta ntang ntơh păng, ma phung kon mpŭt hôm ma păng;$b$,false),
('bunong-vn','DEU',28,55,null,$b$pô ri păng mâu ŭch ăn ôh ma du huê tâm phung khân păng nglay puăch phung kon păng nơm păng gŭ sa, yor lah mâu geh ndơ hôm ma păng ôh, dôl nau nchueng jêh ri nau uh ah phung rlăng khân may mra ƀư rŭng khân may tâm lĕ rngôch ƀon khân may.$b$,false),
('bunong-vn','DEU',28,56,null,$b$Bu ur ueh lơn jêh ri mơng ma nau rdơ̆ rbăn ta nklang khân may nơm mâu mâp mpang jâng păng ta neh ôh yor păng jêng rdơ̆ rbăn jêh ri ueh mra mbeh ma sai ta ntang ntơh păng ma kon bu klâu jêh ri kon bu ur păng,$b$,false),
('bunong-vn','DEU',28,57,null,$b$rsok luh tă vah vang jâng păng đah kon păng deh yor păng mra sa ndơ nây ma nau ndâp, yor pưt kƀah lĕ rngôch ndơ dôl nau nchueng jêh ri nau uh ah phung rlăng khân may mra ƀư rŭng khân may tâm ƀon khân may.$b$,false),
('bunong-vn','DEU',28,58,null,$b$Tơ lah khân may mâu njrăng ƀư kơt lĕ rngôch nau ngơi aơ chih jêh tâm ndrom sămƀŭt aơ, gay ma khân may dơi klach ma amoh Yêhôva Brah Ndu khân may, amoh chrêk rmah jêh ri rnam,$b$,true),
('bunong-vn','DEU',28,59,null,$b$pô ri Yêhôva mra ƀư tât ma khân may jêh ri ma phung kon sau khân may nau rêh ni bu mâu mâp saơ ôh, nau rêh ni ktang jêh ri gŭ jŏ,$b$,false),
('bunong-vn','DEU',28,60,null,$b$Păng mra lŏ ăn tât ma khân may lĕ rngôch nau ji n'gor Êjipt, nau ji nây khân may klach; jêh ri khân păng mra iang ta khân may.$b$,false),
('bunong-vn','DEU',28,61,null,$b$Yêhôva mra ăn tât ma khân may ăp ntil nau ji jêh ri ăp ntil nau ƀư rêh ni bu mâu chih ôh tâm ndrom sămƀŭt nau vay aơ, kŏ khân may rai.$b$,true),
('bunong-vn','DEU',28,62,null,$b$Jêh khân may jêng âk nâm bu mănh tâm trôk, khân may mra ăt hôm knŏng djê̆; yor lah khân may mâu tông bâr Yêhôva Brah Ndu khân may ôh.$b$,false),
('bunong-vn','DEU',28,63,null,$b$Tâm ban ma Yêhôva geh nau maak dôl ƀư ueh ma khân may jêh ri ăn bĭk rơ̆ khân may, pô nây lĕ Yêhôva mra geh nau maak dôl ƀư tât nau ƀư roh jêh ri ƀư rai khân may; jêh ri bu mra rôk khân may bơh n'gor khân may gŭ lăp gay sŏk pha.$b$,true),
('bunong-vn','DEU',28,64,null,$b$Yêhôva mra ăn nchah du khân may ta nklang lĕ rngôch phung ƀon lan, bơh dŭt bri neh aơ ma dŭt bri neh êng; jêh ri ta nây khân may mra pah kan ma phung brah êng ƀư ma si jêh ri lŭ, brah nây khân may jêh ri phung che khân may mâu mâp gĭt năl ôh.$b$,true),
('bunong-vn','DEU',28,65,null,$b$Ta nklang phung ndŭl mpôl aơ khân may mâu mra geh nau đăp mpăn ôh, jêh ri mâu mra geh nau rlu ôh mpang jâng khân may; ƀiă lah Yêhôva mra ăn ma khân may ta nây nuih n'hâm râm sâr, măt klêu, jêh ri huêng rngot rvê.$b$,false),
('bunong-vn','DEU',28,66,null,$b$Khân may mra đing ma nau rêh khân may; măng jêh ri nar, khân may mra klach ngăn, jêh ri mâu geh nau gĭt nanê̆ ma nau rêh khân may ôh.$b$,false),
('bunong-vn','DEU',28,67,null,$b$Dôl ôi khân may mra lah: ‘Ueh ngăn ma mhaơ jêh! Jêh ri ta mhaơ khân may mra lah: ‘Ueh ngăn ma ôi jêh!’ Yor lah nuih n'hâm khân may klach ma nau mhĭk jêh ri yor ndơ măt khân may saơ.$b$,false),
('bunong-vn','DEU',28,68,null,$b$Jêh ri Yêhôva mra njŭn khân may sĭt ta n'gor Êjipt ma Kŭmpăn, nau nsong nây gâp ton jêh khân may mâu hôm mra ƀư ôh. Ta nây khân may mra nhhơr tăch khân may nơm ma phung rlăng khân may, bu ur jêh ri bu klâu tâm ban ma dĭk, ƀiă lah mâu geh nơm mra ăn khân may ôh.$b$,false),
('bunong-vn','DEU',29,1,null,$b$Aơ nau ngơi ma nau tâm rnglăp Yêhôva ntăm jêh ma Y-Môis ăn ƀư đah phung ƀon lan Israel ta n'gor Môap, rmeh ma nau tâm rnglăp păng ƀư jêh ma khân păng ta yôk Hôrep.$b$,true),
('bunong-vn','DEU',29,2,null,$b$Y-Môis kuăl tâm rƀŭn lĕ rngôch phung Israel jêh ri lah ma khân păng: “Khân may saơ jêh lĕ nau Yêhôva ƀư jêh ta năp măt khân may tâm n'gor Êjipt, ma Pharaôn, ma lĕ rngôch phung oh mon păng, jêh ri ma lĕ n'gor păng,$b$,true),
('bunong-vn','DEU',29,3,null,$b$nau rlong uănh toyh măt khân may saơ jêh, nau tâm mbên, jêh ri nau khlay nây.$b$,false),
('bunong-vn','DEU',29,4,null,$b$Ƀiă lah tât ta nar aơ Yêhôva mâu mâp ăn ôh ma khân may nau mĭn gĭt rbăng, măt gĭt saơ, mâu lah tôr gĭt tăng.$b$,false),
('bunong-vn','DEU',29,5,null,$b$Gâp njŭn jêh khân may dôl puăn jât năm tâm bri rdah; bok ao khân may soh mâu mâp mŭnh sat ôh, jêh ri ntâu jot khân may soh mâu mâp plưn ôh.$b$,true),
('bunong-vn','DEU',29,6,null,$b$Khân may mâu mâp sa piăng let ôh, jêh ri khân may mâu mâp sa play kriăk ƀâu mâu lah ndrănh ôh; gay ma khân may dơi gĭt gâp jêng Yêhôva Brah Ndu khân may.$b$,false),
('bunong-vn','DEU',29,7,null,$b$Tơ lah khân may tât jêh ta ntŭk aơ, Y-Sihôn hađăch ƀon Hêsbôn jêh ri Y-Ôk hađăch n'gor Basan luh ŭch tâm lơh đah he, ƀiă lah he dơi jêh đah khân păng.$b$,false),
('bunong-vn','DEU',29,8,null,$b$He sŏk jêh n'gor khân păng jêh ri ăn jêh n'gor nây jêng drăp ndơn ma phung Ruben, phung Gat, jêh ri ma du đah ndŭl mpôl Manasê.$b$,false),
('bunong-vn','DEU',29,9,null,$b$Pô ri njrăng hom ăn ƀư nau ngơi tâm nau tâm rnglăp aơ, gay ma khân may dơi jêng hao tâm lĕ kan khân may ƀư.$b$,false),
('bunong-vn','DEU',29,10,null,$b$Nar aơ lĕ rngôch khân may gŭ ngao ta năp Yêhôva Brah Ndu khân may; phung kôranh ndŭl mpôl khân may, phung bu bŭnh bu ranh khân may, phung kôranh ta han khân may, lĕ rngôch phung bu klâu Israel,$b$,true),
('bunong-vn','DEU',29,11,null,$b$phung kon jê̆ khân may, phung ur khân may, jêh ri phung gŭ jưh ƀât lât tâm nkual, nđâp nơm kăl si khân may jêh ri nơm bâk dak khân may,$b$,false),
('bunong-vn','DEU',29,12,null,$b$gay ma khân may dơi lăp tâm rnglăp Yêhôva Brah Ndu khân may ton jêh, nau tâm rnglăp Yêhôva Brah Ndu khân may ƀư jêh đah khân may nar aơ;$b$,false),
('bunong-vn','DEU',29,13,null,$b$gay ma păng dơi njêng khân may nar aơ jêng phung ƀon lan păng, jêh ri gay ma păng dơi jêng Brah Ndu khân may, jêh ri tĭng nâm păng ton jêh ma phung che khân may, Y-Abraham, Y-Isăk, jêh ri Y-Yakôp.$b$,false),
('bunong-vn','DEU',29,14,null,$b$Mâu di knŏng ma khân may ôh gâp ƀư nau tâm rnglăp jêh ri nau ton aơ,$b$,false),
('bunong-vn','DEU',29,15,null,$b$ƀiă lah đah phung mâu gŭ ôh ta aơ ndrel ma he nar aơ, nđâp ma phung gŭ râng ta aơ ndrel ma he nar aơ ta năp Brah Ndu he.$b$,false),
('bunong-vn','DEU',29,16,null,$b$“Khân may gĭt mâm nau he gŭ tâm n'gor Êjipt, jêh ri mâm nau he rgăn ta nklang phung ntil mpôl bunuyh khân may rgăn jêh;$b$,true),
('bunong-vn','DEU',29,17,null,$b$jêh ri khân may saơ jêh ndơ khân păng bu tâm rmot rup brah khân păng ma tơm si jêh ri lŭ, ma prăk jêh ri mah, gŭ ta nklang khân păng.$b$,false),
('bunong-vn','DEU',29,18,null,$b$Njrăng hom lơi ăn geh ta nklang khân may du huê bu klâu mâu lah bu ur, rnăk vâl mâu lah ndŭl mpôl nar aơ geh nuih n'hâm cha lơi Yêhôva Brah Ndu he gay ŭch hăn pah kan ma brah phung ndŭl mpôl nây; tâm khân may lơi dĭng geh du mlâm reh djôt dah kăch jêh ri play tăng,$b$,false),
('bunong-vn','DEU',29,19,null,$b$Mbu tăng nau ngơi bơh nau gâp ton aơ, lơi ăn geh ôh tâm nuih n'hâm păng, lah: ‘Gâp mra gŭ mpăn, nđâp tơ lah gâp hăn ma nuih n'hâm dăng kđôi.’ Nau nây mra njŭn ma nau roh rai nđâp ndơ bu djrah dah jêh ri ndơ sơh tâm ban đŏng.$b$,false),
('bunong-vn','DEU',29,20,null,$b$Yêhôva mâu mra yô̆ ma păng ôh, ƀiă lah nau Yêhôva nuih jêh ri nau rtăp rak hŏ chih jêh tâm ndrom sămƀŭt aơ mra tŭp ta păng, jêh ri Yêhôva mra jut amoh păng bơh tâm dâng trôk.$b$,true),
('bunong-vn','DEU',29,21,null,$b$Jêh ri Yêhôva mra tâm nkhah păng bơh lĕ rngôch ndŭl mpôl phung Israel, gay prăp ma nau rêh ni tĭng nâm lĕ rngôch nau rtăp rak bơh nau tâm rnglăp chih jêh tâm ndrom sămƀŭt nau vay aơ.$b$,false),
('bunong-vn','DEU',29,22,null,$b$Phung rnôk kăndơ̆ , phung kon khân may văch ma toyh pa kơi khân may, jêh ri bunuyh bu năch văch bơh n'gor ngai mra lah tơ lah khân păng saơ nau rêh ni n'gor aơ jêh ri nau ji kuet Yêhôva ƀư ăn ji n'gor aơ.$b$,true),
('bunong-vn','DEU',29,23,null,$b$Lĕ n'gor jêng lŭ mô ŭnh jêh ri boh, jêh ri du ntŭk lĕ ŭnh sa jêh, bu mâu saơ srih ôh jêh ri mâu geh ndơ hon ôh, ta nây gơ̆ mâu dơi chăt nse ôh. Nau ƀư rai nâm bu ta ƀon Sôdôm, Gômôrơ, Adma, jêh ri Sêbôim. Yêhôva ƀư rai jêh ma nau păng ji nuih jêh ri ji ji nuih$b$,false),
('bunong-vn','DEU',29,24,null,$b$nanê̆ yơh lĕ rngôch phung ndŭl mpôl mra lah: ‘Mâm ƀư Yêhôva ƀư pô aơ ma n'gor aơ?’ ‘Mâm ƀư nau duh nau ji nuih toyh aơ?’$b$,false),
('bunong-vn','DEU',29,25,null,$b$Dôl nây bu mra lah: ‘Yor lah khân păng dun jêh nau tâm rnglăp Yêhôva Brah Ndu phung che khân păng ƀư jêh đah khân păng dôl khân păng njŭn khân păng luh bơh n'gor Êjipt,$b$,false),
('bunong-vn','DEU',29,26,null,$b$jêh ri khân păng hăn pah kan ma phung brah êng, jêh ri mbah yơk ma phung brah nây, phung brah khân păng mâu gĭt năl ôh, jêh ri Yêhôva mâu mâp jao ăn ma khân păng ôh.$b$,false),
('bunong-vn','DEU',29,27,null,$b$Yor nây Yêhôva duh nuih ma n'gor aơ jêh ri ƀư tât ma păng lĕ rngôch nau rtăp rak chih jêh tâm ndrom sămƀŭt aơ;$b$,false),
('bunong-vn','DEU',29,28,null,$b$jêh ri Yêhôva rôk jêh khân păng bơh n'gor khân păng ma nau ji nuih biănh, ma nau nuih jêh ri ma nau ji nuih ktang ngăn jêh ri klŭp mƀăr khân păng ta n'gor êng, nâm bu nar aơ.’$b$,false),
('bunong-vn','DEU',29,29,null,$b$Nau ndâp prăp ma Yêhôva Brah Ndu he; ƀiă lah nau păng tâm mpơl jêh prăp ma he jêh ri ma phung kon he ƀa ƀơ n'ho ro, gay ma he dơi ƀư lĕ rngôch nau ngơi nau vay aơ.$b$,false),
('bunong-vn','DEU',30,1,null,$b$Tơ lah lĕ rngôch nau aơ tât ma khân may, nau ueh uĭn jêh ri nau rtăp rak gâp tâm mpơl jêh ta năp khân may, tơ lah khân may kah gĭt ma nau nây ta nklang lĕ rngôch ndŭl mpôl ntŭk Yêhôva Brah Ndu khân may nsot jêh khân may,$b$,true),
('bunong-vn','DEU',30,2,null,$b$jêh ri plơ̆ sĭt ma Yêhôva Brah Ndu khân may, khân may jêh ri phung kon khân may, jêh ri tông bâr păng ma lĕ nuih n'hâm jêh ri ma lĕ huêng khân may tâm lĕ rngôch nau gâp ntăm ma khân may nar aơ;$b$,false),
('bunong-vn','DEU',30,3,null,$b$dôl nây Yêhôva Brah Ndu khân may mra nhhơk khân may jêh ri mra yô̆ ma khân may jêh ri tâm rƀŭn khân may bơh lĕ rngôch phung ƀon lan ntŭk Yêhôva Brah Ndu khân may ăn nchah rai jêh khân may.$b$,false),
('bunong-vn','DEU',30,4,null,$b$Tơ lah phung khân may bu nsot gŭ tâm dŭt trôk, bơh nây Yêhôva Brah Ndu khân may mra tâm rƀŭn khân may, jêh ri bơh nây păng mra njŭn khân may;$b$,true),
('bunong-vn','DEU',30,5,null,$b$jêh ri Yêhôva Brah Ndu khân may mra njŭn khân may lăp tâm n'gor phung che khân may sŏk jêh, gay ma khân may dơi sŏk pha. Păng mra ăn khân may chăt hon âk lơn jêh ri jêng bĭk rơ̆ lơn ma phung che khân may.$b$,false),
('bunong-vn','DEU',30,6,null,$b$Jêh ri Yêhôva Brah Ndu khân may mra koh ntâu nuih n'hâm khân may jêh ri nuih n'hâm phung kon khân may, pô nây mơ khân may mra rŏng ma Yêhôva Brah Ndu khân may ma lĕ nuih n'hâm khân may jêh ri lĕ huêng khân may gay ma khân may dơi rêh.$b$,true),
('bunong-vn','DEU',30,7,null,$b$Yêhôva Brah Ndu khân may mra ƀư tŭp lĕ rngôch nau rtăp rak ta klơ phung ƀư ma khân may jêh ri phung rlăng khân may, phung ƀư rêh ni khân may.$b$,false),
('bunong-vn','DEU',30,8,null,$b$Khân may mra tông bâr ma Yêhôva jêh ri djôt prăp lĕ rngôch nau păng ntăm gâp ăn ma khân may nar aơ.$b$,false),
('bunong-vn','DEU',30,9,null,$b$Yêhôva Brah Ndu khân may mra ăn ma khân may jêng hao rmeh ler tâm lĕ rngôch kan ti khân may ƀư, tâm play bơh ndŭl proch khân may, play bơh mpô mpa khân may rong jêh ri play bơh neh khân may; yor lah Yêhôva mra geh nau maak tâm nau jêng n'hao khân may, nâm bu păng geh nau maak đah phung che khân may,$b$,false),
('bunong-vn','DEU',30,10,null,$b$tơ lah khân may tông bâr ma Yêhôva Brah Ndu khân may, dôl djôt prăp nau păng ntăm jêh ri nau vay păng chih jêh tâm ndrom sămƀŭt nau vay aơ; tơ lah khân may plơ̆ sĭt ma Yêhôva Brah Ndu khân may ma lĕ nuih n'hâm khân may jêh ri ma lĕ huêng khân may.$b$,false),
('bunong-vn','DEU',30,11,null,$b$Yor lah nau ntăm aơ gâp ăn ma khân may nar aơ mâu jêng jêr ir ma khân may ôh, mâu lĕ păng jêng ngai.$b$,true),
('bunong-vn','DEU',30,12,null,$b$Păng mâu gŭ tâm trôk ôh kŏ khân may lah. ‘Mbu mra hao an ma he ta trôk jêh ri njŭn leo ma he, gay ma he dơi tăng jêh ri tĭng ndô̆ nau nây?’$b$,false),
('bunong-vn','DEU',30,13,null,$b$Mâu lĕ păng gŭ kơh tê̆ dak mƀŭt, kŏ khân may lah: ‘Mbu mra rgăn an ma he dak mƀŭt jêh ri njŭn leo ma he, gay ma he dơi tăng jêh ri tĭng ndô̆ nau nây?’$b$,false),
('bunong-vn','DEU',30,14,null,$b$Ƀiă lah nau ngơi gŭ dăch ngăn ma khân may; păng gŭ tâm trôm mbung khân may jêh ri tâm nuih n'hâm khân may, pô ri khân may dơi tĭng ndô̆ nau nây.$b$,false),
('bunong-vn','DEU',30,15,null,$b$Aơ gâp tâm mpơl nar aơ ta năp khân may nau rêh jêh ri nau ueh lăng, nau khĭt jêh ri nau rai lôch.$b$,true),
('bunong-vn','DEU',30,16,null,$b$Tơ lah khân may tông nau Yêhôva Brah Ndu khân may ntăm gâp ăn ma khân may nar aơ, dôl rŏng ma Yêhôva Brah Ndu khân may, dôl hăn tâm trong păng, jêh ri dôl djôt prăp nau păng ntăm, nau vay păng jêh ri nau păng ăn, pô ri khân may mra rêh jêng bĭk rơ̆ , jêh ri Yêhôva Brah Ndu khân may mra ăn nau ueh uĭn ma khân may tâm n'gor khân may gŭ lăp gay sŏk dơn.$b$,false),
('bunong-vn','DEU',30,17,null,$b$Ƀiă lah tơ lah nuih n'hâm khân may nkhah du, jêh ri khân may mâu ŭch iăt ôh, ƀiă lah dơn nau ndơm yơk mbah ma phung brah êng jêh ri pah kan ma khân păng,$b$,false),
('bunong-vn','DEU',30,18,null,$b$gâp mbơh ma khân may nar aơ, khân may mra rai yot, khân may mâu mra gŭ rêh jŏ ôh tâm n'gor khân may gŭ rgăn dak krong Yurdan gay sŏk pha.$b$,false),
('bunong-vn','DEU',30,19,null,$b$Nar aơ gâp kuăl trôk jêh ri neh ntu jêng nơm mbơh tâm rdâng đak khân may, nau gâp tâm mpơl jêh ta năp măt khân may nau rêh jêh ri nau khĭt, nau mât ton jêh ri nau rtăp rak. Pô ri săch hom nau rêh, gay ma khân may jêh ri phung kon sau khân may dơi gŭ rêh,$b$,true),
('bunong-vn','DEU',30,20,null,$b$rŏng ma Yêhôva Brah Ndu khân may, tông bâr păng, jêh ri tâm rnglăp đah păng; yor lah nau nây jêng nau rêh ma khân may jêh ri ƀư jŏ nar khân may, gay ma khân may dơi gŭ tâm n'gor Yêhôva ton jêh ma phung che khân may, ma Y-Abraham, Y-Isăk jêh ri Y-Yakôb, gay ăn ma khân păng.$b$,false),
('bunong-vn','DEU',31,1,null,$b$Pô ri Y-Môis ăt ngơi nau aơ ma lĕ rngôch phung Israel.$b$,true),
('bunong-vn','DEU',31,2,null,$b$Păng lah: “Nar aơ gâp geh du rhiăng bar jât năm; gâp mâu hôm dơi luh jêh ri lăp ôh. Yêhôva lah ma gâp: ‘May mâu mra rgăn ôh dak krong Yurdan aơ.’$b$,false),
('bunong-vn','DEU',31,3,null,$b$Yêhôva Brah Ndu khân may, păng nơm mra hăn rgăn dak krong ta năp khân may; păng mra ƀư rai ndŭl mpôl aơ ta năp khân may, pô ri khân may mra nsot sŏk dơn n'gor bri khân păng; jêh ri Y-Yôsuê mra rgăn lor jêng kôranh khân may, tĭng nâm Yêhôva ngơi jêh.$b$,false),
('bunong-vn','DEU',31,4,null,$b$Yêhôva mra ƀư ma phung nây nâm bu păng ƀư jêh ma Y-Sihôn jêh ri ma Y-Ôk, hađăch phung Amôrit, jêh ri bri neh khân păng dôl păng ƀư rai jêh phung nây.$b$,false),
('bunong-vn','DEU',31,5,null,$b$Yêhôva mra jao khân păng ma khân may, jêh ri ăn khân may ƀư ma khân păng tĭng nâm lĕ rngôch nau ntăm gâp ăn jêh ma khân may.$b$,false),
('bunong-vn','DEU',31,6,null,$b$Ăn jêng ktang jêh ri n'hao nuih hom. Lơi klach mâu lah rnam ôh ma khân păng; yor lah Yêhôva Brah Ndu khân may yơh hăn ndrel ma khân may; păng mâu mra jêng pưt kƀah ma khân may mâu lah dun cha lơi khân may ôh.”$b$,false),
('bunong-vn','DEU',31,7,null,$b$Y-Môis kuăl Y-Yôsuê jêh ri lah ma păng ta năp lĕ rngôch phung Israel. “Ăn jêng ktang jêh ri n'hao nuih hom; yor lah may mra lăp ndrel ma phung ƀon lan aơ tâm bri Yêhôva ton jêh ma phung che khân păng gay ăn ma khân păng; jêh ri may mra ăn khân păng sŏk dơn bri nây.$b$,true),
('bunong-vn','DEU',31,8,null,$b$Yêhôva yơh jêng nơm hăn ta năp may; păng mra gŭ ndrel ma may, păng mâu mra jêng pưt kƀah ma may mâu lah dun cha lơi may ôh. Lơi klach mâu lah rdja nuih n'hâm ôh.”$b$,false),
('bunong-vn','DEU',31,9,null,$b$Y-Môis chih jêh nau vay aơ jêh ri jao ma phung kôranh ƀư brah phung kon bu klâu Lêvi, phung tung hip nau tâm rnglăp Yêhôva jêh ri ma lĕ rngôch phung bu bŭnh bu ranh Israel.$b$,true),
('bunong-vn','DEU',31,10,null,$b$Y-Môis ntăm ma khân păng: “Ta lôch ăp pơh năm, ta nar tâm nal jêh tâm năm nau ăn mpăn, ta nar nhêt sông ma Ngih Ndưp,$b$,false),
('bunong-vn','DEU',31,11,null,$b$dôl lĕ rngôch phung Israel mra văch tâm mpơl khân păng nơm ta năp Yêhôva Brah Ndu khân may ta ntŭk păng mra săch, ăn khân may uănh nau vay aơ ta năp lĕ rngôch phung Israel ăn khân păng tăng.$b$,false),
('bunong-vn','DEU',31,12,null,$b$Tâm rƀŭn hom phung ƀon lan, bu klâu, bu ur, phung kon se jêh ri nơm gŭ jưh ƀât lât tâm ƀon khân may, gay ma khân păng dơi tăng jêh ri nti klach yơk ma Yêhôva Brah Ndu khân may jêh ri njrăng ăn ƀư kơt lĕ rngôch nau ngơi tâm nau vay aơ,$b$,false),
('bunong-vn','DEU',31,13,null,$b$jêh ri gay ma phung kon khân păng, phung mâu mâp gĭt nau nây ôh dơi iăt jêh ri nti klach yơk ma Yêhôva Brah Ndu khân may, lĕ rngôch rnôk khân may gŭ rêh tâm n'gor khân may mra rgăn dak krong Yurdan ŭch pah kan.”$b$,false),
('bunong-vn','DEU',31,14,null,$b$Yêhôva lah ma Y-Môis: “Aơ, nar may mra khĭt hŏ dăch jêh. Kuăl hom Y-Yôsuê jêh ri mpơl hom khân may nơm tâm ngih bok nau tâm rƀŭn.$b$,true),
('bunong-vn','DEU',31,15,null,$b$Jêh ri Yêhôva tâm mpơl tâm du mlâm meh ndâr tâm ngih bok; jêh ri meh ndâr gŭ dăch mpông ngih bok.$b$,false),
('bunong-vn','DEU',31,16,null,$b$Yêhôva lah ma Y-Môis: “Aơ, may dăch khĭt, hăn gŭ ndrel ma phung che may; jêh ri phung ƀon lan aơ mra dâk ƀư nau văng tĭr đah phung brah bu năch bri khân păng hăn gŭ ndrel. Khân păng mra cha lơi gâp jêh ri rlau nau vay tâm rnglăp gâp ƀư jêh đah khân păng.$b$,true),
('bunong-vn','DEU',31,17,null,$b$Jêh ri gâp mra duh nuih ma khân păng tâm nar nây, jêh ri gâp mra cha lơi khân păng jêh ri pôn muh măt gâp ma khân păng, jêh ri bu mra kăp sa khân păng. Âk ntil nau mhĭk jêh ri uh ah mra tât ma khân păng, pô ri khân păng mra lah tâm nar nây: ‘Mâu di hĕ nau mhĭk aơ tât ma he yor lah Brah Ndu he mâu gŭ ta nklang he ôh?’$b$,false),
('bunong-vn','DEU',31,18,null,$b$Nanê̆ gâp mra pôn muh măt gâp tâm nar nây yor lĕ rngôch nau mhĭk khân păng ƀư jêh, yor lah khân păng plơ̆ hăn jêh ma phung brah êng.$b$,false),
('bunong-vn','DEU',31,19,null,$b$Pô ri aƀaơ aơ chih hom nau mprơ aơ, jêh ri sâm nti păng ma phung ƀon lan Israel; dơm nau nây tâm trôm mbung khân păng, gay ma nau mprơ aơ dơi jêng du nau mbơh nau gâp tâm rdâng đah phung ƀon lan Israel.$b$,true),
('bunong-vn','DEU',31,20,null,$b$Yor lah tơ lah gâp njŭn leo khân păng lăp jêh tâm bri geh ndơ sông sa nhêt rmeh ler gâp ton jêh gay ăn ma phung che khân păng, jêh ri khân păng mâp sông sa jêh kŏ hơm bêng jêh ri jêng rmŏng, khân păng mra plơ̆ hăn ma phung brah êng jêh ri pah kan ma khân păng. Khân păng mra tâm rmot ma gâp, jêh ri rlau nau gâp tâm rnglăp.$b$,false),
('bunong-vn','DEU',31,21,null,$b$Jêh ri tơ lah âk nau mhĭk jêh ri nau uh ah tât ma khân păng, nau mprơ aơ mra jêng du nau mbơh tâm rdâng đah khân păng. Yor lah nau mprơ aơ bu mâu dơi chuêl ôh mra gŭ ƀa ƀơ tâm trôm mbung phung kon sau khân păng; yor lah gâp gĭt nau khân păng mĭn ŭch ƀư khân păng ntơm nkra jêh, lor gâp njŭn khân păng lăp tâm bri gâp ton jêh ŭch ăn.”$b$,false),
('bunong-vn','DEU',31,22,null,$b$Pô ri tâm nar nây Y-Môis chih nau mprơ aơ jêh ri sâm nti păng ma phung ƀon lan Israel.$b$,false),
('bunong-vn','DEU',31,23,null,$b$Yêhôva jao kan ma Y-Yôsuê kon bu klâu Y-Nun, lah: “Ăn jêng ktang jêh ri n'hao nuih hom; yor lah may mra njŭn leo phung kon Israel lăp tâm bri gâp ton jêh gay ăn ma khân păng; gâp mra gŭ ndrel ma may.”$b$,true),
('bunong-vn','DEU',31,24,null,$b$Tơ lah Y-Môis chih lôch jêh nau vay aơ du pŏk ndrom sămƀŭt kŏ lôch.$b$,true),
('bunong-vn','DEU',31,25,null,$b$Y-Môis ntăm ma phung Lêvi phung tung hip nau tâm rnglăp Yêhôva$b$,false),
('bunong-vn','DEU',31,26,null,$b$sŏk hom ndrom sămƀŭt nau vay aơ jêh ri dơm păng ta meng hip nau tâm rnglăp Yêhôva Brah Ndu khân may gay păng dơi gŭ ta nây jêng du nau mbơh tâm rdâng đah khân may.$b$,false),
('bunong-vn','DEU',31,27,null,$b$Yor lah gâp gĭt khân may phung dăng tâm rdâng ri dăng bôk ngăn. Aơ, dôl gâp ăt hôm rêh ndrel khân may, nar aơ khân may tâm rdâng jêh đah Yêhôva; rlau lơn ma nây lĕ jêh gâp khĭt!$b$,true),
('bunong-vn','DEU',31,28,null,$b$Tâm rƀŭn hom ta năp gâp lĕ rngôch phung bu bŭnh bu ranh tâm phung ndŭl mpôl khân may; jêh ri phung kôranh chiă uănh khân may, gay ma gâp dơi ngơi nau aơ ma tôr khân păng jêh ri kuăl trôk jêh ri neh ntu gay mbơh tâm rdâng đah khân păng.$b$,false),
('bunong-vn','DEU',31,29,null,$b$Yor lah gâp gĭt jêh gâp khĭt, nanê̆ khân may mra ƀư nau mhĭk ngăn ngên, jêh ri teng du bơh trong gâp ntăm jêh ma khân may; jêh ri tâm nar kăndơ̆ nau mhĭk mra tât ma khân may, yor lah khân may mra ƀư nau mhĭk ta năp măt Yêhôva, nsônh păng nuih ma kan ti khân may.”$b$,false),
('bunong-vn','DEU',31,30,null,$b$Jêh ri Y-Môis răk rplay ngơi nau mprơ aơ kŏ lôch ma tôr lĕ rngôch phung Israel gŭ tâm rƀŭn iăt:$b$,true),
('bunong-vn','DEU',32,1,null,$b$“Rkêng hom tôr may, Ơ trôk, jêh ri gâp mra ngơi; ăn neh ntu tăng play ngơi bơh trôm mbung gâp.$b$,true),
('bunong-vn','DEU',32,2,null,$b$Ăn nau gâp nti tŭp tâm ban ma dak mih, ăn nau gâp ngơi truh tâm ban ma dak ngom, tâm ban ma dak mih rlơ̆ ta klơ gơ̆ nse, tâm ban n'hŭk mih ta klơ tơm trau.$b$,true),
('bunong-vn','DEU',32,3,null,$b$Yor lah gâp mra mbơh amoh Yêhôva kơp hom Brah Ndu he jêng nơm toyh.$b$,true),
('bunong-vn','DEU',32,4,null,$b$Lŭ Toyh, kan păng jêng rah vah, yor lah lĕ rngôch trong păng jêng sŏng. Brah Ndu nơm răp jăp jêh ri mâu geh nau kue ôh, păng jêng sŏng jêh ri di.$b$,true),
('bunong-vn','DEU',32,5,null,$b$Khân păng ƀư ma ô băl nau tih mhĭk ngăn, khân păng mâu hôm jêng phung kon ô băl ôh yor nau bêk khân păng; khân păng jêng phung ndŭl mpôl tih jêh ri kue.$b$,true),
('bunong-vn','DEU',32,6,null,$b$Tâm ban pô nây hĕ khân may mplơ̆ ma Yêhôva, Ơ phung ƀon lan rluk jêh ri mâu geh nau blau mĭn ôh? Mâu di păng hĕ jêng mbơ̆ khân may, nơm rhăk jêh khân may, nơm njêng khân may jêh ri ƀư nâp jêh khân may?$b$,true),
('bunong-vn','DEU',32,7,null,$b$Kah gĭt hom ma nar kăl i kăl e, gŭ mĭn hom ma năm dôl âk rnôk, ôp hom ma mbơ̆ khân may, jêh ri păng mra tâm mpơl ma khân may, ôp hom ma bu bŭnh bu ranh khân may, jêh ri khân păng mra mbơh ma khân may.$b$,true),
('bunong-vn','DEU',32,8,null,$b$Tơ lah Nơm Klơ Lơn ăn jêh ma phung ndŭl mpôl drăp ndơn khân păng, tơ lah păng tâm nkhah phung kon bunuyh, păng tâm nal n'har phung ƀon lan tĭng nâm dŭm âk phung kon Israel.$b$,true),
('bunong-vn','DEU',32,9,null,$b$Yor lah kô̆ prăp ma Yêhôva jêng phung ƀon lan păng nơm, phung Y-Yakôb jêng drăp ndơn prăp ma păng.$b$,true),
('bunong-vn','DEU',32,10,null,$b$Păng saơ phung khân păng tâm bri rdah, jêh ri tâm ntŭk bri hŏng geh nau nter ngrông; păng rvang jŭm khân păng, păng mât mray, păng chiă uănh khân păng nâm bu găr măt păng nơm.$b$,true),
('bunong-vn','DEU',32,11,null,$b$Tâm ban ma klang tâm rplay kon păng mhe deh, mpăr ta klơ kon păng, ling (lĭ) năr păng, nhŭp khân păng, chông khân păng ta klơ rsau năr păng.$b$,true),
('bunong-vn','DEU',32,12,null,$b$Knŏng Yêhôva njŭn khân păng, jêh ri mâu geh ôh brah bu năch ndrel ma păng,$b$,true),
('bunong-vn','DEU',32,13,null,$b$Păng ăn khân păng hao jêh ta ntŭk prêh tâm neh ntu, jêh ri khân păng sa jêh play tâm mir: Păng ăn khân păng djrêp dak sŭt tă bơh lŭ, jêh ri dak play Ôlivơ bơh lŭ dăng,$b$,false),
('bunong-vn','DEU',32,14,null,$b$Dak toh ndrôk kŏt jêh ri dak toh biăp dak ndrel ma ngi kon biăp jêh ri biăp nkuăng, âk ndrôk bơh bri Basan jêh ri âk be nkuăng ndrel ma ba ƀlê ueh lơn jêh ri khân may nhêt jêh dak iet tă bơh play kriăk ƀâu.$b$,false),
('bunong-vn','DEU',32,15,null,$b$Ƀiă lah Yêsurun văch ma rmŏng jêh ri chưng; may văch ma rmŏng, may jêng săk jăn toyh jêh ri geh ntâu pler; dôl nây plơ̆ cha lat Brah Ndu nơm njêng jêh păng, jêh ri mưch ma Lŭ nơm tâm rklaih păng.$b$,true),
('bunong-vn','DEU',32,16,null,$b$Khân păng nsônh ăn păng ntôn đah phung brah bu năch; ma ndơ păng rmot khân păng tâm lŏk nuih ăn păng nuih.$b$,true),
('bunong-vn','DEU',32,17,null,$b$Khân păng ƀư brah jêh ma phung brah mhĭk mâu jêng brah ngăn ôh: Ma phung brah khân păng mâu mâp gĭt năl ôh, ma phung brah mhe văch pa kơi, ma phung nây phung che khân may mâu mâp klach ôh,$b$,true),
('bunong-vn','DEU',32,18,null,$b$Khân păng mâu mâp chrê ôh ma Lŭ nơm njêng jêh khân may, jêh ri khân may chuêl jêh Brah Ndu nơm deh khân may.$b$,false),
('bunong-vn','DEU',32,19,null,$b$Yêhôva saơ nau nây jêh ri dun ma khân păng, yor nau nsônh bơh phung kon bu klâu bu ur păng.$b$,true),
('bunong-vn','DEU',32,20,null,$b$Păng lah: ‘Gâp mra pôn nuih măt gâp ma khân păng, gâp mra saơ moh mra jêng nau lôch dŭt khân păng, yor lah khân păng jêng du rnôk kue mhĭk ngăn, phung kon mâu răp jăp ôh,$b$,true),
('bunong-vn','DEU',32,21,null,$b$khân păng nsônh jêh găp ăn ntôn đah nơm mâu jêng brah ôh; khân păng tâm lŏk nuih khân păng đah du phung ndŭl mpôl rluk.$b$,false),
('bunong-vn','DEU',32,22,null,$b$Yor lah ŭnh hit jêh đah nau gâp ji nuih, jêh ri ŭnh nây sa tât ta njâng Ƀon phung Khĭt, gŭ sa neh ntu jêh ri play păng, jêh ri ăn ŭnh sa njâng yôk.$b$,true),
('bunong-vn','DEU',32,23,null,$b$Gâp mra bun nau mhĭk ta klơ khân păng;$b$,true),
('bunong-vn','DEU',32,24,null,$b$khân păng mra rai lôch ma nau ji ngot ji hir, nau duh jêh ri nau ji tưp geh dak kăch kăm mra sa khân păng; jêh ri gâp mra njuăl âk mpa bri kăp khân păng, ndrel ma dak kăch kăm bơh mpa vơr ta ndruyh neh.$b$,false),
('bunong-vn','DEU',32,25,null,$b$Pa dih đao mra ăn nau ndrê ndjăng, jêh ri tâm jrô mra geh nau nhhu klach ngăn, ƀư rai nđâp bu klâu ndăm jêh ri bu ur druh, kon se gŭ pu ndrel ma bu klâu ranh.$b$,true),
('bunong-vn','DEU',32,26,null,$b$Gâp lah jêh: “Gâp mra mpuh rlu khân păng ngai, gâp mra ăn lôch nau kah gĭt ma khân păng ta nklang phung bunuyh.”$b$,true),
('bunong-vn','DEU',32,27,null,$b$Tơ lah gâp mâu klach nau nơm rlăng nsônh, klach lah phung rlăng khân păng mĭn vĭ, klach lah khân păng mra lah: “Ti hên dơi jêh, Yêhôva mâu mâp ƀư ôh lĕ rngôch nau nây.”$b$,true),
('bunong-vn','DEU',32,28,null,$b$“Yor lah khân păng jêng du ndŭl mpôl mâu geh gĭt nau, jêh ri mâu geh nau gĭt rlăng ôh tâm khân păng.$b$,true),
('bunong-vn','DEU',32,29,null,$b$Tơ lah khân păng jêng njêh, khân păng mra gĭt rlăng nau aơ, khân păng dơi mĭn ma nau lôch dŭt khân păng pa kơi taơ!$b$,true),
('bunong-vn','DEU',32,30,null,$b$Mâm ƀư knŏng du huê dơi tĭng du rbăn nuyh, jêh ri bar hê dơi nsot rdu jât rbăn nuyh, Knŏng tơ lah Lŭ khân păng tăch jêh khân păng, jêh ri tơ lah Yêhôva jao jêh khân păng?$b$,true),
('bunong-vn','DEU',32,31,null,$b$Yor lah lŭ khân păng mâu jêng nâm bu Lŭ he ôh nđâp phung rlăng he sek nau nây.$b$,true),
('bunong-vn','DEU',32,32,null,$b$Yor lah tơm play kriăk ƀâu khân păng luh tă bơh tơm play kriăk ƀâu ƀon Sôdôm, jêh ri bơh mir ƀon Gômôrơ; play kriăk ƀâu khân păng jêng play kriăk ƀâu geh nau kăch kăm, rkŭm play khân păng jêng tăng;$b$,true),
('bunong-vn','DEU',32,33,null,$b$dak play kriăk ƀâu khân păng jêng dak kăch kăm bêh, jêh ri dak kăch kăm ktang bêh rmâng,$b$,false),
('bunong-vn','DEU',32,34,null,$b$Mâu di hĕ nau aơ bun jêh ndrel ma gâp, tâp pŏng jêh tâm ngih drăp ndơ gâp?$b$,false),
('bunong-vn','DEU',32,35,null,$b$Gâp be nau plơng har, jêh ri nau nkhôm, prăp ma nar jâng khân păng mra nsrat; yor lah nar rêh ni khân păng dăch jêh, jêh ri nau phat dôih khân păng tât gơnh.$b$,true),
('bunong-vn','DEU',32,36,null,$b$Yor lah Yêhôva mra kơp sŏng phung ƀon lan păng, jêh ri geh nau yô̆ ma phung oh mon păng, tơ lah păng saơ nau ktang khân păng lĕ jêh, jêh ri mâu geh du huê ăt hôm ôh, dĭk mâu lah kon me.$b$,true),
('bunong-vn','DEU',32,37,null,$b$Dôl nây păng mra lah: ‘Ta ntŭk phung brah khân păng, lŭ ntŭk khân păng du krap,$b$,true),
('bunong-vn','DEU',32,38,null,$b$Phung brah nây sa mham mpa khân păng ƀư brah jêh ri nhêt dak play kriăk ƀâu ndơ khân păng nhhơr nhêt? Ăn phung brah nây dâk jêh ri kơl khân păng, ăn khân păng jêng phung n'gang khân păng.$b$,false),
('bunong-vn','DEU',32,39,null,$b$Aƀaơ aơ ăn khân may gĭt gâp, gâp, jêng păng, jêh ri mâu geh brah êng ôh rmeh ma gâp; gâp nkhĭt jêh ri gâp ăn rêh; gâp ƀư sôt jêh ri gâp ƀư bah; jêh ri mâu geh nơm dơi tâm rklaih bơh ti gâp ôh.$b$,true),
('bunong-vn','DEU',32,40,null,$b$Yor lah gâp yơr ti gâp mơ pa trôk, jêh ri ton sơm, yor lah gâp gŭ rêh n'ho ro.$b$,true),
('bunong-vn','DEU',32,41,null,$b$Tơ lah gâp tôl ƀư chrêk đao gâp, jêh ri ti djôt kan phat dôih, gâp mra mbơk har ma phung rlăng gâp, jêh ri mra mplơ̆ nau khư ma phung tâm rmot ma gâp.$b$,true),
('bunong-vn','DEU',32,42,null,$b$Gâp mra ăn hăr gâp nhêt mham kŏ nâm bu nhŭl ndrănh, jêh ri đao gưm gâp mra sa nglay ma mham bunuyh bu sreh jêh ri phung bu nă, bơh bôk phung rlăng geh sŏk jong.”$b$,true),
('bunong-vn','DEU',32,43,null,$b$Răm maak hom ơ phung ndŭl mpôl bunuyh ndrel ma phung ƀon lan păng, yor lah păng mra plơng rnoh mham phung n'hăk mƀuăl păng, jêh ri plơng rnoh ma phung ma phung rlăng păng, jêh ri ƀư nau maak ƀư kloh n'gor păng, ma phung ƀon lan păng.$b$,true),
('bunong-vn','DEU',32,44,null,$b$Y-Môis văch jêh ri răk lĕ nau mprơ nây ăn phung ƀon lan iăt, păng jêh ri Y-Yôsuê kon bu klâu Y-Nun,$b$,true),
('bunong-vn','DEU',32,45,null,$b$Tơ lah lôch jêh Y-Môis ngơi nau nây ma lĕ rngôch phung Israel,$b$,false),
('bunong-vn','DEU',32,46,null,$b$păng lah: “Djôt prăp hom tâm nuih n'hâm lĕ rngôch nau ngơi gâp ntăm ma khân may nar aơ, gay ma khân may dơi ntăm nau nây ma phung kon khân may gay ma khân păng dơi njrăng ƀư kơt tĭng lĕ rngôch nau ngơi tâm nau vay nây.$b$,false),
('bunong-vn','DEU',32,47,null,$b$Yor lah nau nây mâu tăp ôh nau mâu khlay ma khân may ƀiă lah păng jêng nau rêh khân may jêh ri yor nau nây khân may mra gŭ rêh jŏ tâm bri khân may mra rgăn dak krong Yurdan gay sŏk dơn.”$b$,false),
('bunong-vn','DEU',32,48,null,$b$Nar nây lĕ Yêhôva lah ma Y-Môis:$b$,true),
('bunong-vn','DEU',32,49,null,$b$“Hao hom ta yôk Abarim aơ, yôk Nêbô gŭ tâm bri Môap mơ pa đah ƀon Yêrikô, jêh ri uănh hom n'gor Kanaan gâp ăn ma phung ƀon lan Israel jêng drăp ndơn,$b$,false),
('bunong-vn','DEU',32,50,null,$b$jêh ri khĭt ta klơ yôk may hao nây jêh ri bu mra rƀŭn may ndrel ma phung ƀon lan may, nâm bu Y-Arôn nâu may khĭt jêh ta yôk Hor jêh ri bu rƀŭn păng ndrel ma phung ƀon lan păng;$b$,false),
('bunong-vn','DEU',32,51,null,$b$yor lah may ƀư tih jêh đah gâp ta nklang phung ƀon lan Israel ta dak Mêriba Kadês tâm bri rdah Sin; yor lah may mâu geh yơk ma gâp jêng kloh ueh ôh ta nklang phung ƀon lan Israel,$b$,false),
('bunong-vn','DEU',32,52,null,$b$yor lah may mra uănh ma n'gor ta năp may, ƀiă lah may mâu dơi hăn lăp ôh tâm bri gâp ăn ma phung ƀon lan Israel.”$b$,false),
('bunong-vn','DEU',33,1,null,$b$Aơ jêng nau ueh uĭn Y-Môis bunuyh Brah Ndu mât ton jêh ma phung kon Israel lor păng khĭt,$b$,true),
('bunong-vn','DEU',33,2,null,$b$Păng lah: “Yêhôva văch jêh bơh yôk Sinai, jêh ri khoh bơh yôk sir; păng sol nchrat bơh yôk Paran, păng luh bơh nklang âk rbăn nuyh phung kloh ueh ndrel ma ŭnh hit mơ pa ma ti ma păng.$b$,false),
('bunong-vn','DEU',33,3,null,$b$Nanê̆ păng rŏng ma phung ƀon lan păng; lĕ rngôch phung kloh ueh gŭ tâm ti păng; pô ri khân păng tĭng ndô̆ têl may, sŏk dơn nau gai tă bơh may,$b$,true),
('bunong-vn','DEU',33,4,null,$b$dôl Y-Môis ntăm jêh ma he du nau vay, jêng du drăp krâm ma phung Yakôb tâm rƀŭn.$b$,false),
('bunong-vn','DEU',33,5,null,$b$Pô ri Yêhôva jêng jêh hađăch tâm Yêsurun, dôl phung kôranh phung ƀon lan tâm rƀŭn jêh, lĕ rngôch phung mpôl băl Israel ndrel.$b$,true),
('bunong-vn','DEU',33,6,null,$b$“Ăn phung Ruben gŭ rêh jêh ri mâu khĭt ôh, mâu lĕ ăn phung bu klâu păng jêng djê̆.”$b$,true),
('bunong-vn','DEU',33,7,null,$b$Jêh ri aơ păng lah nau di ma phung Yuđa: “Iăt hom, Ơ Yêhôva, bâr ngơi phung Yuđa, jêh ri njŭn leo khân păng ma phung ƀon lan khân păng ma ti păng nơm păng n'gang nau păng, jêh ri ăn may kơl tâm rdâng đah phung rlăng khân păng.”$b$,true),
('bunong-vn','DEU',33,8,null,$b$Păng lah nau di ma phung Lêvi: “Ăn Thumin may jêh ri Urim may ma nơm kloh ueh may, nơm may lŏng uănh jêh ta Masa, nơm may tâm rlăch jêh ta dak Mêriba;$b$,true),
('bunong-vn','DEU',33,9,null,$b$nơm lah ma mbơ̆ jêh ri ma me păng, ‘Gâp mâu chrê ma khân păng ôh; păng mâu gĭt năl phung oh nâu păng ôh, jêh ri mâu chrê ôh ma phung kon păng. Ƀiă lah păng rblang nau ngơi, jêh ri djôt prăp nau may tâm rnglăp.$b$,false),
('bunong-vn','DEU',33,10,null,$b$Păng nti nau may ntăm ma phung Y-Yakôb, jêh ri nau vay may ma phung Israel, păng nhhơr mpa ƀâu kah ta năp may, jêh ri mpa nhhơr gŭch ăp ta klơ nơng may.$b$,true),
('bunong-vn','DEU',33,11,null,$b$Ơ Yêhôva, mât ton nau ueh uĭn ma mpa păng geh, jêh ri dơn kan ma ti păng; ƀư chah lơi bŭt phung rlăng păng, phung tâm rmot ma păng, gay ma khân păng mâu hôm dâk ôh.’$b$,true),
('bunong-vn','DEU',33,12,null,$b$Păng lah nau di ma phung Benjamin: “Ăn nơm Yêhôva rŏng gŭ ma nau nâp dăch păng, păng n'gang lĕ nar jêh ri ƀư ntŭk păng gŭ ta vah vang săng nglik khân păng.$b$,false),
('bunong-vn','DEU',33,13,null,$b$Păng lah nau di ma phung Y-Yôsep: “Bri n'gor khân păng mra geh nau mât ton bơh Yêhôva, ma dak ngom bơh trôk klơ, jêh ri dak ueh lơn bơh tâm dâng,$b$,true),
('bunong-vn','DEU',33,14,null,$b$ma play ueh lơn bơh nchrat nar, jêh ri play ueh lơn tâm ăp khay,$b$,false),
('bunong-vn','DEU',33,15,null,$b$ma play ueh lơn bơh yôk ơm, jêh ri mpa rmeh ler tă bơh mbon gŭ ƀa ƀơ.$b$,false),
('bunong-vn','DEU',33,16,null,$b$Ma ndơ ăn ueh lơn bơh neh jêh ri bơh nau bêng ler păng, jêh ri nau yô̆ bơh nơm tâm mpơl jêh tâm pŭm. Ăn lĕ ndơ aơ tŭp ta klơ bôk Y-Yôsep ta bôk nơm jêng Kôranh ta nklang phung oh nâu păng.$b$,true),
('bunong-vn','DEU',33,17,null,$b$Păng geh nau rnam tâm ban ma ndrôk nkuăng păng deh bôk rah, jêh ri nke păng jêng nke ndrôk bri, ma nke nây păng mra tâm phung ndŭl mpôl kŏ tât ta dŭt bri neh; tâm ban pô nây yơh phung jât rbăn nuyh Êphraim, jêh ri tâm ban pô nây yơh phung rbăn nuyh Manasê.”$b$,true),
('bunong-vn','DEU',33,18,null,$b$Păng lah nau di ma phung Sabulôn, “Răm maak hom, Ơ Sabulôn, dôl may hăn nsong, jêh ri may, Ơ Isakar, tâm ngih bok may,$b$,true),
('bunong-vn','DEU',33,19,null,$b$khân păng mra kuăl phung ƀon lan ma yôk khân păng; ta nây khân păng nhhơr mpa ƀư brah di; yor lah khân păng mra rhôp nau rmeh ler dak mƀŭt jêh ri drăp khlay pôn jêh tâm choih.”$b$,false),
('bunong-vn','DEU',33,20,null,$b$Păng lah nau di ma phung Gat: “Ueh maak yơh ma nơm ƀư huy neh ma Gat! Gat gŭ rmơch nâm bu du mlâm yau mŭr, păng hêk nting tur jêh ri bôk.$b$,true),
('bunong-vn','DEU',33,21,null,$b$Păng săch ma păng nơm jêh neh ueh lơn tâm n'gor, yor lah ta nây geh kô̆ prăp jêh ma du huê kôranh ƀĭt gai, tơ lah kôranh phung ƀon lan tâm rƀŭn, păng ƀư nau sŏng Yêhôva, jêh ri tĭng ndô̆ nau vay phung Israel.”$b$,true),
('bunong-vn','DEU',33,22,null,$b$Păng lah nau di ma phung Dan: “Dan jêng du mlâm yau mŭr ndăm, păng nsăt bơh n'gor Basan.”$b$,true),
('bunong-vn','DEU',33,23,null,$b$Păng lah nau di ma phung Naptali: “Ơ Naptali, nơm hơm jêh ma nau Yêhôva yô̆, jêh ri bêng ma nau ueh uĭn bơh Yêhôva, sŏk pha dak nglau jêh ri kô̆ rđŭng.”$b$,true),
('bunong-vn','DEU',33,24,null,$b$Păng lah nau di ma phung Aser: “Aser geh nau ueh uĭn rmeh lơn ma phung kon bu klâu êng; ăn păng jêng nơm phung oh nâu păng rŏng lơn, jêh ri ăn păng mbŭk jêng păng tâm dak play Ôlivơ.$b$,true),
('bunong-vn','DEU',33,25,null,$b$Mâng nđăng mpông may mra ƀư ma loih jêh ri kông, jêh ri nau nđơr may mra tâm ban ma nar may gŭ rêh.$b$,true),
('bunong-vn','DEU',33,26,null,$b$Mâu geh nơm tâm ban ma Brah Ndu Yêsurun ôh, nơm mpăr tâm trôk kơl may, nơm mpăr ma nau rnam păng tâm trôk.$b$,true),
('bunong-vn','DEU',33,27,null,$b$Brah Ndu nơm gŭ n'ho ro jêng ntŭk khân may mbe, jêh ri tâm dâng khân may geh nting tur păng gŭ n'ho ro, păng mra nsot phung rlăng ta năp khân may, jêh ri lah, Ƀư rai hom.$b$,true),
('bunong-vn','DEU',33,28,null,$b$Pô ri phung Israel gŭ tâm nau nâp, bôk ma phung Yakôb gŭ êng tâm bri geh ba jêh ri dak play kriăk ƀâu âk ntŭk trôk ăn hoch dak ngom.$b$,true),
('bunong-vn','DEU',33,29,null,$b$Răm maak yơh khân may, Ơ phung Israel! Mbu nâm jêng nâm bu khân may, du phung ƀon lan Yêhôva tâm rklaih jêh? Păng jêng khêl koh dŏng khân may, jêh ri nơm jêng đao gưm ăn nau dơi ma khân may! Phung rlăng khân may mra văch ma nau kŭnh ƀon ta năp khân may jêh ri khân may mra jot ntŭk klơ khân păng.”$b$,true),
('bunong-vn','DEU',34,1,null,$b$Bơh neh lâng n'gor Môap, Y-Môis hao yôk Nêbô, ta kô yôk Pisga, tra ƀon Yêrikô. Jêh ri Yêhôva mpơl ăn păng saơ lĕ n'gor bri, bơh n'gor bri Galaat tât ta n'gor bri Dan,$b$,true),
('bunong-vn','DEU',34,2,null,$b$glom n'gor bri Naptali, n'gor bri Êphraim, jêh ri n'gor bri Manasê, glom n'gor bri Yuđa tât ta Dak Mƀŭt pa dâng,$b$,false),
('bunong-vn','DEU',34,3,null,$b$n'gor bri Nêgep jêh ri Neh Lâng, nâm bu ntĭt rlŭng Yêrikô ƀon geh âk tơm play đung, tât ta ƀon Sôar,$b$,false),
('bunong-vn','DEU',34,4,null,$b$Yêhôva lah ma păng, “Aơ yơh jêng n'gor bri gâp ton jêh gay ăn ma Y-Abraham ma Y-Isăk jêh ri ma Y-Yakôb. ‘Gâp mra ăn păng ma phung kon sau may.’ Gâp ăn may saơ jêh ma măt may nơm ƀiă lah may mâu dơi rgăn hăn ta nây ôh.”$b$,false),
('bunong-vn','DEU',34,5,null,$b$Pô ri Y-Môis, oh mon Yêhôva khĭt ta nây, tâm bri Môap, tĭng nâm nau Yêhôva ngơi,$b$,true),
('bunong-vn','DEU',34,6,null,$b$jêh ri păng tâp tâm rlŭng n'gor bri Môap tâm tra Bet Pêôr, ƀiă lah tât ta nar aơ mâu geh du huê bunuyh gĭt lâp ntŭk bu tâp păng.$b$,false),
('bunong-vn','DEU',34,7,null,$b$Y-Môis geh du rhiăng bar jât năm tơ lah păng khĭt, măt păng mâu hŏ plâm ôh, nau nđơr păng mâu hŭch lĕ.$b$,false),
('bunong-vn','DEU',34,8,null,$b$Phung ƀon lan Israel nhĭm nhhiăng ma Y-Môis tâm neh lâng bri Môap dôl tâm pe jât nar; jêh ri nar nhĭm nhhiăng jêh ri ndrê ndjăng ma Y-Môis lôch.$b$,false),
('bunong-vn','DEU',34,9,null,$b$Y-Yôsuê kon bu klâu Y-Nun bêng jêh ma Brah Huêng ueh nau blau mĭn, yor lah Y-Môis pah jêh ti ta păng. Pô ri phung ƀon lan Israel tông ma păng, jêh ri ƀư tĭng nâm nau Yêhôva ntăm jêh ma Y-Môis.$b$,true),
('bunong-vn','DEU',34,10,null,$b$Jêh ri bơh nar nây mâu hôm geh ôh tâm n'gor bri Israel du huê kôranh nơm mbơh lor nâm bu Y-Môis, nơm Yêhôva mâp ngơi ndrel tâm tra năp,$b$,true),
('bunong-vn','DEU',34,11,null,$b$mâu geh nơm tâm ban ma păng tâm lĕ rngôch nau tâm mbên jêh ri kan khlay Yêhôva njuăl hăn păng ƀư tâm n'gor bri Êjipt ma Y-Pharaôn, ma lĕ rngôch phung oh mon păng, jêh ri ma lĕ n'gor bri păng.$b$,false),
('bunong-vn','DEU',34,12,null,$b$Jêh ri tâm lĕ nau brah toyh jêh ri lĕ kan toyh jêh ri hôm klach Y-Môis ƀư jêh ta năp măt lĕ rngôch phung Israel.$b$,true);
